@import "tailwindcss" source(none);
@source "../src";
@import "tw-animate-css";
@plugin "@tailwindcss/typography";

@custom-variant dark (&:is(.dark *));

/*
 * Design system — "Sahl" AI workforce.
 * Palette intentionally avoids Stripe's indigo/violet: deep pine ink,
 * jade/teal primary, warm amber + coral accents on a cream canvas.
 * All colors use oklch.
 */

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-offset-background: var(--background);
  --color-ink: var(--ink);
  --color-ink-soft: var(--ink-soft);
  --color-jade: var(--jade);
  --color-jade-deep: var(--jade-deep);
  --color-amber: var(--amber);
  --color-gold: var(--gold);
  --color-gold-deep: var(--gold-deep);
  --color-gold-soft: var(--gold-soft);
  --color-coral: var(--coral);
  --color-sky: var(--sky);
  --color-cream: var(--cream);
  --color-terracotta: var(--jade-deep);
  --color-olive: var(--jade);
  --color-mustard: var(--amber);
  --color-clay: var(--coral);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --font-sans: "IBM Plex Sans Arabic", ui-sans-serif, system-ui, sans-serif;
  --font-display: "IBM Plex Sans Arabic", ui-sans-serif, sans-serif;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-exit: cubic-bezier(0.7, 0, 0.84, 0);
}

:root {
  --radius: 1.15rem;

  /* هوية سهل الموحدة — أبيض دافئ + حبر + قرميدي + ذهبي + تيل */
  --cream: oklch(1 0 0); /* أبيض نقي */
  --ink: oklch(0.16 0.004 60); /* أسود حبري */
  --ink-soft: oklch(0.46 0.006 60);
  --gold: oklch(0.67771 0.12672 73.45);
  --gold-deep: oklch(0.52418 0.13258 37.48);
  --gold-soft: oklch(0.965 0.026 73.45);
  --jade: oklch(0.48558 0.06376 183.77);
  --jade-deep: oklch(0.42 0.064 183.77);
  --amber: var(--gold);
  --coral: var(--gold-deep);
  --sky: var(--jade);

  --background: oklch(1 0 0);
  --foreground: var(--ink);
  --card: oklch(1 0 0);
  --card-foreground: var(--ink);
  --popover: oklch(1 0 0);
  --popover-foreground: var(--ink);
  --primary: var(--coral);
  --primary-foreground: oklch(0.985 0.005 84);
  --secondary: oklch(0.972 0.002 60);
  --secondary-foreground: var(--ink);
  --muted: oklch(0.968 0.002 60);
  --muted-foreground: oklch(0.5 0.006 60);
  --accent: var(--gold-soft);
  --accent-foreground: var(--ink);
  --destructive: var(--coral);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.16 0.004 60 / 0.12);
  --input: oklch(0.16 0.004 60 / 0.16);
  --ring: var(--coral);
  --chart-1: var(--ink);
  --chart-2: var(--jade);
  --chart-3: var(--sky);
  --chart-4: var(--amber);
  --chart-5: oklch(0.62 0.006 60);
  --sidebar: oklch(0.99 0.001 60);
  --sidebar-foreground: var(--ink);
  --sidebar-primary: var(--coral);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.965 0.02 183.77);
  --sidebar-accent-foreground: var(--ink);
  --sidebar-border: oklch(0.16 0.004 60 / 0.1);
  --sidebar-ring: var(--coral);

  --gradient-aurora: linear-gradient(115deg, var(--jade) 0%, var(--gold) 48%, var(--coral) 100%);
  --gradient-ink: linear-gradient(
    150deg,
    oklch(0.18 0.009 59),
    oklch(0.225 0.012 58) 62%,
    oklch(0.29 0.035 37)
  );
  --shadow-lift: 0 34px 80px -40px oklch(0.53 0.105 76 / 0.3);
  --shadow-card:
    0 1px 2px oklch(0.16 0.004 60 / 0.06), 0 18px 40px -28px oklch(0.53 0.105 76 / 0.24);

  /* زجاج سهل — أبيض شفاف بحدود رمادية رقيقة */
  --glass-tint: oklch(1 0 0 / 0.68);
  --glass-tint-strong: oklch(1 0 0 / 0.85);
  --glass-stroke: oklch(0.53 0.105 76 / 0.2);
  --glass-edge: oklch(0.16 0.004 60 / 0.08);
  --glass-blur: 24px;
  --glass-shadow: inset 0 1px 0 oklch(1 0 0 / 0.9), 0 26px 60px -40px oklch(0.53 0.105 76 / 0.25);
}

.dark {
  --background: oklch(0.215 0.012 62); /* #211C17 warm dark brown */
  --foreground: oklch(0.965 0.008 84);
  --card: oklch(0.26 0.014 62);
  --card-foreground: oklch(0.965 0.008 84);
  --popover: oklch(0.26 0.014 62);
  --popover-foreground: oklch(0.965 0.008 84);
  --primary: oklch(0.67 0.12 47);
  --primary-foreground: oklch(0.215 0.012 62);
  --secondary: oklch(0.31 0.016 64);
  --secondary-foreground: oklch(0.965 0.008 84);
  --muted: oklch(0.31 0.016 64);
  --muted-foreground: oklch(0.755 0.02 80);
  --accent: oklch(0.34 0.03 78);
  --accent-foreground: oklch(0.965 0.008 84);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 16%);
  --ring: oklch(0.67 0.12 47);
  --sidebar: oklch(0.26 0.014 62);
  --sidebar-foreground: oklch(0.965 0.008 84);
  --sidebar-primary: oklch(0.67 0.12 47);
  --sidebar-primary-foreground: oklch(0.215 0.012 62);
  --sidebar-accent: oklch(0.31 0.016 64);
  --sidebar-accent-foreground: oklch(0.965 0.008 84);
  --sidebar-border: oklch(1 0 0 / 12%);
  --sidebar-ring: oklch(0.67 0.12 47);
}

/* بطاقات باقات الأسعار — سطح المكتب فقط. نسخة الهاتف مستقلة ولا تتأثر. */
@media (min-width: 768px) {
  .pricing-desktop-grid {
    --pricing-card-radius: 1.45rem;
    --pricing-card-border: color-mix(in oklab, var(--foreground) 11%, transparent);
    --pricing-card-glass: color-mix(in oklab, var(--card) 82%, transparent);
    align-items: stretch;
    gap: 1.75rem;
    padding-block: 1.5rem 1.75rem;
  }

  .pricing-desktop-reveal {
    height: 100%;
  }

  .pricing-desktop-card {
    position: relative;
    display: flex;
    height: 100%;
    min-height: 40rem;
    flex-direction: column;
    padding: 2.1rem 1.8rem 1.8rem;
    border: 1px solid var(--pricing-card-border);
    border-radius: var(--pricing-card-radius);
    background: linear-gradient(
      150deg,
      color-mix(in oklab, var(--card) 94%, transparent),
      var(--pricing-card-glass)
    );
    box-shadow:
      inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
      0 18px 44px -38px color-mix(in oklab, var(--foreground) 32%, transparent);
    backdrop-filter: blur(20px) saturate(135%);
    transition:
      transform 280ms var(--ease-enter),
      border-color 280ms ease,
      box-shadow 280ms ease;
  }

  .pricing-desktop-card:hover {
    transform: translateY(-0.35rem);
    border-color: color-mix(in oklab, var(--primary) 32%, transparent);
    box-shadow:
      inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
      0 28px 58px -34px color-mix(in oklab, var(--foreground) 38%, transparent);
  }

  .pricing-desktop-card.is-featured {
    z-index: 2;
    transform: scale(1.04);
    border-color: color-mix(in oklab, var(--primary) 78%, transparent);
    box-shadow:
      inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
      0 30px 68px -30px color-mix(in oklab, var(--primary) 50%, transparent),
      0 16px 38px -28px color-mix(in oklab, var(--gold) 44%, transparent);
  }

  .pricing-desktop-card.is-featured:hover {
    transform: translateY(-0.35rem) scale(1.04);
    box-shadow:
      inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
      0 38px 78px -30px color-mix(in oklab, var(--primary) 58%, transparent),
      0 20px 42px -25px color-mix(in oklab, var(--gold) 50%, transparent);
  }

  .pricing-desktop-badge {
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: 50%;
    z-index: 3;
    min-width: 7.5rem;
    transform: translate(50%, -50%);
    border: 1px solid color-mix(in oklab, var(--card) 52%, transparent);
    border-radius: 999px;
    background: linear-gradient(115deg, var(--primary), var(--gold));
    box-shadow: 0 10px 24px -13px color-mix(in oklab, var(--primary) 74%, transparent);
    color: var(--primary-foreground);
    padding: 0.48rem 0.9rem;
    text-align: center;
    font-size: 0.73rem;
    font-weight: 800;
    line-height: 1;
  }

  .pricing-desktop-card-head h2 {
    font-family: "Almarai", var(--font-display);
    font-size: 1.55rem;
    font-weight: 800;
    line-height: 1.25;
  }

  .pricing-desktop-card-head p {
    min-height: 1.5rem;
    margin-top: 0.55rem;
    overflow: hidden;
    color: var(--muted-foreground);
    font-size: 0.82rem;
    font-weight: 400;
    line-height: 1.5rem;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .pricing-desktop-price {
    display: flex;
    min-height: 6.8rem;
    align-items: flex-end;
    gap: 0.65rem;
    padding-block: 1.3rem 1.15rem;
  }

  .pricing-desktop-price strong {
    color: var(--primary);
    font-family: "Almarai", var(--font-display);
    font-size: clamp(3.35rem, 4.2vw, 4.6rem);
    font-weight: 900;
    line-height: 0.95;
  }

  .pricing-desktop-price span {
    padding-bottom: 0.42rem;
    color: var(--muted-foreground);
    font-size: 0.78rem;
    font-weight: 600;
    white-space: nowrap;
  }

  .pricing-desktop-price.is-custom strong {
    font-size: clamp(2.3rem, 3vw, 3.15rem);
    line-height: 1.1;
  }

  .pricing-desktop-divider {
    height: 1px;
    flex: none;
    background: color-mix(in oklab, var(--foreground) 10%, transparent);
  }

  .pricing-desktop-perks {
    display: grid;
    gap: 0;
    margin-block: 1.45rem 1.75rem;
  }

  .pricing-desktop-perks li {
    display: grid;
    grid-template-columns: 1.35rem minmax(0, 1fr);
    min-height: 3rem;
    align-items: flex-start;
    gap: 0.75rem;
    padding-block: 0.68rem;
    border-bottom: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
    font-family: "IBM Plex Sans Arabic", var(--font-sans);
    font-size: 0.92rem;
    font-weight: 500;
    line-height: 1.65;
  }

  .pricing-desktop-perks li:last-child {
    border-bottom: 0;
  }

  .pricing-desktop-perk-icon {
    display: grid;
    width: 1.35rem;
    height: 1.35rem;
    margin-top: 0.1rem;
    place-items: center;
    border: 1px solid color-mix(in oklab, currentColor 26%, transparent);
    border-radius: 999px;
  }

  .pricing-desktop-perk-icon svg {
    width: 0.72rem;
    height: 0.72rem;
  }

  .pricing-desktop-perk-icon[data-tone="teal"] {
    background: color-mix(in oklab, var(--jade) 14%, transparent);
    color: var(--jade-deep);
  }

  .pricing-desktop-perk-icon[data-tone="gold"] {
    background: color-mix(in oklab, var(--gold) 15%, transparent);
    color: var(--gold-deep);
  }

  .pricing-desktop-perk-icon[data-tone="brick"] {
    background: color-mix(in oklab, var(--primary) 13%, transparent);
    color: var(--primary);
  }

  .pricing-desktop-cta {
    width: 100%;
    min-height: 3.15rem;
    margin-top: auto;
    border-color: color-mix(in oklab, var(--primary) 62%, transparent);
    border-radius: 999px;
    background: transparent;
    color: var(--primary);
    font-weight: 800;
    box-shadow: none;
  }

  .pricing-desktop-cta:hover {
    border-color: var(--primary);
    background: color-mix(in oklab, var(--primary) 7%, transparent);
    color: var(--primary);
  }

  .pricing-desktop-card.is-featured .pricing-desktop-cta {
    border-color: transparent;
    background: linear-gradient(115deg, var(--primary), var(--gold));
    color: var(--primary-foreground);
    box-shadow: 0 12px 30px -14px color-mix(in oklab, var(--primary) 72%, transparent);
  }

  .pricing-desktop-card.is-featured .pricing-desktop-cta:hover {
    color: var(--primary-foreground);
    box-shadow: 0 16px 34px -12px color-mix(in oklab, var(--primary) 82%, transparent);
  }
}

@media (min-width: 768px) and (prefers-reduced-motion: reduce) {
  .pricing-desktop-card,
  .pricing-desktop-card:hover,
  .pricing-desktop-card.is-featured,
  .pricing-desktop-card.is-featured:hover {
    transition: none;
  }

  .pricing-desktop-card:hover {
    transform: none;
  }

  .pricing-desktop-card.is-featured,
  .pricing-desktop-card.is-featured:hover {
    transform: scale(1.04);
  }
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
    /* واجهة فاتحة ثابتة: المتصفح لا يقلب الألوان ولا شريط العنوان. */
    color-scheme: light;
    background-color: var(--color-background);
    /* لا تمدّد أفقي مهما طال المحتوى — clip لا يكسر position: sticky. */
    overflow-x: clip;
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    line-height: 1.7;
    -webkit-font-smoothing: antialiased;
    /* لا تمدّد أفقي على أي شاشة — clip لا يجعل body حاوية تمرير فتبقى الشرائط اللاصقة تعمل. */
    overflow-x: clip;
  }

  /* الصور والوسائط لا تتجاوز حاويتها أبداً. */
  img,
  svg,
  video,
  canvas,
  iframe,
  table {
    max-width: 100%;
  }

  /* النصوص الطويلة بلا مسافات (روابط/أكواد) تُكسر بدل أن تمدّ الصفحة. */
  p,
  li,
  h1,
  h2,
  h3,
  h4,
  td,
  th {
    overflow-wrap: anywhere;
  }

  ::selection {
    background: oklch(0.7 0.125 79 / 0.4);
  }
}

/* ---------- Utilities ---------- */

@utility text-gradient {
  background-image: var(--gradient-aurora);
  background-size: 200% 200%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: aurora-pan 12s ease-in-out infinite;
}

@utility surface-ink {
  background-image: var(--gradient-ink);
  color: oklch(0.97 0.01 95);
}

@utility shadow-lift {
  box-shadow: var(--shadow-lift);
}

@utility shadow-card {
  box-shadow: var(--shadow-card);
}

/* Stripe-style skewed gradient ribbon behind the hero */
@utility hero-ribbon {
  position: absolute;
  inset: -40% -20% auto -20%;
  height: 145%;
  background-image: var(--gradient-aurora);
  background-size: 220% 220%;
  animation: aurora-pan 16s ease-in-out infinite;
  transform: skewY(-8deg);
  filter: blur(0px);
  opacity: 0.95;
  clip-path: polygon(0 0, 100% 0, 100% 68%, 0 100%);
}

@utility grid-lines {
  background-image:
    linear-gradient(to right, oklch(1 0 0 / 0.09) 1px, transparent 1px),
    linear-gradient(to bottom, oklch(1 0 0 / 0.09) 1px, transparent 1px);
  background-size: 56px 56px;
}

@utility glass {
  background: oklch(1 0 0 / 0.7);
  backdrop-filter: blur(14px) saturate(160%);
}

@utility marquee-track {
  display: flex;
  width: max-content;
  animation: marquee 34s linear infinite;
}

@utility marquee-track-rtl {
  display: flex;
  width: max-content;
  animation: marquee-rev 30s linear infinite;
}

@keyframes aurora-pan {
  0%,
  100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

@keyframes marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

@keyframes marquee-rev {
  from {
    transform: translateX(-50%);
  }
  to {
    transform: translateX(0);
  }
}

@keyframes float-soft {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

@keyframes pulse-ring {
  0% {
    box-shadow: 0 0 0 0 oklch(0.585 0.115 46 / 0.42);
  }
  70% {
    box-shadow: 0 0 0 14px oklch(0.585 0.115 46 / 0);
  }
  100% {
    box-shadow: 0 0 0 0 oklch(0.585 0.115 46 / 0);
  }
}

@keyframes ticker-up {
  from {
    transform: translateY(100%);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

/* شاشة ترقية الأسعار على الهاتف */
@keyframes sahl-pricing-wave-run {
  from {
    background-position:
      0 0,
      14px 14px,
      28px 28px;
  }
  to {
    background-position:
      -42px 0,
      -28px 14px,
      -14px 28px;
  }
}

@media (max-width: 767px) {
  .sahl-pricing-shell {
    height: 100svh;
    min-height: 0;
    overflow: hidden;
  }

  .sahl-pricing-shell > .sahl-white-nav {
    display: none;
  }

  .sahl-pricing-shell > main {
    height: 100%;
  }

  .sahl-upgrade {
    position: relative;
    isolation: isolate;
    height: 100%;
    overflow: hidden;
    background: color-mix(in oklab, var(--background) 96%, var(--gold-soft));
  }

  .sahl-upgrade-dots {
    position: absolute;
    z-index: -1;
    inset: 0;
    background-image:
      radial-gradient(
        circle,
        color-mix(in oklab, var(--primary) 27%, transparent) 1px,
        transparent 1.45px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--gold) 25%, transparent) 1px,
        transparent 1.45px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--jade) 25%, transparent) 1px,
        transparent 1.45px
      );
    background-position:
      0 0,
      14px 14px,
      28px 28px;
    background-size: 42px 42px;
    mask-image: linear-gradient(to bottom, black, transparent 92%);
    opacity: 0.62;
    contain: strict;
    pointer-events: none;
  }

  .sahl-upgrade-dots::after {
    content: "";
    position: absolute;
    inset: 0 -28%;
    background-image:
      radial-gradient(
        circle,
        color-mix(in oklab, var(--primary) 64%, transparent) 2px,
        transparent 2.8px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--gold) 60%, transparent) 2px,
        transparent 2.8px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--jade) 58%, transparent) 2px,
        transparent 2.8px
      );
    background-position:
      0 0,
      14px 14px,
      28px 28px;
    background-size: 42px 42px;
    mask-image: linear-gradient(125deg, transparent 38%, black 46%, black 54%, transparent 62%);
    mask-repeat: no-repeat;
    opacity: 0.7;
    animation: sahl-pricing-wave-run 2.35s linear infinite;
    will-change: background-position;
  }

  .sahl-upgrade-inner {
    display: grid;
    grid-template-rows: auto auto auto minmax(0, 1fr) auto;
    width: min(100%, 30rem);
    height: 100%;
    margin-inline: auto;
    padding: max(0.5rem, env(safe-area-inset-top)) 1rem max(0.4rem, env(safe-area-inset-bottom));
  }

  .sahl-upgrade-topbar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    min-height: 2rem;
  }

  .sahl-upgrade-brand {
    grid-column: 1;
    display: grid;
    width: 2rem;
    height: 2rem;
    place-items: center;
    border: 1px solid color-mix(in oklab, var(--primary) 20%, var(--border));
    border-radius: 999px;
    background: color-mix(in oklab, var(--card) 94%, var(--background));
    opacity: 0.68;
  }

  .sahl-upgrade-brand img {
    width: 1.1rem;
    height: 1.1rem;
    object-fit: contain;
  }

  .sahl-upgrade-close {
    grid-column: 2;
    width: 2rem;
    height: 2rem;
    border: 1px solid var(--border);
    border-radius: 999px;
    background: color-mix(in oklab, var(--card) 94%, var(--background));
  }

  .sahl-upgrade-close svg {
    width: 1rem;
    height: 1rem;
  }

  .sahl-upgrade-heading {
    text-align: center;
    line-height: 1.2;
  }

  .sahl-upgrade-heading p {
    color: var(--muted-foreground);
    font-size: 0.68rem;
    font-weight: 700;
  }

  .sahl-upgrade-heading h1,
  .sahl-upgrade-plan-title h2 {
    font-family: "Almarai", var(--font-sans);
    letter-spacing: 0;
  }

  .sahl-upgrade-heading h1 {
    margin-top: 0.1rem;
    font-size: clamp(1.35rem, 5.8vw, 1.75rem);
    font-weight: 800;
  }

  .sahl-upgrade-tabs {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.25rem;
    margin-top: 0.45rem;
    padding: 0.2rem;
    border: 1px solid var(--border);
    border-radius: 0.8rem;
    background: color-mix(in oklab, var(--card) 94%, var(--background));
  }

  .sahl-upgrade-tabs button {
    min-width: 0;
    height: 1.9rem;
    padding-inline: 0.3rem;
    border-radius: 0.58rem;
    color: var(--muted-foreground);
    font-size: 0.72rem;
    font-weight: 800;
  }

  .sahl-upgrade-tabs button.is-active {
    background: var(--primary);
    color: var(--primary-foreground);
    box-shadow: 0 6px 18px color-mix(in oklab, var(--primary) 24%, transparent);
  }

  .sahl-upgrade-plan {
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto auto auto auto;
    min-height: 0;
    padding-top: 0.48rem;
  }

  .sahl-upgrade-plan-title {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 0.55rem;
  }

  .sahl-upgrade-plan-title h2 {
    font-size: clamp(1.12rem, 4.8vw, 1.45rem);
    font-weight: 800;
    line-height: 1.25;
  }

  .sahl-upgrade-plan-title p {
    overflow: hidden;
    color: var(--muted-foreground);
    font-size: 0.64rem;
    font-weight: 600;
    line-height: 1.35;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .sahl-upgrade-plan-title > span {
    flex-shrink: 0;
    padding: 0.2rem 0.48rem;
    border-radius: 999px;
    background: color-mix(in oklab, var(--gold) 16%, var(--card));
    color: var(--gold-deep);
    font-size: 0.56rem;
    font-weight: 800;
  }

  .sahl-upgrade-perks {
    min-height: 0;
    margin-top: 0.42rem;
    padding: 0.3rem 0.85rem;
    border: 1px solid color-mix(in oklab, var(--border) 72%, var(--gold));
    border-radius: 0.9rem;
    background: color-mix(in oklab, var(--card) 94%, var(--background));
    box-shadow: var(--glass-shadow);
  }

  .sahl-upgrade-perks ul {
    display: grid;
    align-content: center;
    height: 100%;
  }

  .sahl-upgrade-perks li {
    display: grid;
    grid-template-columns: 1.2rem minmax(0, 1fr);
    align-items: start;
    gap: 0.62rem;
    min-height: 1.65rem;
    padding-block: 0.36rem;
    border-bottom: 1px solid color-mix(in oklab, var(--border) 58%, transparent);
    font-family: "IBM Plex Sans Arabic", var(--font-sans);
    font-size: clamp(0.72rem, 3.2vw, 0.82rem);
    font-weight: 500;
    line-height: 1.5;
  }

  .sahl-upgrade-perks li:last-child {
    border-bottom: 0;
  }

  .sahl-upgrade-perk-check {
    display: grid;
    width: 1.2rem;
    height: 1.2rem;
    margin-top: 0.08rem;
    place-items: center;
    border: 1px solid color-mix(in oklab, currentColor 26%, transparent);
    border-radius: 999px;
    background: color-mix(in oklab, currentColor 9%, transparent);
  }

  .sahl-upgrade-perk-check svg {
    width: 0.7rem;
    height: 0.7rem;
  }

  .sahl-upgrade-perk-check[data-tone="primary"] {
    color: var(--primary);
  }
  .sahl-upgrade-perk-check[data-tone="gold"] {
    color: var(--gold-deep);
  }
  .sahl-upgrade-perk-check[data-tone="jade"] {
    color: var(--jade-deep);
  }

  .sahl-upgrade-billing {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.45rem;
    margin-top: 0.45rem;
  }

  .sahl-upgrade-billing button {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-rows: auto auto;
    column-gap: 0.42rem;
    width: 100%;
    height: 3.25rem;
    padding: 0.38rem 0.52rem;
    border: 1.5px solid var(--border);
    border-radius: 0.78rem;
    background: color-mix(in oklab, var(--card) 82%, transparent);
    text-align: right;
  }

  .sahl-upgrade-billing button.is-selected {
    border-color: var(--primary);
    background: color-mix(in oklab, var(--primary) 5%, var(--card));
  }

  .sahl-upgrade-radio {
    grid-row: 1 / 3;
    align-self: center;
    display: grid;
    place-items: center;
    width: 1rem;
    height: 1rem;
    border: 1.5px solid var(--border);
    border-radius: 999px;
  }

  .is-selected .sahl-upgrade-radio {
    border-color: var(--primary);
  }
  .is-selected .sahl-upgrade-radio i {
    width: 0.52rem;
    height: 0.52rem;
    border-radius: 999px;
    background: var(--primary);
  }

  .sahl-upgrade-cycle {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 0.25rem;
    font-size: 0.67rem;
    font-weight: 800;
    line-height: 1;
  }

  .sahl-upgrade-cycle small {
    padding: 0.14rem 0.25rem;
    border-radius: 999px;
    background: color-mix(in oklab, var(--gold) 16%, var(--card));
    color: var(--gold-deep);
    font-size: 0.49rem;
    white-space: nowrap;
  }

  .sahl-upgrade-billing strong {
    align-self: end;
    overflow: hidden;
    font-family: "Almarai", var(--font-sans);
    font-size: 0.72rem;
    font-weight: 800;
    line-height: 1;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .sahl-upgrade-custom-offer {
    display: grid;
    place-items: center;
    min-height: 3.25rem;
    margin-top: 0.45rem;
    padding: 0.45rem 0.7rem;
    border: 1.5px solid color-mix(in oklab, var(--primary) 66%, var(--border));
    border-radius: 0.78rem;
    background: color-mix(in oklab, var(--primary) 5%, var(--card));
    text-align: center;
  }

  .sahl-upgrade-custom-offer strong {
    font-family: "Almarai", var(--font-sans);
    font-size: 0.82rem;
    font-weight: 800;
  }

  .sahl-upgrade-custom-offer span {
    color: var(--muted-foreground);
    font-size: 0.6rem;
    font-weight: 600;
  }

  .sahl-upgrade-note {
    margin-top: 0.28rem;
    color: var(--muted-foreground);
    font-size: 0.58rem;
    font-weight: 600;
    line-height: 1.35;
    text-align: center;
  }

  .sahl-upgrade-cta {
    width: 100%;
    height: 2.7rem;
    margin-top: 0.35rem;
    border-radius: 0.78rem;
    background: var(--primary);
    color: var(--primary-foreground);
    font-family: "Almarai", var(--font-sans);
    font-size: 0.8rem;
    font-weight: 800;
    box-shadow: 0 12px 28px color-mix(in oklab, var(--primary) 24%, transparent);
  }

  .sahl-upgrade-trust {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.25rem;
    margin-top: 0.28rem;
    color: var(--muted-foreground);
    font-size: 0.53rem;
    font-weight: 700;
    line-height: 1;
  }

  .sahl-upgrade-trust svg {
    width: 0.72rem;
    height: 0.72rem;
    color: var(--jade-deep);
  }

  .sahl-upgrade-legal {
    display: flex;
    align-items: end;
    justify-content: center;
    gap: 0.35rem;
    min-height: 1rem;
    color: var(--muted-foreground);
    font-size: 0.64rem;
    font-weight: 700;
    line-height: 1;
  }
}

@media (max-width: 767px) and (max-height: 700px) {
  .sahl-upgrade-inner {
    padding-inline: 0.78rem;
  }

  .sahl-upgrade-topbar {
    min-height: 1.65rem;
  }
  .sahl-upgrade-close {
    width: 1.65rem;
    height: 1.65rem;
  }
  .sahl-upgrade-brand {
    width: 1.65rem;
    height: 1.65rem;
  }
  .sahl-upgrade-heading p {
    display: none;
  }
  .sahl-upgrade-heading h1 {
    margin-top: 0;
    font-size: 1.22rem;
  }
  .sahl-upgrade-tabs {
    margin-top: 0.28rem;
  }
  .sahl-upgrade-tabs button {
    height: 1.72rem;
  }
  .sahl-upgrade-plan {
    padding-top: 0.28rem;
  }
  .sahl-upgrade-plan-title h2 {
    font-size: 1rem;
  }
  .sahl-upgrade-plan-title p {
    font-size: 0.56rem;
  }
  .sahl-upgrade-perks {
    margin-top: 0.25rem;
    padding-block: 0.2rem;
  }
  .sahl-upgrade-perks li {
    min-height: 1.35rem;
    padding-block: 0.22rem;
    font-size: 0.66rem;
    line-height: 1.35;
  }
  .sahl-upgrade-perk-check {
    width: 1rem;
    height: 1rem;
  }
  .sahl-upgrade-perk-check svg {
    width: 0.6rem;
    height: 0.6rem;
  }
  .sahl-upgrade-billing {
    margin-top: 0.28rem;
  }
  .sahl-upgrade-billing button {
    height: 2.9rem;
  }
  .sahl-upgrade-custom-offer {
    min-height: 2.9rem;
    margin-top: 0.28rem;
    padding-block: 0.28rem;
  }
  .sahl-upgrade-custom-offer strong {
    font-size: 0.74rem;
  }
  .sahl-upgrade-custom-offer span {
    font-size: 0.54rem;
  }
  .sahl-upgrade-note {
    margin-top: 0.2rem;
    font-size: 0.52rem;
  }
  .sahl-upgrade-cta {
    height: 2.35rem;
    margin-top: 0.25rem;
  }
  .sahl-upgrade-trust {
    margin-top: 0.2rem;
  }
  .sahl-upgrade-legal {
    min-height: 0.9rem;
    font-size: 0.58rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sahl-upgrade-dots {
    animation: none;
  }

  .sahl-upgrade-dots::after {
    animation: none;
    mask-position: 50% 0;
  }
}

/* تدفق التكاملات في الصفحة الرئيسية */
@utility integration-grid {
  background-image: radial-gradient(circle, oklch(1 0 0 / 0.11) 1px, transparent 1.5px);
  background-size: 24px 24px;
  mask-image: linear-gradient(to bottom, transparent, black 12%, black 88%, transparent);
}

@utility integration-flow-line {
  background-image: repeating-linear-gradient(
    to left,
    color-mix(in oklab, var(--amber) 75%, transparent) 0 6px,
    transparent 6px 13px
  );
}

@keyframes integration-app-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-5px);
  }
}

@keyframes integration-employee-active {
  0%,
  38%,
  100% {
    border-color: var(--border);
    background-color: color-mix(in oklab, var(--secondary) 70%, transparent);
  }
  48%,
  68% {
    border-color: color-mix(in oklab, var(--primary) 45%, var(--border));
    background-color: color-mix(in oklab, var(--primary) 9%, var(--card));
  }
}

@keyframes integration-pulse-travel {
  0% {
    transform: translateX(110px);
    opacity: 0;
  }
  15%,
  70% {
    opacity: 1;
  }
  100% {
    transform: translateX(-110px);
    opacity: 0;
  }
}

@utility integration-app {
  animation: integration-app-float 4.5s ease-in-out infinite;
}

@utility integration-employee {
  animation: integration-employee-active 4.8s ease-in-out infinite;
}

@utility integration-pulse {
  position: absolute;
  z-index: 20;
  top: 50%;
  width: 7px;
  height: 7px;
  margin-top: -3px;
  border-radius: 999px;
  background-color: var(--amber);
  box-shadow: 0 0 16px color-mix(in oklab, var(--amber) 80%, transparent);
  animation: integration-pulse-travel 3.2s linear infinite;
}

@utility integration-pulse-a {
  right: 50%;
}

@utility integration-pulse-b {
  left: 50%;
  animation-delay: 1.6s;
}

@utility animate-float {
  animation: float-soft 6s ease-in-out infinite;
}

@utility animate-pulse-ring {
  animation: pulse-ring 2.4s ease-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ===== Sahl homepage — monochrome motion system ===== */
.mono-page {
  --mono-black: oklch(0.12 0 0);
  --mono-graphite: oklch(0.34 0 0);
  --mono-mid: oklch(0.56 0 0);
  --mono-line: oklch(0.12 0 0 / 0.13);
  --mono-soft: oklch(0.97 0 0);
  background: oklch(1 0 0);
  color: var(--mono-black);
}
.mono-page .nav-floating-control {
  border-color: var(--mono-line);
  background: oklch(1 0 0 / 0.88);
  color: var(--mono-black);
  box-shadow: 0 8px 25px -20px var(--mono-black);
  backdrop-filter: blur(16px);
}
.mono-page .nav-glass-sheet {
  border-color: var(--mono-line);
  background: oklch(1 0 0 / 0.96);
  box-shadow: 0 24px 70px -40px var(--mono-black);
}
.mono-page .nav-glass-sheet::before,
.mono-page .nav-glass-sheet::after {
  display: none;
}
.mono-page .nav-glass-cta-primary,
.mono-page .nav-glass-cta-aurora {
  border-color: var(--mono-black);
  background: var(--mono-black);
  color: oklch(1 0 0);
  box-shadow: none;
}
.mono-home {
  overflow: clip;
  background: oklch(1 0 0);
  color: var(--mono-black);
  font-family: "IBM Plex Sans Arabic", ui-sans-serif, sans-serif;
}
.mono-home *,
.mono-home *::before,
.mono-home *::after {
  box-sizing: border-box;
}
.mono-home h1,
.mono-home h2,
.mono-home h3,
.mono-home p {
  letter-spacing: 0;
}
.mono-shell {
  width: min(100% - 3rem, 76rem);
  margin-inline: auto;
}
.mono-grid-field {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(to left, var(--mono-line) 1px, transparent 1px),
    linear-gradient(to bottom, var(--mono-line) 1px, transparent 1px);
  background-size: 4.5rem 4.5rem;
  mask-image: linear-gradient(to bottom, black, transparent 86%);
  opacity: 0.48;
}

.mono-hero {
  position: relative;
  min-height: 61rem;
  padding: 10rem 0 7rem;
  border-bottom: 1px solid var(--mono-line);
  background: oklch(1 0 0);
}
.mono-hero::before {
  content: "SAHL / 01";
  position: absolute;
  top: 8rem;
  left: 2.5rem;
  color: var(--mono-mid);
  font:
    600 0.62rem/1 ui-monospace,
    monospace;
  writing-mode: vertical-rl;
}
.mono-hero-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 0.83fr 1.17fr;
  align-items: center;
  gap: clamp(2rem, 5vw, 5rem);
}
.mono-hero-copy {
  padding-block: 3rem;
}
.mono-kicker {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 1.7rem;
  color: var(--mono-graphite);
  font-size: 0.8rem;
  font-weight: 600;
}
.mono-kicker span {
  border: 1px solid var(--mono-black);
  padding: 0.3rem 0.55rem;
  color: var(--mono-black);
  font-size: 0.65rem;
}
.mono-hero h1 {
  max-width: 45rem;
  font-size: clamp(4rem, 6.7vw, 7rem);
  font-weight: 700;
  line-height: 1.04;
  text-wrap: balance;
}
.mono-hero h1 em {
  display: inline-block;
  font-style: normal;
  font-weight: 400;
  color: var(--mono-graphite);
}
.mono-hero-copy > p:not(.mono-kicker) {
  max-width: 35rem;
  margin-top: 1.7rem;
  color: var(--mono-graphite);
  font-size: 1.08rem;
  line-height: 1.9;
}
.mono-actions {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  margin-top: 2rem;
}
.mono-actions a,
.mono-final a {
  display: inline-flex;
  min-height: 3.2rem;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  padding-inline: 1.25rem;
  border: 1px solid var(--mono-black);
  font-size: 0.82rem;
  font-weight: 700;
  transition:
    transform 0.25s ease,
    background 0.25s ease,
    color 0.25s ease;
}
.mono-actions a:first-child,
.mono-final a {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-actions a:hover,
.mono-final a:hover {
  transform: translateY(-3px);
}
.mono-actions a:last-child:hover {
  background: var(--mono-soft);
}
.mono-actions svg,
.mono-final svg {
  width: 1rem;
}
.mono-trial {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-top: 1rem;
  color: var(--mono-mid);
  font-size: 0.72rem;
}
.mono-trial svg {
  width: 0.9rem;
}
.mono-hero-product {
  position: relative;
  transform: perspective(1500px) rotateY(-2deg) rotateX(1deg);
  transform-origin: center left;
}
.mono-scroll-cue {
  position: absolute;
  z-index: 3;
  bottom: 2rem;
  left: 50%;
  display: grid;
  justify-items: center;
  gap: 0.7rem;
  transform: translateX(-50%);
  color: var(--mono-mid);
  font-size: 0.62rem;
}
.mono-scroll-cue i {
  position: relative;
  width: 1px;
  height: 2.8rem;
  overflow: hidden;
  background: var(--mono-line);
}
.mono-scroll-cue i::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--mono-black);
  animation: mono-scroll 2.2s ease-in-out infinite;
}
@keyframes mono-scroll {
  0% {
    transform: translateY(-100%);
  }
  65%,
  100% {
    transform: translateY(100%);
  }
}

.mono-workspace,
.mono-studio {
  overflow: hidden;
  border: 1px solid var(--mono-black);
  background: oklch(1 0 0);
  box-shadow:
    18px 18px 0 var(--mono-soft),
    18px 18px 0 1px var(--mono-line);
}
.mono-window-bar {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  height: 3.4rem;
  align-items: center;
  padding-inline: 1rem;
  border-bottom: 1px solid var(--mono-line);
  font-size: 0.7rem;
}
.mono-window-bar > span {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--mono-mid);
}
.mono-window-bar > span i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--mono-black);
  animation: mono-pulse 2s ease-out infinite;
}
.mono-window-controls {
  display: flex;
  gap: 0.3rem;
  direction: ltr;
}
.mono-window-controls i {
  width: 0.48rem;
  height: 0.48rem;
  border: 1px solid var(--mono-mid);
  border-radius: 50%;
}
@keyframes mono-pulse {
  50% {
    box-shadow: 0 0 0 0.35rem oklch(0.12 0 0 / 0.08);
  }
}
.mono-workspace-grid {
  display: grid;
  grid-template-columns: 9.5rem 1fr;
  min-height: 34rem;
}
.mono-employee-rail {
  padding: 0.65rem;
  border-inline-end: 1px solid var(--mono-line);
  background: var(--mono-soft);
}
.mono-employee-rail button {
  position: relative;
  width: 100%;
  height: 4.35rem;
  justify-content: flex-start;
  gap: 0.55rem;
  padding: 0.4rem;
  border-radius: 0;
  color: var(--mono-black);
  white-space: normal;
}
.mono-employee-rail button::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 1px;
  background: var(--mono-line);
}
.mono-employee-rail button.is-active {
