/* MENA map background layer (hero only) — purely decorative, sits below all content (z-10) */
.mena-map-layer {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  mask-image: linear-gradient(to bottom, black 55%, transparent 96%);
}

.mena-map-layer svg {
  width: min(64rem, 88%);
  height: auto;
  max-height: 92%;
  margin-inline-end: -6%;
  opacity: 0.9;
}

.mena-map-layer.mena-map-orbit {
  inset: 0;
  z-index: auto;
  justify-content: center;
  overflow: visible;
  mask-image: none;
}
.mena-map-layer.mena-map-orbit svg {
  width: 100%;
  height: 100%;
  max-height: none;
  margin: 0;
  overflow: visible;
  opacity: 1;
  filter: drop-shadow(0 0 10px color-mix(in oklab, var(--amber) 22%, transparent))
    drop-shadow(0 10px 18px color-mix(in oklab, var(--primary) 20%, transparent));
}
.mena-map-orbit .mena-map-fill {
  fill: color-mix(in oklab, var(--primary) 22%, transparent);
}
.mena-map-orbit .mena-map-outline {
  stroke: color-mix(in oklab, var(--amber) 62%, var(--primary));
  stroke-width: 1.8;
  stroke-linejoin: round;
  stroke-dasharray: 1800;
  animation:
    mena-outline-draw 3.2s var(--ease-enter) both,
    mena-outline-glow 5s 3.2s ease-in-out infinite;
}
.mena-map-orbit .mena-map-borders {
  stroke: color-mix(in oklab, var(--amber) 34%, transparent);
  stroke-width: 0.9;
  stroke-dasharray: 3 4;
}
.mena-map-orbit .mena-map-aura {
  display: none;
}
.mena-map-orbit .mena-route {
  stroke: color-mix(in oklab, var(--amber) 62%, transparent);
  stroke-width: 1.6;
  stroke-dasharray: 3 9;
}
.mena-map-orbit .mena-capital-dot {
  stroke-width: 1.8;
}
.mena-map-orbit .mena-capital-pulse {
  animation-duration: 3.4s;
}
.mena-map-orbit .mena-place-labels {
  fill: color-mix(in oklab, var(--primary) 60%, var(--foreground));
  font-size: 11px;
  letter-spacing: 0.02em;
}

.mena-map-fill {
  fill: color-mix(in oklab, var(--primary) 6%, transparent);
}
.mena-map-outline {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 92%, transparent);
  stroke-width: 1.5;
  stroke-linejoin: round;
}
.mena-map-borders {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 30%, transparent);
  stroke-width: 0.7;
}
.mena-route {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 55%, transparent);
  stroke-width: 1.1;
  stroke-linecap: round;
  stroke-dasharray: 4 8;
  animation: mena-route-flow 9s linear infinite;
}
.mena-pulse {
  fill: var(--amber);
  filter: drop-shadow(0 0 6px color-mix(in oklab, var(--amber) 90%, transparent));
}
.mena-capital-dot {
  fill: var(--primary);
  stroke: color-mix(in oklab, var(--card) 88%, transparent);
  stroke-width: 1.4;
}
.mena-capital-pulse {
  fill: color-mix(in oklab, var(--primary) 26%, transparent);
  transform-box: fill-box;
  transform-origin: center;
  animation: mena-capital-pulse 2.8s ease-out infinite;
}
.mena-capital-hub .mena-capital-dot {
  fill: var(--amber);
}
.mena-capital-hub .mena-capital-pulse {
  fill: color-mix(in oklab, var(--amber) 30%, transparent);
}
.mena-map-aura {
  fill: color-mix(in oklab, var(--primary) 8%, transparent);
  filter: url(#mena-soft-glow);
}
.mena-map-scan {
  fill: none;
  stroke: color-mix(in oklab, var(--amber) 58%, transparent);
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-dasharray: 1 22;
  animation: mena-scan 8s linear infinite;
}
.mena-place-labels {
  fill: color-mix(in oklab, var(--foreground) 58%, transparent);
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 800;
}
@keyframes mena-route-flow {
  to {
    stroke-dashoffset: -60;
  }
}
@keyframes mena-scan {
  to {
    stroke-dashoffset: -184;
  }
}
@keyframes mena-capital-pulse {
  0% {
    scale: 0.45;
    opacity: 0.9;
  }
  75%,
  100% {
    scale: 1.65;
    opacity: 0;
  }
}
@keyframes mena-map-breathe {
  0%,
  100% {
    transform: translateY(0) scale(1);
  }
  50% {
    transform: translateY(-5px) scale(1.018);
  }
}
@keyframes mena-outline-draw {
  from {
    stroke-dashoffset: 1800;
    opacity: 0.35;
  }
  to {
    stroke-dashoffset: 0;
    opacity: 1;
  }
}
@keyframes mena-outline-glow {
  0%,
  100% {
    filter: drop-shadow(0 0 0 transparent);
  }
  50% {
    filter: drop-shadow(0 0 4px color-mix(in oklab, var(--primary) 48%, transparent));
  }
}

.dark .mena-map-fill {
  fill: color-mix(in oklab, var(--primary) 10%, transparent);
}
.dark .mena-map-outline {
  stroke: color-mix(in oklab, var(--primary) 85%, transparent);
}
.dark .mena-map-borders {
  stroke: color-mix(in oklab, var(--foreground) 22%, transparent);
}

@media (max-width: 768px) {
  .mena-map-layer {
    justify-content: center;
  }
  .mena-map-layer svg {
    width: 145%;
    margin-inline-end: 0;
    opacity: 0.58;
  }
  .mena-map-layer.mena-map-orbit svg {
    width: 100%;
    margin: 0;
    opacity: 1;
  }
}

