}
@keyframes orbit-commentary-in {
  from {
    opacity: 0;
    translate: 50% 10px;
    scale: 0.97;
  }
  to {
    opacity: 1;
    translate: 50% 0;
    scale: 1;
  }
}
.orbit-bubble::after {
  content: "";
  position: absolute;
  z-index: -1;
  inset: auto 1.4rem -0.34rem auto;
  width: 0.7rem;
  height: 0.7rem;
  rotate: 45deg;
  border-inline-end: 1px solid
    color-mix(in oklab, var(--employee-tone, var(--primary)) 34%, transparent);
  border-block-end: 1px solid
    color-mix(in oklab, var(--employee-tone, var(--primary)) 34%, transparent);
