}
.team-orbit-dark .orbit-bubble {
  border-color: color-mix(in oklab, var(--employee-tone, var(--primary)) 48%, transparent);
  background:
    linear-gradient(
      160deg,
      color-mix(in oklab, var(--employee-tone, var(--primary)) 18%, transparent),
      transparent 60%
    ),
    color-mix(in oklab, var(--foreground) 82%, transparent);
