}
.team-orbit-dark .orbit-bubble-text {
  color: var(--background);
}
.team-orbit-dark .orbit-bubble-head {
  color: color-mix(in oklab, var(--employee-tone, var(--primary)) 62%, var(--background));
}
.team-orbit-dark .orbit-bubble-head b,
.team-orbit-dark .orbit-bubble-foot {
  color: color-mix(in oklab, var(--background) 55%, transparent);
}
@keyframes orbit-bubble-in {
  from {
    opacity: 0;
    translate: 0 12px;
    scale: 0.94;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}
@keyframes orbit-bubble-line {
  from {
    opacity: 0;
    translate: 0 6px;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes orbit-typing {
