    width: 11rem;
    padding: 0.5rem 0.6rem;
  }
  .orbit-slot:nth-child(odd) .orbit-bubble {
    right: 0;
    left: auto;
  }
  .orbit-slot:nth-child(even) .orbit-bubble {
    right: auto;
    left: 0;
  }
  .orbit-bubble-text {
    font-size: 0.63rem;
    line-height: 1.55;
  }
  .orbit-bubble-head {
    font-size: 0.58rem;
  }
  .orbit-bubble-head b {
    display: none;
  }
  .orbit-bubble-foot {
    font-size: 0.48rem;
  }
  .orbit-commentary {
    grid-template-columns: auto minmax(0, 1fr);
    width: calc(100% - 0.5rem);
    min-height: 5.75rem;
    gap: 0.35rem 0.55rem;
    padding: 0.62rem 0.7rem;
  }
  .orbit-commentary .orbit-bubble-head {
    grid-row: 1;
  }
  .orbit-commentary .orbit-bubble-text,
  .orbit-commentary .orbit-bubble-typing {
    grid-column: 1 / -1;
  }
  .orbit-commentary .orbit-bubble-apps {
    grid-column: 2;
    grid-row: 1;
