  }
  .orbit-commentary .orbit-bubble-foot {
    grid-column: 1 / -1;
  }
  .mena-place-labels {
    display: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .orbit-bubble,
  .orbit-commentary,
  .orbit-bubble-text,
  .orbit-bubble-typing i,
  .mena-map-scan,
  .integration-team-status i {
    animation: none;
