/* ═════ هوية سهل الذهبية — Antique Champagne + دخان ضوئي ═════ */
.sahl-smoke {
  position: absolute;
  z-index: 0;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  isolation: isolate;
}
.sahl-smoke i {
  position: absolute;
  display: block;
  width: min(54rem, 84vw);
  aspect-ratio: 1.45;
  border-radius: 48% 52% 62% 38%;
  filter: blur(72px);
  opacity: 0.28;
  mix-blend-mode: multiply;
  will-change: transform;
}
.sahl-smoke i:nth-child(1) {
  inset: -18% auto auto -16%;
  background: color-mix(in oklab, var(--gold) 72%, transparent);
  animation: sahl-gold-smoke-a 20s ease-in-out infinite alternate;
}
.sahl-smoke i:nth-child(2) {
  inset: 12% -22% auto auto;
  background: color-mix(in oklab, var(--sky) 42%, transparent);
  animation: sahl-gold-smoke-b 25s ease-in-out infinite alternate;
}
.sahl-smoke i:nth-child(3) {
  inset: auto 18% -27% auto;
  background: color-mix(in oklab, var(--coral) 34%, var(--amber) 32%);
  animation: sahl-gold-smoke-c 29s ease-in-out infinite alternate;
}
@keyframes sahl-gold-smoke-a {
  0% {
    opacity: 0.08;
    transform: translate3d(-8%, -5%, 0) rotate(-5deg) scale(0.82);
  }
  35% {
    opacity: 0.46;
    transform: translate3d(8%, 5%, 0) rotate(4deg) scale(1.08);
  }
  70% {
    opacity: 0.18;
    transform: translate3d(21%, 13%, 0) rotate(10deg) scale(1.2);
  }
  100% {
    opacity: 0.38;
    transform: translate3d(12%, 2%, 0) rotate(2deg) scale(0.96);
  }
}
@keyframes sahl-gold-smoke-b {
  0% {
    opacity: 0.06;
    transform: translate3d(12%, -7%, 0) rotate(5deg) scale(0.88);
  }
  40% {
    opacity: 0.28;
    transform: translate3d(-5%, 8%, 0) rotate(-4deg) scale(1.12);
  }
  75% {
    opacity: 0.1;
    transform: translate3d(-20%, 16%, 0) rotate(-12deg) scale(0.94);
  }
  100% {
    opacity: 0.3;
    transform: translate3d(-9%, 3%, 0) rotate(3deg) scale(1.06);
  }
}
@keyframes sahl-gold-smoke-c {
  0% {
    opacity: 0.05;
    transform: translate3d(8%, 14%, 0) rotate(-3deg) scale(0.9);
  }
  34% {
    opacity: 0.32;
    transform: translate3d(-5%, -4%, 0) rotate(5deg) scale(1.13);
  }
  72% {
    opacity: 0.12;
    transform: translate3d(-16%, -18%, 0) rotate(9deg) scale(1.22);
  }
  100% {
    opacity: 0.27;
    transform: translate3d(2%, -7%, 0) rotate(-2deg) scale(0.98);
  }
}

/* مساحة الموظف: خدماته في سياق المحادثة، لا في التنقل العام. */
.employee-command-deck {
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--primary) 17%, var(--border));
  border-radius: 0.75rem;
  padding: 0.7rem;
  background:
    linear-gradient(
      125deg,
      color-mix(in oklab, var(--gold-soft) 52%, transparent),
      transparent 48%
    ),
    color-mix(in oklab, var(--card) 88%, transparent);
  box-shadow: 0 12px 32px -30px var(--gold-deep);
  backdrop-filter: blur(18px);
}
.employee-command-deck::before {
  content: "";
  position: absolute;
  inset: -6rem auto auto -5rem;
  width: 13rem;
  aspect-ratio: 1;
  border-radius: 50%;
  background: color-mix(in oklab, var(--gold) 16%, transparent);
  filter: blur(36px);
  animation: employee-deck-glow 9s ease-in-out infinite alternate;
  pointer-events: none;
}
.employee-command-deck > * {
  position: relative;
  z-index: 1;
}
.employee-command-scroll {
  cursor: grab;
  scroll-snap-type: inline proximity;
  overscroll-behavior-inline: contain;
  touch-action: pan-x;
  scroll-behavior: smooth;
}
.employee-command-scroll:active {
  cursor: grabbing;
}
.employee-command-scroll > * {
  scroll-snap-align: start;
}
@keyframes employee-deck-glow {
  to {
    opacity: 0.25;
    transform: translate3d(6rem, 2rem, 0) scale(1.2);
  }
}

/* مركز القيادة: شريط واحد ثابت، قلب هادئ للمحادثة، ومربع إدخال زجاجي. */
.chat-command-layout {
  display: block;
  min-height: calc(100dvh - 4rem);
}
.chat-stage {
  isolation: isolate;
  background:
    linear-gradient(
      to bottom,
      color-mix(in oklab, var(--gold-soft) 24%, transparent),
      transparent 17rem
    ),
    var(--background);
}
.employee-command-bar {
  position: sticky;
  z-index: 24;
  top: 4rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 4.25rem;
  margin-inline: -0.4rem;
  padding: 0.55rem 0.65rem;
  border: 1px solid color-mix(in oklab, var(--border) 82%, transparent);
  border-radius: 0 0 0.9rem 0.9rem;
  background: color-mix(in oklab, var(--background) 78%, transparent);
  box-shadow: 0 16px 38px -34px var(--foreground);
  backdrop-filter: blur(24px) saturate(1.15);
}
.employee-command-identity {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 0.55rem;
  padding-inline-end: 0.75rem;
  border-inline-end: 1px solid var(--border);
}
.employee-command-skills {
  min-width: 0;
  flex: 1;
}
.employee-command-apps {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  gap: 0.25rem;
}
.employee-command-apps > span {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 0.55rem;
  background: color-mix(in oklab, var(--card) 72%, transparent);
}
.employee-command-history {
  display: inline-flex;
  min-height: 2.25rem;
  align-items: center;
  gap: 0.4rem;
  flex: 0 0 auto;
  border: 1px solid var(--border);
  border-radius: 0.6rem;
  padding-inline: 0.75rem;
  background: color-mix(in oklab, var(--card) 72%, transparent);
  font-size: 0.72rem;
  font-weight: 800;
  transition: 180ms ease;
}
.employee-command-history:hover,
.employee-command-history.is-active {
  border-color: color-mix(in oklab, var(--primary) 45%, var(--border));
  color: var(--primary);
}
.chat-welcome {
  display: flex;
  width: min(100%, 42rem);
  min-height: 24rem;
  margin: auto;
  padding: 4rem 1rem 3rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}
.chat-welcome-portraits {
  position: relative;
  width: 6.6rem;
  height: 4.6rem;
  margin-bottom: 1.2rem;
}
.chat-welcome-avatar {
  position: absolute;
  top: 0;
  display: block;
  width: 4.5rem;
  height: 4.5rem;
  overflow: hidden;
  border: 3px solid var(--background);
  border-radius: 1.1rem;
  box-shadow: 0 14px 34px -22px var(--foreground);
}
.chat-welcome-avatar.is-user {
  inset-inline-start: 0;
  transform: rotate(3deg) translateY(0.4rem);
}
.chat-welcome-avatar.is-employee {
  z-index: 2;
  inset-inline-end: 0;
  transform: rotate(-3deg);
}
.chat-welcome-eyebrow {
  color: var(--primary);
  font-size: 0.72rem;
  font-weight: 800;
}
.chat-welcome h2 {
  margin-top: 0.35rem;
  font-family: var(--font-display);
  font-size: clamp(1.65rem, 4vw, 2.45rem);
  font-weight: 900;
}
.chat-welcome-rotating {
  min-height: 3.5rem;
  max-width: 34rem;
  margin-top: 0.65rem;
  color: var(--foreground);
  font-size: clamp(0.94rem, 2vw, 1.08rem);
  line-height: 1.9;
}
.typewriter-caret {
  display: inline-block;
  width: 1px;
  height: 1em;
  margin-inline-start: 0.2rem;
  vertical-align: -0.1em;
  background: var(--primary);
  animation: chat-caret 0.85s steps(1) infinite;
}
@keyframes chat-caret {
  50% {
    opacity: 0;
  }
}
.chat-composer-dock {
  background: linear-gradient(
    to top,
    var(--background) 18%,
    color-mix(in oklab, var(--background) 72%, transparent) 68%,
    transparent
  );
}
.chat-composer {
  background: color-mix(in oklab, var(--background) 54%, transparent);
  box-shadow: 0 18px 45px -34px var(--foreground);
  backdrop-filter: blur(16px) saturate(1.18);
}
.chat-apps-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}
.chat-app-item {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.55rem;
  border: 1px solid var(--border);
  border-radius: 0.6rem;
  padding: 0.65rem 0.75rem;
  background: var(--card);
  font-size: 0.72rem;
  font-weight: 700;
}
.chat-thread-panel {
  position: fixed;
  z-index: 51;
  inset-block: 4rem 0;
  inset-inline-end: 0;
  width: min(22rem, 92vw);
  overflow-y: auto;
  box-shadow: 0 24px 70px -28px var(--foreground);
  transform: translateX(-105%);
  transition: transform 260ms cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
}
.chat-thread-panel.is-open {
  transform: translateX(0);
  pointer-events: auto;
}
.chat-thread-backdrop {
  position: fixed;
  z-index: 50;
  inset: 0;
  background: color-mix(in oklab, var(--foreground) 18%, transparent);
  backdrop-filter: blur(3px);
}
@media (max-width: 1023px) {
  .chat-thread-panel {
    width: min(20rem, 88vw);
  }
}
@media (max-width: 640px) {
  .employee-command-bar {
    top: 4rem;
    gap: 0.45rem;
    margin-inline: -0.2rem;
    padding: 0.45rem;
  }
  .employee-command-identity {
    padding-inline-end: 0.45rem;
  }
  .employee-command-identity > span:last-child,
  .employee-command-apps {
    display: none;
  }
  .employee-command-history {
    width: 2.25rem;
    padding: 0;
    justify-content: center;
  }
  .employee-command-history span {
    display: none;
  }
  .employee-command-skills .employee-command-scroll {
    display: none;
  }
  .chat-welcome {
    min-height: 25rem;
    padding: 3rem 0.75rem 2rem;
  }
  .chat-composer-dock {
    padding-inline: 0.7rem;
  }
}
@media (prefers-reduced-motion: reduce) {
  .typewriter-caret {
    animation: none;
  }
  .chat-thread-panel {
    transition: none;
  }
}

/* الصفحة الرئيسية: أبيض وحبر كقاعدة، والذهب هو الإشارة البصرية الأساسية. */
.mono-page {
  --mono-gold: var(--gold-deep);
  --mono-soft: oklch(0.975 0.008 84);
}
.mono-page .nav-floating-control {
  border-color: color-mix(in oklab, var(--mono-gold) 28%, var(--mono-line));
}
.mono-page .nav-floating-control:hover {
  border-color: color-mix(in oklab, var(--mono-gold) 65%, transparent);
  background: color-mix(in oklab, var(--gold-soft) 64%, transparent);
}
.mono-page .nav-glass-cta-primary,
.mono-page .nav-glass-cta-aurora {
  border-color: var(--mono-gold);
  background: var(--mono-gold);
  color: var(--primary-foreground);
  box-shadow: 0 14px 32px -20px var(--mono-gold);
}
.mono-hero {
  isolation: isolate;
  overflow: hidden;
}
.mono-hero .mono-grid-field,
.mono-final .mono-grid-field {
  z-index: 1;
}
.sahl-smoke-hero {
  inset: 0 0 18%;
}
.sahl-smoke-hero i:nth-child(1) {
  opacity: 0.42;
}
.sahl-smoke-hero i:nth-child(2) {
  opacity: 0.18;
}
.sahl-smoke-hero i:nth-child(3) {
  opacity: 0.2;
}
.mono-kicker span {
  border-color: var(--mono-gold);
  background: color-mix(in oklab, var(--gold-soft) 72%, transparent);
  color: var(--mono-gold);
}
.mono-hero h1 em {
  background: linear-gradient(95deg, var(--gold-deep), var(--gold) 55%, oklch(0.79 0.11 95));
  background-clip: text;
  color: transparent;
  font-weight: 500;
}
.mono-actions a:first-child,
.mono-final a {
  border-color: var(--mono-gold);
  background: var(--mono-gold);
  color: var(--primary-foreground);
  box-shadow: 0 16px 34px -22px var(--mono-gold);
}
.mono-window-bar > span i,
.mono-real-media > span i,
.mono-scene-card figcaption i {
  background: var(--mono-gold);
}
.mono-proof strong,
.mono-section-head > span,
.mono-cell-number,
.mono-scene-card > div > span,
.mono-use-grid a > span,
.mono-plan-grid article > span {
  color: var(--mono-gold);
}
.mono-team-cell:hover,
.mono-use-grid a:hover {
  background: var(--gold-soft);
  color: var(--mono-black);
}
.mono-team-cell:hover > img {
  filter: grayscale(0.3) sepia(0.1) contrast(1.06);
}
.mono-real-media {
  border-color: color-mix(in oklab, var(--mono-gold) 58%, var(--mono-black));
}
.mono-real-media img,
.mono-real-media video,
.mono-scene-card video {
  filter: grayscale(0.72) sepia(0.08);
}
.mono-real-media > span,
.mono-scene-card figcaption {
  border-color: var(--mono-gold);
  color: var(--mono-gold);
}
.mono-real-media.is-hero {
  box-shadow:
    22px 22px 0 var(--gold-soft),
    22px 22px 0 1px color-mix(in oklab, var(--mono-gold) 34%, transparent);
}
.mono-real-media.is-tour,
.mono-real-media.is-dark {
  border-color: color-mix(in oklab, var(--gold) 58%, transparent);
}
.mono-real-media.is-tour > span,
.mono-real-media.is-dark > span {
  border-color: color-mix(in oklab, var(--gold) 62%, transparent);
  background: oklch(0.14 0.018 72 / 0.92);
  color: var(--gold);
}
.mono-composer {
  border-color: var(--mono-gold);
  background: linear-gradient(
    120deg,
    oklch(1 0 0 / 0.94),
    color-mix(in oklab, var(--gold-soft) 48%, transparent)
  );
  box-shadow: 0 18px 42px -34px var(--mono-gold);
}
.mono-composer label {
  color: var(--mono-gold);
}
.mono-composer button,
.mono-approval-row button:last-child {
  background: var(--mono-gold);
  color: var(--primary-foreground);
}
.mono-plan-grid article.is-highlight {
  border-color: var(--mono-gold);
  background: linear-gradient(155deg, oklch(0.16 0.015 72), oklch(0.25 0.055 74));
  color: oklch(1 0 0);
  box-shadow: 0 30px 65px -42px var(--mono-gold);
}
.mono-final {
  isolation: isolate;
  background: linear-gradient(180deg, oklch(1 0 0), var(--gold-soft));
}
.sahl-smoke-final i {
  opacity: 0.2;
}
.sahl-smoke-page i,
.sahl-smoke-auth i {
  opacity: 0.45;
  mix-blend-mode: screen;
}
.sahl-smoke-page + div,
.sahl-smoke-auth + div {
  z-index: 0;
}

/* مساحة العمل: الدخان خلف المحتوى فقط، والذهبي للحالة النشطة والتركيز. */
.app-shell {
  position: relative;
  isolation: isolate;
  /* لا overflow: clip — يمنع ثبات الشريط العلوي (sticky) أثناء التقليب على الهواتف. */
}
.app-shell > div > header.app-topbar {
  position: sticky;
  top: 0;
  z-index: 40;
}
.app-shell > aside {
  position: sticky;
  z-index: 10;
}
.sahl-smoke-app {
  position: fixed;
  inset: 0 0 auto 0;
  height: 28rem;
  opacity: 0.48;
  mask-image: linear-gradient(to bottom, black, transparent);
}
.sahl-smoke-app i {
  opacity: 0.12;
  filter: blur(94px);
}
.app-shell > div > header {
  border-bottom-color: color-mix(in oklab, var(--gold-deep) 18%, var(--border));
  box-shadow: 0 12px 34px -34px var(--gold-deep);
}

/* المحادثة: هالة Gemini-like حول المساحة ومربع الإدخال مع نص واضح دائماً. */
.chat-stage::before,
.chat-stage::after {
  content: "";
  position: absolute;
  z-index: 0;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(82px);
  mix-blend-mode: multiply;
}
.chat-stage::before {
  top: -8rem;
  right: -8rem;
  width: 28rem;
  height: 22rem;
  background: color-mix(in oklab, var(--gold) 20%, transparent);
  animation: sahl-chat-aura 17s ease-in-out infinite alternate;
}
.chat-stage::after {
  bottom: 4rem;
  left: -9rem;
  width: 25rem;
  height: 19rem;
  background: color-mix(in oklab, var(--sky) 12%, transparent);
  animation: sahl-chat-aura 21s ease-in-out infinite alternate-reverse;
}
@keyframes sahl-chat-aura {
  to {
    transform: translate3d(10%, 8%, 0) scale(1.12);
  }
}
.chat-stage > * {
  position: relative;
  z-index: 1;
}
.chat-composer {
  position: relative;
  isolation: isolate;
  border-color: color-mix(in oklab, var(--gold-deep) 48%, var(--border));
  background: color-mix(in oklab, var(--card) 88%, transparent);
  box-shadow:
    0 22px 60px -38px var(--gold-deep),
    inset 0 1px 0 oklch(1 0 0 / 0.92);
}
.chat-composer::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -0.45rem;
  border-radius: inherit;
  background: linear-gradient(
    105deg,
    color-mix(in oklab, var(--gold) 28%, transparent),
    color-mix(in oklab, var(--coral) 12%, transparent),
    color-mix(in oklab, var(--sky) 16%, transparent),
    color-mix(in oklab, var(--gold) 28%, transparent)
  );
  background-size: 260% 100%;
  filter: blur(15px);
  opacity: 0.7;
  animation: sahl-composer-smoke 9s ease-in-out infinite alternate;
}
@keyframes sahl-composer-smoke {
  to {
    background-position: 100% 0;
    transform: scale(1.012);
  }
}
.chat-composer button[type="submit"] {
  background: var(--primary);
  color: var(--primary-foreground);
  box-shadow: 0 10px 24px -14px var(--gold-deep);
}
.bubble-user {
  background-image: linear-gradient(145deg, oklch(0.19 0.012 70), oklch(0.28 0.055 75));
}

@media (max-width: 700px) {
  .sahl-smoke i {
    width: 34rem;
    filter: blur(64px);
    opacity: 0.2;
  }
  .sahl-smoke-hero {
    bottom: 35%;
  }
  .sahl-smoke-app {
    height: 20rem;
    opacity: 0.45;
  }
  .chat-stage::before,
  .chat-stage::after {
    filter: blur(68px);
    opacity: 0.72;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sahl-smoke i,
  .chat-stage::before,
  .chat-stage::after,
  .chat-composer::before {
    animation: none !important;
  }
}

/* ═════ مركز محادثة الموظف — دخان ذهبي متحرك + مربع إدخال شفاف ═════
   يعتمد على متغيّرين يضبطهما كل موظف: --chat-accent و --chat-accent-soft. */
.chat-stage {
  --chat-accent: var(--gold);
  --chat-accent-soft: color-mix(in oklab, var(--gold) 16%, transparent);
  position: relative;
  isolation: isolate;
  background: var(--background);
}

/* الدخان الذهبي: يروح وييجي ويخلّف آثار مروره. */
.chat-smoke {
  position: absolute;
  z-index: 0;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  contain: paint;
}
.chat-smoke i {
  position: absolute;
  display: block;
  width: min(46rem, 78vw);
  aspect-ratio: 1.35;
  border-radius: 48% 52% 60% 40%;
  filter: blur(64px);
  opacity: 0.32;
  will-change: transform, opacity;
}
.chat-smoke i:nth-child(1) {
  inset: -14% auto auto -12%;
  background: color-mix(in oklab, var(--chat-accent) 46%, var(--gold) 54%);
  animation: chat-smoke-a 26s ease-in-out infinite alternate;
}
.chat-smoke i:nth-child(2) {
  inset: 8% -18% auto auto;
  background: color-mix(in oklab, var(--gold) 62%, var(--chat-accent) 38%);
  animation: chat-smoke-b 33s ease-in-out infinite alternate;
}
.chat-smoke i:nth-child(3) {
  inset: auto 14% -22% auto;
  background: color-mix(in oklab, var(--chat-accent) 40%, var(--amber, var(--gold)) 60%);
  animation: chat-smoke-c 39s ease-in-out infinite alternate;
}
/* آثار المرور: خطوط ضوئية باهتة تبقى بعد تحرّك الدخان. */
.chat-smoke b {
  position: absolute;
  inset-inline: -10%;
  height: 22rem;
  display: block;
  border-radius: 50%;
  background: radial-gradient(
    60% 100% at 50% 50%,
    color-mix(in oklab, var(--chat-accent) 13%, transparent),
    transparent 72%
  );
  filter: blur(38px);
  opacity: 0;
  will-change: transform, opacity;
}
.chat-smoke b:nth-of-type(1) {
  top: 6%;
  animation: chat-smoke-trail 18s ease-in-out infinite;
}
.chat-smoke b:nth-of-type(2) {
  top: 42%;
  animation: chat-smoke-trail 23s ease-in-out infinite 4s;
}
.chat-smoke b:nth-of-type(3) {
  bottom: 4%;
  animation: chat-smoke-trail 29s ease-in-out infinite 9s;
}
@keyframes chat-smoke-a {
  0% {
    opacity: 0.1;
    transform: translate3d(-7%, -4%, 0) rotate(-4deg) scale(0.86);
  }
  40% {
    opacity: 0.4;
    transform: translate3d(9%, 6%, 0) rotate(4deg) scale(1.1);
  }
  75% {
    opacity: 0.16;
    transform: translate3d(20%, 12%, 0) rotate(9deg) scale(1.18);
  }
  100% {
    opacity: 0.45;
    transform: translate3d(11%, 1%, 0) rotate(2deg) scale(0.96);
  }
}
@keyframes chat-smoke-b {
  0% {
    opacity: 0.08;
    transform: translate3d(10%, -6%, 0) rotate(4deg) scale(0.9);
  }
  45% {
    opacity: 0.3;
    transform: translate3d(-6%, 9%, 0) rotate(-5deg) scale(1.14);
  }
  80% {
    opacity: 0.12;
    transform: translate3d(-19%, 15%, 0) rotate(-11deg) scale(0.95);
  }
  100% {
    opacity: 0.28;
    transform: translate3d(-8%, 3%, 0) rotate(3deg) scale(1.06);
  }
}
@keyframes chat-smoke-c {
  0% {
    opacity: 0.07;
    transform: translate3d(7%, 13%, 0) rotate(-3deg) scale(0.9);
  }
  38% {
    opacity: 0.3;
    transform: translate3d(-5%, -5%, 0) rotate(5deg) scale(1.12);
  }
  74% {
    opacity: 0.12;
    transform: translate3d(-15%, -17%, 0) rotate(8deg) scale(1.2);
  }
  100% {
    opacity: 0.26;
    transform: translate3d(2%, -6%, 0) rotate(-2deg) scale(0.98);
  }
}
@keyframes chat-smoke-trail {
  0% {
    opacity: 0;
    transform: translate3d(-24%, 0, 0) scaleY(0.7);
  }
  18% {
    opacity: 0.9;
  }
  50% {
    opacity: 0.55;
    transform: translate3d(6%, 0, 0) scaleY(1.05);
  }
  82% {
    opacity: 0.2;
  }
  100% {
    opacity: 0;
    transform: translate3d(26%, 0, 0) scaleY(0.8);
  }
}

/* الشريط الثابت: صف واحد نظيف — الهوية · المحادثة الحالية · القدرات · التطبيقات. */
.employee-command-bar {
  position: sticky;
  z-index: 26;
  top: 4rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-height: 3.9rem;
  margin-inline: -0.4rem;
  padding: 0.5rem 0.7rem;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 18%, var(--border));
  border-top-color: transparent;
  border-radius: 0 0 1.1rem 1.1rem;
  background: color-mix(in oklab, var(--background) 62%, transparent);
  box-shadow:
    0 1px 0 0 color-mix(in oklab, var(--chat-accent) 22%, transparent) inset,
    0 22px 44px -40px var(--foreground);
  backdrop-filter: blur(26px) saturate(1.2);
}
.employee-command-bar::after {
  content: "";
  position: absolute;
  inset-inline: 12%;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--chat-accent) 55%, transparent),
    transparent
  );
  pointer-events: none;
}
.employee-command-identity {
  border-inline-end-color: color-mix(in oklab, var(--chat-accent) 20%, var(--border));
}
.employee-command-identity .chat-live-dot {
  background: var(--chat-accent);
  box-shadow: 0 0 0 0 color-mix(in oklab, var(--chat-accent) 60%, transparent);
  animation: chat-live-pulse 2.4s ease-out infinite;
}
@keyframes chat-live-pulse {
  70% {
    box-shadow: 0 0 0 0.32rem color-mix(in oklab, var(--chat-accent) 0%, transparent);
  }
  100% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--chat-accent) 0%, transparent);
  }
}

/* منتقي المحادثات داخل الشريط نفسه. */
.chat-thread-picker {
  position: relative;
  flex: 0 0 auto;
}
.chat-thread-trigger {
  display: inline-flex;
  max-width: 13rem;
  min-height: 2.3rem;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid var(--border);
  border-radius: 0.7rem;
  padding-inline: 0.7rem;
  background: color-mix(in oklab, var(--card) 55%, transparent);
  font-size: 0.72rem;
  font-weight: 800;
  transition: 180ms ease;
}
.chat-thread-trigger:hover,
.chat-thread-trigger[aria-expanded="true"] {
  border-color: color-mix(in oklab, var(--chat-accent) 48%, var(--border));
  color: color-mix(in oklab, var(--chat-accent) 72%, var(--foreground));
}
.chat-thread-trigger span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chat-thread-menu {
  position: absolute;
  z-index: 40;
  top: calc(100% + 0.5rem);
  inset-inline-start: 0;
  width: min(20rem, 82vw);
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 16%, var(--border));
  border-radius: 0.9rem;
  background: color-mix(in oklab, var(--card) 92%, transparent);
  box-shadow: 0 28px 60px -34px var(--foreground);
  backdrop-filter: blur(22px);
  animation: chat-menu-in 180ms cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes chat-menu-in {
  from {
    opacity: 0;
    transform: translateY(-0.35rem);
  }
}
.chat-thread-menu-list {
  max-height: 46dvh;
  overflow-y: auto;
  padding: 0.4rem;
}
.chat-thread-row {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  border: 1px solid transparent;
  border-radius: 0.6rem;
  padding: 0.15rem 0.3rem;
}
.chat-thread-row:hover {
  background: color-mix(in oklab, var(--chat-accent) 8%, transparent);
}
.chat-thread-row.is-active {
  border-color: color-mix(in oklab, var(--chat-accent) 40%, transparent);
  background: color-mix(in oklab, var(--chat-accent) 12%, transparent);
}

/* لوحة الترحيب قبل الإرسال. */
.chat-welcome-avatar {
  border-color: color-mix(in oklab, var(--background) 88%, var(--chat-accent));
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--chat-accent) 28%, transparent),
    0 18px 40px -24px var(--foreground);
  animation: chat-welcome-float 7s ease-in-out infinite alternate;
}
.chat-welcome-avatar.is-employee {
  animation-delay: -3.2s;
}
@keyframes chat-welcome-float {
  to {
    transform: translateY(-0.4rem) rotate(0deg);
  }
}
.chat-welcome-eyebrow {
  align-self: center;
  color: color-mix(in oklab, var(--chat-accent) 72%, var(--foreground));
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.01em;
  text-align: center;
}
.chat-welcome h2 {
  margin-top: 0.8rem;
}
.typewriter-caret {
  background: var(--chat-accent, var(--primary));
}

/* مربع الإدخال: شفاف من كل الاتجاهات، والكلام حوله يبقى مقروءاً. */
.chat-composer-dock {
  position: fixed;
  inset-inline: 0;
  bottom: 0;
  z-index: 40;
  background: transparent;
}
.chat-message-column {
  padding-bottom: 9rem;
}
@media (min-width: 1024px) {
  .chat-composer-dock {
    inset-inline-start: 16rem;
  }
}
.chat-composer {
  position: relative;
  border-color: color-mix(in oklab, var(--chat-accent) 26%, var(--border));
  background: color-mix(in oklab, var(--background) 26%, transparent);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--background) 30%, transparent) inset,
    0 26px 60px -46px var(--foreground);
  backdrop-filter: blur(9px) saturate(1.1);
  transition: 220ms ease;
}
.chat-composer::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -0.7rem;
  border-radius: 1.6rem;
  background: radial-gradient(
    70% 120% at 50% 100%,
    color-mix(in oklab, var(--chat-accent) 12%, transparent),
    transparent 70%
  );
  opacity: 0.85;
  pointer-events: none;
  animation: chat-composer-halo 9s ease-in-out infinite alternate;
}
@keyframes chat-composer-halo {
  to {
    opacity: 0.35;
    transform: translateY(-0.25rem) scale(1.03);
  }
}
.chat-composer:focus-within {
  border-color: color-mix(in oklab, var(--chat-accent) 55%, var(--border));
  background: color-mix(in oklab, var(--background) 42%, transparent);
  box-shadow:
    0 0 0 4px color-mix(in oklab, var(--chat-accent) 12%, transparent),
    0 30px 70px -46px var(--foreground);
}
.chat-composer textarea::placeholder {
  color: color-mix(in oklab, var(--muted-foreground) 88%, var(--chat-accent));
  opacity: 1;
}

@media (max-width: 640px) {
  .chat-thread-trigger {
    max-width: 7.5rem;
  }
  .chat-smoke i {
    filter: blur(48px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .chat-smoke i,
  .chat-smoke b,
  .chat-welcome-avatar,
  .chat-composer::before,
  .employee-command-identity .chat-live-dot {
    animation: none !important;
  }
  .chat-smoke b {
    opacity: 0.25;
  }
}

/* شريط الموظف الموحد: كل الأدوات في سطر واحد واضح وقابل للسحب على الشاشات الضيقة. */
.employee-command-bar {
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scrollbar-width: none;
}
.employee-command-bar::-webkit-scrollbar {
  display: none;
}
.employee-command-link {
  display: inline-flex;
  min-height: 2.3rem;
  flex: 0 0 auto;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 14%, var(--border));
  border-radius: 0.7rem;
  padding-inline: 0.7rem;
  background: color-mix(in oklab, var(--card) 48%, transparent);
  color: var(--ink-soft);
  font-size: 0.7rem;
  font-weight: 800;
  white-space: nowrap;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}
.employee-command-link:hover {
  border-color: color-mix(in oklab, var(--chat-accent) 45%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 9%, transparent);
  color: var(--foreground);
  transform: translateY(-1px);
}

/* لوحة محادثات الموظف: هوية، حسابات، سجل، تنفيذ، ومراجع في تسلسل بصري واحد. */
.chat-thread-panel {
  padding: 0.9rem;
  border-color: color-mix(in oklab, var(--chat-accent) 18%, var(--border));
  background:
    linear-gradient(
      150deg,
      color-mix(in oklab, var(--chat-accent) 8%, transparent),
      transparent 16rem
    ),
    color-mix(in oklab, var(--card) 88%, transparent);
  backdrop-filter: blur(28px) saturate(1.18);
}
.chat-side-employee {
  position: sticky;
  z-index: 2;
  top: -0.9rem;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  margin: -0.9rem -0.9rem 0.8rem;
  padding: 1rem 0.9rem 0.85rem;
  border-bottom: 1px solid color-mix(in oklab, var(--chat-accent) 18%, var(--border));
  background: color-mix(in oklab, var(--card) 82%, transparent);
  backdrop-filter: blur(22px);
}
.chat-side-employee > button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 0.6rem;
  color: var(--muted-foreground);
  transition: 180ms ease;
}
.chat-side-employee > button:hover {
  background: var(--secondary);
  color: var(--foreground);
}
.chat-side-section {
  margin-bottom: 0.75rem;
  padding: 0.8rem;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 12%, var(--border));
  border-radius: 0.75rem;
  background: color-mix(in oklab, var(--background) 52%, transparent);
}
.chat-side-tabs {
  position: sticky;
  z-index: 2;
  top: 5.05rem;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.25rem;
  margin: 0 -0.2rem;
  padding: 0.6rem 0.2rem;
  background: color-mix(in oklab, var(--background) 82%, transparent);
  backdrop-filter: blur(22px);
}
.chat-side-tabs button {
  min-height: 2.2rem;
  border-radius: 999px;
  color: var(--muted-foreground);
  font-size: 0.68rem;
  font-weight: 800;
  transition: 180ms ease;
}
.chat-side-tabs button:hover,
.chat-side-tabs button.is-active {
  background: color-mix(in oklab, var(--chat-accent) 9%, transparent);
  color: var(--foreground);
}
.chat-side-label {
  color: var(--muted-foreground);
  font-size: 0.67rem;
  font-weight: 800;
}
.chat-side-thread {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  border: 1px solid transparent;
  border-radius: 0.6rem;
  padding: 0.25rem 0.35rem;
  transition: 180ms ease;
}
.chat-side-thread:hover {
  background: color-mix(in oklab, var(--chat-accent) 7%, transparent);
}
.chat-side-links {
  display: grid;
  gap: 0.45rem;
}
.chat-side-links > a,
.chat-side-links > button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.7rem;
  min-height: 3.5rem;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 14%, var(--border));
  border-radius: 0.7rem;
  padding: 0.65rem 0.75rem;
  background: color-mix(in oklab, var(--background) 48%, transparent);
  font-size: 0.75rem;
  font-weight: 800;
  transition: 180ms ease;
}
.chat-side-links > a:hover,
.chat-side-links > button:hover {
  border-color: color-mix(in oklab, var(--chat-accent) 42%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 8%, transparent);
}
.chat-side-links small {
  display: block;
  margin-top: 0.1rem;
  color: var(--muted-foreground);
  font-size: 0.62rem;
  font-weight: 600;
}

/* قائمتا الوسائط والطول تطفوان أعلى مربع الكتابة بزجاج شفاف. */
.chat-tool-launcher {
  display: flex;
  gap: 0.45rem;
  padding: 0.3rem 0.35rem 0.45rem;
  border-top: 1px solid color-mix(in oklab, var(--chat-accent) 14%, var(--border));
}
.chat-tool-choice {
  display: inline-flex;
  min-height: 2.15rem;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid var(--border);
  border-radius: 0.65rem;
  padding-inline: 0.75rem;
  background: color-mix(in oklab, var(--background) 42%, transparent);
  color: var(--ink-soft);
  font-size: 0.7rem;
  font-weight: 800;
  transition: 180ms ease;
}
.chat-tool-choice > span {
  display: grid;
  min-width: 1.1rem;
  height: 1.1rem;
  place-items: center;
  border-radius: 999px;
  background: var(--foreground);
  color: var(--background);
  font-size: 0.58rem;
}
.chat-tool-choice:hover,
.chat-tool-choice.is-active {
  border-color: color-mix(in oklab, var(--chat-accent) 52%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 10%, transparent);
  color: var(--foreground);
}
.chat-tool-popover {
  position: absolute;
  z-index: 35;
  inset-inline: 0;
  bottom: calc(100% + 0.65rem);
  max-height: min(65dvh, 36rem);
  overflow-y: auto;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 24%, var(--border));
  border-radius: 0.9rem;
  padding: 0.75rem;
  background:
    linear-gradient(
      145deg,
      color-mix(in oklab, var(--chat-accent) 8%, transparent),
      transparent 50%
    ),
    color-mix(in oklab, var(--background) 76%, transparent);
  box-shadow: 0 28px 70px -40px var(--foreground);
  backdrop-filter: blur(26px) saturate(1.18);
}
.chat-tool-popover-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 1rem;
  margin-bottom: 0.65rem;
  padding: 0.1rem 0.15rem 0.65rem;
  border-bottom: 1px solid var(--border);
}
.chat-tool-popover-head p {
  font-size: 0.78rem;
  font-weight: 900;
}
.chat-tool-popover-head span {
  color: var(--muted-foreground);
  font-size: 0.65rem;
}
.chat-tool-popover-head button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 0.6rem;
  color: var(--muted-foreground);
}
.chat-tool-popover-head button:hover {
  background: var(--secondary);
  color: var(--foreground);
}
.chat-length-options {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
}
.chat-length-option {
  position: relative;
  display: flex;
  min-height: 4.4rem;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: 0.7rem;
  padding: 0.65rem;
  background: color-mix(in oklab, var(--card) 55%, transparent);
  text-align: start;
  transition: 180ms ease;
}
.chat-length-option > span {
  font-size: 0.76rem;
  font-weight: 900;
}
.chat-length-option small {
  color: var(--muted-foreground);
  font-size: 0.62rem;
}
.chat-length-option svg {
  position: absolute;
  top: 0.55rem;
  inset-inline-end: 0.55rem;
  color: var(--chat-accent);
}
.chat-length-option:hover,
.chat-length-option.is-active {
  border-color: color-mix(in oklab, var(--chat-accent) 55%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 10%, transparent);
}

@media (max-width: 640px) {
  .employee-command-bar {
    margin-inline: -0.75rem;
    border-inline: 0;
    border-radius: 0;
  }
  .employee-command-identity {
    position: sticky;
    z-index: 2;
    inset-inline-start: 0;
    min-width: 6.25rem;
    padding-inline: 0.35rem 0.55rem;
    background: color-mix(in oklab, var(--background) 88%, transparent);
    backdrop-filter: blur(18px);
  }
  .employee-command-identity > span:last-child {
    display: block;
  }
  .employee-command-skills {
    min-width: max-content;
    flex: 0 0 auto;
  }
  .employee-command-link span {
    display: inline;
  }
  .chat-length-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .chat-tool-popover {
    inset-inline: -0.15rem;
    max-height: 58dvh;
    padding: 0.6rem;
  }
}

