    0 22px 44px -16px color-mix(in oklab, var(--home-ink) 48%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--home-bg) 86%, transparent);
  backdrop-filter: blur(24px) saturate(155%);
}
.sahl-hero-product > .sahl-float-note b,
.sahl-hero-product > .sahl-float-note small {
  display: block;
  white-space: nowrap;
}
.sahl-hero-product > .sahl-float-note b {
  color: var(--home-ink);
