}
.sahl-hero-product > .sahl-float-note small {
  margin-top: 2px;
  color: var(--home-copy);
  font-size: 0.62rem;
  line-height: 1.45;
}

/* Desktop chat uses the available workspace while keeping long text readable. */
.is-chat-shell {
  height: 100dvh;
  min-height: 0;
  overflow: hidden;
}
.is-chat-shell > .relative.z-10,
.is-chat-shell main,
.is-chat-shell .chat-command-layout,
.is-chat-shell .chat-stage {
  min-height: 0;
}
.is-chat-shell > .relative.z-10 {
  height: 100dvh;
  overflow: hidden;
}
.is-chat-shell main {
  flex: 1 1 auto;
  overflow: hidden;
}
.is-chat-shell .chat-command-layout,
.is-chat-shell .chat-stage {
  width: 100%;
  height: 100%;
}
.is-chat-shell .chat-stage {
  overflow: hidden;
}
.is-chat-shell .chat-message-column {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

@media (min-width: 1024px) {
  .is-chat-shell .app-topbar-inner > div:first-of-type {
    flex: 0 0 clamp(8rem, 11vw, 11rem);
  }
  .is-chat-shell .app-topbar-controls {
    flex: 1 1 auto;
    overflow: hidden;
  }
  .is-chat-shell .chat-topbar-actions {
    justify-content: flex-start;
    padding-block: 0.2rem;
  }
  .is-chat-shell .chat-message-column,
  .is-chat-shell .chat-composer {
    width: min(calc(100% - 2rem), 88rem);
  }
}

@media (min-width: 1600px) {
  .is-chat-shell .chat-message-column,
  .is-chat-shell .chat-composer {
    width: min(calc(100% - 3rem), 94rem);
  }
  .is-chat-shell .chat-message-column {
    padding-inline: 2.5rem;
  }
}

@media (max-width: 720px) {
  .sahl-hero-product > .sahl-float-note {
    position: relative;
    inset: auto;
    width: min(100%, 216px);
    min-height: 58px;
    margin: 12px auto 0;
    padding: 9px 10px;
    grid-template-columns: 32px minmax(0, 1fr);
  }
  .sahl-hero-product > .sahl-float-note b {
    font-size: 0.72rem;
  }
  .sahl-hero-product > .sahl-float-note small {
    font-size: 0.56rem;
  }
