  place-items: center;
  border: 1px solid var(--gold);
  border-radius: 50%;
  color: var(--gold);
}
.stripe-brain-map span {
  position: absolute;
  padding: 7px 12px;
  border: 1px solid color-mix(in oklab, var(--background) 30%, transparent);
  border-radius: 4px;
  color: var(--background);
  font-size: 0.7rem;
}
.stripe-brain-map span::after {
  content: "";
  position: absolute;
  width: 100px;
  height: 1px;
  background: color-mix(in oklab, var(--gold) 45%, transparent);
  transform-origin: right;
}
.stripe-brain-map span:nth-child(2) {
  top: 5%;
  right: 8%;
}
.stripe-brain-map span:nth-child(3) {
  top: 12%;
  left: 8%;
}
.stripe-brain-map span:nth-child(4) {
  bottom: 10%;
  right: 4%;
}
.stripe-brain-map span:nth-child(5) {
  bottom: 5%;
  left: 10%;
}

.stripe-scale {
  position: relative;
  overflow: hidden;
  padding-top: 105px;
  background: color-mix(in oklab, var(--accent) 64%, var(--background));
  border-block: 1px solid var(--border);
}
.stripe-scale header {
  max-width: 590px;
  text-align: center;
  margin: 0 auto 65px;
}
.stripe-scale header span {
  color: var(--gold-deep);
  font-size: 0.78rem;
  font-weight: 800;
}
.stripe-scale h2 {
  margin-top: 12px !important;
  font-size: clamp(2.7rem, 5vw, 5rem);
  line-height: 1;
  font-weight: 560;
}
.stripe-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-block: 1px solid var(--border);
}
.stripe-metrics article {
  min-height: 130px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-left: 1px solid var(--border);
}
.stripe-metrics article:last-child {
  border-left: 0;
}
.stripe-metrics strong {
  font-size: 2.2rem;
  line-height: 1;
}
.stripe-metrics span {
  margin-top: 9px;
  color: var(--muted-foreground);
  font-size: 0.72rem;
}
.stripe-scale-art {
  height: 445px;
  position: relative;
  overflow: hidden;
}
.stripe-scale-core {
  position: absolute;
  z-index: 2;
  left: 50%;
  bottom: -55px;
  width: 150px;
  height: 150px;
  transform: translateX(-50%);
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--foreground);
  color: var(--background);
  box-shadow: 0 0 0 30px color-mix(in oklab, var(--gold) 18%, transparent);
}
.stripe-scale-art > i {
  --angle: calc(var(--ray) * 4deg - 88deg);
  position: absolute;
  width: 2px;
  height: calc(185px + (var(--ray) * 4px));
  bottom: 15px;
  left: 50%;
  transform-origin: bottom;
  transform: rotate(var(--angle));
  background: linear-gradient(
    to top,
    var(--gold-deep),
    color-mix(in oklab, var(--gold) 15%, transparent)
  );
}
.stripe-scale-art > i b {
  position: absolute;
  top: 0;
  left: -3px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold-deep);
  animation: stripe-node-pulse 2.5s ease-in-out infinite alternate;
  animation-delay: calc(var(--ray) * -60ms);
}

.stripe-platform {
  padding: 130px 0;
  background: var(--foreground);
  color: var(--background);
}
.stripe-platform .stripe-sahl-shell {
  display: grid;
  grid-template-columns: 0.72fr 1.28fr;
  gap: 70px;
}
.stripe-platform-copy > p {
  color: color-mix(in oklab, var(--background) 64%, transparent);
}
.stripe-platform .stripe-sahl-actions a:first-child {
  background: var(--gold);
  color: var(--foreground);
}
.stripe-platform .stripe-sahl-actions a:last-child {
  color: var(--background);
