  grid-template-columns: repeat(3, 1fr);
  margin-top: 30px;
  border-top: 1px solid color-mix(in oklab, var(--background) 17%, transparent);
}
.stripe-platform-features article {
  padding: 35px 26px 0;
  border-left: 1px solid color-mix(in oklab, var(--background) 17%, transparent);
}
.stripe-platform-features article:last-child {
  border-left: 0;
}
.stripe-platform-features svg {
  width: 24px;
  color: var(--gold);
  margin-bottom: 26px;
}
.stripe-platform-features b {
  display: block;
  font-size: 0.92rem;
}
.stripe-platform-features p {
  margin-top: 8px !important;
  color: color-mix(in oklab, var(--background) 58%, transparent);
  font-size: 0.78rem;
  line-height: 1.65;
}

.stripe-live-product {
