  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border: 1px solid var(--gold);
  background: var(--accent);
  border-radius: 5px;
}
.stripe-success svg {
  width: 20px;
  color: var(--gold-deep);
}
.stripe-success span {
  display: grid;
}
.stripe-success small {
  color: var(--muted-foreground);
}
.stripe-composer {
  position: relative;
  margin-top: auto;
