  border: 0;
  outline: 0;
  background: transparent;
  line-height: 1.6;
}
.stripe-composer button {
  position: absolute;
  left: 12px;
  bottom: 13px;
  border-radius: 5px;
}
.stripe-demo-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.stripe-sector-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-bottom: 1px solid var(--border);
}
.stripe-sector-tabs button {
