}
.stripe-sector-panel > div {
  padding: 55px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
.stripe-sector-panel > div > span {
  color: var(--gold-deep);
  font-size: 0.74rem;
  font-weight: 800;
}
.stripe-sector-panel h3 {
  margin-top: 14px !important;
  font-size: 2.4rem;
  line-height: 1.18;
}
.stripe-sector-panel p {
  margin-top: 18px !important;
  color: var(--muted-foreground);
  line-height: 1.7;
}
.stripe-sector-panel strong {
  margin-top: auto;
  font-size: 2.8rem;
}
.stripe-sector-panel small {
  color: var(--muted-foreground);
}
.stripe-sector-panel a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 24px;
  color: var(--gold-deep);
  font-size: 0.8rem;
  font-weight: 800;
}
.stripe-sector-panel a svg {
  width: 15px;
}
.stripe-sector-panel figure {
