  align-items: flex-end;
  padding: 45px 0 0 45px;
}
.stripe-sector-panel img {
  width: 110%;
  max-width: none;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-card);
}

.stripe-real-scenes {
  border-top: 1px solid var(--border);
}
.stripe-scenes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--border);
  border-right: 1px solid var(--border);
}
.stripe-scenes-grid > a {
  min-width: 0;
  padding: 28px;
  color: var(--foreground);
  border-left: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.stripe-scenes-grid .stripe-product-frame {
  transition: transform 0.35s var(--ease-enter);
}
.stripe-scenes-grid > a:hover .stripe-product-frame {
  transform: translateY(-6px);
}
.stripe-scenes-grid h3 {
  margin-top: 24px !important;
  font-size: 1.25rem;
}
.stripe-scenes-grid p {
  margin-top: 8px !important;
  color: var(--muted-foreground);
  font-size: 0.82rem;
}

.stripe-stories {
  padding: 120px 0;
  background: var(--foreground);
  color: var(--background);
}
.stripe-stories .stripe-sahl-shell {
  display: grid;
  grid-template-columns: 0.7fr 1.3fr;
  gap: 70px;
}
.stripe-stories blockquote {
  margin: 0;
  padding: 45px;
  border-right: 1px solid color-mix(in oklab, var(--background) 20%, transparent);
}
.stripe-stories blockquote > svg {
  color: var(--gold);
}
.stripe-stories blockquote p {
  margin-top: 25px !important;
  font-size: clamp(1.55rem, 3vw, 2.7rem);
  line-height: 1.35;
}
.stripe-stories blockquote footer {
  margin-top: 32px;
  display: grid;
}
.stripe-stories blockquote footer span {
  color: color-mix(in oklab, var(--background) 55%, transparent);
  font-size: 0.75rem;
}
.stripe-story-stats {
  grid-column: 1/-1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid color-mix(in oklab, var(--background) 20%, transparent);
}
.stripe-story-stats > span {
  display: grid;
  padding: 32px;
  border-left: 1px solid color-mix(in oklab, var(--background) 20%, transparent);
}
.stripe-story-stats > span:last-child {
  border-left: 0;
}
.stripe-story-stats svg {
  width: 22px;
  color: var(--gold);
  margin-bottom: 18px;
}
.stripe-story-stats b {
  font-size: 2rem;
}
.stripe-story-stats small {
  color: color-mix(in oklab, var(--background) 56%, transparent);
}

.stripe-pricing {
  background: var(--muted);
}
.stripe-plan-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  align-items: stretch;
}
.stripe-plan-grid article {
  position: relative;
  padding: 34px;
  border: 1px solid var(--border);
  background: var(--card);
  border-radius: 7px;
}
.stripe-plan-grid article.is-featured {
  border-top: 4px solid var(--gold-deep);
}
.stripe-plan-tag {
  position: absolute;
  top: 14px;
  left: 14px;
  color: var(--gold-deep);
  font-size: 0.64rem;
  font-weight: 800;
}
.stripe-plan-grid article > small {
  color: var(--gold-deep);
}
.stripe-plan-grid h3 {
  margin-top: 8px !important;
  font-size: 1.45rem;
}
.stripe-plan-grid article > div {
  margin-top: 24px;
  display: flex;
  align-items: baseline;
  gap: 7px;
}
.stripe-plan-grid article > div strong {
  font-size: 2.6rem;
}
.stripe-plan-grid article > div .is-text {
  font-size: 1.7rem;
}
.stripe-plan-grid article > div span {
  color: var(--muted-foreground);
  font-size: 0.72rem;
}
.stripe-plan-grid article > p {
  margin-top: 16px !important;
  color: var(--muted-foreground);
  min-height: 54px;
  font-size: 0.82rem;
}
.stripe-plan-grid ul {
  margin: 24px 0;
  display: grid;
  gap: 10px;
}
.stripe-plan-grid li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 0.77rem;
}
.stripe-plan-grid li svg {
  width: 15px;
  color: var(--gold-deep);
  margin-top: 3px;
}
.stripe-plan-grid article > a {
  min-height: 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 14px;
  border: 1px solid var(--border);
  color: var(--foreground);
  font-size: 0.8rem;
  font-weight: 800;
  border-radius: 5px;
}
.stripe-plan-grid .is-featured > a {
  background: var(--foreground);
  color: var(--background);
}

.stripe-resources {
  padding: 120px 0;
  border-bottom: 1px solid var(--border);
}
.stripe-resources .stripe-sahl-shell {
  display: grid;
  grid-template-columns: 0.64fr 1.36fr;
  gap: 70px;
}
.stripe-resources .stripe-sahl-shell > div {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--border);
  border-right: 1px solid var(--border);
}
.stripe-resources .stripe-sahl-shell > div a {
  min-height: 330px;
  padding: 28px;
  display: flex;
  flex-direction: column;
  color: var(--foreground);
  border-left: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.stripe-resources a > span {
  color: var(--gold-deep);
  font-size: 0.68rem;
  font-weight: 800;
}
.stripe-resources a > svg {
  width: 30px;
  height: 30px;
  margin-top: 45px;
  color: var(--gold-deep);
}
.stripe-resources a h3 {
  margin-top: 20px !important;
  font-size: 1.2rem;
  line-height: 1.45;
}
.stripe-resources a b {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: auto;
  font-size: 0.72rem;
}
.stripe-resources a b svg {
  width: 14px;
}

.stripe-faq .stripe-sahl-shell {
  display: grid;
  grid-template-columns: 0.72fr 1.28fr;
  gap: 85px;
}
.stripe-faq .stripe-section-intro {
  position: sticky;
  top: 110px;
  align-self: start;
}
.stripe-faq [data-slot="accordion-item"] {
  border-bottom-color: var(--border);
}
.stripe-faq [data-slot="accordion-trigger"] {
  min-height: 72px;
  font-size: 1rem;
  text-align: right;
}
.stripe-faq [data-slot="accordion-content"] {
  color: var(--muted-foreground);
  line-height: 1.8;
}

.stripe-final-cta {
  min-height: 580px;
  position: relative;
  display: flex;
  align-items: center;
  overflow: hidden;
  border-top: 1px solid var(--border);
}
.stripe-final-ribbon {
  position: absolute;
  z-index: 0;
  inset: 20% 55% -50% -15%;
  transform: skewY(12deg);
  background: var(--gradient-aurora);
  opacity: 0.85;
}
.stripe-final-cta .stripe-sahl-shell {
  z-index: 1;
}
.stripe-final-cta .stripe-sahl-shell > span {
  color: var(--gold-deep);
  font-size: 0.78rem;
  font-weight: 800;
}
.stripe-final-cta h2 {
  margin-top: 12px !important;
  font-size: clamp(3rem, 6vw, 6rem);
  line-height: 0.98;
  font-weight: 580;
}
.stripe-final-cta p {
  margin-top: 22px !important;
  color: var(--muted-foreground);
  font-size: 1.05rem;
}

@keyframes stripe-ribbon-drift {
  to {
    transform: translate3d(-7%, 4%, 0) rotate(7deg) scale(1.08);
  }
}
@keyframes stripe-float {
  50% {
    transform: translateY(-10px);
  }
}
@keyframes stripe-node-pulse {
  to {
    transform: scale(1.7);
    opacity: 0.45;
  }
}

@media (max-width: 1024px) {
  .stripe-nav-links,
  .stripe-nav-actions {
    display: none;
  }
  .stripe-nav-menu {
    display: inline-flex;
    margin-right: auto;
  }
  .stripe-mobile-menu {
    display: grid;
    position: absolute;
    top: 70px;
    inset-inline: 16px;
    max-height: calc(100dvh - 86px);
    overflow: auto;
    padding: 16px;
    border: 1px solid var(--border);
    background: var(--background);
    box-shadow: var(--shadow-card);
    border-radius: 7px;
  }
  .stripe-mobile-menu > a {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 13px 8px;
    border-bottom: 1px solid var(--border);
    color: var(--foreground);
  }
  .stripe-mobile-menu > div {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    padding-top: 14px;
  }
  .stripe-mobile-menu > div a {
    padding: 11px;
    text-align: center;
    border: 1px solid var(--border);
    color: var(--foreground);
    border-radius: 5px;
  }
  .stripe-mobile-menu > div a:last-child {
    background: var(--foreground);
    color: var(--background);
  }
  .stripe-sahl-hero-inner {
    grid-template-columns: 1fr;
  }
  .stripe-sahl-hero-copy {
    max-width: 720px;
  }
  .stripe-hero-stage {
    width: min(820px, 100%);
  }
  .stripe-sahl-ribbon {
    inset-inline: 24% -20%;
  }
  .stripe-trust .stripe-sahl-shell {
    display: block;
  }
  .stripe-trust p {
    width: 100%;
    min-height: 70px;
    border-left: 0;
    border-bottom: 1px solid var(--border);
  }
  .stripe-trust .stripe-sahl-shell > div {
    grid-template-columns: repeat(3, 1fr);
  }
  .stripe-trust span:nth-child(3) {
    border-left: 0;
  }
  .stripe-platform .stripe-sahl-shell,
  .stripe-faq .stripe-sahl-shell {
    grid-template-columns: 1fr;
  }
  .stripe-platform-copy {
    max-width: 760px;
  }
  .stripe-faq .stripe-section-intro {
    position: static;
  }
  .stripe-resources .stripe-sahl-shell {
    grid-template-columns: 1fr;
  }
  .stripe-stories .stripe-sahl-shell {
    grid-template-columns: 1fr;
  }
