.sahl-infrastructure {
  background: var(--home-soft);
}
.sahl-system-board {
  overflow: hidden;
  padding: 48px 48px 0;
  border-radius: 14px;
  background: var(--home-ink);
  color: var(--home-bg);
}
.sahl-system-board .sahl-product-frame {
  max-width: 960px;
  margin-inline: auto;
  transform: translateY(1px);
}
.sahl-tool-connections {
  position: relative;
  width: min(760px, 100%);
  height: 286px;
  margin: 0 auto;
  direction: ltr;
}
.sahl-tool-wires {
  position: absolute;
  inset: 75px 0 auto;
  width: 100%;
  height: 136px;
  overflow: visible;
}
.sahl-tool-wires > path {
  fill: none;
  stroke: color-mix(in oklab, var(--home-bg) 23%, transparent);
  stroke-width: 0.8;
  vector-effect: non-scaling-stroke;
}
.sahl-tool-pulses use {
  fill: none;
  stroke: var(--home-gold);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 1 1000;
  stroke-dashoffset: 0;
  opacity: 0;
  filter: drop-shadow(0 0 5px color-mix(in oklab, var(--home-gold) 78%, transparent));
  animation: sahl-tool-pulse 10s linear infinite;
}
.sahl-tool-pulses use:nth-child(2) {
  animation-delay: 2s;
}
.sahl-tool-pulses use:nth-child(3) {
  animation-delay: 4s;
}
.sahl-tool-pulses use:nth-child(4) {
  animation-delay: 6s;
}
.sahl-tool-pulses use:nth-child(5) {
  animation-delay: 8s;
}
.sahl-tool-icon,
.sahl-tool-core {
  position: absolute;
  z-index: 2;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in oklab, var(--tool-tone) 55%, transparent);
  border-radius: 50%;
  background: color-mix(in oklab, var(--home-ink) 88%, var(--tool-tone));
  color: var(--tool-tone);
  box-shadow: 0 0 20px color-mix(in oklab, var(--tool-tone) 10%, transparent);
}
.sahl-tool-icon {
  width: 48px;
  height: 48px;
}
.sahl-tool-icon svg {
  width: 22px;
  height: 22px;
  stroke-width: 1.75;
}
.sahl-tool-icon b {
  font-family: Arial, sans-serif;
  font-size: 1.28rem;
  line-height: 1;
}
.sahl-tool-icon span,
.sahl-tool-core span {
  position: absolute;
  top: calc(100% + 5px);
  color: color-mix(in oklab, var(--home-bg) 57%, transparent);
  font-size: 0.52rem;
  white-space: nowrap;
}
.sahl-tool-icon.is-instagram {
  --tool-tone: var(--home-terracotta);
  left: 8%;
  top: 65px;
}
.sahl-tool-icon.is-whatsapp {
  --tool-tone: var(--home-teal);
  left: 8%;
  top: 114px;
}
.sahl-tool-icon.is-google {
  --tool-tone: var(--home-gold);
  left: 8%;
  top: 163px;
}
.sahl-tool-icon.is-facebook {
  --tool-tone: var(--home-teal);
  right: 8%;
  top: 81px;
}
.sahl-tool-icon.is-shopify {
  --tool-tone: var(--home-terracotta);
  right: 8%;
  top: 147px;
}
.sahl-tool-core {
  --tool-tone: var(--home-gold);
  left: 50%;
  top: 50%;
  width: 72px;
  height: 72px;
  padding: 14px;
  transform: translate(-50%, -50%);
  background: color-mix(in oklab, var(--home-ink) 82%, var(--home-gold));
  box-shadow: 0 0 32px color-mix(in oklab, var(--home-gold) 18%, transparent);
}
.sahl-tool-core img {
  width: 34px;
  height: 34px;
}
@keyframes sahl-tool-pulse {
  0%,
  1% {
    stroke-dashoffset: 0;
    opacity: 0;
  }
  3% {
    opacity: 1;
  }
  17% {
    stroke-dashoffset: -1000;
    opacity: 1;
  }
  19%,
  100% {
    stroke-dashoffset: -1000;
    opacity: 0;
  }
}
.sahl-system-points {
