/* ===========================================================
   صفحات التسجيل والدخول — بساطة مقصودة (بطاقة بيضاء + تدرج زوايا)
   =========================================================== */
.sauth-page {
  position: relative;
  height: 100svh;
  min-height: 100svh;
  background: #faf6ef;
  color: #24201b;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: "Almarai", system-ui, sans-serif;
}

.sauth-glow {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.sauth-glow-blob {
  position: absolute;
  width: 64vmax;
  height: 64vmax;
  min-width: 540px;
  min-height: 540px;
  border-radius: 50%;
  opacity: 0.45;
  will-change: filter, background-color;
}
/* مراكز الدوائر خارج الشاشة تمامًا — الظاهر هو القوس فقط من كل زاوية */
.sauth-glow-blob {
  filter: blur(110px);
}
.sauth-glow-blob.is-one {
  top: -40vmax;
  left: -34vmax;
  animation: sauth-hue-a 18s ease-in-out infinite;
}
.sauth-glow-blob.is-two {
  top: -40vmax;
  right: -34vmax;
  animation: sauth-hue-b 18s ease-in-out infinite;
  animation-delay: -6s;
}
.sauth-glow-blob.is-three {
  bottom: -40vmax;
  left: -34vmax;
  animation: sauth-hue-a 18s ease-in-out infinite;
  animation-delay: -12s;
}
.sauth-glow-blob.is-four {
  bottom: -40vmax;
  right: -34vmax;
  animation: sauth-hue-b 18s ease-in-out infinite;
  animation-delay: -9s;
}

@keyframes sauth-hue-a {
  0% {
    background-color: #a8492c;
  }
  33% {
    background-color: #c68a2e;
  }
  66% {
    background-color: #2f6b63;
  }
  100% {
    background-color: #a8492c;
  }
}
@keyframes sauth-hue-b {
  0% {
    background-color: #2f6b63;
  }
  35% {
    background-color: #a8492c;
  }
  70% {
    background-color: #c68a2e;
  }
  100% {
    background-color: #2f6b63;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sauth-glow-blob {
    animation: none !important;
    filter: blur(110px);
  }
  .sauth-glow-blob.is-one,
  .sauth-glow-blob.is-four {
    background-color: #a8492c;
  }
  .sauth-glow-blob.is-two {
    background-color: #c68a2e;
  }
  .sauth-glow-blob.is-three {
    background-color: #2f6b63;
  }
}

