  margin-bottom: 8px;
  color: var(--home-terracotta);
  font-size: 0.74rem;
  font-weight: 700;
}
.sahl-ads-steps b {
  display: block;
  color: var(--home-ink);
  font-size: 1rem;
}
.sahl-ads-steps span {
  display: block;
  margin-top: 7px;
  color: var(--home-copy);
  font-size: 0.84rem;
  line-height: 1.8;
}
.sahl-ads-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 28px;
  padding-top: 18px;
  border-top: 1px solid var(--home-line);
  color: var(--home-copy);
  font-size: 0.78rem;
  line-height: 1.8;
}
.sahl-ads-note svg {
  flex: none;
  width: 15px;
  margin-top: 3px;
  color: var(--home-teal);
}

@media (max-width: 720px) {
  .sahl-proof-grid,
  .sahl-ads-metrics,
  .sahl-ads-steps {
    grid-template-columns: 1fr;
  }
  .sahl-ads-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .sahl-proof-grid article {
    padding: 22px;
  }
  .sahl-ads-board {
    padding: 20px;
  }

  /* بطاقات الموظفين: نفس المحتوى كاملاً، بمقاس أصغر ومساحات أقل على الهاتف */
  .sahl-cap-card,
  .sahl-cap-card.is-wide {
    margin-bottom: 10px;
  }
  .sahl-cap-card > div:first-child {
    padding: 20px;
  }
  .sahl-cap-card > div:first-child > svg {
    width: 20px;
    margin-bottom: 16px;
  }
  .sahl-cap-card > div:first-child > span {
    font-size: 0.7rem;
  }
  .sahl-cap-card h3 {
    margin-top: 8px;
    font-size: 1.32rem;
    line-height: 1.3;
  }
  .sahl-cap-card p {
    margin-top: 10px;
    font-size: 0.86rem;
    line-height: 1.75;
  }
  .sahl-cap-card .sahl-coming-ads {
    padding: 14px;
  }
