    font-size: 0.72rem;
  }
  .sahl-cap-card a {
    margin-top: 16px;
    font-size: 0.76rem;
  }
  .sahl-cap-card .sahl-device-frame,
  .sahl-cap-card.is-wide .sahl-device-frame {
    width: min(58%, 196px);
    margin: 16px auto 20px;
  }
}
.sahl-pricing .sahl-section-head p a {
  color: var(--home-terracotta);
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* ===== مقدمة بصورة المنتج + الأقسام الجديدة (عينة مخرج · مقارنة · ضمانات) ===== */
.sahl-cap-card:not(.is-wide) > div:first-child {
  padding: 34px 32px 32px;
}
.sahl-cap-card:not(.is-wide) h3 {
  font-size: clamp(1.5rem, 2.2vw, 2.1rem);
}
.sahl-cap-card:not(.is-wide) > div:first-child > svg {
  margin-bottom: 26px;
}
.sahl-cap-card:not(.is-wide) a {
  margin-top: 20px;
}

/* ===== dark editorial sections: sample / versus / guard ===== */
.sahl-dark {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--home-ink);
  color: var(--home-bg);
}
.sahl-dark > .sahl-shell {
  position: relative;
  z-index: 2;
}
.sahl-dark .sahl-section-head > span,
.sahl-dark .sahl-section-head > div > span {
  color: color-mix(in oklab, var(--home-gold) 85%, var(--home-bg));
}
.sahl-dark .sahl-section-head h2 {
  color: color-mix(in oklab, var(--home-bg) 96%, var(--home-gold));
}
.sahl-dark .sahl-section-head h2 em {
  color: color-mix(in oklab, var(--home-bg) 54%, transparent);
}
.sahl-dark .sahl-section-head > p,
.sahl-dark .sahl-section-head > div + p {
  color: color-mix(in oklab, var(--home-bg) 66%, transparent);
}
.sahl-dark-veil {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

/* sample — streaming output lines */
.sahl-sample .sahl-dark-veil {
  background:
    radial-gradient(
      circle at 12% 10%,
      color-mix(in oklab, var(--home-terracotta) 20%, transparent),
      transparent 42%
    ),
    radial-gradient(
      circle at 88% 82%,
      color-mix(in oklab, var(--home-teal) 17%, transparent),
      transparent 44%
    );
}
/* sahl-sample-stream removed — was animated gold light trails */
.sahl-sample-board {
  position: relative;
  margin-top: 44px;
  padding: clamp(20px, 3vw, 34px);
