}
.sahl-sample-ask small {
  display: block;
  color: color-mix(in oklab, var(--home-gold) 88%, var(--home-bg));
  font-size: 0.68rem;
  font-weight: 700;
}
.sahl-sample-ask p {
  margin-top: 6px;
  color: var(--home-bg);
  font-size: 1.02rem;
