  padding: 12px 15px;
  border-bottom: 1px solid color-mix(in oklab, var(--home-bg) 12%, transparent);
  background: color-mix(in oklab, var(--home-bg) 6%, transparent);
}
.sahl-sample-grid header svg {
  width: 17px;
  color: color-mix(in oklab, var(--home-terracotta) 62%, var(--home-bg));
}
.sahl-sample-grid header b {
