/* إشعار كوكيز صغير وغير معطّل للتصفح. */
.sahl-cookie-consent {
  position: fixed;
  z-index: 150;
  inset: auto auto max(20px, env(safe-area-inset-bottom)) 20px;
  width: min(380px, calc(100vw - 40px));
  min-height: 94px;
  padding: 16px;
  display: grid;
  gap: 12px;
  border: 1px solid color-mix(in oklab, var(--home-bg, var(--background)) 74%, transparent);
  border-radius: 17px;
  background: color-mix(in oklab, var(--glass-tint) 90%, var(--background));
  box-shadow:
    0 24px 54px -18px color-mix(in oklab, var(--foreground) 42%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--background) 86%, transparent);
  animation: sahl-cookie-enter 360ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
}
.sahl-cookie-consent.is-leaving {
  pointer-events: none;
  animation: sahl-cookie-exit 240ms ease-in both;
}
.sahl-cookie-consent p {
  position: relative;
  z-index: 1;
  margin: 0;
  color: var(--foreground);
  font-family: "Almarai", "IBM Plex Sans Arabic", sans-serif;
  font-size: 0.78rem;
  line-height: 1.7;
}
.sahl-cookie-consent p a {
  color: var(--home-terracotta, var(--primary));
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.sahl-cookie-actions {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 6px;
}
.sahl-cookie-actions [data-slot="button"] {
  height: 32px;
  padding-inline: 14px;
  border-radius: 7px;
  font-family: "Almarai", "IBM Plex Sans Arabic", sans-serif;
  font-size: 0.7rem;
}
.sahl-cookie-actions [data-slot="button"]:first-child {
  background: var(--home-terracotta, var(--primary));
  color: var(--primary-foreground);
  box-shadow: none;
}
.sahl-cookie-actions [data-slot="button"]:last-child {
  color: var(--muted-foreground);
}
@keyframes sahl-cookie-enter {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes sahl-cookie-exit {
  from {
    opacity: 1;
    transform: none;
  }
  to {
    opacity: 0;
    transform: translateY(10px);
  }
}
@media (max-width: 720px) {
  .sahl-cookie-consent {
    inset: auto 12px max(12px, env(safe-area-inset-bottom)) 12px;
    width: auto;
    min-height: 0;
    max-height: 25vh;
    padding: 12px 13px;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 8px;
  }
  .sahl-cookie-consent p {
    font-size: 0.68rem;
    line-height: 1.65;
  }
  .sahl-cookie-actions {
    gap: 3px;
  }
  .sahl-cookie-actions [data-slot="button"] {
    height: 30px;
    padding-inline: 9px;
    font-size: 0.64rem;
  }
}
@media (max-width: 360px) {
  .sahl-cookie-consent {
    grid-template-columns: 1fr;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sahl-cookie-consent,
  .sahl-cookie-consent.is-leaving {
    animation: none;
  }
}

/* ===== هبوط الأجهزة + مشاهد متحركة جديدة + سلاسة التمرير ===== */
html {
  scroll-padding-top: 96px;
}
.sahl-white-home {
  overflow-x: clip;
}

/* الأجهزة تنزل من الأعلى إلى مكانها — بأسلوب Stripe */
.sahl-device-drop {
  opacity: 0;
  transform: translate3d(0, -72px, 0) scale(0.965);
  transition:
    opacity 0.9s cubic-bezier(0.16, 0.84, 0.3, 1),
    transform 1.05s cubic-bezier(0.16, 0.84, 0.3, 1);
  will-change: transform, opacity;
}
.sahl-device-drop.is-landed {
  opacity: 1;
  transform: translate3d(0, 0, 0) scale(1);
  will-change: auto;
}
.sahl-device-frame.is-hero.sahl-device-drop {
  transform: translate3d(0, -88px, 0) rotateY(5deg) rotateX(1deg) scale(0.96);
}
.sahl-device-frame.is-hero.sahl-device-drop.is-landed {
  transform: translate3d(0, 0, 0) rotateY(5deg) rotateX(1deg) scale(1);
}
.sahl-cap-card .sahl-device-frame.sahl-device-drop.is-landed {
  transform: none;
}

/* إيقاف الحركة خارج الشاشة = تمرير أنعم */
.sahl-scene:not(.is-onscreen) *,
.sahl-scene:not(.is-onscreen) *::before,
.sahl-scene:not(.is-onscreen) *::after {
  animation-play-state: paused !important;
}

/* قسم الإثباتات الداكن */
.sahl-proof {
  position: relative;
  overflow: hidden;
}
.sahl-proof .sahl-dark-veil {
  background:
    radial-gradient(
      circle at 18% 12%,
      color-mix(in oklab, var(--home-teal) 20%, transparent),
      transparent 44%
    ),
    radial-gradient(
      circle at 86% 88%,
      color-mix(in oklab, var(--home-gold) 16%, transparent),
      transparent 46%
    );
}
.sahl-proof-ledger {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  opacity: 0.32;
}
.sahl-proof-ledger i {
  position: absolute;
  inset-inline: 6%;
  height: 1px;
  background: repeating-linear-gradient(
    90deg,
    color-mix(in oklab, var(--home-bg) 40%, transparent) 0 3px,
    transparent 3px 16px
  );
  animation: sahl-ledger-tick 7.5s ease-in-out infinite;
}
.sahl-proof-ledger i:nth-child(1) {
  top: 14%;
}
.sahl-proof-ledger i:nth-child(2) {
  top: 28%;
  animation-delay: -1.1s;
}
.sahl-proof-ledger i:nth-child(3) {
  top: 44%;
  animation-delay: -2.4s;
}
.sahl-proof-ledger i:nth-child(4) {
  top: 60%;
  animation-delay: -3.6s;
}
.sahl-proof-ledger i:nth-child(5) {
  top: 76%;
  animation-delay: -4.8s;
}
.sahl-proof-ledger i:nth-child(6) {
  top: 90%;
  animation-delay: -6s;
}
@keyframes sahl-ledger-tick {
  0%,
  100% {
    opacity: 0.25;
    transform: translateX(0);
  }
  50% {
    opacity: 0.8;
    transform: translateX(-14px);
  }
}
.sahl-proof .sahl-shell {
  position: relative;
  z-index: 2;
}
.sahl-proof .sahl-proof-grid article {
  border-color: color-mix(in oklab, var(--home-bg) 15%, transparent);
  background: color-mix(in oklab, var(--home-bg) 6%, transparent);
  backdrop-filter: blur(6px);
}
.sahl-proof .sahl-proof-grid article h3 {
  color: var(--home-bg);
}
.sahl-proof .sahl-proof-grid article p {
  color: color-mix(in oklab, var(--home-bg) 66%, transparent);
}
.sahl-proof .sahl-proof-grid article span {
  background: color-mix(in oklab, var(--home-gold) 22%, transparent);
  color: color-mix(in oklab, var(--home-gold) 40%, var(--home-bg));
}

/* لوحات الصور الجديدة */
.sahl-proof-visual {
  margin-top: 40px;
}
.sahl-proof-visual figure,
.sahl-ads-visual figure {
  position: relative;
  margin: 0;
  border: 1px solid color-mix(in oklab, var(--home-ink) 12%, transparent);
  border-radius: 18px;
  overflow: hidden;
  background: var(--home-bg);
}
.sahl-proof-visual figure {
  border-color: color-mix(in oklab, var(--home-bg) 16%, transparent);
}
.sahl-proof-visual img,
.sahl-ads-visual img {
  display: block;
  width: 100%;
  height: auto;
}
.sahl-proof-visual figcaption {
  margin-top: 14px;
  color: color-mix(in oklab, var(--home-bg) 62%, transparent);
  font-size: 0.82rem;
}
.sahl-visual-sweep {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    105deg,
    transparent 40%,
    color-mix(in oklab, var(--home-bg) 42%, transparent) 50%,
    transparent 60%
  );
  mix-blend-mode: overlay;
  animation: sahl-visual-sweep 9s ease-in-out infinite;
}
@keyframes sahl-visual-sweep {
  0% {
    transform: translateX(-60%);
    opacity: 0;
  }
  18% {
    opacity: 1;
  }
  60% {
    transform: translateX(60%);
    opacity: 0;
  }
  100% {
    transform: translateX(60%);
    opacity: 0;
  }
}
.sahl-visual-ring {
  position: absolute;
  inset-inline-start: 8%;
  top: 12%;
  width: 120px;
  height: 120px;
  border: 1px solid color-mix(in oklab, var(--home-gold) 55%, transparent);
  border-radius: 50%;
  pointer-events: none;
  animation: sahl-visual-ring 6s ease-out infinite;
}
@keyframes sahl-visual-ring {
  0% {
    transform: scale(0.6);
    opacity: 0;
  }
  25% {
    opacity: 0.75;
  }
  100% {
    transform: scale(1.9);
    opacity: 0;
  }
}
.sahl-ads-visual {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  align-items: center;
  gap: 28px;
  margin-top: 40px;
}
.sahl-ads-visual > div span {
  display: inline-block;
  padding: 5px 11px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--home-terracotta) 12%, transparent);
  color: var(--home-terracotta);
  font-size: 0.72rem;
  font-weight: 700;
}
.sahl-ads-visual > div h3 {
  margin-top: 14px;
  font-size: clamp(1.4rem, 2.4vw, 1.85rem);
  line-height: 1.4;
  color: var(--home-ink);
}
.sahl-ads-visual > div p {
  margin-top: 12px;
  color: var(--home-copy);
  font-size: 0.95rem;
  line-height: 1.9;
}
.sahl-visual-orbit {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.sahl-visual-orbit i {
  position: absolute;
  inset-inline-end: 16%;
  top: 24%;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--home-terracotta);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--home-terracotta) 16%, transparent);
  animation: sahl-orbit-float 7s ease-in-out infinite;
}
.sahl-visual-orbit i:nth-child(2) {
  inset-inline-end: 34%;
  top: 62%;
  background: var(--home-teal);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--home-teal) 16%, transparent);
  animation-delay: -2.3s;
}
.sahl-visual-orbit i:nth-child(3) {
  inset-inline-end: 62%;
  top: 38%;
  background: var(--home-gold);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--home-gold) 18%, transparent);
  animation-delay: -4.6s;
}
@keyframes sahl-orbit-float {
  0%,
  100% {
    transform: translate3d(0, 0, 0);
    opacity: 0.55;
  }
  50% {
    transform: translate3d(0, -16px, 0);
    opacity: 1;
  }
}

@media (max-width: 860px) {
  .sahl-ads-visual {
    grid-template-columns: 1fr;
  }
  .sahl-visual-ring {
    width: 78px;
    height: 78px;
