/* ===== لوحة العمل الأحادية — قياس ونتائج بلا زخرفة ===== */
.app-command-center {
  --command-bg: var(--background);
  --command-ink: var(--foreground);
  --command-line: var(--border);
  --command-dim: var(--muted-foreground);
  --command-muted: color-mix(in oklab, var(--foreground) 55%, transparent);

  overflow: hidden;
  border: 1px solid var(--command-line);
  border-radius: 20px;
  background: var(--command-bg);
  color: var(--command-ink);
  box-shadow: var(--shadow-card);
}
.app-command-center > * {
  margin: 0 !important;
  border-inline: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

.app-command-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.5rem 1.6rem;
  border-bottom: 1px solid var(--command-line);
  background: var(--secondary);
}
.app-command-head p {
  color: var(--command-muted);
  font-family: ui-monospace, monospace;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.05em;
}
.app-command-head h2 {
  margin-top: 0.35rem;
  color: var(--command-ink);
  font-family: var(--font-display);
  font-size: clamp(1.2rem, 2.5vw, 1.65rem);
  font-weight: 900;
}
.app-command-head > span {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--command-muted);
  font-size: 0.7rem;
  font-weight: 600;
}
.app-command-head > span i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--jade);
  animation: command-live 2s ease-in-out infinite;
}

.app-metric-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  background: var(--background);
  border-bottom: 1px solid var(--command-line);
}
.app-metric {
  padding: 1.4rem 1.6rem;
  border-inline-end: 1px solid var(--command-line);
}
.app-metric:last-child {
  border-inline-end: 0;
}
.app-metric-label {
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--command-muted);
}
.app-metric-number {
  font-size: 2.25rem;
  font-weight: 900;
  margin: 0.2rem 0;
  line-height: 1;
}
.app-metric-note {
  font-size: 0.68rem;
  color: var(--command-dim);
}

.ads-report {
  background: var(--background);
  color: var(--foreground);
  border-bottom: 1px solid var(--command-line);
}
.ads-report-head {
  background: transparent;
  padding: 1.5rem 1.6rem;
  border-bottom: 1px solid var(--command-line);
}
.ads-report-head p {
  color: var(--command-muted);
}
.ads-report-head h2 {
  color: var(--foreground);
}
.ads-report-head > span {
  color: var(--command-dim);
}

.ads-platform-rail {
  background: var(--secondary);
  border-bottom: 1px solid var(--command-line);
}
.ads-platform-rail > div {
  border-inline-end: 1px solid var(--command-line);
  padding: 1rem 1.2rem;
}
.ads-platform-rail b {
  color: var(--foreground);
  font-weight: 800;
}
.ads-platform-rail .is-connected span,
.ads-platform-rail .is-reporting span {
  color: var(--jade);
  font-weight: 800;
}

.ads-report-metrics {
  border-bottom: 1px solid var(--command-line);
}
.ads-report-metrics > div {
  padding: 1.4rem 1.6rem;
  border-inline-end: 1px solid var(--command-line);
  border-bottom: 0;
}
.ads-report-metrics strong {
  color: var(--foreground);
}

.ads-chart {
  border-inline-end: 1px solid var(--command-line);
  background: var(--background);
}
.ads-chart-bars i {
  background: var(--jade);
  border-radius: 4px 4px 0 0;
}

.ads-campaign-board {
  background: var(--background);
}
.ads-report-label {
  background: var(--secondary);
  border-bottom: 1px solid var(--command-line);
  color: var(--command-muted);
}
.ads-campaign-track i {
  background: var(--jade);
  border-radius: 2px;
}

.app-operations-grid {
  background: var(--background);
}
.app-running-panel {
  background: var(--background) !important;
  color: var(--foreground) !important;
}
.app-running-panel .app-running-index {
  background: var(--jade);
}
.app-running-list {
  border-top-color: var(--command-line);
}
.app-running-list li {
  border-bottom-color: var(--command-line);
}
.app-work-list {
  border-top-color: var(--command-line);
}
.app-work-row {
  border-bottom-color: var(--command-line);
}

/* ===== Sahl homepage — monochrome motion system ===== */
.mono-page {
  --mono-black: oklch(0.12 0 0);
  --mono-graphite: oklch(0.34 0 0);
  --mono-mid: oklch(0.56 0 0);
  --mono-line: oklch(0.12 0 0 / 0.13);
  --mono-soft: oklch(0.97 0 0);
  background: oklch(1 0 0);
  color: var(--mono-black);
}
.mono-page .nav-floating-control {
  border-color: var(--mono-line);
  background: oklch(1 0 0 / 0.88);
  color: var(--mono-black);
  box-shadow: 0 8px 25px -20px var(--mono-black);
  backdrop-filter: blur(16px);
}
.mono-page .nav-glass-sheet {
  border-color: var(--mono-line);
  background: oklch(1 0 0 / 0.96);
  box-shadow: 0 24px 70px -40px var(--mono-black);
}
.mono-page .nav-glass-sheet::before,
.mono-page .nav-glass-sheet::after {
  display: none;
}
.mono-page .nav-glass-cta-primary,
.mono-page .nav-glass-cta-aurora {
  border-color: var(--mono-black);
  background: var(--mono-black);
  color: oklch(1 0 0);
  box-shadow: none;
}
.mono-home {
  overflow: clip;
  background: oklch(1 0 0);
  color: var(--mono-black);
  font-family: "IBM Plex Sans Arabic", ui-sans-serif, sans-serif;
}
.mono-home *,
.mono-home *::before,
.mono-home *::after {
  box-sizing: border-box;
}
.mono-home h1,
.mono-home h2,
.mono-home h3,
.mono-home p {
  letter-spacing: 0;
}
.mono-shell {
  width: min(100% - 3rem, 76rem);
  margin-inline: auto;
}
.mono-grid-field {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(to left, var(--mono-line) 1px, transparent 1px),
    linear-gradient(to bottom, var(--mono-line) 1px, transparent 1px);
  background-size: 4.5rem 4.5rem;
  mask-image: linear-gradient(to bottom, black, transparent 86%);
  opacity: 0.48;
}

.mono-hero {
  position: relative;
  min-height: 61rem;
  padding: 10rem 0 7rem;
  border-bottom: 1px solid var(--mono-line);
  background: oklch(1 0 0);
}
.mono-hero::before {
  content: "SAHL / 01";
  position: absolute;
  top: 8rem;
  left: 2.5rem;
  color: var(--mono-mid);
  font:
    600 0.62rem/1 ui-monospace,
    monospace;
  writing-mode: vertical-rl;
}
.mono-hero-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 0.83fr 1.17fr;
  align-items: center;
  gap: clamp(2rem, 5vw, 5rem);
}
.mono-hero-copy {
  padding-block: 3rem;
}
.mono-kicker {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 1.7rem;
  color: var(--mono-graphite);
  font-size: 0.8rem;
  font-weight: 600;
}
.mono-kicker span {
  border: 1px solid var(--mono-black);
  padding: 0.3rem 0.55rem;
  color: var(--mono-black);
  font-size: 0.65rem;
}
.mono-hero h1 {
  max-width: 45rem;
  font-size: clamp(4rem, 6.7vw, 7rem);
  font-weight: 700;
  line-height: 1.04;
  text-wrap: balance;
}
.mono-hero h1 em {
  display: inline-block;
  font-style: normal;
  font-weight: 400;
  color: var(--mono-graphite);
}
.mono-hero-copy > p:not(.mono-kicker) {
  max-width: 35rem;
  margin-top: 1.7rem;
  color: var(--mono-graphite);
  font-size: 1.08rem;
  line-height: 1.9;
}
.mono-actions {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  margin-top: 2rem;
}
.mono-actions a,
.mono-final a {
  display: inline-flex;
  min-height: 3.2rem;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  padding-inline: 1.25rem;
  border: 1px solid var(--mono-black);
  font-size: 0.82rem;
  font-weight: 700;
  transition:
    transform 0.25s ease,
    background 0.25s ease,
    color 0.25s ease;
}
.mono-actions a:first-child,
.mono-final a {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-actions a:hover,
.mono-final a:hover {
  transform: translateY(-3px);
}
.mono-actions a:last-child:hover {
  background: var(--mono-soft);
}
.mono-actions svg,
.mono-final svg {
  width: 1rem;
}
.mono-trial {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-top: 1rem;
  color: var(--mono-mid);
  font-size: 0.72rem;
}
.mono-trial svg {
  width: 0.9rem;
}
.mono-hero-product {
  position: relative;
  transform: perspective(1500px) rotateY(-2deg) rotateX(1deg);
  transform-origin: center left;
}
.mono-scroll-cue {
  position: absolute;
  z-index: 3;
  bottom: 2rem;
  left: 50%;
  display: grid;
  justify-items: center;
  gap: 0.7rem;
  transform: translateX(-50%);
  color: var(--mono-mid);
  font-size: 0.62rem;
}
.mono-scroll-cue i {
  position: relative;
  width: 1px;
  height: 2.8rem;
  overflow: hidden;
  background: var(--mono-line);
}
.mono-scroll-cue i::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--mono-black);
  animation: mono-scroll 2.2s ease-in-out infinite;
}
@keyframes mono-scroll {
  0% {
    transform: translateY(-100%);
  }
  65%,
  100% {
    transform: translateY(100%);
  }
}

.mono-workspace,
.mono-studio {
  overflow: hidden;
  border: 1px solid var(--mono-black);
  background: oklch(1 0 0);
  box-shadow:
    18px 18px 0 var(--mono-soft),
    18px 18px 0 1px var(--mono-line);
}
.mono-window-bar {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  height: 3.4rem;
  align-items: center;
  padding-inline: 1rem;
  border-bottom: 1px solid var(--mono-line);
  font-size: 0.7rem;
}
.mono-window-bar > span {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--mono-mid);
}
.mono-window-bar > span i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--mono-black);
  animation: mono-pulse 2s ease-out infinite;
}
.mono-window-controls {
  display: flex;
  gap: 0.3rem;
  direction: ltr;
}
.mono-window-controls i {
  width: 0.48rem;
  height: 0.48rem;
  border: 1px solid var(--mono-mid);
  border-radius: 50%;
}
@keyframes mono-pulse {
  50% {
    box-shadow: 0 0 0 0.35rem oklch(0.12 0 0 / 0.08);
  }
}
.mono-workspace-grid {
  display: grid;
  grid-template-columns: 9.5rem 1fr;
  min-height: 34rem;
}
.mono-employee-rail {
  padding: 0.65rem;
  border-inline-end: 1px solid var(--mono-line);
  background: var(--mono-soft);
}
.mono-employee-rail button {
  position: relative;
  width: 100%;
  height: 4.35rem;
  justify-content: flex-start;
  gap: 0.55rem;
  padding: 0.4rem;
  border-radius: 0;
  color: var(--mono-black);
  white-space: normal;
}
.mono-employee-rail button::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 1px;
  background: var(--mono-line);
}
.mono-employee-rail button.is-active {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-employee-rail img {
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 0;
  filter: grayscale(1);
  object-fit: cover;
}
.mono-employee-rail span,
.mono-employee-rail strong,
.mono-employee-rail small {
  display: block;
  text-align: right;
}
.mono-employee-rail strong {
  font-size: 0.72rem;
}
.mono-employee-rail small {
  max-width: 5rem;
  overflow: hidden;
  color: var(--mono-mid);
  font-size: 0.53rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mono-employee-rail button.is-active small {
  color: oklch(1 0 0 / 0.62);
}
.mono-employee-rail button > i {
  position: absolute;
  left: 0.45rem;
  width: 0.3rem;
  height: 0.3rem;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.25;
}
.mono-employee-rail button.is-active > i {
  opacity: 1;
}
.mono-workspace-main {
  display: flex;
  min-width: 0;
  flex-direction: column;
  padding: 1.2rem;
}
.mono-workspace-main > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--mono-line);
}
.mono-workspace-main header small {
  color: var(--mono-mid);
  font-size: 0.6rem;
}
.mono-workspace-main header h3 {
  margin-top: 0.15rem;
  font-size: 1.35rem;
}
.mono-workspace-main header > span {
  font-size: 1.25rem;
  font-weight: 700;
  text-align: left;
}
.mono-workspace-main header > span small {
  display: block;
}
.mono-conversation {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 1rem;
  padding: 1.5rem 0;
}
.mono-conversation > p {
  align-self: flex-start;
  max-width: 82%;
  padding: 0.8rem 1rem;
  background: var(--mono-black);
  color: oklch(1 0 0);
  font-size: 0.73rem;
}
.mono-conversation .is-employee {
  display: flex;
  max-width: 92%;
  align-items: flex-start;
  gap: 0.7rem;
  padding: 0.9rem;
  border: 1px solid var(--mono-line);
}
.mono-conversation .is-employee img {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 0;
  filter: grayscale(1);
}
.mono-conversation strong,
.mono-conversation span {
  display: block;
}
.mono-conversation strong {
  font-size: 0.72rem;
}
.mono-conversation span {
  margin-top: 0.25rem;
  color: var(--mono-graphite);
  font-size: 0.62rem;
  line-height: 1.65;
}
.mono-deliverable {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  padding: 0.85rem;
  border: 1px solid var(--mono-line);
  background: var(--mono-soft);
  transition:
    background 0.25s ease,
    color 0.25s ease;
}
.mono-deliverable.phase-approved {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-deliverable > div {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.6rem;
}
.mono-deliverable svg {
  width: 0.95rem;
}
.mono-deliverable span,
.mono-deliverable small,
.mono-deliverable strong {
  display: block;
}
.mono-deliverable small {
  color: var(--mono-mid);
  font-size: 0.56rem;
}
.mono-deliverable strong {
  max-width: 13rem;
  overflow: hidden;
  font-size: 0.66rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mono-deliverable button {
  min-width: max-content;
  height: 2.35rem;
  border-radius: 0;
  background: var(--mono-black);
  color: oklch(1 0 0);
  font-size: 0.61rem;
}
.mono-deliverable.phase-approved button {
  border: 1px solid oklch(1 0 0 / 0.3);
  background: transparent;
}

.mono-proof {
  padding: 2.5rem 0;
  border-bottom: 1px solid var(--mono-line);
}
.mono-proof .mono-shell {
  display: grid;
  grid-template-columns: 1fr 2.4fr;
  align-items: center;
  gap: 3rem;
}
.mono-proof p {
  color: var(--mono-mid);
  font-size: 0.74rem;
}
.mono-proof .mono-shell > div {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}
.mono-proof span {
  display: grid;
  border-inline-start: 1px solid var(--mono-line);
  padding-inline: 1.3rem;
  color: var(--mono-mid);
  font-size: 0.62rem;
}
.mono-proof strong {
  color: var(--mono-black);
  font-size: 1.45rem;
}
.mono-team-system,
.mono-siraj-section,
.mono-flow-section,
.mono-network-section,
.mono-product-scenes,
.mono-use-cases,
.mono-pricing,
.mono-faq {
  padding-block: clamp(7rem, 11vw, 11rem);
  border-bottom: 1px solid var(--mono-line);
}
.mono-section-head {
  max-width: 51rem;
}
.mono-section-head > span {
  display: block;
  margin-bottom: 1.2rem;
  color: var(--mono-mid);
  font:
    600 0.7rem/1 ui-monospace,
    monospace;
}
.mono-section-head h2 {
  font-size: clamp(3rem, 5.6vw, 5.8rem);
  font-weight: 600;
  line-height: 1.12;
  text-wrap: balance;
}
.mono-section-head > p {
  max-width: 42rem;
  margin-top: 1.5rem;
  color: var(--mono-graphite);
  font-size: 1rem;
  line-height: 1.9;
}
.mono-section-head.is-wide {
  max-width: 68rem;
}
.mono-team-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 5rem;
  border-top: 1px solid var(--mono-line);
  border-inline-start: 1px solid var(--mono-line);
}
.mono-team-cell {
  position: relative;
  display: grid;
  grid-template-columns: 4.5rem 1fr;
  min-height: 27rem;
  overflow: hidden;
  border-inline-end: 1px solid var(--mono-line);
  border-bottom: 1px solid var(--mono-line);
  background: oklch(1 0 0);
  transition:
    background 0.3s ease,
    color 0.3s ease;
}
.mono-team-cell:hover {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-team-cell > svg {
  position: absolute;
  top: 1.2rem;
  left: 1.2rem;
  width: 1rem;
}
.mono-cell-number {
  position: absolute;
  top: 1rem;
  right: 1rem;
  color: var(--mono-mid);
  font:
    600 0.65rem/1 ui-monospace,
    monospace;
}
.mono-team-cell > img {
  grid-column: 2;
  align-self: end;
  width: 100%;
  height: 19rem;
  object-fit: cover;
  object-position: top center;
  filter: grayscale(1) contrast(1.04);
  transition:
    filter 0.3s ease,
    transform 0.5s var(--ease-enter);
}
.mono-team-cell:hover > img {
  filter: grayscale(1) contrast(1.15);
  transform: scale(1.025);
}
.mono-team-cell > div {
  grid-column: 1 / -1;
  position: absolute;
  inset: auto 0 0;
  padding: 1.25rem;
  background: oklch(1 0 0 / 0.93);
  border-top: 1px solid var(--mono-line);
  color: var(--mono-black);
  backdrop-filter: blur(10px);
}
.mono-team-cell small {
  color: var(--mono-mid);
  font-size: 0.62rem;
}
.mono-team-cell h3 {
  margin-top: 0.2rem;
  font-size: 1.55rem;
}
.mono-team-cell p {
  margin-top: 0.25rem;
  color: var(--mono-graphite);
  font-size: 0.72rem;
}
.mono-team-cell > div > span {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.75rem;
  font-size: 0.64rem;
  font-weight: 700;
}
.mono-team-cell > div > span svg {
  width: 0.8rem;
}

.mono-day {
  min-height: 225vh;
  border-bottom: 1px solid var(--mono-line);
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-day-layout {
  position: sticky;
  top: 0;
  display: grid;
  min-height: 100vh;
  grid-template-columns: 0.78fr 1.22fr;
  align-items: center;
  gap: 5rem;
  padding-block: 7rem;
}
.mono-day-copy > span {
  color: oklch(1 0 0 / 0.45);
  font:
    600 0.7rem/1 ui-monospace,
    monospace;
}
.mono-day-copy h2 {
  margin-top: 1.3rem;
  font-size: clamp(3rem, 5vw, 5.5rem);
  font-weight: 500;
  line-height: 1.1;
}
.mono-day-copy p {
  max-width: 32rem;
  margin-top: 1.5rem;
  color: oklch(1 0 0 / 0.6);
  line-height: 1.9;
}
.mono-day-stage {
  min-width: 0;
  border: 1px solid oklch(1 0 0 / 0.22);
  background: oklch(1 0 0 / 0.035);
}
.mono-day-focus {
  display: grid;
  min-height: 27rem;
  grid-template-columns: 0.86fr 1.14fr;
  animation: mono-stage-in 0.55s var(--ease-enter) both;
}
@keyframes mono-stage-in {
  from {
    opacity: 0;
    transform: translateY(1rem);
  }
}
.mono-day-focus > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
  filter: grayscale(1) contrast(1.1);
}
.mono-day-focus > div {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 2rem;
}
.mono-day-focus time {
  font:
    500 2.6rem/1 ui-monospace,
    monospace;
}
.mono-day-focus small {
  margin-top: 1rem;
  color: oklch(1 0 0 / 0.48);
}
.mono-day-focus h3 {
  margin-top: 1.2rem;
  font-size: 2rem;
}
.mono-day-focus p {
  margin-top: 0.65rem;
  color: oklch(1 0 0 / 0.65);
  font-size: 0.8rem;
  line-height: 1.8;
}
.mono-day-focus span {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-top: 2rem;
  font-size: 0.65rem;
}
.mono-day-focus span i {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: oklch(1 0 0);
  animation: mono-pulse-white 2s infinite;
}
@keyframes mono-pulse-white {
  50% {
    box-shadow: 0 0 0 0.4rem oklch(1 0 0 / 0.1);
  }
}
.mono-day-timeline {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  border-top: 1px solid oklch(1 0 0 / 0.18);
}
.mono-day-timeline button {
  height: 4.4rem;
  border-inline-start: 1px solid oklch(1 0 0 / 0.13);
  border-radius: 0;
  color: oklch(1 0 0 / 0.48);
}
.mono-day-timeline button.is-active {
  background: oklch(1 0 0);
  color: var(--mono-black);
}
.mono-day-timeline time,
.mono-day-timeline span {
  display: block;
  font-size: 0.58rem;
}
.mono-day-timeline span {
  margin-top: 0.2rem;
}
.mono-day-copy > a,
.mono-inline-link {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 1.5rem;
  border-bottom: 1px solid currentColor;
  padding-bottom: 0.25rem;
  font-size: 0.75rem;
  font-weight: 700;
}
.mono-day-copy > a svg,
.mono-inline-link svg {
  width: 0.9rem;
}
.mono-real-media {
  position: relative;
  display: block;
  overflow: hidden;
  border: 1px solid var(--mono-black);
  background: var(--mono-soft);
  box-shadow:
    18px 18px 0 var(--mono-soft),
    18px 18px 0 1px var(--mono-line);
  isolation: isolate;
}
.mono-real-media img,
.mono-real-media video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top center;
  filter: grayscale(1);
  transition:
    filter 0.45s ease,
    transform 1.1s var(--ease-enter);
}
.mono-real-media:hover img,
.mono-real-media:hover video {
  filter: grayscale(0);
  transform: scale(1.018);
}
.mono-real-media > span {
  position: absolute;
  z-index: 2;
  right: 1rem;
  bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid var(--mono-black);
  background: oklch(1 0 0 / 0.94);
  padding: 0.65rem 0.8rem;
  color: var(--mono-black);
  font-size: 0.65rem;
  font-weight: 700;
  backdrop-filter: blur(10px);
}
.mono-real-media > span i {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 50%;
  background: currentColor;
  animation: mono-pulse 2s infinite;
}
.mono-real-media > span svg {
  width: 0.85rem;
}
.mono-real-media.is-hero {
  aspect-ratio: 16 / 10;
  box-shadow:
    22px 22px 0 var(--mono-soft),
    22px 22px 0 1px var(--mono-line);
}
.mono-real-media.is-hero video {
  object-position: center;
}
.mono-real-media.is-tour {
  aspect-ratio: 16 / 10;
  border-color: oklch(1 0 0 / 0.28);
  box-shadow:
    20px 20px 0 oklch(1 0 0 / 0.04),
    20px 20px 0 1px oklch(1 0 0 / 0.12);
}
.mono-real-media.is-tour > span,
.mono-real-media.is-dark > span {
  border-color: oklch(1 0 0 / 0.3);
  background: oklch(0.12 0 0 / 0.92);
  color: oklch(1 0 0);
}
.mono-real-media.is-wide {
  aspect-ratio: 16 / 9;
  margin-top: 4rem;
}
.mono-real-media.is-wide img {
  object-position: top center;
}
.mono-real-media.is-dark {
  aspect-ratio: 4 / 3;
  border-color: oklch(1 0 0 / 0.25);
  box-shadow:
    18px 18px 0 oklch(1 0 0 / 0.04),
    18px 18px 0 1px oklch(1 0 0 / 0.12);
}

.mono-siraj-section {
  background: var(--mono-soft);
}
.mono-studio {
  margin-top: 4rem;
  box-shadow:
    18px 18px 0 oklch(0.9 0 0),
    18px 18px 0 1px var(--mono-line);
}
.mono-studio-body {
  display: grid;
  grid-template-columns: 13rem 1fr;
  min-height: 39rem;
}
.mono-studio-body > aside {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem 1rem;
  border-inline-end: 1px solid var(--mono-line);
  background: var(--mono-soft);
  text-align: center;
}
.mono-studio-body > aside img {
  width: 6rem;
  height: 6rem;
  object-fit: cover;
  filter: grayscale(1);
}
.mono-studio-body > aside > strong {
  margin-top: 1rem;
  font-size: 1.25rem;
}
.mono-studio-body > aside > span {
  color: var(--mono-mid);
  font-size: 0.68rem;
}
.mono-studio-body > aside > div {
  display: grid;
  width: 100%;
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--mono-line);
}
.mono-studio-body > aside b {
  font-size: 2rem;
}
.mono-studio-body > aside small {
  color: var(--mono-mid);
}
.mono-studio-chat {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1rem;
  padding: 2rem;
}
.mono-message {
  max-width: 78%;
  padding: 1rem;
  border: 1px solid var(--mono-line);
}
.mono-message > span {
  color: var(--mono-mid);
  font-size: 0.6rem;
}
.mono-message p {
  margin-top: 0.5rem;
  font-size: 0.82rem;
  line-height: 1.75;
}
.mono-message.is-owner {
  align-self: flex-start;
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-message.is-owner > span {
  color: oklch(1 0 0 / 0.55);
}
.mono-message.is-siraj {
  animation: mono-message-in 0.45s var(--ease-enter) both;
}
.mono-message footer {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin-top: 0.8rem;
}
.mono-message footer span {
  border: 1px solid var(--mono-line);
  padding: 0.2rem 0.4rem;
  color: var(--mono-mid);
  font-size: 0.54rem;
}
@keyframes mono-message-in {
  from {
    opacity: 0;
    transform: translateY(0.8rem);
  }
}
.mono-thinking {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  color: var(--mono-graphite);
  font-size: 0.7rem;
}
.mono-thinking svg {
  width: 1rem;
  animation: spin 1s linear infinite;
}
.mono-thinking i {
  width: 0.3rem;
  height: 0.3rem;
  border-radius: 50%;
  background: var(--mono-black);
  animation: mono-dot 1.1s ease-in-out infinite;
}
.mono-thinking i:nth-of-type(2) {
  animation-delay: 0.14s;
}
.mono-thinking i:nth-of-type(3) {
  animation-delay: 0.28s;
}
@keyframes mono-dot {
  50% {
    transform: translateY(-0.3rem);
    opacity: 0.3;
  }
}
.mono-scheduled {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0.8rem 1rem;
  border: 1px solid var(--mono-black);
  background: var(--mono-soft);
  animation: mono-message-in 0.4s both;
}
.mono-scheduled svg {
  width: 1.2rem;
}
.mono-scheduled span,
.mono-scheduled strong,
.mono-scheduled small {
  display: block;
}
.mono-scheduled strong {
  font-size: 0.72rem;
}
.mono-scheduled small {
  color: var(--mono-mid);
  font-size: 0.6rem;
}
.mono-composer {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.75rem;
  margin-top: auto;
  padding: 0.85rem;
  border: 1px solid var(--mono-black);
}
.mono-composer label {
  grid-column: 1 / -1;
  color: var(--mono-mid);
  font-size: 0.58rem;
}
.mono-composer textarea {
  min-height: 3rem;
  resize: none;
  border: 0;
  outline: none;
  background: transparent;
  font-size: 0.78rem;
  line-height: 1.6;
}
.mono-composer button {
  align-self: end;
  border-radius: 0;
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-composer button svg {
  width: 1rem;
}
.mono-approval-row {
  display: flex;
  justify-content: flex-end;
  gap: 0.6rem;
}
.mono-approval-row button {
  border-radius: 0;
}
.mono-approval-row button:last-child {
  background: var(--mono-black);
  color: oklch(1 0 0);
}

.mono-handoff {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 5rem;
  border-block: 1px solid var(--mono-line);
}
.mono-handoff-line {
  position: absolute;
  z-index: 0;
  top: 7rem;
  right: 12.5%;
  left: 12.5%;
  height: 1px;
  background: var(--mono-line);
  direction: rtl;
}
.mono-handoff-line i {
  display: block;
  width: 100%;
  height: 100%;
  transform: scaleX(0);
  transform-origin: right;
  background: var(--mono-black);
  transition: transform 0.6s var(--ease-enter);
}
.mono-handoff-line.progress-1 i {
  transform: scaleX(0.333);
}
.mono-handoff-line.progress-2 i {
  transform: scaleX(0.666);
}
.mono-handoff-line.progress-3 i {
  transform: scaleX(1);
}
.mono-handoff button {
  position: relative;
  z-index: 1;
  display: flex;
  height: 20rem;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 0.8rem;
  padding: 1.4rem;
  border-inline-start: 1px solid var(--mono-line);
  border-radius: 0;
  color: var(--mono-black);
  white-space: normal;
}
.mono-handoff button:first-of-type {
  border-inline-start: 0;
}
.mono-handoff button:hover {
  background: var(--mono-soft);
}
.mono-handoff button > img {
  width: 5rem;
  height: 5rem;
  margin-top: 2.6rem;
  object-fit: cover;
  filter: grayscale(1);
  opacity: 0.35;
  transition:
    opacity 0.3s,
    filter 0.3s;
}
.mono-handoff button.is-complete > img {
  opacity: 1;
  filter: grayscale(1) contrast(1.1);
}
.mono-step-index {
  color: var(--mono-mid);
  font:
    600 0.65rem/1 ui-monospace,
    monospace;
}
.mono-handoff button > span:last-child {
  display: grid;
  text-align: right;
}
.mono-handoff strong {
  font-size: 1.1rem;
}
.mono-handoff small {
  color: var(--mono-mid);
  font-size: 0.65rem;
}
.mono-handoff em {
  margin-top: 0.6rem;
  font-style: normal;
  font-size: 0.6rem;
  font-weight: 700;
}

.mono-network-section {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-network-layout {
  display: grid;
  grid-template-columns: 0.75fr 1.25fr;
  align-items: center;
  gap: 5rem;
}
.mono-network-section .mono-section-head > span,
.mono-network-section .mono-section-head > p {
  color: oklch(1 0 0 / 0.54);
}
.mono-network-section .mono-section-head > a {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: 1.5rem;
  border-bottom: 1px solid currentColor;
  padding-bottom: 0.2rem;
  font-size: 0.75rem;
}
.mono-network-section .mono-section-head > a svg {
  width: 0.85rem;
}
.mono-network {
  position: relative;
  min-height: 38rem;
  border: 1px solid oklch(1 0 0 / 0.2);
  background-image:
    linear-gradient(to left, oklch(1 0 0 / 0.06) 1px, transparent 1px),
    linear-gradient(to bottom, oklch(1 0 0 / 0.06) 1px, transparent 1px);
  background-size: 3.5rem 3.5rem;
}
.mono-network::before,
.mono-network::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  border: 1px solid oklch(1 0 0 / 0.14);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}
.mono-network::before {
  width: 18rem;
  height: 18rem;
}
.mono-network::after {
  width: 29rem;
  height: 29rem;
}
.mono-network-core {
  position: absolute;
  z-index: 3;
  top: 50%;
  left: 50%;
  display: grid;
  width: 8rem;
  height: 8rem;
  place-content: center;
  justify-items: center;
  border: 1px solid oklch(1 0 0 / 0.5);
  background: var(--mono-black);
  transform: translate(-50%, -50%);
}
.mono-network-core svg {
  width: 1.2rem;
}
.mono-network-core strong {
  margin-top: 0.4rem;
  font-size: 1.2rem;
}
.mono-network-core small {
  color: oklch(1 0 0 / 0.5);
  font-size: 0.55rem;
}
.mono-network button {
  position: absolute;
  z-index: 2;
  height: 2.5rem;
  border-color: oklch(1 0 0 / 0.22);
  border-radius: 0;
  background: var(--mono-black);
  color: oklch(1 0 0 / 0.55);
  font-size: 0.62rem;
  transition:
    background 0.25s,
    color 0.25s,
    transform 0.25s;
}
.mono-network button svg {
  width: 0.7rem;
}
.mono-network button.is-active {
  background: oklch(1 0 0);
  color: var(--mono-black);
  transform: translateY(-3px);
}
.mono-network .app-1 {
  top: 9%;
  left: 12%;
}
.mono-network .app-2 {
  top: 10%;
  right: 11%;
}
.mono-network .app-3 {
  top: 43%;
  left: 3%;
}
.mono-network .app-4 {
  top: 43%;
  right: 4%;
}
.mono-network .app-5 {
  bottom: 9%;
  left: 11%;
}
.mono-network .app-6 {
  bottom: 10%;
  right: 10%;
}
.mono-network .app-7 {
  top: 24%;
  left: 38%;
}
.mono-network .app-8 {
  bottom: 22%;
  right: 38%;
}
.mono-data-pulse {
  position: absolute;
  z-index: 4;
  top: 50%;
  left: 50%;
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: oklch(1 0 0);
  animation: mono-orbit 6s linear infinite;
}
@keyframes mono-orbit {
  from {
    transform: translate(-50%, -50%) rotate(0) translateX(9rem);
  }
  to {
    transform: translate(-50%, -50%) rotate(360deg) translateX(9rem);
  }
}
.mono-product-scenes {
  background: oklch(1 0 0);
}
.mono-scenes-grid {
  display: grid;
  gap: 1px;
  margin-top: 5rem;
  border: 1px solid var(--mono-line);
  background: var(--mono-line);
}
.mono-scene-card {
  display: grid;
  min-height: 34rem;
  grid-template-columns: 0.68fr 1.32fr;
  overflow: hidden;
  background: oklch(1 0 0);
}
.mono-scene-card > div {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(2rem, 4vw, 4rem);
}
.mono-scene-card > div > span {
  color: var(--mono-mid);
  font:
    600 0.65rem/1 ui-monospace,
    monospace;
}
.mono-scene-card h3 {
  max-width: 24rem;
  margin-top: 1.2rem;
  font-size: clamp(2rem, 3.5vw, 3.7rem);
  line-height: 1.15;
}
.mono-scene-card p {
  max-width: 27rem;
  margin-top: 1rem;
  color: var(--mono-graphite);
  line-height: 1.9;
}
.mono-scene-card b {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 2rem;
  font-size: 0.72rem;
}
.mono-scene-card b svg {
  width: 0.9rem;
}
.mono-scene-card figure {
  position: relative;
  overflow: hidden;
  min-width: 0;
  border-inline-start: 1px solid var(--mono-line);
}
.mono-scene-card video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top center;
  filter: grayscale(1);
  transition:
    filter 0.45s ease,
    transform 1s var(--ease-enter);
}
.mono-scene-card:hover video {
  filter: grayscale(0);
  transform: scale(1.018);
}
.mono-scene-card figcaption {
  position: absolute;
  right: 1rem;
  bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  border: 1px solid var(--mono-black);
  padding: 0.55rem 0.7rem;
  background: oklch(1 0 0 / 0.94);
  color: var(--mono-black);
  font-size: 0.6rem;
  font-weight: 700;
}
.mono-scene-card figcaption i {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: currentColor;
  animation: mono-pulse 2s infinite;
}
.mono-scene-card:nth-child(even) > div {
  order: 2;
}
.mono-scene-card:nth-child(even) figure {
  border-inline-start: 0;
  border-inline-end: 1px solid var(--mono-line);
}
.mono-section-video {
  margin-bottom: 2.5rem;
}

.mono-use-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  margin-top: 5rem;
  border-top: 1px solid var(--mono-line);
  border-inline-start: 1px solid var(--mono-line);
}
.mono-use-grid a {
  position: relative;
  min-height: 18rem;
  padding: 2rem;
  border-inline-end: 1px solid var(--mono-line);
  border-bottom: 1px solid var(--mono-line);
  transition:
    background 0.25s,
    color 0.25s;
}
.mono-use-grid a:hover {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-use-grid a > span {
  color: var(--mono-mid);
  font:
    600 0.65rem/1 ui-monospace,
    monospace;
}
.mono-use-grid small {
  display: block;
  margin-top: 4rem;
  color: var(--mono-mid);
}
.mono-use-grid h3 {
  max-width: 25rem;
  margin-top: 0.7rem;
  font-size: 1.7rem;
  line-height: 1.4;
}
.mono-use-grid svg {
  position: absolute;
  left: 2rem;
  bottom: 2rem;
  width: 1.2rem;
}
.mono-pricing {
  background: var(--mono-soft);
}
.mono-plan-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 5rem;
  border-top: 1px solid var(--mono-black);
  border-inline-start: 1px solid var(--mono-black);
}
.mono-plan-grid article {
  display: flex;
  min-height: 34rem;
  flex-direction: column;
  padding: 2rem;
  border-inline-end: 1px solid var(--mono-black);
  border-bottom: 1px solid var(--mono-black);
  background: oklch(1 0 0);
}
.mono-plan-grid article.is-highlight {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-plan-grid article > span {
  color: var(--mono-mid);
  font-size: 0.65rem;
}
.mono-plan-grid h3 {
  margin-top: 0.7rem;
  font-size: 1.8rem;
}
.mono-plan-grid article > div {
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
  margin-top: 2rem;
}
.mono-plan-grid article > div strong {
  font-size: 3.4rem;
  line-height: 1;
}
.mono-plan-grid article > div strong.is-text {
  font-size: 2rem;
}
.mono-plan-grid article > div small {
  color: var(--mono-mid);
  font-size: 0.6rem;
}
.mono-plan-grid article > p {
  min-height: 4rem;
  margin-top: 1.4rem;
  color: var(--mono-mid);
  font-size: 0.78rem;
  line-height: 1.7;
}
.mono-plan-grid ul {
  display: grid;
  gap: 0.8rem;
  margin-top: 1.5rem;
}
.mono-plan-grid li {
  display: flex;
  gap: 0.45rem;
  font-size: 0.72rem;
}
.mono-plan-grid li svg {
  width: 0.85rem;
  flex: none;
}
.mono-plan-grid article > a {
  display: flex;
  min-height: 3.1rem;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  border: 1px solid currentColor;
  padding-inline: 1rem;
  font-size: 0.72rem;
  font-weight: 700;
}
.mono-plan-grid article > a svg {
  width: 0.9rem;
}
.mono-plan-grid article:not(.is-highlight) > a:hover {
  background: var(--mono-black);
  color: oklch(1 0 0);
}
.mono-faq-layout {
  display: grid;
  grid-template-columns: 0.75fr 1.25fr;
  gap: 6rem;
}
.mono-faq [data-slot="accordion-item"] {
  border-color: var(--mono-line);
}
.mono-faq [data-slot="accordion-trigger"] {
  padding-block: 1.4rem;
  font-size: 0.9rem;
}
.mono-faq [data-slot="accordion-content"] {
  color: var(--mono-graphite);
  line-height: 1.9;
}
.mono-final {
  position: relative;
  min-height: 42rem;
  display: grid;
  place-items: center;
  overflow: hidden;
  text-align: center;
}
.mono-final .mono-shell {
  position: relative;
  z-index: 2;
}
.mono-final .mono-shell > span {
  color: var(--mono-mid);
  font:
    600 0.7rem/1 ui-monospace,
    monospace;
}
.mono-final h2 {
  margin-top: 1rem;
  font-size: clamp(3.5rem, 7vw, 7.2rem);
  font-weight: 600;
  line-height: 1.04;
}
.mono-final a {
  width: fit-content;
  margin: 2rem auto 0;
}
.mono-final p {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  margin-top: 1rem;
  color: var(--mono-mid);
  font-size: 0.65rem;
}
.mono-final p svg {
  width: 0.8rem;
}

@media (max-width: 980px) {
  .mono-hero {
    min-height: auto;
    padding-top: 9rem;
  }
  .mono-hero-grid,
  .mono-day-layout,
  .mono-network-layout,
  .mono-faq-layout {
    grid-template-columns: 1fr;
  }
  .mono-hero-product {
    margin-top: 1rem;
    transform: none;
  }
  .mono-team-grid {
    grid-template-columns: repeat(2, 1fr);
  }
