/* ————— الدردشة: دخول الرسائل، مؤشر التفكير، ووميض التحميل ————— */
@keyframes bubble-in {
  from {
    transform: translateY(10px) scale(0.98);
    opacity: 0;
  }
  to {
    transform: translateY(0) scale(1);
    opacity: 1;
  }
}

@keyframes think-dot {
  0%,
  80%,
  100% {
    transform: translateY(0) scale(0.85);
    opacity: 0.35;
  }
  40% {
    transform: translateY(-4px) scale(1);
    opacity: 1;
  }
}

@keyframes shimmer-x {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}

@keyframes pop-in {
  from {
    transform: translateY(12px) scale(0.97);
    opacity: 0;
  }
  to {
    transform: translateY(0) scale(1);
    opacity: 1;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@utility animate-bubble-in {
  animation: bubble-in 0.45s var(--ease-enter) both;
}

@utility animate-pop-in {
  animation: pop-in 0.35s var(--ease-enter) both;
}

@utility animate-fade-in {
  animation: fade-in 0.25s ease-out both;
}

@utility think-dot {
  animation: think-dot 1.3s ease-in-out infinite;
}

@utility shimmer-line {
  background-image: linear-gradient(
    90deg,
    color-mix(in oklab, var(--secondary) 100%, transparent) 0%,
    color-mix(in oklab, var(--primary) 18%, var(--secondary)) 50%,
    color-mix(in oklab, var(--secondary) 100%, transparent) 100%
  );
  background-size: 200% 100%;
  animation: shimmer-x 1.8s linear infinite;
}

@utility shimmer-text {
  background-image: linear-gradient(
    90deg,
    var(--muted-foreground) 0%,
    var(--primary) 50%,
    var(--muted-foreground) 100%
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: shimmer-x 2.2s linear infinite;
}

@utility bubble-user {
  background-image: linear-gradient(
    150deg,
    color-mix(in oklab, var(--foreground) 88%, var(--jade-deep)) 0%,
    var(--foreground) 100%
  );
}

@utility no-scrollbar {
  scrollbar-width: none;
  &::-webkit-scrollbar {
    display: none;
  }
}

/* ————— Homepage & auth experience ————— */
.ambient-field {
  --smoke-scroll: 0px;
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  isolation: isolate;
  background:
    radial-gradient(
      circle at 50% 0%,
      color-mix(in oklab, var(--amber) 14%, transparent),
      transparent 45%
    ),
    linear-gradient(
      180deg,
      color-mix(in oklab, var(--background) 45%, transparent),
      var(--background)
    );
}

.ambient-cloud {
  position: absolute;
  width: min(58rem, 90vw);
  aspect-ratio: 1.5;
  border-radius: 48% 52% 62% 38%;
  filter: blur(72px);
  opacity: 0.32;
  transform: translate3d(0, var(--smoke-scroll), 0);
  will-change: transform;
  mix-blend-mode: multiply;
}

.dark .ambient-cloud {
  mix-blend-mode: screen;
  opacity: 0.18;
}
.ambient-cloud-a {
  inset: -10% auto auto -18%;
  background: color-mix(in oklab, var(--primary) 62%, var(--amber));
  animation: smoke-drift-a 22s ease-in-out infinite alternate;
}
.ambient-cloud-b {
  inset: 18% -24% auto auto;
  background: color-mix(in oklab, var(--primary) 48%, var(--amber));
  animation: smoke-drift-b 27s ease-in-out infinite alternate;
}
.ambient-cloud-c {
  inset: auto 20% -22% auto;
  background: color-mix(in oklab, var(--amber) 68%, var(--coral));
  animation: smoke-drift-a 31s ease-in-out infinite alternate-reverse;
}
.ambient-field-quiet .ambient-cloud {
  opacity: 0.2;
}
.ambient-grain {
  position: absolute;
  inset: 0;
  opacity: 0.2;
  background-image: radial-gradient(
    circle,
    color-mix(in oklab, var(--foreground) 18%, transparent) 0.55px,
    transparent 0.75px
  );
  background-size: 6px 6px;
  mask-image: linear-gradient(to bottom, black, transparent 85%);
}

@keyframes smoke-drift-a {
  to {
    translate: 12% 7%;
    rotate: 7deg;
    scale: 1.08;
  }
}
@keyframes smoke-drift-b {
  to {
    translate: -10% 12%;
    rotate: -8deg;
    scale: 0.92;
  }
}

.liquid-glass {
  --glass-x: 50%;
  --glass-y: 50%;
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background:
    radial-gradient(
      circle at var(--glass-x) var(--glass-y),
      color-mix(in oklab, var(--card) 92%, transparent),
      transparent 34%
    ),
    color-mix(in oklab, var(--card) 67%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 92%, transparent),
    var(--shadow-card);
  backdrop-filter: blur(24px) saturate(145%);
}
.nav-liquid-glass {
  background: color-mix(in oklab, var(--card) 66%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
    var(--shadow-card);
  backdrop-filter: blur(22px) saturate(150%);
}
.nav-floating-control {
  border: 1px solid color-mix(in oklab, var(--primary-foreground) 18%, transparent);
  background: color-mix(in oklab, var(--foreground) 12%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--primary-foreground) 18%, transparent),
    0 0.45rem 1.4rem -0.8rem color-mix(in oklab, var(--foreground) 45%, transparent);
  backdrop-filter: blur(12px) saturate(125%);
}
.nav-floating-control:hover {
  background: color-mix(in oklab, var(--foreground) 22%, transparent);
}
.pricing-liquid-glass {
  background: color-mix(in oklab, var(--card) 68%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 94%, transparent),
    var(--shadow-card);
  backdrop-filter: blur(24px) saturate(145%);
}
.pricing-liquid-glass.is-highlight {
  background: color-mix(in oklab, var(--foreground) 90%, transparent);
}

/* ===== iOS liquid glass — mobile nav sheet ===== */
.nav-glass-sheet {
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--primary-foreground) 16%, transparent);
  border-radius: 1.6rem;
  background: linear-gradient(
    150deg,
    color-mix(in oklab, var(--card) 92%, transparent),
    color-mix(in oklab, var(--card) 80%, transparent)
  );
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--primary-foreground) 26%, transparent),
    inset 0 0 0 1px color-mix(in oklab, var(--card) 30%, transparent),
    0 26px 60px -26px color-mix(in oklab, var(--foreground) 60%, transparent),
    0 8px 20px -12px color-mix(in oklab, var(--foreground) 38%, transparent);
  backdrop-filter: blur(38px) saturate(180%);
  -webkit-backdrop-filter: blur(38px) saturate(180%);
}
.nav-glass-sheet::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(
      130% 70% at 12% -10%,
      color-mix(in oklab, var(--primary) 20%, transparent),
      transparent 55%
    ),
    radial-gradient(
      130% 70% at 90% 108%,
      color-mix(in oklab, var(--amber) 18%, transparent),
      transparent 55%
    );
  opacity: 0.7;
}
.nav-glass-sheet::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(
    115deg,
    transparent 30%,
    color-mix(in oklab, var(--primary-foreground) 26%, transparent) 46%,
    transparent 62%
  );
  background-size: 260% 260%;
  background-position: 120% 0%;
  opacity: 0;
  transition:
    opacity 0.6s ease,
    background-position 0.9s ease;
}
.nav-glass-sheet:hover::after {
  opacity: 0.55;
  background-position: -20% 0%;
}

.nav-glass-item {
  position: relative;
  border-radius: 0.95rem;
  transition:
    background 0.22s ease,
    transform 0.22s ease,
    color 0.22s ease;
}
.nav-glass-item:hover {
  background: color-mix(in oklab, var(--foreground) 9%, transparent);
  transform: translateY(-1px);
}
.nav-glass-item.is-active {
  background: color-mix(in oklab, var(--primary) 18%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--primary) 42%, transparent);
  color: var(--primary);
}
.nav-glass-cta {
  position: relative;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--foreground) 16%, transparent);
  background: color-mix(in oklab, var(--foreground) 8%, transparent);
  backdrop-filter: blur(12px) saturate(135%);
  transition:
    background 0.22s ease,
    transform 0.22s ease;
}
.nav-glass-cta:hover {
  background: color-mix(in oklab, var(--foreground) 16%, transparent);
  transform: translateY(-1px);
}
.nav-glass-cta-primary {
  border: 1px solid color-mix(in oklab, var(--primary) 40%, transparent);
  background: color-mix(in oklab, var(--primary) 86%, transparent);
  box-shadow:
    0 12px 26px -14px color-mix(in oklab, var(--primary) 80%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--primary-foreground) 30%, transparent);
  backdrop-filter: blur(14px) saturate(150%);
  transition:
    transform 0.22s ease,
    box-shadow 0.22s ease;
}
.nav-glass-cta-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 30px -14px color-mix(in oklab, var(--primary) 90%, transparent);
}
.nav-glass-cta-aurora {
  border: 1px solid color-mix(in oklab, var(--primary-foreground) 18%, transparent);
  background-image: var(--gradient-aurora);
  box-shadow:
    0 14px 30px -16px color-mix(in oklab, var(--primary) 70%, transparent),
    inset 0 1px 0 color-mix(in oklab, var(--primary-foreground) 26%, transparent);
  backdrop-filter: blur(14px) saturate(150%);
  transition:
    transform 0.22s ease,
    box-shadow 0.22s ease;
}
.nav-glass-cta-aurora:hover {
  transform: translateY(-1px);
  box-shadow: 0 18px 34px -16px color-mix(in oklab, var(--primary) 85%, transparent);
}
.nav-glass-divider {
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--foreground) 18%, transparent),
    transparent
  );
}
.nav-glass-sheet * {
  position: relative;
  z-index: 1;
}
@media (prefers-reduced-motion: reduce) {
  .nav-glass-sheet::after,
  .nav-glass-item,
  .nav-glass-cta,
  .nav-glass-cta-primary,
  .nav-glass-cta-aurora {
    transition: none;
  }
}

