  .cinematic-hero-content {
    left: 2.25rem;
    width: 48vw;
  }
  .cinematic-hero h1 {
    font-size: clamp(3rem, 6.5vw, 5rem);
  }
  .cinematic-stats {
    right: 2rem;
  }
}

