  .cinematic-employee,
  .cinematic-primary,
  .cinematic-secondary {
    transition-duration: 1ms;
  }
  .cinematic-hero-beam,
  .cinematic-progress i.is-active span,
  .cinematic-enter-1,
  .cinematic-enter-2,
  .cinematic-enter-3,
  .cinematic-enter-4,
  .cinematic-enter-5 {
