}

.orbit-employee {
  position: relative;
  display: flex;
  width: 100%;
  min-height: 5.25rem;
  align-items: center;
  gap: 0.75rem;
  border-radius: 1rem;
  padding: 0.7rem;
  animation: orbit-float 5s ease-in-out infinite;
  animation-delay: var(--float-delay);
  transition:
    border-color 280ms ease,
    box-shadow 280ms ease;
}
.orbit-connections .orbit-connection.is-active {
