  filter: drop-shadow(0 0 5px color-mix(in oklab, var(--primary) 78%, transparent));
}
.orbit-employee:hover {
  border-color: color-mix(in oklab, var(--employee-tone) 54%, var(--border));
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
    0 18px 38px -22px color-mix(in oklab, var(--employee-tone) 65%, transparent);
}
.orbit-portrait {
  position: relative;
  width: 3.5rem;
  height: 3.5rem;
