}
.orbit-slot.orbit-employee-1 {
  top: 4%;
  right: 14%;
}
.orbit-slot.orbit-employee-2 {
  top: 4%;
  left: 14%;
}
.orbit-slot.orbit-employee-3 {
  top: 40%;
  right: 1%;
}
.orbit-slot.orbit-employee-4 {
  top: 40%;
  left: 1%;
}
.orbit-slot.orbit-employee-5 {
  bottom: 2%;
  right: 14%;
}
.orbit-slot.orbit-employee-6 {
  bottom: 2%;
  left: 14%;
}
@keyframes orbit-float {
  50% {
    translate: 0 -7px;
  }
}

.impact-strip {
  position: relative;
  isolation: isolate;
  margin-top: -1px;
  overflow: hidden;
  padding: 4.25rem 0 5rem;
  background: linear-gradient(
    145deg,
    color-mix(in oklab, var(--secondary) 82%, var(--card)),
    color-mix(in oklab, var(--background) 72%, var(--card))
  );
}
.impact-strip::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -65% 55% 20% -20%;
  border-radius: 50%;
  background: color-mix(in oklab, var(--primary) 15%, transparent);
  filter: blur(90px);
}
.impact-strip::after {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 38% -12% -62% 58%;
  border-radius: 50%;
  background: color-mix(in oklab, var(--amber) 15%, transparent);
  filter: blur(95px);
}
.impact-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.15rem;
}
.impact-card {
  position: relative;
  min-height: 21rem;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--card) 80%, transparent);
  border-radius: 1.65rem;
  background: color-mix(in oklab, var(--card) 58%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
    inset 0 -1px 0 color-mix(in oklab, var(--foreground) 6%, transparent),
    0 22px 55px -32px color-mix(in oklab, var(--foreground) 38%, transparent);
  backdrop-filter: blur(28px) saturate(170%);
  opacity: 0;
  animation: impact-card-enter 700ms var(--ease-enter) forwards;
  animation-delay: var(--impact-delay);
  transition:
    transform 420ms var(--ease-enter),
    box-shadow 420ms ease,
    border-color 420ms ease;
}
.impact-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 48%;
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--card) 72%, transparent),
    transparent
  );
  pointer-events: none;
}
.impact-card::after {
  content: "";
  position: absolute;
  inset: -35% auto -35% -52%;
  width: 34%;
  rotate: 12deg;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--card) 68%, transparent),
    transparent
  );
  animation: impact-glint 7s ease-in-out infinite;
  animation-delay: calc(var(--impact-delay) + 1.2s);
  pointer-events: none;
}
.impact-card:hover {
  transform: translateY(-7px) scale(1.012);
  border-color: color-mix(in oklab, var(--primary) 24%, var(--card));
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 100%, transparent),
    0 30px 70px -34px color-mix(in oklab, var(--primary) 35%, transparent);
}
.impact-card-inner {
  position: relative;
  z-index: 1;
  display: flex;
  min-height: 21rem;
  height: 100%;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1.35rem 1.25rem 1.15rem;
}
.impact-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.6rem;
}
.impact-head-id {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}
.impact-icon-shell {
  display: grid;
  width: 2.1rem;
  height: 2.1rem;
  flex: none;
  place-items: center;
  border: 1px solid color-mix(in oklab, var(--primary) 15%, var(--card));
  border-radius: 0.7rem;
  color: var(--primary);
  background: color-mix(in oklab, var(--primary) 9%, var(--card));
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--card) 92%, transparent);
}
.impact-icon {
  width: 1rem;
}
.impact-title {
  color: color-mix(in oklab, var(--foreground) 74%, var(--muted-foreground));
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.impact-delta {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  border-radius: 999px;
  padding: 0.22rem 0.55rem;
  font-size: 0.66rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.impact-delta svg {
  width: 0.8rem;
  height: 0.8rem;
}
.impact-delta.is-up {
  color: var(--jade);
  border: 1px solid color-mix(in oklab, var(--jade) 26%, transparent);
  background: color-mix(in oklab, var(--jade) 12%, transparent);
}
.impact-delta.is-down {
  color: var(--primary);
  border: 1px solid color-mix(in oklab, var(--primary) 26%, transparent);
  background: color-mix(in oklab, var(--primary) 11%, transparent);
}
.impact-readout {
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  margin-top: 0.35rem;
}
.impact-value {
  color: var(--foreground);
  font-size: clamp(2rem, 2.7vw, 2.9rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.impact-unit {
  color: var(--muted-foreground);
  font-size: 0.68rem;
  font-weight: 700;
}
.impact-spark {
  width: 100%;
  height: 4.6rem;
  overflow: visible;
}
.impact-spark-area {
  fill: color-mix(in oklab, var(--jade) 16%, transparent);
}
.impact-spark-line {
  fill: none;
  stroke: var(--jade);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 240;
  stroke-dashoffset: 240;
  animation: impact-draw 1.5s var(--ease-enter) forwards;
  animation-delay: calc(var(--impact-delay) + 220ms);
}
.impact-spark-dot {
  fill: var(--card);
  stroke: var(--jade);
  stroke-width: 2.5;
  opacity: 0;
  animation: impact-dot 500ms ease forwards;
  animation-delay: calc(var(--impact-delay) + 1.5s);
}
.impact-spark.is-down .impact-spark-area {
  fill: color-mix(in oklab, var(--primary) 16%, transparent);
}
.impact-spark.is-down .impact-spark-line,
.impact-spark.is-down .impact-spark-dot {
  stroke: var(--primary);
}
.impact-label {
  color: var(--muted-foreground);
  font-size: 0.73rem;
  line-height: 1.7;
}
.impact-meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
  margin-top: auto;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  padding-top: 0.75rem;
}
.impact-meta dt {
  color: var(--muted-foreground);
  font-size: 0.62rem;
  font-weight: 700;
}
.impact-meta dd {
  margin-top: 0.15rem;
  color: var(--foreground);
  font-size: 0.82rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.impact-meta > div + div {
  text-align: end;
}
@keyframes impact-draw {
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes impact-dot {
  to {
    opacity: 1;
  }
}
@keyframes impact-card-enter {
  from {
    opacity: 0;
    translate: 0 18px;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes impact-glint {
  0%,
  68% {
    translate: 0;
    opacity: 0;
  }
  77% {
    opacity: 0.75;
  }
  92%,
  100% {
    translate: 570%;
    opacity: 0;
  }
}
@keyframes impact-bars {
  50% {
    scale: 1 0.7;
    opacity: 0.68;
  }
}
@keyframes impact-ring {
  50% {
    rotate: 5deg;
    scale: 1.035;
  }
}
@keyframes impact-day {
  50% {
    scale: 1 0.82;
    opacity: 0.72;
  }
}
@keyframes impact-task {
  50% {
    opacity: 0.45;
    scale: 0.92 1;
  }
}

/* ===== Daily flow timeline (replaces impact cards) ===== */
.flow-head {
  max-width: 44rem;
  margin-inline: auto;
  text-align: center;
}
.flow-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  border: 1px solid color-mix(in oklab, var(--jade) 26%, transparent);
  border-radius: 999px;
  padding: 0.3rem 0.7rem;
  color: var(--jade);
  font-size: 0.7rem;
  font-weight: 800;
  background: color-mix(in oklab, var(--jade) 10%, transparent);
}
.flow-chip-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 999px;
  background: var(--jade);
  box-shadow: 0 0 0 0 color-mix(in oklab, var(--jade) 60%, transparent);
  animation: flow-pulse 2s ease-out infinite;
}
.flow-title {
  margin-top: 0.85rem;
  font-size: clamp(1.7rem, 3.4vw, 2.9rem);
  font-weight: 900;
  line-height: 1.2;
  letter-spacing: -0.02em;
}
.flow-sub {
  margin-top: 0.7rem;
  color: var(--muted-foreground);
  font-size: 0.95rem;
  line-height: 1.9;
}
.flow-panel {
  position: relative;
  margin-top: 2.4rem;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--card) 78%, transparent);
  border-radius: 1.75rem;
  padding: 2.6rem 1.9rem 1.6rem;
  background: color-mix(in oklab, var(--card) 56%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
    0 30px 70px -40px color-mix(in oklab, var(--foreground) 40%, transparent);
  backdrop-filter: blur(28px) saturate(170%);
}
.flow-panel::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 40%;
  background: linear-gradient(
    180deg,
    color-mix(in oklab, var(--card) 62%, transparent),
    transparent
  );
  pointer-events: none;
}
.flow-ruler {
  position: relative;
  height: 1.2rem;
  margin: 0 0 1.6rem 8.5rem;
  color: var(--muted-foreground);
  font-size: 0.66rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.flow-ruler span {
  position: absolute;
  translate: -50% 0;
}
.flow-lanes {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 0.2rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.flow-lane:first-child {
  border-top: 0;
}
.flow-lane {
  display: grid;
  grid-template-columns: 8.5rem 1fr;
  align-items: center;
  gap: 0.5rem;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 7%, transparent);
  padding: 1.15rem 0;
}
.flow-lane-name {
  color: color-mix(in oklab, var(--muted-foreground) 88%, transparent);
  font-size: 0.82rem;
  font-weight: 800;
  text-align: right;
  transition: color 400ms ease;
}
.flow-lane.is-active .flow-lane-name {
  color: var(--primary);
}
.flow-track {
  position: relative;
  height: 2rem;
  margin-inline: 0.55rem;
}
.flow-rail {
  position: absolute;
  inset: 50% 0 auto;
  height: 2px;
  translate: 0 -50%;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 11%, transparent);
}
.flow-rail-fill {
  position: absolute;
  inset: 50% auto auto 0;
  height: 2px;
  translate: 0 -50%;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--primary) 65%, transparent)
  );
  transition: width 900ms var(--ease-enter);
}
.flow-node {
  position: absolute;
  top: 50%;
  width: 0.85rem;
  height: 1.6rem;
  translate: -50% -50%;
  border: 2px solid color-mix(in oklab, var(--foreground) 16%, transparent);
  border-radius: 999px;
  background: color-mix(in oklab, var(--card) 45%, transparent);
  transition:
    border-color 420ms ease,
    background 420ms ease,
    scale 420ms var(--ease-enter),
    box-shadow 420ms ease;
}
.flow-node.is-on {
  border-color: color-mix(in oklab, var(--primary) 55%, transparent);
  background: color-mix(in oklab, var(--primary) 22%, transparent);
}
.flow-node.is-now {
  border-color: transparent;
  background: var(--primary);
  scale: 1.12;
  box-shadow:
    0 0 0 6px color-mix(in oklab, var(--primary) 14%, transparent),
    0 10px 26px -8px color-mix(in oklab, var(--primary) 65%, transparent);
}
.flow-tip {
  position: absolute;
  bottom: calc(100% + 1.35rem);
  left: 50%;
  translate: -50% 0;
  white-space: nowrap;
  border: 1px solid color-mix(in oklab, var(--primary) 22%, transparent);
  border-radius: 0.6rem;
  padding: 0.28rem 0.6rem;
  color: var(--primary);
  font-size: 0.7rem;
  font-weight: 800;
  background: color-mix(in oklab, var(--card) 88%, transparent);
  box-shadow: 0 14px 30px -18px color-mix(in oklab, var(--foreground) 55%, transparent);
  backdrop-filter: blur(14px);
  animation: flow-tip-in 420ms var(--ease-enter) both;
}
.flow-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.9rem;
  margin-top: 1.5rem;
}
.flow-kpis > div {
  border: 1px solid color-mix(in oklab, var(--card) 76%, transparent);
  border-radius: 1.1rem;
  padding: 1rem 1.05rem;
  background: color-mix(in oklab, var(--card) 48%, transparent);
  backdrop-filter: blur(20px) saturate(160%);
}
.flow-kpis dt {
  color: var(--foreground);
  font-size: clamp(1.25rem, 2.1vw, 1.75rem);
  font-weight: 900;
  letter-spacing: -0.02em;
}
.flow-kpis dd {
  margin: 0.2rem 0 0;
  color: var(--muted-foreground);
  font-size: 0.72rem;
  line-height: 1.6;
}
@keyframes flow-pulse {
  70% {
    box-shadow: 0 0 0 7px color-mix(in oklab, var(--jade) 0%, transparent);
  }
  100% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--jade) 0%, transparent);
  }
}
@keyframes flow-tip-in {
  from {
    opacity: 0;
    translate: -50% 6px;
  }
  to {
    opacity: 1;
    translate: -50% 0;
  }
}
@media (max-width: 767px) {
