}
.mena-map-orbit .mena-map-fill {
  fill: color-mix(in oklab, var(--primary) 22%, transparent);
}
.mena-map-orbit .mena-map-outline {
  stroke: color-mix(in oklab, var(--amber) 62%, var(--primary));
  stroke-width: 1.8;
  stroke-linejoin: round;
  stroke-dasharray: 1800;
  animation:
    mena-outline-draw 3.2s var(--ease-enter) both,
    mena-outline-glow 5s 3.2s ease-in-out infinite;
}
.mena-map-orbit .mena-map-borders {
  stroke: color-mix(in oklab, var(--amber) 34%, transparent);
  stroke-width: 0.9;
  stroke-dasharray: 3 4;
}
.mena-map-orbit .mena-map-aura {
  display: none;
}
.mena-map-orbit .mena-route {
  stroke: color-mix(in oklab, var(--amber) 62%, transparent);
  stroke-width: 1.6;
  stroke-dasharray: 3 9;
}
.mena-map-orbit .mena-capital-dot {
  stroke-width: 1.8;
}
.mena-map-orbit .mena-capital-pulse {
  animation-duration: 3.4s;
}
.mena-map-orbit .mena-place-labels {
  fill: color-mix(in oklab, var(--primary) 60%, var(--foreground));
  font-size: 11px;
  letter-spacing: 0.02em;
}

.mena-map-fill {
  fill: color-mix(in oklab, var(--primary) 6%, transparent);
}
.mena-map-outline {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 92%, transparent);
  stroke-width: 1.5;
  stroke-linejoin: round;
}
.mena-map-borders {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 30%, transparent);
  stroke-width: 0.7;
}
.mena-route {
  fill: none;
  stroke: color-mix(in oklab, var(--primary) 55%, transparent);
  stroke-width: 1.1;
  stroke-linecap: round;
  stroke-dasharray: 4 8;
  animation: mena-route-flow 9s linear infinite;
}
.mena-pulse {
  fill: var(--amber);
  filter: drop-shadow(0 0 6px color-mix(in oklab, var(--amber) 90%, transparent));
}
.mena-capital-dot {
  fill: var(--primary);
  stroke: color-mix(in oklab, var(--card) 88%, transparent);
  stroke-width: 1.4;
}
.mena-capital-pulse {
  fill: color-mix(in oklab, var(--primary) 26%, transparent);
  transform-box: fill-box;
  transform-origin: center;
  animation: mena-capital-pulse 2.8s ease-out infinite;
}
.mena-capital-hub .mena-capital-dot {
  fill: var(--amber);
}
.mena-capital-hub .mena-capital-pulse {
  fill: color-mix(in oklab, var(--amber) 30%, transparent);
}
.mena-map-aura {
  fill: color-mix(in oklab, var(--primary) 8%, transparent);
  filter: url(#mena-soft-glow);
}
.mena-map-scan {
  fill: none;
  stroke: color-mix(in oklab, var(--amber) 58%, transparent);
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-dasharray: 1 22;
  animation: mena-scan 8s linear infinite;
}
.mena-place-labels {
  fill: color-mix(in oklab, var(--foreground) 58%, transparent);
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 800;
}
@keyframes mena-route-flow {
  to {
    stroke-dashoffset: -60;
  }
}
@keyframes mena-scan {
  to {
    stroke-dashoffset: -184;
  }
}
@keyframes mena-capital-pulse {
  0% {
    scale: 0.45;
    opacity: 0.9;
  }
  75%,
  100% {
    scale: 1.65;
    opacity: 0;
  }
}
@keyframes mena-map-breathe {
  0%,
  100% {
    transform: translateY(0) scale(1);
  }
  50% {
    transform: translateY(-5px) scale(1.018);
  }
}
@keyframes mena-outline-draw {
  from {
    stroke-dashoffset: 1800;
    opacity: 0.35;
  }
  to {
    stroke-dashoffset: 0;
    opacity: 1;
  }
}
@keyframes mena-outline-glow {
  0%,
  100% {
    filter: drop-shadow(0 0 0 transparent);
  }
  50% {
    filter: drop-shadow(0 0 4px color-mix(in oklab, var(--primary) 48%, transparent));
  }
}

.dark .mena-map-fill {
  fill: color-mix(in oklab, var(--primary) 10%, transparent);
}
.dark .mena-map-outline {
  stroke: color-mix(in oklab, var(--primary) 85%, transparent);
}
.dark .mena-map-borders {
  stroke: color-mix(in oklab, var(--foreground) 22%, transparent);
}

@media (max-width: 768px) {
  .mena-map-layer {
    justify-content: center;
  }
  .mena-map-layer svg {
    width: 145%;
    margin-inline-end: 0;
    opacity: 0.58;
  }
  .mena-map-layer.mena-map-orbit svg {
    width: 100%;
    margin: 0;
    opacity: 1;
  }
}

/* مشهد الفريق المداري مباشرة فوق القسم الداكن، بلا غلاف */
.integration-team-stage {
  isolation: isolate;
}
.integration-team-stage::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 17% 10%;
  border-radius: 50%;
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  filter: blur(90px);
  pointer-events: none;
}
.integration-team-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-inline: 1rem;
  color: color-mix(in oklab, var(--background) 58%, transparent);
  font-size: 0.72rem;
}
.integration-team-status span {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--background);
  font-weight: 800;
}
.integration-team-status i {
  width: 0.48rem;
  height: 0.48rem;
  border-radius: 50%;
  background: var(--jade);
  box-shadow: 0 0 0 0.35rem color-mix(in oklab, var(--jade) 14%, transparent);
  animation: pulse-ring 2.4s infinite;
}
.integration-team-stage .team-orbit-compact {
  min-height: 36rem;
}
.integration-team-stage .orbit-slot.orbit-employee-5,
.integration-team-stage .orbit-slot.orbit-employee-6 {
  bottom: 7.5rem;
}
@media (min-width: 1024px) {
  .integration-team-stage .orbit-slot {
    width: min(14.5rem, 25%);
  }
  .integration-team-stage .orbit-map-center {
    width: 20rem;
    height: 12rem;
  }
}
@media (max-width: 640px) {
  .integration-team-stage .team-orbit-compact {
    min-height: 33rem;
  }
  .integration-team-stage .orbit-slot.orbit-employee-5,
  .integration-team-stage .orbit-slot.orbit-employee-6 {
    bottom: 7rem;
  }
  .integration-team-status {
    align-items: flex-start;
    flex-direction: column;
    padding-inline: 0;
  }
}

.team-orbit-dark {
  color: var(--background);
}
.team-orbit-dark .orbit-connection {
  stroke: color-mix(in oklab, var(--primary) 34%, transparent);
}
.team-orbit-dark .orbit-employee {
  border-color: color-mix(in oklab, var(--background) 12%, transparent);
  background: color-mix(in oklab, var(--background) 7%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--background) 13%, transparent),
    0 18px 45px -28px color-mix(in oklab, var(--primary) 45%, transparent);
  backdrop-filter: blur(20px) saturate(145%);
}
.team-orbit-dark .orbit-copy small {
  color: color-mix(in oklab, var(--background) 72%, transparent);
}
.team-orbit-dark .orbit-map-center > small {
  color: var(--amber);
}
.team-orbit-dark .orbit-map-center > small span {
  color: color-mix(in oklab, var(--background) 58%, transparent);
}
.team-orbit-dark .mena-map-orbit {
  color: var(--primary);
}
.team-orbit-dark .mena-map-fill {
  fill: url(#mena-land);
}
.team-orbit-dark .mena-map-outline {
  stroke: color-mix(in oklab, var(--primary) 92%, var(--background));
}
.team-orbit-dark .mena-map-borders {
  stroke: color-mix(in oklab, var(--background) 30%, transparent);
}
.team-orbit-dark .mena-place-labels {
  fill: color-mix(in oklab, var(--background) 60%, transparent);
}

.integration-team-glass {
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--background) 18%, transparent);
  background:
    radial-gradient(
      circle at 50% 0%,
      color-mix(in oklab, var(--background) 10%, transparent),
      transparent 54%
    ),
    color-mix(in oklab, var(--foreground) 90%, transparent);
  color: var(--background);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--background) 28%, transparent),
    0 24px 58px -30px color-mix(in oklab, var(--foreground) 75%, transparent);
  backdrop-filter: blur(24px) saturate(145%);
}
.integration-team-glass .integration-employee {
  border-color: color-mix(in oklab, var(--background) 13%, transparent);
  background: color-mix(in oklab, var(--background) 7%, transparent);
  color: var(--background);
}
.integration-team-glass .integration-employee span span {
  color: color-mix(in oklab, var(--background) 64%, transparent);
}
.integration-team-glass .integration-employee {
  animation-name: integration-employee-dark-active;
}
@keyframes integration-employee-dark-active {
  0%,
  38%,
  100% {
    border-color: color-mix(in oklab, var(--background) 13%, transparent);
    background-color: color-mix(in oklab, var(--background) 7%, transparent);
  }
  48%,
  68% {
    border-color: color-mix(in oklab, var(--primary) 58%, transparent);
    background-color: color-mix(in oklab, var(--primary) 22%, var(--foreground));
  }
}

@media (prefers-reduced-motion: reduce) {
  .mena-map-layer svg {
    opacity: 0.62;
  }
  .mena-route,
  .mena-capital-pulse,
  .orbit-map-center,
  .mena-map-orbit .mena-map-outline {
    animation: none;
  }
}

/* ===== إعادة تصميم أقسام الصفحة ===== */

/* 1) لماذا سهل — بينتو احترافي بنمط SaaS */
.features-section {
  position: relative;
  background:
    radial-gradient(
      120% 70% at 50% -10%,
      color-mix(in oklab, var(--primary) 10%, transparent),
      transparent 62%
    ),
    color-mix(in oklab, var(--secondary) 45%, transparent);
}
.features-section::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(
      to left,
      color-mix(in oklab, var(--foreground) 5%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      to bottom,
      color-mix(in oklab, var(--foreground) 5%, transparent) 1px,
      transparent 1px
    );
  background-size: 72px 72px;
  mask-image: radial-gradient(90% 60% at 50% 0%, #000, transparent 75%);
}
.features-section > * {
  position: relative;
}

.section-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--primary) 26%, var(--border));
  background: color-mix(in oklab, var(--primary) 10%, transparent);
  padding: 0.32rem 0.75rem;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: color-mix(in oklab, var(--primary) 78%, var(--foreground));
}

.compare-strip {
  display: grid;
  gap: 0.6rem;
  grid-template-columns: 1fr;
}
@media (min-width: 768px) {
  .compare-strip {
    grid-template-columns: repeat(3, 1fr);
  }
}
.compare-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.35rem;
  border-radius: 1rem;
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--card) 55%, transparent);
  padding: 0.75rem 0.9rem;
  font-size: 0.82rem;
}
.compare-bad,
.compare-good {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  line-height: 1.5;
}
.compare-bad {
  color: var(--muted-foreground);
  text-decoration: line-through;
  text-decoration-thickness: 1px;
  text-decoration-color: color-mix(in oklab, var(--muted-foreground) 60%, transparent);
}
.compare-good {
  font-weight: 800;
  color: color-mix(in oklab, var(--primary) 82%, var(--foreground));
}

.feature-glass-card {
  background: color-mix(in oklab, var(--card) 62%, transparent);
  backdrop-filter: blur(22px) saturate(145%);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 92%, transparent),
    var(--shadow-card);
  transition:
    transform 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.45s ease,
    border-color 0.45s ease;
}
.feature-glass-card:hover {
  transform: translateY(-6px);
  border-color: color-mix(in oklab, var(--primary) 38%, var(--border));
  box-shadow:
    var(--shadow-lift),
    0 0 0 1px color-mix(in oklab, var(--primary) 30%, transparent),
    0 0 26px -6px color-mix(in oklab, var(--primary) 40%, transparent);
}
.feature-spotlight {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.35s ease;
  background: radial-gradient(
    280px circle at var(--mx, 50%) var(--my, 0%),
    color-mix(in oklab, var(--primary) 16%, transparent),
    transparent 70%
  );
}
.feature-glass-card:hover .feature-spotlight {
  opacity: 1;
}
.feature-icon-shell {
  background: color-mix(in oklab, var(--jade) 12%, transparent);
  color: var(--jade-deep);
  transition:
    background-color 0.35s ease,
    color 0.35s ease;
}
.feature-glass-card:hover .feature-icon-shell {
  background: color-mix(in oklab, var(--primary) 88%, transparent);
  color: var(--background);
}

.feature-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}
.feature-tags li {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: color-mix(in oklab, var(--foreground) 4%, transparent);
  padding: 0.24rem 0.6rem;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--muted-foreground);
}
.feature-metric {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  border-top: 1px dashed color-mix(in oklab, var(--foreground) 14%, transparent);
  padding-top: 0.9rem;
}
.feature-metric strong {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 900;
  color: color-mix(in oklab, var(--primary) 85%, var(--foreground));
}
.feature-metric span {
  font-size: 0.78rem;
  color: var(--muted-foreground);
}

.feature-visual {
  margin-top: 1.25rem;
  border-radius: 1.1rem;
  border: 1px solid color-mix(in oklab, var(--foreground) 9%, transparent);
  background: color-mix(in oklab, var(--background) 55%, transparent);
  padding: 0.9rem;
}
.fv-line {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}
.fv-chip {
  border-radius: 999px;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  padding: 0.2rem 0.6rem;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--muted-foreground);
}
.fv-chip-active {
  border-color: transparent;
  background: color-mix(in oklab, var(--primary) 88%, transparent);
  color: var(--background);
}
.feature-glass-card:hover .fv-chip {
  animation: fv-cycle 4s ease-in-out infinite;
}
.feature-glass-card:hover .fv-chip:nth-child(2) {
  animation-delay: 1s;
}
.feature-glass-card:hover .fv-chip:nth-child(3) {
  animation-delay: 2s;
}
.feature-glass-card:hover .fv-chip:nth-child(4) {
  animation-delay: 3s;
}
@keyframes fv-cycle {
  0%,
  18%,
  100% {
    border-color: transparent;
    background: color-mix(in oklab, var(--primary) 88%, transparent);
    color: var(--background);
  }
  25%,
  95% {
    border-color: color-mix(in oklab, var(--foreground) 10%, transparent);
    background: transparent;
    color: var(--muted-foreground);
  }
}
.fv-card {
  margin-top: 0.75rem;
  border-radius: 0.9rem;
  background: color-mix(in oklab, var(--card) 80%, transparent);
  padding: 0.75rem 0.85rem;
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--card) 92%, transparent);
}
.fv-text {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 800;
}
.fv-bars {
  margin-top: 0.6rem;
  display: flex;
  gap: 0.35rem;
}
.fv-bars span {
  height: 6px;
  border-radius: 999px;
  background-image: var(--gradient-aurora);
  opacity: 0.55;
}
.fv-bars span:nth-child(1) {
  width: 46%;
}
.fv-bars span:nth-child(2) {
  width: 28%;
}
.fv-bars span:nth-child(3) {
  width: 14%;
}

.feature-visual-memory {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.fv-core {
  display: grid;
  place-items: center;
  width: 2.5rem;
  height: 2.5rem;
  flex: none;
  border-radius: 999px;
  background-image: var(--gradient-aurora);
  color: var(--background);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--primary) 12%, transparent);
}
.fv-nodes {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}
.fv-node {
  border-radius: 999px;
  border: 1px dashed color-mix(in oklab, var(--primary) 32%, transparent);
  background: color-mix(in oklab, var(--primary) 7%, transparent);
  padding: 0.22rem 0.6rem;
  font-size: 0.72rem;
  font-weight: 700;
  color: color-mix(in oklab, var(--primary) 78%, var(--foreground));
}
.feature-icon {
  transform-origin: center;
}
@keyframes feat-flip {
  0%,
  100% {
    transform: rotateY(0);
  }
  50% {
    transform: rotateY(180deg);
  }
}
@keyframes feat-play {
  0%,
  100% {
    transform: scale(1);
  }
  35% {
    transform: scale(1.22);
  }
  60% {
    transform: scale(0.94);
  }
}
@keyframes feat-spark {
  0%,
  100% {
    transform: translateY(0) rotate(0);
  }
  30% {
    transform: translateY(-3px) rotate(-8deg);
  }
  60% {
    transform: translateY(2px) rotate(6deg);
  }
}
@keyframes feat-stack {
  0%,
  100% {
    transform: translateY(0);
  }
  45% {
    transform: translateY(-4px) scale(1.06);
  }
}
@keyframes feat-tilt {
  0%,
  100% {
    transform: rotate(0);
  }
  40% {
    transform: rotate(-11deg);
  }
  70% {
    transform: rotate(5deg);
  }
}
@keyframes feat-lock {
  0%,
  100% {
    transform: translateY(0) scale(1);
  }
  30% {
    transform: translateY(-3px) scale(1.05);
  }
  55% {
    transform: translateY(0) scale(0.96);
  }
}
.feature-glass-card:hover .icon-flip {
  animation: feat-flip 1.1s ease-in-out;
}
.feature-glass-card:hover .icon-play {
  animation: feat-play 0.9s ease-in-out;
}
.feature-glass-card:hover .icon-spark {
  animation: feat-spark 0.9s ease-in-out;
}
.feature-glass-card:hover .icon-stack {
  animation: feat-stack 0.9s ease-in-out;
}
.feature-glass-card:hover .icon-tilt {
  animation: feat-tilt 0.9s ease-in-out;
}
.feature-glass-card:hover .icon-lock {
  animation: feat-lock 0.9s ease-in-out;
}

/* 2) كيف يعمل — خط زمني عمودي */
.timeline-list {
  --rail: 1.5rem;
}
.timeline-rail,
.timeline-rail-fill {
  position: absolute;
  top: 0.35rem;
  bottom: 0.35rem;
  inset-inline-start: var(--rail);
  width: 2px;
  border-radius: 2px;
}
.timeline-rail {
  background: color-mix(in oklab, var(--foreground) 12%, transparent);
}
.timeline-rail-fill {
  background-image: var(--gradient-aurora);
  transform-origin: top center;
  transition: transform 0.35s linear;
}
.timeline-step {
  padding-inline-start: 0;
}
.timeline-dot {
  position: absolute;
  top: 0;
  inset-inline-start: -3.4rem;
  display: grid;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 1rem;
  color: color-mix(in oklab, var(--foreground) 55%, transparent);
  background: var(--card);
  border: 2px solid color-mix(in oklab, var(--foreground) 14%, transparent);
  transition:
    color 0.5s ease,
    border-color 0.5s ease,
    background-color 0.5s ease,
    transform 0.5s ease;
}
.timeline-step.is-on .timeline-dot {
  color: var(--background);
  border-color: transparent;
  background-image: var(--gradient-ink);
  animation: timeline-ping 1.1s ease-out;
}
@keyframes timeline-ping {
  0% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--primary) 55%, transparent);
    transform: scale(0.9);
  }
  60% {
    transform: scale(1.06);
  }
  100% {
    box-shadow: 0 0 0 16px transparent;
    transform: scale(1);
  }
}
.timeline-title,
.timeline-body {
  opacity: 0;
  transform: translateX(18px);
  transition:
    opacity 0.6s ease,
    transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.timeline-body {
  transition-delay: 0.1s;
}
.timeline-step.is-on .timeline-title,
.timeline-step.is-on .timeline-body {
  opacity: 1;
  transform: translateX(0);
}

/* 3) شهادات — كاروسيل زجاجي */
.testimonial-track {
  display: flex;
  gap: 1.25rem;
  overflow-x: auto;
  scroll-snap-type: none;
  padding: 0.5rem 1.25rem 1.5rem;
  scrollbar-width: none;
}
.testimonial-track::-webkit-scrollbar {
  display: none;
}
@media (hover: none) {
  .testimonial-track.is-user {
    scroll-snap-type: x proximity;
  }
}
.testimonial-card {
  position: relative;
  flex: 0 0 auto;
  width: 22rem;
  max-width: 85vw;
  overflow: hidden;
  scroll-snap-align: center;
  border: 1px solid var(--border);
  border-radius: 1.5rem;
  padding: 1.75rem;
  transition:
    transform 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.45s ease;
}
.testimonial-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-lift);
}
.testimonial-quote-mark {
  position: absolute;
  inset-inline-start: -0.75rem;
  bottom: -1.25rem;
  width: 8rem;
  height: 8rem;
  color: color-mix(in oklab, var(--primary) 12%, transparent);
  pointer-events: none;
}

/* 4) التكاملات — شبكة نقطية متموجة وشرارات تدفق */
.integration-grid-wave::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at 50% 50%,
    color-mix(in oklab, var(--amber) 34%, transparent),
    transparent 45%
  );
  mask-image: radial-gradient(circle, oklch(1 0 0) 1px, transparent 1.5px);
  mask-size: 24px 24px;
  animation: dot-wave 9s ease-in-out infinite;
}
@keyframes dot-wave {
  0% {
    transform: translateX(-35%) scale(1.1);
    opacity: 0;
  }
  25%,
  60% {
    opacity: 0.85;
  }
  100% {
    transform: translateX(35%) scale(1.1);
    opacity: 0;
  }
}
.flow-spark {
  position: absolute;
  top: 50%;
  width: 7rem;
  height: 2px;
  border-radius: 2px;
  background: linear-gradient(
    to left,
    transparent,
    color-mix(in oklab, var(--amber) 90%, transparent),
    transparent
  );
  filter: blur(0.4px);
}
.flow-spark-in {
  right: 12%;
  animation: spark-in 4.4s ease-in-out infinite;
}
.flow-spark-out {
  left: 12%;
  animation: spark-out 4.4s ease-in-out infinite 1.4s;
}
@keyframes spark-in {
  0% {
    transform: translate(0, -50%);
    opacity: 0;
  }
  15%,
  70% {
    opacity: 1;
  }
  100% {
    transform: translate(190%, -50%);
    opacity: 0;
  }
}
@keyframes spark-out {
  0% {
    transform: translate(0, -50%);
    opacity: 0;
  }
  15%,
  70% {
    opacity: 1;
  }
  100% {
    transform: translate(-190%, -50%);
    opacity: 0;
  }
}
.status-dot {
  animation: status-pulse 2.2s ease-in-out infinite;
}
@keyframes status-pulse {
  0%,
  100% {
    opacity: 0.55;
    box-shadow: 0 0 0 0 currentColor;
  }
  50% {
    opacity: 1;
    box-shadow: 0 0 0 3px color-mix(in oklab, currentColor 22%, transparent);
  }
}

/* 5) الأسئلة الشائعة */
.faq-item {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 1.25rem;
  background: color-mix(in oklab, var(--card) 55%, transparent);
  backdrop-filter: blur(16px) saturate(140%);
  transition:
    background-color 0.45s ease,
    border-color 0.45s ease;
}
.faq-item::before {
  content: "";
  position: absolute;
  inset-inline-end: 0;
  top: 0.75rem;
  bottom: 0.75rem;
  width: 3px;
  border-radius: 3px;
  background-image: var(--gradient-aurora);
  opacity: 0;
  transform: scaleY(0.3);
  transform-origin: center;
  transition:
    opacity 0.4s ease,
    transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.faq-item:has([data-state="open"]) {
  background: color-mix(in oklab, var(--primary) 7%, var(--card));
  border-color: color-mix(in oklab, var(--primary) 28%, var(--border));
}
.faq-item:has([data-state="open"])::before {
  opacity: 1;
  transform: scaleY(1);
}
.faq-trigger {
  transition: color 0.3s ease;
}
.faq-trigger > svg {
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.faq-answer {
  animation: faq-fade 0.45s ease-out;
}
@keyframes faq-fade {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 6) بانر الدعوة */
@keyframes aurora-shift {
  0% {
    background-position: 0% 50%;
    filter: hue-rotate(0deg);
  }
  50% {
    background-position: 100% 45%;
    filter: hue-rotate(-6deg);
  }
  100% {
    background-position: 0% 50%;
    filter: hue-rotate(0deg);
  }
}
.cta-glow-button {
  animation: cta-glow 3.2s ease-in-out infinite;
}
@keyframes cta-glow {
  0%,
  100% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--card) 55%, transparent);
  }
  50% {
    box-shadow: 0 0 24px 6px color-mix(in oklab, var(--card) 40%, transparent);
  }
}

/* 7) الأسعار */
.pricing-glow {
  animation: pricing-glow 4.5s ease-in-out infinite;
}
@keyframes pricing-glow {
  0%,
  100% {
    box-shadow:
      var(--shadow-lift),
      0 0 22px -6px color-mix(in oklab, var(--primary) 40%, transparent);
  }
  50% {
    box-shadow:
      var(--shadow-lift),
      0 0 40px 2px color-mix(in oklab, var(--primary) 46%, transparent);
  }
}
.perk-row {
  animation: perk-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes perk-in {
  from {
    opacity: 0;
    transform: translateX(10px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .feature-glass-card:hover .feature-icon,
  .integration-grid-wave::after,
  .flow-spark,
  .status-dot,
  .cta-glow-button,
  .pricing-glow,
  .perk-row,
  .faq-answer,
  .timeline-step.is-on .timeline-dot {
    animation: none;
  }
  .timeline-title,
  .timeline-body {
    opacity: 1;
    transform: none;
  }
}

/* Orbit flow: travelling pulse + employee notification bubbles */
.orbit-travel-dot {
  fill: var(--primary);
  filter: drop-shadow(0 0 8px color-mix(in oklab, var(--primary) 85%, transparent));
}
.orbit-employee.is-lit {
  border-color: color-mix(in oklab, var(--employee-tone) 62%, var(--border));
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
    0 0 0 1px color-mix(in oklab, var(--employee-tone) 30%, transparent),
    0 22px 46px -24px color-mix(in oklab, var(--employee-tone) 75%, transparent);
}
.orbit-bubble {
  position: absolute;
  z-index: 6;
  inset: auto 0 calc(100% + 0.7rem) 0;
  display: grid;
  gap: 0.4rem;
  border: 1px solid color-mix(in oklab, var(--employee-tone, var(--primary)) 34%, transparent);
  border-radius: 1rem;
  padding: 0.6rem 0.72rem;
  background:
    linear-gradient(
      160deg,
      color-mix(in oklab, var(--employee-tone, var(--primary)) 12%, transparent),
      transparent 62%
    ),
    color-mix(in oklab, var(--card) 92%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 90%, transparent),
    0 22px 48px -24px color-mix(in oklab, var(--employee-tone, var(--primary)) 72%, transparent);
  backdrop-filter: blur(20px) saturate(160%);
  animation: orbit-bubble-in 420ms var(--ease-enter) both;
}
.orbit-commentary {
  position: absolute;
  z-index: 10;
  inset: auto 50% 0 auto;
  translate: 50% 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  width: min(31rem, calc(100% - 1rem));
  min-height: 5.4rem;
  align-items: center;
  gap: 0.45rem 0.75rem;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--employee-tone, var(--primary)) 32%, transparent);
  border-radius: 1rem;
  padding: 0.72rem 0.85rem;
  background: color-mix(in oklab, var(--card) 94%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--card) 96%, transparent),
    0 20px 46px -28px color-mix(in oklab, var(--employee-tone, var(--primary)) 72%, transparent);
  backdrop-filter: blur(24px) saturate(155%);
  animation: orbit-commentary-in 420ms var(--ease-enter) both;
}
.orbit-commentary::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--employee-tone, var(--primary)) 62%, transparent),
    transparent
  );
}
.orbit-commentary .orbit-bubble-head {
  grid-row: 1 / span 2;
}
.orbit-commentary .orbit-bubble-text,
.orbit-commentary .orbit-bubble-typing {
  grid-column: 2;
}
.orbit-commentary .orbit-bubble-apps {
  grid-column: 3;
  grid-row: 1;
  border: 0;
  padding: 0;
}
.orbit-commentary .orbit-bubble-foot {
  grid-column: 2 / 4;
}
.team-orbit-dark .orbit-commentary {
  border-color: color-mix(in oklab, var(--employee-tone, var(--primary)) 44%, transparent);
  background: color-mix(in oklab, var(--foreground) 91%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--background) 12%, transparent),
    0 22px 48px -24px color-mix(in oklab, var(--employee-tone, var(--primary)) 62%, transparent);
}
.team-orbit-dark .orbit-commentary .orbit-bubble-text {
  color: var(--background);
}
.team-orbit-dark .orbit-commentary .orbit-bubble-head {
  color: color-mix(in oklab, var(--employee-tone, var(--primary)) 62%, var(--background));
}
.team-orbit-dark .orbit-commentary .orbit-bubble-head b,
.team-orbit-dark .orbit-commentary .orbit-bubble-foot {
  color: color-mix(in oklab, var(--background) 58%, transparent);
}
@keyframes orbit-commentary-in {
  from {
    opacity: 0;
    translate: 50% 10px;
    scale: 0.97;
  }
  to {
    opacity: 1;
    translate: 50% 0;
    scale: 1;
  }
}
.orbit-bubble::after {
  content: "";
  position: absolute;
  z-index: -1;
  inset: auto 1.4rem -0.34rem auto;
  width: 0.7rem;
  height: 0.7rem;
  rotate: 45deg;
  border-inline-end: 1px solid
    color-mix(in oklab, var(--employee-tone, var(--primary)) 34%, transparent);
  border-block-end: 1px solid
    color-mix(in oklab, var(--employee-tone, var(--primary)) 34%, transparent);
  border-end-end-radius: 0.18rem;
  background: color-mix(in oklab, var(--card) 92%, transparent);
}
.orbit-bubble-avatar {
  position: relative;
  width: 1.65rem;
  height: 1.65rem;
  flex: none;
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--employee-tone, var(--primary)) 45%, transparent);
  border-radius: 0.6rem;
  background: color-mix(in oklab, var(--employee-tone, var(--primary)) 12%, transparent);
}
.orbit-bubble-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.orbit-bubble-avatar > i {
  position: absolute;
  inset: auto 0.08rem 0.08rem auto;
  width: 0.34rem;
  height: 0.34rem;
  border-radius: 50%;
  background: var(--jade);
  box-shadow: 0 0 0 1.5px color-mix(in oklab, var(--card) 90%, transparent);
}
.orbit-bubble-id {
  display: grid;
  min-width: 0;
  gap: 0.05rem;
  line-height: 1.15;
}
.orbit-bubble-id strong {
  font-family: var(--font-display);
  font-size: 0.7rem;
  font-weight: 900;
}
.orbit-bubble-apps {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding-top: 0.1rem;
  border-top: 1px solid color-mix(in oklab, var(--employee-tone, var(--primary)) 16%, transparent);
  opacity: 0.85;
}
.orbit-bubble-head {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  color: color-mix(in oklab, var(--employee-tone, var(--primary)) 78%, var(--foreground));
  font-family: var(--font-display);
  font-size: 0.68rem;
  font-weight: 900;
}
.orbit-bubble-head i {
  width: 0.4rem;
  height: 0.4rem;
  flex: none;
  border-radius: 50%;
  background: var(--jade);
  box-shadow: 0 0 0 0.22rem color-mix(in oklab, var(--jade) 15%, transparent);
}
.orbit-bubble-head b {
  overflow: hidden;
  color: var(--muted-foreground);
  font-family: inherit;
  font-size: 0.53rem;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.orbit-bubble-text {
  color: var(--foreground);
  font-size: 0.73rem;
  font-weight: 700;
  line-height: 1.5;
  animation: orbit-bubble-line 340ms var(--ease-enter) both;
}
.orbit-bubble-typing {
  display: flex;
  gap: 0.22rem;
  padding-block: 0.35rem;
}
.orbit-bubble-typing i {
  width: 0.28rem;
  height: 0.28rem;
  border-radius: 50%;
  background: color-mix(in oklab, var(--employee-tone, var(--primary)) 70%, transparent);
  animation: orbit-typing 1.1s ease-in-out infinite;
}
.orbit-bubble-typing i:nth-child(2) {
  animation-delay: 0.15s;
}
.orbit-bubble-typing i:nth-child(3) {
  animation-delay: 0.3s;
}
.orbit-bubble-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  color: var(--muted-foreground);
  font-size: 0.54rem;
  font-weight: 700;
}
.orbit-bubble-foot em {
  font-style: normal;
  white-space: nowrap;
}
.orbit-bubble-progress {
  display: flex;
  gap: 0.16rem;
}
.orbit-bubble-progress i {
  width: 0.28rem;
  height: 0.16rem;
  border-radius: 99px;
  background: color-mix(in oklab, var(--muted-foreground) 32%, transparent);
  transition: background 260ms ease;
}
.orbit-bubble-progress i.is-on {
  background: color-mix(in oklab, var(--employee-tone, var(--primary)) 80%, transparent);
}
.team-orbit-dark .orbit-bubble {
  border-color: color-mix(in oklab, var(--employee-tone, var(--primary)) 48%, transparent);
  background:
    linear-gradient(
      160deg,
      color-mix(in oklab, var(--employee-tone, var(--primary)) 18%, transparent),
      transparent 60%
    ),
    color-mix(in oklab, var(--foreground) 82%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in oklab, var(--background) 12%, transparent),
    0 22px 48px -20px color-mix(in oklab, var(--employee-tone, var(--primary)) 55%, transparent);
}
.team-orbit-dark .orbit-bubble::after {
  background: color-mix(in oklab, var(--foreground) 82%, transparent);
  border-color: color-mix(in oklab, var(--employee-tone, var(--primary)) 48%, transparent);
}
.team-orbit-dark .orbit-bubble-text {
  color: var(--background);
}
.team-orbit-dark .orbit-bubble-head {
  color: color-mix(in oklab, var(--employee-tone, var(--primary)) 62%, var(--background));
}
.team-orbit-dark .orbit-bubble-head b,
.team-orbit-dark .orbit-bubble-foot {
  color: color-mix(in oklab, var(--background) 55%, transparent);
}
@keyframes orbit-bubble-in {
  from {
    opacity: 0;
    translate: 0 12px;
    scale: 0.94;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}
@keyframes orbit-bubble-line {
  from {
    opacity: 0;
    translate: 0 6px;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}
@keyframes orbit-typing {
  0%,
  100% {
    opacity: 0.35;
    translate: 0 0;
  }
  50% {
    opacity: 1;
    translate: 0 -3px;
  }
}
@media (max-width: 768px) {
  .orbit-bubble {
    width: 11rem;
    padding: 0.5rem 0.6rem;
  }
  .orbit-slot:nth-child(odd) .orbit-bubble {
    right: 0;
    left: auto;
  }
  .orbit-slot:nth-child(even) .orbit-bubble {
    right: auto;
    left: 0;
  }
  .orbit-bubble-text {
    font-size: 0.63rem;
    line-height: 1.55;
  }
  .orbit-bubble-head {
    font-size: 0.58rem;
  }
  .orbit-bubble-head b {
    display: none;
  }
  .orbit-bubble-foot {
    font-size: 0.48rem;
  }
  .orbit-commentary {
    grid-template-columns: auto minmax(0, 1fr);
    width: calc(100% - 0.5rem);
    min-height: 5.75rem;
    gap: 0.35rem 0.55rem;
    padding: 0.62rem 0.7rem;
  }
  .orbit-commentary .orbit-bubble-head {
    grid-row: 1;
  }
  .orbit-commentary .orbit-bubble-text,
  .orbit-commentary .orbit-bubble-typing {
    grid-column: 1 / -1;
  }
  .orbit-commentary .orbit-bubble-apps {
    grid-column: 2;
    grid-row: 1;
    justify-self: end;
  }
  .orbit-commentary .orbit-bubble-foot {
    grid-column: 1 / -1;
  }
  .mena-place-labels {
    display: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .orbit-bubble,
  .orbit-commentary,
  .orbit-bubble-text,
  .orbit-bubble-typing i,
  .mena-map-scan,
  .integration-team-status i {
    animation: none;
  }
}

.orbit-slot.orbit-employee-1 .orbit-bubble,
.orbit-slot.orbit-employee-2 .orbit-bubble {
  animation-name: orbit-bubble-in-down;
}
.orbit-slot.orbit-employee-1 .orbit-bubble {
  inset: calc(100% + 0.7rem) 24% auto -24%;
}
.orbit-slot.orbit-employee-2 .orbit-bubble {
  inset: calc(100% + 0.7rem) -24% auto 24%;
}
.orbit-slot.orbit-employee-1 .orbit-bubble::after {
  inset: -0.34rem 12% auto auto;
  rotate: 225deg;
}
.orbit-slot.orbit-employee-2 .orbit-bubble::after {
  inset: -0.34rem auto auto 12%;
  rotate: 225deg;
}
@keyframes orbit-bubble-in-down {
  from {
    opacity: 0;
    translate: 0 -12px;
    scale: 0.94;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}

/* Brand-tinted infinite icon marquee */
.brand-icon-track {
  align-items: center;
  animation-duration: 46s;
}
.brand-word-chip {
  display: inline-flex;
  flex: none;
  align-items: center;
  border: 1px solid color-mix(in oklab, var(--primary) 15%, transparent);
  border-radius: 999px;
  padding: 0.5rem 1rem;
  background: color-mix(in oklab, var(--card) 80%, transparent);
  color: color-mix(in oklab, var(--foreground) 78%, transparent);
  font-size: 0.86rem;
  font-weight: 700;
  white-space: nowrap;
  backdrop-filter: blur(14px) saturate(140%);
}
.brand-icon-chip {
  display: inline-grid;
  width: 3.25rem;
  height: 3.25rem;
  flex: none;
  place-items: center;
  border: 1px solid color-mix(in oklab, var(--primary) 16%, transparent);
  border-radius: 1rem;
  background: color-mix(in oklab, var(--card) 82%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--card) 92%, transparent);
  backdrop-filter: blur(14px) saturate(140%);
  transition:
    transform 240ms var(--ease-enter),
    border-color 240ms ease;
}
.brand-icon-chip svg {
  color: var(--primary);
}
.brand-icon-chip:nth-child(3n + 2) svg {
  color: var(--amber);
}
.brand-icon-chip:nth-child(3n + 3) svg {
  color: var(--jade);
}
.brand-icon-chip:hover {
  transform: translateY(-3px);
  border-color: color-mix(in oklab, var(--primary) 38%, transparent);
}

/* ===== الإعداد الأولي — زجاج بأسلوب iOS ===== */
.onboarding-stage {
  position: relative;
  background:
    radial-gradient(
      1200px 600px at 85% -10%,
      color-mix(in oklab, var(--primary) 22%, transparent),
      transparent 60%
    ),
    radial-gradient(
      900px 500px at 10% 110%,
      color-mix(in oklab, var(--primary) 14%, transparent),
      transparent 60%
    ),
    var(--background);
}
.onboarding-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(
    color-mix(in oklab, var(--foreground) 6%, transparent) 1px,
    transparent 1px
  );
  background-size: 22px 22px;
  mask-image: radial-gradient(70% 60% at 50% 30%, #000, transparent);
}
.onboarding-glass {
  position: relative;
  border: 1px solid color-mix(in oklab, var(--foreground) 10%, transparent);
  background: color-mix(in oklab, var(--card) 60%, transparent);
  backdrop-filter: blur(28px) saturate(160%);
  -webkit-backdrop-filter: blur(28px) saturate(160%);
  box-shadow:
    0 1px 0 color-mix(in oklab, white 25%, transparent) inset,
    0 24px 70px -30px color-mix(in oklab, var(--foreground) 40%, transparent);
}

/* ===== iOS-style liquid glass footer ===== */
.site-footer {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-top: 1px solid color-mix(in oklab, var(--foreground) 8%, transparent);
  background:
    linear-gradient(
      to bottom,
      color-mix(in oklab, var(--foreground) 3%, transparent),
      transparent 40%
    ),
    var(--background);
}
.site-footer-glow {
  position: absolute;
  inset-inline: -20%;
