}
.auth-cover-stage {
  position: absolute;
  inset: 0;
  z-index: 3;
}
.auth-cover-figure {
  position: absolute;
  aspect-ratio: 0.6 / 1;
  will-change: transform, filter, opacity;
  transition:
    transform 700ms cubic-bezier(0.4, 0, 0.2, 1),
    filter 700ms cubic-bezier(0.4, 0, 0.2, 1),
    opacity 700ms cubic-bezier(0.4, 0, 0.2, 1),
