  opacity: 0.85;
  z-index: 10;
  filter: blur(2px);
}
.auth-cover-figure[data-role="right"] {
  left: 78%;
  bottom: 12%;
  height: 26%;
  transform: translateX(-50%) scale(1);
  opacity: 0.85;
  z-index: 10;
  filter: blur(2px);
}
.auth-cover-figure[data-role="back"] {
  left: 50%;
  bottom: 12%;
