  font-weight: 600;
}

.diwan-eyebrow i {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 999px;
  background: var(--jade);
  box-shadow: 0 0 0 4px oklch(0.55 0.19 255 / 0.18);
  animation: diwan-pulse 2.4s ease-in-out infinite;
}

@keyframes diwan-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.55;
    transform: scale(0.82);
  }
}

.diwan-title {
  margin: 1.4rem 0 0;
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 5.4vw, 4.6rem);
  font-weight: 800;
  line-height: 1.22;
  letter-spacing: -0.01em;
  color: var(--ink);
  text-wrap: balance;
}

.diwan-title span {
  display: block;
  background: var(--gradient-aurora);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.diwan-lead {
  max-width: 40rem;
  margin: 1.35rem auto 0;
  color: var(--muted-foreground);
  font-size: clamp(0.95rem, 1.2vw, 1.15rem);
  line-height: 1.9;
  text-wrap: pretty;
}

.diwan-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.75rem;
  margin-top: 2rem;
}

.diwan-cta {
  display: inline-flex;
  min-height: 3.35rem;
  align-items: center;
  gap: 0.6rem;
  padding: 0 1.75rem;
  border-radius: 999px;
  background: var(--gradient-aurora);
  color: var(--primary-foreground);
  font-size: 0.95rem;
  font-weight: 700;
  box-shadow: 0 18px 38px -20px oklch(0.47 0.2 258 / 0.6);
  transition:
    transform 260ms var(--ease-enter),
    box-shadow 260ms ease;
}

.diwan-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 24px 46px -20px oklch(0.47 0.2 258 / 0.66);
}

.diwan-ghost {
  display: inline-flex;
  min-height: 3.35rem;
  align-items: center;
  gap: 0.55rem;
  padding: 0 1.5rem;
  border-radius: 999px;
  border: 1px solid var(--glass-stroke);
  background: var(--glass-tint);
  backdrop-filter: blur(16px) saturate(170%);
  color: var(--ink);
  font-size: 0.95rem;
  font-weight: 600;
  transition:
    transform 260ms var(--ease-enter),
    background 260ms ease;
}

.diwan-ghost:hover {
  transform: translateY(-2px);
  background: var(--glass-tint-strong);
}

/* ---------- حلقة المجلس ---------- */
.diwan-majlis {
  position: relative;
  width: min(100%, 62rem);
  margin: clamp(3rem, 6vw, 5rem) auto 0;
  aspect-ratio: 1 / 0.5;
}

.diwan-arc {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.diwan-arc svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.diwan-seat {
  position: absolute;
  top: 50%;
  left: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  width: 9.5rem;
  padding: 0.7rem 0.6rem 0.85rem;
  border-radius: 1.35rem;
  border: 1px solid var(--glass-stroke);
  background: var(--glass-tint-strong);
  backdrop-filter: blur(18px) saturate(180%);
  box-shadow: var(--glass-shadow);
  text-align: center;
  transform: translate(calc(-50% + var(--sx)), calc(-50% + var(--sy)));
  animation: diwan-float 7s ease-in-out infinite;
  animation-delay: calc(var(--i) * -0.9s);
  transition: box-shadow 300ms ease;
}

.diwan-seat:hover {
  box-shadow: 0 26px 54px -22px oklch(0.47 0.2 258 / 0.42);
}

@keyframes diwan-float {
  0%,
  100% {
    margin-top: 0;
  }
  50% {
    margin-top: -0.5rem;
  }
}

.diwan-seat figure {
  width: 3.4rem;
  height: 3.4rem;
  margin: 0;
  border-radius: 999px;
  overflow: hidden;
  box-shadow:
    0 0 0 3px oklch(1 0 0),
    0 0 0 4.5px oklch(0.55 0.19 255 / 0.25);
}
.diwan-seat figure img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.diwan-seat strong {
  font-family: var(--font-display);
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--ink);
}
.diwan-seat small {
  color: var(--muted-foreground);
  font-size: 0.64rem;
  line-height: 1.5;
}
.diwan-seat b {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  color: var(--jade-deep);
  font-size: 0.58rem;
  font-weight: 700;
}
.diwan-seat b::before {
  content: "";
  width: 0.36rem;
  height: 0.36rem;
  border-radius: 999px;
  background: oklch(0.7 0.16 150);
}

/* ---------- الطبلية: تدفّق حيّ ---------- */
.diwan-table {
  position: absolute;
  top: 52%;
  left: 50%;
  width: min(88%, 27rem);
  padding: 1.1rem 1.2rem 1.2rem;
  transform: translate(-50%, -46%);
  border-radius: 1.9rem;
  border: 1px solid var(--glass-stroke);
  background: var(--glass-tint-strong);
  backdrop-filter: blur(30px) saturate(200%);
  box-shadow: var(--glass-shadow);
}

.diwan-table header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border);
}
.diwan-table header p {
  margin: 0;
  font-family: var(--font-display);
  font-size: 0.9rem;
  font-weight: 700;
}
.diwan-table header span {
  color: var(--jade-deep);
  font-size: 0.68rem;
  font-weight: 700;
}

.diwan-feed {
  display: grid;
  gap: 0.55rem;
  margin: 0.85rem 0 0;
  padding: 0;
  list-style: none;
}
.diwan-feed li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.6rem 0.7rem;
  border-radius: 1rem;
  background: oklch(1 0 0 / 0.72);
  border: 1px solid oklch(0.55 0.19 255 / 0.08);
  font-size: 0.76rem;
  color: var(--ink-soft);
  animation: diwan-in 520ms var(--ease-enter) both;
}
.diwan-feed li span {
  margin-inline-start: auto;
  color: var(--muted-foreground);
  font-size: 0.63rem;
  font-variant-numeric: tabular-nums;
}
.diwan-feed li i {
  display: grid;
  place-items: center;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 999px;
  background: oklch(0.55 0.19 255 / 0.12);
  color: var(--jade-deep);
}

@keyframes diwan-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.diwan-proof {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.9rem;
  margin: clamp(2rem, 4vw, 3rem) auto 0;
}
.diwan-proof div {
  padding: 0.85rem 1.25rem;
  border-radius: 1.25rem;
  border: 1px solid var(--glass-stroke);
  background: var(--glass-tint);
  backdrop-filter: blur(16px) saturate(170%);
  text-align: center;
}
.diwan-proof strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--jade-deep);
  font-variant-numeric: tabular-nums;
}
.diwan-proof small {
  color: var(--muted-foreground);
  font-size: 0.68rem;
}

@media (max-width: 900px) {
  .diwan-majlis {
    aspect-ratio: auto;
  }
  .diwan-arc {
    display: none;
  }
  .diwan-table {
    position: static;
    width: 100%;
    transform: none;
  }
  .diwan-seats {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
    gap: 0.7rem;
    margin-top: 1rem;
  }
  .diwan-seat {
    position: static;
    width: auto;
    transform: none;
    animation: none;
  }
}

/* قسم العرض يتماشى مع القماش الأبيض بدل الخلفية الداكنة */
.product-showcase {
  background: linear-gradient(180deg, oklch(0.978 0.001 60), var(--background));
  color: var(--foreground);
}
.product-showcase .section-kicker {
  color: var(--jade-deep);
}
.product-showcase .section-lead {
  color: var(--muted-foreground);
}

.diwan-halo {
  position: absolute;
  inset: 6% 4% 10%;
  border-radius: 999px;
  background: radial-gradient(
    closest-side,
    oklch(1 0 0 / 0.75),
    oklch(0.55 0.19 255 / 0.06) 72%,
    transparent
  );
  box-shadow: inset 0 0 0 1px oklch(0.55 0.19 255 / 0.08);
  pointer-events: none;
}

/* ============ الديوان — روح واحدة لكل الصفحة ============ */
.diwan-sec {
  position: relative;
  padding: clamp(3.5rem, 7vw, 6.5rem) 0;
}
.diwan-sec-head {
  max-width: 46rem;
  margin-inline: auto;
  text-align: center;
}
.diwan-sec-kicker {
  display: inline-block;
  margin: 0 0 0.85rem;
  padding: 0.3rem 0.85rem;
  border-radius: 999px;
  border: 1px solid var(--glass-edge);
  background: var(--glass-tint);
  backdrop-filter: blur(var(--glass-blur));
  color: var(--jade-deep);
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}
.diwan-sec-title {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: -0.02em;
  font-size: clamp(1.6rem, 3.6vw, 2.75rem);
  line-height: 1.25;
  color: var(--foreground);
  text-wrap: balance;
}
.diwan-sec-lead {
  margin: 0.9rem auto 0;
  max-width: 40rem;
  color: var(--muted-foreground);
  font-size: clamp(0.94rem, 1.15vw, 1.06rem);
  line-height: 1.9;
  text-wrap: pretty;
}

/* دفتر المحل */
.ledger-sec {
  background: linear-gradient(180deg, var(--background), oklch(0.985 0.008 250));
}
.ledger {
  margin-top: clamp(2rem, 4vw, 3rem);
  padding: 0.75rem;
  border-radius: 1.6rem;
  overflow: hidden;
}
.ledger-head,
.ledger-rows li {
  display: grid;
  grid-template-columns: 4.5rem 5.5rem 1fr 8rem;
  align-items: center;
  gap: 0.75rem;
  padding: 0.8rem 1rem;
}
.ledger-head {
  color: var(--muted-foreground);
  font-size: 0.72rem;
  font-weight: 800;
}
.ledger-rows {
  margin: 0;
  padding: 0;
  list-style: none;
}
.ledger-rows li {
  border-top: 1px dashed color-mix(in oklab, var(--jade) 16%, transparent);
  font-size: 0.86rem;
  opacity: 0;
  transform: translateY(6px);
  transition:
    opacity 520ms ease,
    transform 520ms cubic-bezier(0.22, 1, 0.36, 1);
}
.ledger-rows li.is-written {
  opacity: 1;
  transform: none;
}
.ledger-time {
  color: var(--muted-foreground);
  font-size: 0.75rem;
}
.ledger-who {
  font-weight: 800;
  color: var(--jade-deep);
}
.ledger-act {
  color: var(--foreground);
  line-height: 1.7;
}
.ledger-win {
  justify-self: start;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  background: color-mix(in oklab, var(--jade) 12%, transparent);
  color: var(--jade-deep);
  font-size: 0.72rem;
  font-weight: 800;
  white-space: nowrap;
}
.ledger-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.4rem;
  padding: 0.85rem 1rem 0.5rem;
  border-top: 1px solid var(--border);
  color: var(--muted-foreground);
  font-size: 0.74rem;
}
.ledger-foot b {
  color: var(--jade-deep);
}
.ledger-totals {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
  gap: 0.8rem;
  margin: clamp(1.5rem, 3vw, 2.5rem) 0 0;
}
.ledger-totals div {
  padding: 1.1rem;
  border-radius: 1.2rem;
  border: 1px solid var(--glass-edge);
  background: var(--glass-tint-strong);
  backdrop-filter: blur(var(--glass-blur));
  box-shadow: var(--glass-shadow);
  text-align: center;
}
.ledger-totals dt {
  color: var(--jade);
  font-size: clamp(1.3rem, 2.4vw, 1.75rem);
  font-weight: 800;
}
.ledger-totals dd {
  margin: 0.3rem 0 0;
  color: var(--muted-foreground);
  font-size: 0.76rem;
  line-height: 1.6;
}

/* مراسم الدخول */
.steps-ribbon {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: 0.9rem;
  margin: clamp(2rem, 4vw, 3rem) 0 0;
  padding: 0;
  list-style: none;
}
.steps-card {
  position: relative;
  padding: 1.5rem 1.35rem;
  border-radius: 1.5rem;
}
.steps-num {
  position: absolute;
  inset-block-start: 1rem;
  inset-inline-end: 1.1rem;
  color: color-mix(in oklab, var(--jade) 26%, transparent);
  font-size: 2rem;
  font-weight: 800;
  line-height: 1;
}
.steps-icon {
  display: inline-flex;
  width: 2.6rem;
  height: 2.6rem;
  align-items: center;
  justify-content: center;
  border-radius: 0.95rem;
  background: var(--gradient-aurora);
  color: oklch(1 0 0);
  box-shadow: 0 10px 24px -14px oklch(0.47 0.2 258 / 0.7);
}
.steps-title {
  margin: 1rem 0 0;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--foreground);
}
.steps-body {
  margin: 0.5rem 0 0;
  color: var(--muted-foreground);
  font-size: 0.86rem;
  line-height: 1.85;
}

/* إعادة كسوة بقية الأقسام بروح الديوان الزجاجية */
.employees-stage,
.features-section {
  background: linear-gradient(180deg, oklch(0.985 0.008 250), var(--background));
}
.features-section::before {
  opacity: 0.35;
}
.section-kicker,
.section-eyebrow {
  color: var(--jade-deep);
}
.section-title {
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: -0.02em;
}
.feature-glass-card,
.testimonial-card,
.faq-item {
  border-color: var(--glass-edge) !important;
  background: var(--glass-tint-strong) !important;
  backdrop-filter: blur(var(--glass-blur));
  box-shadow: var(--glass-shadow);
}
.faq-item {
  border-radius: 1.25rem;
}

@media (max-width: 720px) {
  .ledger-head {
    display: none;
  }
  .ledger-rows li {
    grid-template-columns: 3.6rem 1fr;
    grid-template-areas: "t who" "t act" ". win";
    row-gap: 0.3rem;
  }
  .ledger-time {
    grid-area: t;
  }
  .ledger-who {
    grid-area: who;
  }
  .ledger-act {
    grid-area: act;
  }
  .ledger-win {
    grid-area: win;
  }
}

/* كانفاس أبيض واحد لكل الأقسام */
section:has(> .integration-grid-wave) {
  background-image: linear-gradient(180deg, oklch(1 0 0), oklch(0.975 0.002 60));
  color: var(--foreground);
}
section:has(> .integration-grid-wave) * {
  color: inherit;
}
.pricing-liquid-glass.is-highlight {
  background-image: linear-gradient(165deg, oklch(0.22 0.005 60), oklch(0.14 0.004 60)) !important;
  border: 1px solid oklch(0.16 0.004 60);
  color: oklch(1 0 0);
}
.cta-glow-button {
  background-image: none;
  background-color: oklch(0.16 0.004 60);
  color: oklch(1 0 0) !important;
}

/* ═════ زجاج سهل — سطح عائم واحد لكل الصفحة ═════ */
.liquid-glass-sahl {
  background: var(--glass-tint);
  backdrop-filter: blur(28px) saturate(160%);
  border: none;
  box-shadow: var(--glass-shadow);
  position: relative;
  overflow: hidden;
}
.liquid-glass-sahl::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.4px;
  background: linear-gradient(
    180deg,
    oklch(0.66 0.116 74 / 0.55) 0%,
    oklch(0.66 0.116 74 / 0.15) 20%,
    transparent 40%,
    transparent 60%,
    oklch(0.445 0.058 179 / 0.2) 80%,
    oklch(0.66 0.116 74 / 0.45) 100%
  );
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  pointer-events: none;
  z-index: 2;
}

/* ═════ المعاينة الحية (Hero) ═════ */
.sahl-live {
  position: relative;
  isolation: isolate;
  padding: clamp(5.5rem, 11vw, 8rem) clamp(0.9rem, 3vw, 2.5rem) clamp(3rem, 6vw, 5rem);
  background: var(--background);
  overflow: hidden;
}
.sahl-live-glowA,
.sahl-live-glowB {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  z-index: -1;
  pointer-events: none;
}
.sahl-live-glowA {
  inset-inline-end: -8%;
  top: -10%;
  width: 46vw;
  height: 46vw;
  background: oklch(0.16 0.004 60 / 0.05);
}
.sahl-live-glowB {
  inset-inline-start: -12%;
  bottom: -18%;
  width: 44vw;
  height: 44vw;
  background: oklch(0.16 0.004 60 / 0.04);
}

.sahl-live-head {
  margin: 0 auto clamp(1.5rem, 3vw, 2.4rem);
  max-width: 46rem;
  text-align: center;
}
.sahl-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border-radius: 999px;
  background: oklch(0.16 0.004 60 / 0.04);
  box-shadow: inset 0 0 0 1px oklch(0.16 0.004 60 / 0.14);
  padding: 0.35rem 0.85rem;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--foreground);
}
.sahl-badge i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--sky);
  box-shadow: 0 0 0 0 oklch(0.445 0.058 179 / 0.6);
  animation: sahl-pulse 1.9s ease-out infinite;
}
@keyframes sahl-pulse {
  70% {
    box-shadow: 0 0 0 0.5rem oklch(0.445 0.058 179 / 0);
  }
  100% {
    box-shadow: 0 0 0 0 oklch(0.445 0.058 179 / 0);
  }
}
.sahl-live-title {
  margin: 0.85rem 0 1.1rem;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  line-height: 1.4;
  text-wrap: balance;
  letter-spacing: -0.01em;
  color: var(--foreground);
}
.sahl-live-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border-radius: 999px;
  background: var(--primary);
  color: var(--primary-foreground);
  padding: 0.8rem 1.5rem;
  font-weight: 700;
  transition:
    transform 0.25s var(--ease-enter),
    box-shadow 0.25s var(--ease-enter);
}
.sahl-live-cta:hover {
  transform: translateY(-2px);
  box-shadow:
    0 0 0 1px oklch(0.66 0.116 74 / 0.55),
    0 18px 40px -18px oklch(0.66 0.116 74 / 0.55);
}

.sahl-window {
  margin: 0 auto;
  max-width: 74rem;
  border-radius: 1.6rem;
}
.sahl-window-bar {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.7rem 1rem;
  border-bottom: 1px solid oklch(0.935 0.019 84 / 0.1);
}
.sahl-window-bar span {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: oklch(0.935 0.019 84 / 0.22);
}
.sahl-window-bar p {
  margin: 0;
  margin-inline-start: auto;
  font-size: 0.75rem;
  color: var(--muted-foreground);
}
.sahl-window-body {
  display: grid;
  grid-template-columns: 8.5rem minmax(0, 1fr) 13rem;
  gap: 1px;
  min-height: 26rem;
}
.sahl-window-body > * {
  padding: 1rem;
}

.sahl-rail {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  background: oklch(0.935 0.019 84 / 0.03);
}
.sahl-rail-item {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: center;
  gap: 0.45rem;
  border-radius: 0.85rem;
  padding: 0.35rem 0.45rem;
  transition: background 0.4s ease;
}
.sahl-rail-item img {
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 50%;
  object-fit: cover;
}
.sahl-rail-item b {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: oklch(0.935 0.019 84 / 0.2);
  transition:
    background 0.4s ease,
    box-shadow 0.4s ease;
}
.sahl-rail-item span {
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--muted-foreground);
  white-space: nowrap;
}
.sahl-rail-item.is-on {
  background: oklch(0.935 0.019 84 / 0.07);
}
.sahl-rail-item.is-on b {
  background: var(--sky);
  box-shadow: 0 0 0.5rem oklch(0.445 0.058 179 / 0.9);
}
.sahl-rail-item.is-on span {
  color: var(--foreground);
}

.sahl-chat {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  justify-content: flex-start;
  background: oklch(0.935 0.019 84 / 0.02);
}
.sahl-bubble {
  border-radius: 1.1rem;
  padding: 0.75rem 0.95rem;
  font-size: 0.86rem;
  line-height: 1.75;
  max-width: 92%;
}
.sahl-bubble.is-user {
  align-self: flex-start;
  background: oklch(0.487 0.135 38 / 0.24);
  box-shadow: inset 0 0 0 1px oklch(0.487 0.135 38 / 0.35);
}
.sahl-bubble.is-agent {
  align-self: flex-end;
  background: oklch(0.935 0.019 84 / 0.06);
  box-shadow: inset 0 0 0 1px oklch(0.935 0.019 84 / 0.1);
}
.sahl-bubble p {
  margin: 0;
}
.sahl-bubble.is-agent header {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-bottom: 0.5rem;
}
.sahl-bubble.is-agent header img {
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  object-fit: cover;
}
.sahl-bubble.is-agent header strong {
  font-family: var(--font-display);
  font-size: 0.8rem;
}
.sahl-bubble.is-agent header small {
  font-size: 0.68rem;
  color: var(--muted-foreground);
}
.sahl-caret {
  display: inline-block;
  width: 2px;
  height: 0.95em;
  vertical-align: -0.15em;
  margin-inline-start: 2px;
  background: var(--amber);
  animation: sahl-blink 0.9s steps(2) infinite;
}
@keyframes sahl-blink {
  50% {
    opacity: 0;
  }
}
.sahl-dots {
  display: inline-flex;
  gap: 0.25rem;
}
.sahl-dots i {
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 50%;
  background: var(--muted-foreground);
  animation: sahl-bounce 1s infinite;
}
.sahl-dots i:nth-child(2) {
  animation-delay: 0.15s;
}
.sahl-dots i:nth-child(3) {
  animation-delay: 0.3s;
}
@keyframes sahl-bounce {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.5;
  }
  50% {
    transform: translateY(-0.25rem);
    opacity: 1;
  }
}

.sahl-approvals {
  background: oklch(0.935 0.019 84 / 0.03);
}
.sahl-approvals-title {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0 0 0.7rem;
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--amber);
}
.sahl-approvals-empty {
  margin: 0;
  font-size: 0.74rem;
  color: var(--muted-foreground);
}
.sahl-approval-card {
  border-radius: 1rem;
  padding: 0.7rem;
  background: oklch(0.935 0.019 84 / 0.06);
  box-shadow: inset 0 0 0 1px oklch(0.66 0.116 74 / 0.35);
  animation: sahl-drop 0.5s var(--ease-enter) both;
}
@keyframes sahl-drop {
  from {
    opacity: 0;
    transform: translateY(-0.75rem) scale(0.97);
  }
}
.sahl-approval-thumb {
  height: 3.6rem;
  border-radius: 0.7rem;
  background: var(--gradient-aurora);
  margin-bottom: 0.5rem;
}
.sahl-approval-card strong {
  display: block;
  font-size: 0.78rem;
  font-family: var(--font-display);
}
.sahl-approval-card small {
  display: block;
  margin-top: 0.15rem;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}
.sahl-approval-card span {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  margin-top: 0.55rem;
  border-radius: 999px;
  padding: 0.2rem 0.6rem;
  font-size: 0.68rem;
  font-weight: 700;
  background: oklch(0.66 0.116 74 / 0.18);
  color: var(--amber);
}
.sahl-approval-card.is-done {
  box-shadow: inset 0 0 0 1px oklch(0.445 0.058 179 / 0.6);
}
.sahl-approval-card.is-done span {
  background: oklch(0.445 0.058 179 / 0.28);
  color: oklch(0.78 0.07 179);
}

@media (max-width: 900px) {
  .sahl-window-body {
    grid-template-columns: minmax(0, 1fr);
    min-height: auto;
  }
  .sahl-rail {
    flex-direction: row;
    overflow: hidden;
  }
  .sahl-rail-item span {
    display: none;
  }
  .sahl-approvals {
    display: none;
  }
  .sahl-chat {
    min-height: 21rem;
  }
}

/* ═════ الكانفاس الأبيض: توحيد كل الأسطح على أبيض + حبر أسود ═════ */
:root {
  --ink-line: oklch(0.16 0.004 60 / 0.1);
  --ink-line-2: oklch(0.16 0.004 60 / 0.16);
  --ink-fill: oklch(0.16 0.004 60 / 0.035);
  --ink-fill-2: oklch(0.16 0.004 60 / 0.07);
}
.sahl-live {
  background: oklch(1 0 0);
}
.sahl-window {
  box-shadow:
    0 1px 0 var(--ink-line),
    0 30px 70px -50px oklch(0.16 0.004 60 / 0.3);
  border: 1px solid var(--ink-line-2) !important;
  background: oklch(1 0 0) !important;
  overflow: hidden;
}
.sahl-window-bar {
  border-bottom: 1px solid var(--ink-line);
  background: oklch(0.985 0.001 60);
}
.sahl-window-bar span {
  background: var(--ink-line-2);
}
.sahl-window-body {
  background: var(--ink-line);
}
.sahl-rail,
.sahl-approvals {
  background: oklch(0.978 0.001 60);
}
.sahl-chat {
  background: oklch(1 0 0);
}
.sahl-rail-item b {
  background: var(--ink-line-2);
}
.sahl-rail-item.is-on {
  background: var(--ink-fill-2);
}
.sahl-rail-item.is-on b {
  background: oklch(0.55 0.14 150);
  box-shadow: 0 0 0.5rem oklch(0.55 0.14 150 / 0.6);
}
.sahl-bubble.is-user {
  background: oklch(0.16 0.004 60);
  color: oklch(1 0 0);
  box-shadow: none;
}
.sahl-bubble.is-agent {
  background: oklch(0.972 0.001 60);
  box-shadow: inset 0 0 0 1px var(--ink-line);
}
.sahl-caret {
  background: var(--foreground);
}
.sahl-approvals-title {
  color: var(--foreground);
}
.sahl-approval-card {
  background: oklch(1 0 0);
  box-shadow:
    inset 0 0 0 1px var(--ink-line-2),
    0 12px 26px -22px oklch(0.16 0.004 60 / 0.4);
}
.sahl-approval-thumb {
  background: linear-gradient(140deg, oklch(0.94 0.001 60), oklch(0.88 0.002 60));
}
.sahl-approval-card span {
  background: var(--ink-fill-2);
  color: var(--foreground);
}
.sahl-approval-card.is-done {
  box-shadow: inset 0 0 0 1px oklch(0.55 0.14 150 / 0.5);
}
.sahl-approval-card.is-done span {
  background: oklch(0.55 0.14 150 / 0.12);
  color: oklch(0.42 0.12 150);
}
.sahl-live-cta:hover {
  box-shadow: 0 18px 40px -18px oklch(0.16 0.004 60 / 0.45);
}

/* أقسام بلا صبغة لونية */
.ledger-sec,
.features-section,
.employees-stage,
section:has(> .integration-grid-wave) {
  background: linear-gradient(180deg, oklch(1 0 0), oklch(0.978 0.001 60)) !important;
}
.liquid-glass-sahl::before {
  background: linear-gradient(
    180deg,
    oklch(0.16 0.004 60 / 0.18) 0%,
    oklch(0.16 0.004 60 / 0.08) 30%,
    transparent 55%,
    oklch(0.16 0.004 60 / 0.1) 100%
  );
}

/* ═════ الصفحة الرئيسية التحريرية — قصة فريق سهل ═════ */
.editorial-home {
  overflow: clip;
  background: var(--background);
  color: var(--foreground);
}
.editorial-home h1,
.editorial-home h2,
.editorial-home h3 {
  font-family: var(--font-display);
  letter-spacing: 0;
}
.editorial-section-shell {
  width: min(100% - 2.5rem, 76rem);
  margin-inline: auto;
}
.editorial-chapter {
  display: grid;
  grid-template-columns: 8rem 1fr;
  gap: 2rem;
  align-items: start;
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
}
.editorial-chapter-number {
  font-family: var(--font-display);
  font-size: clamp(3.5rem, 8vw, 7.5rem);
  font-weight: 800;
  line-height: 0.8;
  color: var(--foreground);
}
.editorial-chapter p {
  margin-bottom: 0.8rem;
  color: var(--jade);
  font-size: 0.78rem;
  font-weight: 800;
}
.editorial-chapter h2 {
  max-width: 49rem;
  font-size: clamp(2.3rem, 5vw, 5rem);
  font-weight: 800;
  line-height: 1.12;
}

.editorial-hero {
  position: relative;
  min-height: min(58rem, 100svh);
  padding: 10rem max(1.25rem, calc((100vw - 76rem) / 2)) 4rem;
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(27rem, 1.08fr);
  gap: 3rem;
  align-items: center;
  border-bottom: 1px solid var(--border);
}
.editorial-hero-copy {
  position: relative;
  z-index: 3;
}
.editorial-edition {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 2rem;
  font-size: 0.78rem;
  font-weight: 800;
  color: var(--jade);
}
.editorial-edition::before {
  content: "";
  width: 2.5rem;
  height: 2px;
  background: var(--jade);
}
.editorial-hero h1 {
  font-size: clamp(3.7rem, 6.8vw, 7.6rem);
  font-weight: 800;
  line-height: 1.02;
}
.editorial-hero h1 em {
  color: var(--jade);
  font-style: normal;
}
.editorial-hero-lead {
  max-width: 38rem;
  margin-top: 2rem;
  font-size: clamp(1.08rem, 1.8vw, 1.35rem);
  line-height: 1.9;
  color: var(--ink-soft);
}
.editorial-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.4rem;
  margin-top: 2rem;
}
.editorial-primary-action {
  display: inline-flex;
  align-items: center;
  gap: 0.8rem;
  min-height: 3.7rem;
  padding-inline: 1.5rem;
  background: var(--foreground);
  color: var(--background);
  font-weight: 800;
  border-radius: 0.25rem;
  transition:
    transform 0.25s ease,
    background 0.25s ease;
}
.editorial-primary-action:hover {
  transform: translateY(-3px);
  background: var(--jade-deep);
}
.editorial-primary-action svg,
.editorial-text-action svg {
  width: 1.1rem;
}
.editorial-text-action {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  font-weight: 800;
  border-bottom: 1px solid var(--foreground);
  padding-bottom: 0.2rem;
}
.editorial-trust {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 1.35rem;
  font-size: 0.78rem;
  color: var(--muted-foreground);
}
.editorial-trust svg {
  width: 1rem;
  color: var(--jade);
}
.editorial-hero-portraits {
  position: relative;
  height: 39rem;
}
.editorial-hero-person {
  position: absolute;
  display: block;
  width: 31%;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  border: 1px solid var(--foreground);
  background: var(--muted);
  transition:
    z-index 0.2s,
    transform 0.3s ease;
}
.editorial-hero-person:hover {
  z-index: 10;
  transform: translateY(-8px) rotate(0);
}
.editorial-hero-person img {
  width: 100%;
  height: 100%;
  filter: saturate(0.76);
}
.editorial-hero-person::after {
  content: "";
  position: absolute;
  inset: 45% 0 0;
  background: linear-gradient(to bottom, transparent, oklch(0.16 0.004 60 / 0.82));
}
.person-1 {
  inset: 0 auto auto 34%;
  transform: rotate(2deg);
}
.person-2 {
  inset: 12% 2% auto auto;
  transform: rotate(-2deg);
}
.person-3 {
  inset: 24% auto auto 1%;
  transform: rotate(-3deg);
}
.person-4 {
  inset: 45% 30% auto auto;
  transform: rotate(2deg);
}
.person-5 {
  inset: auto 0 2% auto;
  transform: rotate(1deg);
}
.person-6 {
  inset: auto auto 0 5%;
  transform: rotate(-1deg);
}
.editorial-person-index {
  position: absolute;
  z-index: 3;
  inset: 0.55rem 0.65rem auto auto;
  color: var(--background);
  font-size: 0.72rem;
  font-weight: 800;
}
.editorial-person-caption {
  position: absolute;
  z-index: 3;
  inset: auto 0.8rem 0.75rem;
  color: var(--background);
}
.editorial-person-caption strong,
.editorial-person-caption small {
  display: block;
}
.editorial-person-caption strong {
  font-family: var(--font-display);
  font-size: 1.15rem;
}
.editorial-person-caption small {
  margin-top: 0.15rem;
  font-size: 0.66rem;
  opacity: 0.76;
}
.editorial-scroll-note {
  position: absolute;
  bottom: 1.5rem;
  right: max(1.25rem, calc((100vw - 76rem) / 2));
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.7rem;
  color: var(--muted-foreground);
}
.editorial-scroll-note span {
  width: 2.8rem;
  height: 1px;
  background: var(--border);
}

.editorial-pressure,
.editorial-team,
.editorial-day,
.editorial-proof,
.editorial-live,
.editorial-connections,
.editorial-hire,
.editorial-faq {
  padding-block: clamp(6rem, 11vw, 10rem);
}
.editorial-pressure-layout {
  display: grid;
  grid-template-columns: 1fr 0.8fr;
  gap: 8vw;
  margin-top: 6rem;
}
.editorial-pressure-statement {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 4rem);
  font-weight: 700;
  line-height: 1.45;
}
.editorial-pressure-list {
  border-top: 1px solid var(--border);
}
.editorial-pressure-list li {
  display: grid;
  grid-template-columns: 5rem 1fr;
  gap: 1.5rem;
  padding: 1.35rem 0;
  border-bottom: 1px solid var(--border);
  color: var(--ink-soft);
}
.editorial-pressure-list time {
  color: var(--jade);
  font-weight: 800;
}
.editorial-breakline {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: end;
  gap: 3rem;
  margin-top: 7rem;
  padding-top: 1.5rem;
  border-top: 4px solid var(--foreground);
}
.editorial-breakline span {
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 7vw, 7rem);
  font-weight: 800;
  line-height: 1;
}
.editorial-breakline p {
  max-width: 26rem;
  font-size: 1.25rem;
  line-height: 1.8;
  color: var(--ink-soft);
}

.editorial-team {
  padding-bottom: 0;
}
.editorial-team-list {
  margin-top: 6rem;
}
.editorial-dossier {
  position: relative;
  display: grid;
  grid-template-columns: 5rem minmax(13rem, 0.64fr) 1.25fr 0.65fr;
  gap: 2rem;
  align-items: center;
  min-height: 28rem;
  padding-block: 3rem;
  border-top: 1px solid var(--border);
}
.editorial-dossier:last-child {
  border-bottom: 1px solid var(--border);
}
.editorial-dossier-number {
  align-self: start;
  font-family: var(--font-display);
  font-weight: 800;
  color: var(--jade);
}
.editorial-dossier-photo {
  height: 22rem;
  overflow: hidden;
  background: var(--muted);
}
.editorial-dossier-photo img {
  width: 100%;
  height: 100%;
  filter: saturate(0.72);
  transition:
    transform 0.5s ease,
    filter 0.5s ease;
}
.editorial-dossier:hover .editorial-dossier-photo img {
  transform: scale(1.025);
  filter: saturate(1);
}
.editorial-dossier-copy > p {
  color: var(--jade);
  font-weight: 800;
  font-size: 0.76rem;
}
.editorial-dossier-copy h3 {
  margin-top: 0.5rem;
  font-size: clamp(3rem, 6vw, 6rem);
  line-height: 1;
}
.editorial-dossier-copy > strong {
  display: block;
  margin-top: 1rem;
  font-family: var(--font-display);
  font-size: 1.15rem;
}
.editorial-dossier-copy > span {
  display: block;
  margin-top: 1rem;
  max-width: 38rem;
  line-height: 1.9;
  color: var(--ink-soft);
}
.editorial-dossier-copy a,
.editorial-inline-link {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 1.3rem;
  font-weight: 800;
  border-bottom: 1px solid var(--foreground);
  padding-bottom: 0.2rem;
}
.editorial-dossier-copy svg,
.editorial-inline-link svg {
  width: 1rem;
}
.editorial-dossier-metrics {
  display: grid;
  gap: 1.4rem;
}
.editorial-dossier-metrics div {
  border-top: 1px solid var(--border);
  padding-top: 0.8rem;
}
.editorial-dossier-metrics dt {
  font-size: 0.72rem;
  color: var(--muted-foreground);
}
.editorial-dossier-metrics dd {
  margin-top: 0.25rem;
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 800;
}

.editorial-day-grid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 6rem;
  align-items: start;
  margin-top: 6rem;
}
.editorial-day-focus {
  position: sticky;
  top: 7rem;
  min-height: 35rem;
  background: var(--foreground);
  color: var(--background);
  overflow: hidden;
}
.editorial-day-focus time {
  position: absolute;
  z-index: 3;
  top: 1.5rem;
  right: 1.5rem;
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 4rem);
  font-weight: 800;
}
.editorial-day-focus img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0.73;
  filter: grayscale(0.25);
}
.editorial-day-focus::after {
  content: "";
  position: absolute;
  inset: 40% 0 0;
  background: linear-gradient(to bottom, transparent, var(--foreground));
}
.editorial-day-focus p {
  position: absolute;
  z-index: 3;
  inset: auto 2rem 2rem;
  max-width: 30rem;
  font-size: 1.2rem;
  line-height: 1.8;
}
.editorial-day-focus p strong {
  display: block;
  font-family: var(--font-display);
  font-size: 2rem;
}
.editorial-timeline {
  position: relative;
}
.editorial-timeline::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  right: 4.5rem;
  width: 1px;
  background: var(--border);
}
.editorial-timeline li {
  position: relative;
}
.editorial-timeline li::before {
  content: "";
  position: absolute;
  top: 2rem;
  right: 4.22rem;
  z-index: 2;
  width: 0.6rem;
  height: 0.6rem;
  border-radius: 50%;
  background: var(--background);
  border: 1px solid var(--foreground);
}
.editorial-timeline li.is-active::before {
  background: var(--jade);
  border-color: var(--jade);
  transform: scale(1.6);
}
.editorial-timeline button {
  width: 100%;
  height: auto;
  display: grid;
  grid-template-columns: 5rem 6rem 1fr;
  gap: 1.5rem;
  align-items: start;
  border-radius: 0;
  padding: 1.5rem 0;
  white-space: normal;
  text-align: right;
}
.editorial-timeline time {
  color: var(--jade);
  font-weight: 800;
}
.editorial-timeline span {
  font-family: var(--font-display);
  font-weight: 800;
}
.editorial-timeline p {
  line-height: 1.7;
  color: var(--ink-soft);
}

.editorial-proof {
  border-block: 1px solid var(--border);
}
.editorial-proof-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 6rem;
  border-block: 1px solid var(--border);
}
.editorial-proof-grid article {
  padding: 2.5rem;
  border-inline-start: 1px solid var(--border);
}
.editorial-proof-grid article:first-child {
  border-inline-start: 0;
}
.editorial-proof-grid strong {
  font-family: var(--font-display);
  font-size: clamp(4rem, 8vw, 7rem);
  line-height: 0.9;
  color: var(--jade);
}
.editorial-proof-grid h3 {
  margin-top: 1.5rem;
  font-size: 1.1rem;
  line-height: 1.6;
}
.editorial-proof-grid p {
  margin-top: 0.6rem;
  color: var(--muted-foreground);
  font-size: 0.84rem;
}
.editorial-quotes {
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 1px;
  margin-top: 5rem;
  background: var(--border);
}
.editorial-quotes figure {
  min-height: 17rem;
  padding: 2rem;
  background: var(--background);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.editorial-quotes figure.is-featured {
  grid-row: span 2;
}
.editorial-quotes blockquote {
  font-family: var(--font-display);
  font-size: clamp(1.3rem, 2.4vw, 2.5rem);
  font-weight: 700;
  line-height: 1.65;
}
.editorial-quotes figcaption span,
.editorial-quotes figcaption strong {
  display: block;
}
.editorial-quotes figcaption span {
  color: var(--muted-foreground);
  font-size: 0.8rem;
}

.editorial-section-intro {
  max-width: 42rem;
  margin: 2rem 10rem 0 0;
  font-size: 1.2rem;
  line-height: 1.8;
  color: var(--ink-soft);
}
.editorial-workspace {
  margin-top: 4rem;
  border: 1px solid var(--foreground);
  background: var(--background);
  box-shadow: 1rem 1rem 0 var(--muted);
}
.editorial-workspace-top {
  height: 4rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-inline: 1.25rem;
  border-bottom: 1px solid var(--border);
}
.editorial-workspace-top span {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.76rem;
  color: var(--muted-foreground);
}
.editorial-workspace-top i {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: oklch(0.58 0.13 145);
}
.editorial-workspace-grid {
  display: grid;
  grid-template-columns: 15rem 1fr 18rem;
  min-height: 34rem;
}
.editorial-workspace-team {
  border-inline-end: 1px solid var(--border);
  padding: 0.75rem;
}
.editorial-workspace-team button {
  width: 100%;
  height: 4rem;
  justify-content: flex-start;
  gap: 0.75rem;
  border-radius: 0.2rem;
  padding-inline: 0.65rem;
}
.editorial-workspace-team button.is-active {
  background: var(--foreground);
  color: var(--background);
}
.editorial-workspace-team img {
  width: 2.7rem;
  height: 2.7rem;
}
.editorial-workspace-team span,
.editorial-workspace-team strong,
.editorial-workspace-team small {
  display: block;
  text-align: right;
}
.editorial-workspace-team small {
  margin-top: 0.15rem;
  opacity: 0.65;
  font-size: 0.66rem;
}
.editorial-conversation {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  padding: 3rem;
}
.editorial-message {
  max-width: 31rem;
  padding: 1rem 1.15rem;
  line-height: 1.8;
}
.editorial-message.is-owner {
  align-self: flex-start;
  background: var(--foreground);
  color: var(--background);
}
.editorial-message.is-agent {
  border: 1px solid var(--border);
}
.editorial-message header {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-bottom: 0.8rem;
}
.editorial-message header img {
  width: 2.8rem;
  height: 2.8rem;
}
.editorial-message header span,
.editorial-message header strong,
.editorial-message header small {
  display: block;
}
.editorial-message header small {
  color: var(--muted-foreground);
  font-size: 0.7rem;
}
.editorial-approval {
  border-inline-start: 1px solid var(--border);
  padding: 1.25rem;
  background: var(--muted);
}
.editorial-approval > p {
  display: flex;
  gap: 0.4rem;
  align-items: center;
  font-size: 0.75rem;
  font-weight: 800;
}
.editorial-approval > p svg {
  width: 1rem;
  color: var(--jade);
}
.editorial-approval > div {
  margin-top: 1.2rem;
  padding: 1.25rem;
  background: var(--background);
  border: 1px solid var(--border);
}
.editorial-output-label,
.editorial-approval strong,
.editorial-approval small {
  display: block;
}
.editorial-output-label {
  color: var(--jade);
  font-size: 0.7rem;
  font-weight: 800;
}
.editorial-approval strong {
  margin-top: 1.25rem;
  font-family: var(--font-display);
  font-size: 1.2rem;
  line-height: 1.6;
}
.editorial-approval small {
  margin-top: 0.75rem;
  color: var(--muted-foreground);
  line-height: 1.6;
}
.editorial-approval button {
  width: 100%;
  margin-top: 1.5rem;
  border-radius: 0.2rem;
}
.editorial-approval button svg {
  width: 1rem;
}

.editorial-connections {
  border-top: 1px solid var(--border);
}
.editorial-connections-layout {
  display: grid;
  grid-template-columns: 0.6fr 1.4fr;
  gap: 5rem;
  margin-top: 5rem;
}
.editorial-connections-layout > p {
  font-size: 1.2rem;
  line-height: 1.9;
  color: var(--ink-soft);
}
.editorial-apps {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}
.editorial-apps span {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-height: 3.5rem;
  padding-inline: 1.15rem;
  border: 1px solid var(--border);
  font-weight: 700;
}
.editorial-apps svg {
  width: 1rem;
  color: var(--jade);
}
.editorial-hire {
  border-top: 1px solid var(--border);
}
.editorial-hire-grid {
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  gap: 1px;
  max-width: 60rem;
  margin: 5rem auto 0;
  background: var(--foreground);
  border: 1px solid var(--foreground);
}
.editorial-hire-grid article {
  padding: clamp(2rem, 5vw, 4rem);
  background: var(--background);
}
.editorial-hire-grid article.is-team {
  background: var(--foreground);
  color: var(--background);
}
.editorial-hire-grid article > p {
  color: var(--jade);
  font-size: 0.76rem;
  font-weight: 800;
}
.editorial-hire-grid h3 {
  margin-top: 0.7rem;
  font-size: 2rem;
}
.editorial-hire-grid article > strong {
  display: block;
  margin-top: 2rem;
}
.editorial-hire-grid article > strong b {
  font-family: var(--font-display);
  font-size: clamp(4rem, 7vw, 6rem);
}
.editorial-hire-grid article > strong small {
  font-weight: 400;
  opacity: 0.65;
}
.editorial-hire-grid article > span {
  display: block;
  margin-top: 1rem;
  min-height: 3.6rem;
  line-height: 1.8;
  opacity: 0.72;
}
.editorial-hire-grid ul {
  margin-top: 2rem;
  display: grid;
  gap: 0.85rem;
}
.editorial-hire-grid li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.9rem;
}
.editorial-hire-grid li svg {
  width: 1rem;
  color: var(--jade);
}
.editorial-hire-grid article > a {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 2.5rem;
  padding: 1rem;
  border: 1px solid currentColor;
  font-weight: 800;
}
.editorial-hire-grid article > a svg {
  width: 1rem;
}
.editorial-enterprise {
  margin-top: 2rem;
  text-align: center;
  color: var(--muted-foreground);
}
.editorial-enterprise a {
  color: var(--foreground);
  border-bottom: 1px solid var(--foreground);
}
.editorial-faq {
  border-top: 1px solid var(--border);
}
.editorial-faq-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 7rem;
}
.editorial-faq-layout .editorial-chapter {
  display: block;
}
.editorial-faq-layout .editorial-chapter-number {
  display: block;
  margin-bottom: 3rem;
}
.editorial-faq-list {
  border-top: 1px solid var(--foreground);
}
.editorial-faq-list [data-slot="accordion-item"] {
  border-color: var(--border);
}
.editorial-faq-list [data-slot="accordion-trigger"] {
  padding-block: 1.4rem;
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
  text-align: right;
}
.editorial-faq-list [data-slot="accordion-content"] {
  color: var(--ink-soft);
  line-height: 1.9;
}
.editorial-final {
  padding: clamp(7rem, 13vw, 13rem) 0;
  border-top: 1px solid var(--border);
  text-align: center;
}
.editorial-final p {
  color: var(--jade);
  font-weight: 800;
}
.editorial-final h2 {
  margin-top: 1.2rem;
  font-size: clamp(3rem, 8vw, 8rem);
  font-weight: 800;
  line-height: 1.08;
}
.editorial-final h2 em {
  color: var(--jade);
  font-style: normal;
}
.editorial-final a {
  display: flex;
  width: fit-content;
  align-items: center;
  gap: 0.8rem;
  margin: 2.5rem auto 0;
  padding: 1.1rem 1.5rem;
  background: var(--foreground);
  color: var(--background);
  font-weight: 800;
}
.editorial-final a svg {
  width: 1rem;
}
.editorial-final span {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.45rem;
  margin-top: 1rem;
  color: var(--muted-foreground);
  font-size: 0.76rem;
}
.editorial-final span svg {
  width: 0.9rem;
}

@media (max-width: 900px) {
  .editorial-hero {
    min-height: auto;
    padding-top: 8rem;
    grid-template-columns: 1fr;
  }
  .editorial-hero-copy {
    text-align: center;
  }
  .editorial-edition,
  .editorial-actions,
  .editorial-trust {
    justify-content: center;
  }
  .editorial-hero-lead {
    margin-inline: auto;
  }
  .editorial-hero-portraits {
    height: 32rem;
    max-width: 38rem;
    width: 100%;
    margin-inline: auto;
  }
  .editorial-chapter {
    grid-template-columns: 5rem 1fr;
  }
  .editorial-pressure-layout,
  .editorial-breakline,
  .editorial-day-grid,
  .editorial-connections-layout,
  .editorial-faq-layout {
    grid-template-columns: 1fr;
    gap: 3rem;
  }
  .editorial-dossier {
    grid-template-columns: 3rem minmax(12rem, 0.7fr) 1.3fr;
  }
  .editorial-dossier-metrics {
    display: none;
  }
  .editorial-day-focus {
    position: relative;
    top: 0;
  }
  .editorial-workspace-grid {
    grid-template-columns: 11rem 1fr;
  }
  .editorial-approval {
    grid-column: 1 / -1;
    border-inline-start: 0;
    border-top: 1px solid var(--border);
  }
  .editorial-section-intro {
    margin-right: 7rem;
  }
}

@media (max-width: 640px) {
  .editorial-section-shell {
    width: min(100% - 2rem, 76rem);
  }
  .editorial-hero {
    padding: 7rem 1rem 3.5rem;
    gap: 2rem;
  }
  .editorial-hero h1 {
    font-size: clamp(2.65rem, 13vw, 4rem);
  }
  .editorial-hero h1 br {
    display: none;
  }
  .editorial-hero-lead {
    font-size: 1rem;
  }
  .editorial-actions {
    flex-direction: column;
  }
  .editorial-hero-portraits {
    height: 25rem;
  }
  .editorial-hero-person {
    width: 37%;
  }
  .person-1 {
    left: 32%;
  }
  .person-2 {
    right: 0;
    top: 15%;
  }
  .person-3 {
    left: 0;
    top: 20%;
  }
  .person-4 {
    right: 27%;
    top: 46%;
  }
  .person-5 {
    right: 0;
  }
  .person-6 {
    left: 1%;
  }
  .editorial-person-caption small {
    display: none;
  }
  .editorial-scroll-note {
    display: none;
  }
  .editorial-pressure,
  .editorial-team,
  .editorial-day,
  .editorial-proof,
  .editorial-live,
  .editorial-connections,
  .editorial-hire,
  .editorial-faq {
    padding-block: 5.5rem;
  }
  .editorial-chapter {
    grid-template-columns: 1fr;
    gap: 1.25rem;
  }
  .editorial-chapter-number {
    font-size: 3rem;
  }
  .editorial-chapter h2 {
    font-size: 2.35rem;
  }
  .editorial-pressure-layout,
  .editorial-team-list,
  .editorial-day-grid,
  .editorial-proof-grid,
  .editorial-quotes,
  .editorial-connections-layout,
  .editorial-hire-grid {
    margin-top: 3.5rem;
  }
  .editorial-pressure-statement {
    font-size: 1.8rem;
  }
  .editorial-breakline {
    margin-top: 4rem;
  }
  .editorial-breakline span {
    font-size: 3.2rem;
  }
  .editorial-dossier {
    grid-template-columns: 2.5rem 1fr;
    gap: 1rem;
    min-height: auto;
  }
  .editorial-dossier-photo {
    height: 24rem;
  }
  .editorial-dossier-copy {
    grid-column: 2;
  }
  .editorial-dossier-copy h3 {
    font-size: 3.4rem;
  }
  .editorial-proof-grid,
  .editorial-quotes,
  .editorial-hire-grid {
    grid-template-columns: 1fr;
  }
  .editorial-proof-grid article,
  .editorial-proof-grid article:first-child {
    border-inline-start: 0;
    border-bottom: 1px solid var(--border);
  }
  .editorial-quotes figure.is-featured {
    grid-row: auto;
  }
  .editorial-day-focus {
    min-height: 29rem;
  }
  .editorial-timeline::before {
    right: 0.25rem;
  }
  .editorial-timeline li::before {
    right: 0;
  }
  .editorial-timeline button {
    grid-template-columns: 4.7rem 4rem 1fr;
    padding-right: 1.4rem;
    gap: 0.6rem;
  }
  .editorial-section-intro {
    margin: 1.5rem 0 0;
  }
  .editorial-workspace {
    box-shadow: 0.5rem 0.5rem 0 var(--muted);
  }
  .editorial-workspace-grid {
    grid-template-columns: 1fr;
  }
  .editorial-workspace-team {
    display: flex;
    overflow-x: auto;
    border-inline-end: 0;
    border-bottom: 1px solid var(--border);
  }
  .editorial-workspace-team button {
    min-width: 4rem;
    width: 4rem;
    padding: 0.4rem;
  }
  .editorial-workspace-team button > span {
    display: none;
  }
  .editorial-conversation {
    min-height: 25rem;
    padding: 1.25rem;
  }
  .editorial-approval {
    grid-column: auto;
  }
  .editorial-connections-layout {
    gap: 2rem;
  }
  .editorial-hire-grid article > strong b {
    font-size: 3.8rem;
  }
  .editorial-faq-layout .editorial-chapter-number {
    margin-bottom: 1.25rem;
  }
  .editorial-final h2 {
    font-size: 3.4rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .editorial-home *,
  .editorial-home *::before,
  .editorial-home *::after {
    scroll-behavior: auto !important;
    animation: none !important;
    transition-duration: 0.01ms !important;
  }
}

/* ═════ سهل × منطق Stripe — صفحة المنتج الكاملة ═════ */
:root {
  --stripe-navy: oklch(0.26 0.07 245);
  --stripe-navy-deep: oklch(0.19 0.055 250);
  --stripe-violet: oklch(0.58 0.24 285);
  --stripe-pink: oklch(0.67 0.23 345);
  --stripe-orange: oklch(0.72 0.18 52);
  --stripe-cyan: oklch(0.76 0.13 205);
  --stripe-wash: oklch(0.975 0.008 245);
  --stripe-line: oklch(0.88 0.018 250);
  --stripe-ink-soft: oklch(0.48 0.045 250);
  --stripe-shadow: 0 30px 80px -36px oklch(0.28 0.12 275 / 0.34);
}

.stripe-home {
  overflow: clip;
  background: var(--background);
  color: var(--stripe-navy);
  font-family: "IBM Plex Sans Arabic", ui-sans-serif, sans-serif;
}
.stripe-home h1,
.stripe-home h2,
.stripe-home h3,
.stripe-home p {
  letter-spacing: 0;
}
.stripe-shell {
  width: min(100% - 3rem, 76rem);
  margin-inline: auto;
}
.stripe-spectrum {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
.stripe-spectrum::before {
  content: "";
  position: absolute;
  inset: -35% -10% 32%;
  transform: skewY(-8deg);
  transform-origin: left top;
  background: linear-gradient(
    120deg,
    var(--stripe-orange),
    var(--stripe-pink) 34%,
    var(--stripe-violet) 68%,
    var(--stripe-cyan)
  );
  opacity: 0.92;
}
.stripe-spectrum::after {
  content: "";
  position: absolute;
  inset: 10% -15% 35%;
  transform: skewY(-8deg);
  background: linear-gradient(100deg, transparent 10%, oklch(1 0 0 / 0.38), transparent 72%);
  filter: blur(36px);
}
.stripe-spectrum i {
  position: absolute;
  z-index: 1;
  height: 1px;
  width: 55%;
  background: oklch(1 0 0 / 0.3);
  transform: rotate(-8deg);
}
.stripe-spectrum i:nth-child(1) {
  top: 18%;
  left: -5%;
}
.stripe-spectrum i:nth-child(2) {
  top: 34%;
  right: -8%;
}
.stripe-spectrum i:nth-child(3) {
  top: 50%;
  left: 24%;
}

.stripe-hero {
  position: relative;
  min-height: 57rem;
  padding: 11rem 0 8rem;
  background: var(--stripe-wash);
}
.stripe-hero::after {
  content: "";
  position: absolute;
  inset: 43% 0 0;
  background: linear-gradient(to bottom, transparent, var(--stripe-wash) 42%);
  pointer-events: none;
}
.stripe-hero-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 0.88fr 1.12fr;
  gap: 4rem;
  align-items: center;
}
.stripe-hero-copy {
  position: relative;
  z-index: 4;
  padding-top: 3rem;
}
.stripe-eyebrow {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  width: fit-content;
  margin-bottom: 1.5rem;
  color: var(--stripe-violet);
  font-size: 0.83rem;
  font-weight: 700;
}
.stripe-eyebrow svg {
  width: 1rem;
}
.stripe-hero h1 {
  max-width: 45rem;
  font-size: clamp(4rem, 7.1vw, 7.2rem);
  font-weight: 700;
  line-height: 1.07;
}
.stripe-hero h1 em {
  display: inline-block;
  font-style: normal;
  color: transparent;
  background: linear-gradient(
    95deg,
    var(--stripe-violet),
    var(--stripe-pink) 55%,
    var(--stripe-orange)
  );
  background-clip: text;
}
.stripe-hero-copy > p:not(.stripe-eyebrow) {
  max-width: 37rem;
  margin-top: 2rem;
  color: var(--stripe-ink-soft);
  font-size: 1.18rem;
  line-height: 1.85;
}
.stripe-actions {
  display: flex;
  align-items: center;
  gap: 1.4rem;
  margin-top: 2rem;
}
.stripe-primary-action,
.stripe-final a {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  min-height: 3.25rem;
  padding-inline: 1.3rem;
  border-radius: 999px;
  background: var(--stripe-navy);
  color: var(--primary-foreground);
  font-weight: 700;
  transition:
    transform 0.25s ease,
    background 0.25s ease;
}
.stripe-primary-action:hover,
.stripe-final a:hover {
  transform: translateY(-2px);
  background: var(--stripe-violet);
}
.stripe-primary-action svg,
.stripe-final a svg {
  width: 1rem;
}
.stripe-secondary-action {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  font-weight: 700;
}
.stripe-secondary-action svg {
  width: 1rem;
}
.stripe-trial {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin-top: 1.1rem;
  color: var(--stripe-ink-soft);
  font-size: 0.76rem;
}
.stripe-trial svg {
  width: 0.95rem;
  color: var(--stripe-violet);
}
.stripe-hero-product {
  position: relative;
  padding-top: 5rem;
  transform: perspective(1400px) rotateY(4deg) rotateX(1deg);
  transform-origin: center right;
}

.stripe-console {
  overflow: hidden;
  border: 1px solid oklch(1 0 0 / 0.45);
  border-radius: 0.8rem;
  background: oklch(1 0 0 / 0.94);
  box-shadow: var(--stripe-shadow);
  color: var(--stripe-navy);
}
.stripe-console-bar {
  height: 3.6rem;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding-inline: 1rem;
  border-bottom: 1px solid var(--stripe-line);
  font-size: 0.75rem;
}
.stripe-console-bar > span {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--stripe-ink-soft);
}
.stripe-console-bar > span i {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: oklch(0.72 0.18 150);
  box-shadow: 0 0 0 0.25rem oklch(0.72 0.18 150 / 0.12);
}
.stripe-console-dots {
  display: flex;
  gap: 0.3rem;
  direction: ltr;
}
.stripe-console-dots i {
