/* مساحة العمل: الدخان خلف المحتوى فقط، والذهبي للحالة النشطة والتركيز. */
.app-shell {
  position: relative;
  isolation: isolate;
  /* لا overflow: clip — يمنع ثبات الشريط العلوي (sticky) أثناء التقليب على الهواتف. */
}
.app-shell > div > header.app-topbar {
  position: sticky;
  top: 0;
  z-index: 40;
}
.app-shell > aside {
  position: sticky;
  z-index: 10;
}
.sahl-smoke-app {
  position: fixed;
  inset: 0 0 auto 0;
  height: 28rem;
  opacity: 0.48;
  mask-image: linear-gradient(to bottom, black, transparent);
}
.sahl-smoke-app i {
  opacity: 0.12;
  filter: blur(94px);
}
.app-shell > div > header {
  border-bottom-color: color-mix(in oklab, var(--gold-deep) 18%, var(--border));
  box-shadow: 0 12px 34px -34px var(--gold-deep);
}

/* المحادثة: هالة Gemini-like حول المساحة ومربع الإدخال مع نص واضح دائماً. */
.chat-stage::before,
.chat-stage::after {
  content: "";
  position: absolute;
  z-index: 0;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(82px);
  mix-blend-mode: multiply;
}
.chat-stage::before {
  top: -8rem;
  right: -8rem;
  width: 28rem;
  height: 22rem;
  background: color-mix(in oklab, var(--gold) 20%, transparent);
  animation: sahl-chat-aura 17s ease-in-out infinite alternate;
}
.chat-stage::after {
  bottom: 4rem;
  left: -9rem;
  width: 25rem;
  height: 19rem;
  background: color-mix(in oklab, var(--sky) 12%, transparent);
  animation: sahl-chat-aura 21s ease-in-out infinite alternate-reverse;
}
@keyframes sahl-chat-aura {
  to {
    transform: translate3d(10%, 8%, 0) scale(1.12);
  }
}
.chat-stage > * {
  position: relative;
  z-index: 1;
}
.chat-composer {
  position: relative;
  isolation: isolate;
  border-color: color-mix(in oklab, var(--gold-deep) 48%, var(--border));
  background: color-mix(in oklab, var(--card) 88%, transparent);
  box-shadow:
    0 22px 60px -38px var(--gold-deep),
    inset 0 1px 0 oklch(1 0 0 / 0.92);
}
.chat-composer::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -0.45rem;
  border-radius: inherit;
  background: linear-gradient(
    105deg,
    color-mix(in oklab, var(--gold) 28%, transparent),
    color-mix(in oklab, var(--coral) 12%, transparent),
    color-mix(in oklab, var(--sky) 16%, transparent),
    color-mix(in oklab, var(--gold) 28%, transparent)
  );
  background-size: 260% 100%;
  filter: blur(15px);
  opacity: 0.7;
  animation: sahl-composer-smoke 9s ease-in-out infinite alternate;
}
@keyframes sahl-composer-smoke {
  to {
    background-position: 100% 0;
    transform: scale(1.012);
  }
}
.chat-composer button[type="submit"] {
  background: var(--primary);
  color: var(--primary-foreground);
  box-shadow: 0 10px 24px -14px var(--gold-deep);
}
.bubble-user {
  background-image: linear-gradient(145deg, oklch(0.19 0.012 70), oklch(0.28 0.055 75));
}

@media (max-width: 700px) {
  .sahl-smoke i {
    width: 34rem;
    filter: blur(64px);
    opacity: 0.2;
  }
  .sahl-smoke-hero {
    bottom: 35%;
  }
  .sahl-smoke-app {
    height: 20rem;
    opacity: 0.45;
  }
  .chat-stage::before,
  .chat-stage::after {
    filter: blur(68px);
    opacity: 0.72;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sahl-smoke i,
  .chat-stage::before,
  .chat-stage::after,
  .chat-composer::before {
    animation: none !important;
  }
}

/* ═════ مركز محادثة الموظف — دخان ذهبي متحرك + مربع إدخال شفاف ═════
   يعتمد على متغيّرين يضبطهما كل موظف: --chat-accent و --chat-accent-soft. */
.chat-stage {
  --chat-accent: var(--gold);
  --chat-accent-soft: color-mix(in oklab, var(--gold) 16%, transparent);
  position: relative;
  isolation: isolate;
  background: var(--background);
}

/* الدخان الذهبي: يروح وييجي ويخلّف آثار مروره. */
.chat-smoke {
  position: absolute;
  z-index: 0;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  contain: paint;
}
.chat-smoke i {
  position: absolute;
  display: block;
  width: min(46rem, 78vw);
  aspect-ratio: 1.35;
  border-radius: 48% 52% 60% 40%;
  filter: blur(64px);
  opacity: 0.32;
  will-change: transform, opacity;
}
.chat-smoke i:nth-child(1) {
  inset: -14% auto auto -12%;
  background: color-mix(in oklab, var(--chat-accent) 46%, var(--gold) 54%);
  animation: chat-smoke-a 26s ease-in-out infinite alternate;
}
.chat-smoke i:nth-child(2) {
  inset: 8% -18% auto auto;
  background: color-mix(in oklab, var(--gold) 62%, var(--chat-accent) 38%);
  animation: chat-smoke-b 33s ease-in-out infinite alternate;
}
.chat-smoke i:nth-child(3) {
  inset: auto 14% -22% auto;
  background: color-mix(in oklab, var(--chat-accent) 40%, var(--amber, var(--gold)) 60%);
  animation: chat-smoke-c 39s ease-in-out infinite alternate;
}
/* آثار المرور: خطوط ضوئية باهتة تبقى بعد تحرّك الدخان. */
.chat-smoke b {
  position: absolute;
  inset-inline: -10%;
  height: 22rem;
  display: block;
  border-radius: 50%;
  background: radial-gradient(
    60% 100% at 50% 50%,
    color-mix(in oklab, var(--chat-accent) 13%, transparent),
    transparent 72%
  );
  filter: blur(38px);
  opacity: 0;
  will-change: transform, opacity;
}
.chat-smoke b:nth-of-type(1) {
  top: 6%;
  animation: chat-smoke-trail 18s ease-in-out infinite;
}
.chat-smoke b:nth-of-type(2) {
  top: 42%;
  animation: chat-smoke-trail 23s ease-in-out infinite 4s;
}
.chat-smoke b:nth-of-type(3) {
  bottom: 4%;
  animation: chat-smoke-trail 29s ease-in-out infinite 9s;
}
@keyframes chat-smoke-a {
  0% {
    opacity: 0.1;
    transform: translate3d(-7%, -4%, 0) rotate(-4deg) scale(0.86);
  }
  40% {
    opacity: 0.4;
    transform: translate3d(9%, 6%, 0) rotate(4deg) scale(1.1);
  }
  75% {
    opacity: 0.16;
    transform: translate3d(20%, 12%, 0) rotate(9deg) scale(1.18);
  }
  100% {
    opacity: 0.45;
    transform: translate3d(11%, 1%, 0) rotate(2deg) scale(0.96);
  }
}
@keyframes chat-smoke-b {
  0% {
    opacity: 0.08;
    transform: translate3d(10%, -6%, 0) rotate(4deg) scale(0.9);
  }
  45% {
    opacity: 0.3;
    transform: translate3d(-6%, 9%, 0) rotate(-5deg) scale(1.14);
  }
  80% {
    opacity: 0.12;
    transform: translate3d(-19%, 15%, 0) rotate(-11deg) scale(0.95);
  }
  100% {
    opacity: 0.28;
    transform: translate3d(-8%, 3%, 0) rotate(3deg) scale(1.06);
  }
}
@keyframes chat-smoke-c {
  0% {
    opacity: 0.07;
    transform: translate3d(7%, 13%, 0) rotate(-3deg) scale(0.9);
  }
  38% {
    opacity: 0.3;
    transform: translate3d(-5%, -5%, 0) rotate(5deg) scale(1.12);
  }
  74% {
    opacity: 0.12;
    transform: translate3d(-15%, -17%, 0) rotate(8deg) scale(1.2);
  }
  100% {
    opacity: 0.26;
    transform: translate3d(2%, -6%, 0) rotate(-2deg) scale(0.98);
  }
}
@keyframes chat-smoke-trail {
  0% {
    opacity: 0;
    transform: translate3d(-24%, 0, 0) scaleY(0.7);
  }
  18% {
    opacity: 0.9;
  }
  50% {
    opacity: 0.55;
    transform: translate3d(6%, 0, 0) scaleY(1.05);
  }
  82% {
    opacity: 0.2;
  }
  100% {
    opacity: 0;
    transform: translate3d(26%, 0, 0) scaleY(0.8);
  }
}

/* الشريط الثابت: صف واحد نظيف — الهوية · المحادثة الحالية · القدرات · التطبيقات. */
.employee-command-bar {
  position: sticky;
  z-index: 26;
  top: 4rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-height: 3.9rem;
  margin-inline: -0.4rem;
  padding: 0.5rem 0.7rem;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 18%, var(--border));
  border-top-color: transparent;
  border-radius: 0 0 1.1rem 1.1rem;
  background: color-mix(in oklab, var(--background) 62%, transparent);
  box-shadow:
    0 1px 0 0 color-mix(in oklab, var(--chat-accent) 22%, transparent) inset,
    0 22px 44px -40px var(--foreground);
  backdrop-filter: blur(26px) saturate(1.2);
}
.employee-command-bar::after {
  content: "";
  position: absolute;
  inset-inline: 12%;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--chat-accent) 55%, transparent),
    transparent
  );
  pointer-events: none;
}
.employee-command-identity {
  border-inline-end-color: color-mix(in oklab, var(--chat-accent) 20%, var(--border));
}
.employee-command-identity .chat-live-dot {
  background: var(--chat-accent);
  box-shadow: 0 0 0 0 color-mix(in oklab, var(--chat-accent) 60%, transparent);
  animation: chat-live-pulse 2.4s ease-out infinite;
}
@keyframes chat-live-pulse {
  70% {
    box-shadow: 0 0 0 0.32rem color-mix(in oklab, var(--chat-accent) 0%, transparent);
  }
  100% {
    box-shadow: 0 0 0 0 color-mix(in oklab, var(--chat-accent) 0%, transparent);
  }
}

/* منتقي المحادثات داخل الشريط نفسه. */
.chat-thread-picker {
  position: relative;
  flex: 0 0 auto;
}
.chat-thread-trigger {
  display: inline-flex;
  max-width: 13rem;
  min-height: 2.3rem;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid var(--border);
  border-radius: 0.7rem;
  padding-inline: 0.7rem;
  background: color-mix(in oklab, var(--card) 55%, transparent);
  font-size: 0.72rem;
  font-weight: 800;
  transition: 180ms ease;
}
.chat-thread-trigger:hover,
.chat-thread-trigger[aria-expanded="true"] {
  border-color: color-mix(in oklab, var(--chat-accent) 48%, var(--border));
  color: color-mix(in oklab, var(--chat-accent) 72%, var(--foreground));
}
.chat-thread-trigger span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chat-thread-menu {
  position: absolute;
  z-index: 40;
  top: calc(100% + 0.5rem);
  inset-inline-start: 0;
  width: min(20rem, 82vw);
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 16%, var(--border));
  border-radius: 0.9rem;
  background: color-mix(in oklab, var(--card) 92%, transparent);
  box-shadow: 0 28px 60px -34px var(--foreground);
  backdrop-filter: blur(22px);
  animation: chat-menu-in 180ms cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes chat-menu-in {
  from {
    opacity: 0;
    transform: translateY(-0.35rem);
  }
}
.chat-thread-menu-list {
  max-height: 46dvh;
  overflow-y: auto;
  padding: 0.4rem;
}
.chat-thread-row {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  border: 1px solid transparent;
  border-radius: 0.6rem;
  padding: 0.15rem 0.3rem;
}
.chat-thread-row:hover {
  background: color-mix(in oklab, var(--chat-accent) 8%, transparent);
}
.chat-thread-row.is-active {
  border-color: color-mix(in oklab, var(--chat-accent) 40%, transparent);
  background: color-mix(in oklab, var(--chat-accent) 12%, transparent);
}

/* لوحة الترحيب قبل الإرسال. */
.chat-welcome-avatar {
  border-color: color-mix(in oklab, var(--background) 88%, var(--chat-accent));
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--chat-accent) 28%, transparent),
    0 18px 40px -24px var(--foreground);
  animation: chat-welcome-float 7s ease-in-out infinite alternate;
}
.chat-welcome-avatar.is-employee {
  animation-delay: -3.2s;
}
@keyframes chat-welcome-float {
  to {
    transform: translateY(-0.4rem) rotate(0deg);
  }
}
.chat-welcome-eyebrow {
  align-self: center;
  color: color-mix(in oklab, var(--chat-accent) 72%, var(--foreground));
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.01em;
  text-align: center;
}
.chat-welcome h2 {
  margin-top: 0.8rem;
}
.typewriter-caret {
  background: var(--chat-accent, var(--primary));
}

/* مربع الإدخال: شفاف من كل الاتجاهات، والكلام حوله يبقى مقروءاً. */
.chat-composer-dock {
  position: fixed;
  inset-inline: 0;
  bottom: 0;
  z-index: 40;
  background: transparent;
}
.chat-message-column {
  padding-bottom: 9rem;
}
@media (min-width: 1024px) {
  .chat-composer-dock {
    inset-inline-start: 16rem;
  }
}
.chat-composer {
  position: relative;
  border-color: color-mix(in oklab, var(--chat-accent) 26%, var(--border));
  background: color-mix(in oklab, var(--background) 26%, transparent);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--background) 30%, transparent) inset,
    0 26px 60px -46px var(--foreground);
  backdrop-filter: blur(9px) saturate(1.1);
  transition: 220ms ease;
}
.chat-composer::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -0.7rem;
  border-radius: 1.6rem;
  background: radial-gradient(
    70% 120% at 50% 100%,
    color-mix(in oklab, var(--chat-accent) 12%, transparent),
    transparent 70%
  );
  opacity: 0.85;
  pointer-events: none;
  animation: chat-composer-halo 9s ease-in-out infinite alternate;
}
@keyframes chat-composer-halo {
  to {
    opacity: 0.35;
    transform: translateY(-0.25rem) scale(1.03);
  }
}
.chat-composer:focus-within {
  border-color: color-mix(in oklab, var(--chat-accent) 55%, var(--border));
  background: color-mix(in oklab, var(--background) 42%, transparent);
  box-shadow:
    0 0 0 4px color-mix(in oklab, var(--chat-accent) 12%, transparent),
    0 30px 70px -46px var(--foreground);
}
.chat-composer textarea::placeholder {
  color: color-mix(in oklab, var(--muted-foreground) 88%, var(--chat-accent));
  opacity: 1;
}

@media (max-width: 640px) {
  .chat-thread-trigger {
    max-width: 7.5rem;
  }
  .chat-smoke i {
    filter: blur(48px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .chat-smoke i,
  .chat-smoke b,
  .chat-welcome-avatar,
  .chat-composer::before,
  .employee-command-identity .chat-live-dot {
    animation: none !important;
  }
  .chat-smoke b {
    opacity: 0.25;
  }
}

/* شريط الموظف الموحد: كل الأدوات في سطر واحد واضح وقابل للسحب على الشاشات الضيقة. */
.employee-command-bar {
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scrollbar-width: none;
}
.employee-command-bar::-webkit-scrollbar {
  display: none;
}
.employee-command-link {
  display: inline-flex;
  min-height: 2.3rem;
  flex: 0 0 auto;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 14%, var(--border));
  border-radius: 0.7rem;
  padding-inline: 0.7rem;
  background: color-mix(in oklab, var(--card) 48%, transparent);
  color: var(--ink-soft);
  font-size: 0.7rem;
  font-weight: 800;
  white-space: nowrap;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}
.employee-command-link:hover {
  border-color: color-mix(in oklab, var(--chat-accent) 45%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 9%, transparent);
  color: var(--foreground);
  transform: translateY(-1px);
}

/* لوحة محادثات الموظف: هوية، حسابات، سجل، تنفيذ، ومراجع في تسلسل بصري واحد. */
.chat-thread-panel {
  padding: 0.9rem;
  border-color: color-mix(in oklab, var(--chat-accent) 18%, var(--border));
  background:
    linear-gradient(
      150deg,
      color-mix(in oklab, var(--chat-accent) 8%, transparent),
      transparent 16rem
    ),
    color-mix(in oklab, var(--card) 88%, transparent);
  backdrop-filter: blur(28px) saturate(1.18);
}
.chat-side-employee {
  position: sticky;
  z-index: 2;
  top: -0.9rem;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  margin: -0.9rem -0.9rem 0.8rem;
  padding: 1rem 0.9rem 0.85rem;
  border-bottom: 1px solid color-mix(in oklab, var(--chat-accent) 18%, var(--border));
  background: color-mix(in oklab, var(--card) 82%, transparent);
  backdrop-filter: blur(22px);
}
.chat-side-employee > button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 0.6rem;
  color: var(--muted-foreground);
  transition: 180ms ease;
}
.chat-side-employee > button:hover {
  background: var(--secondary);
  color: var(--foreground);
}
.chat-side-section {
  margin-bottom: 0.75rem;
  padding: 0.8rem;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 12%, var(--border));
  border-radius: 0.75rem;
  background: color-mix(in oklab, var(--background) 52%, transparent);
}
.chat-side-tabs {
  position: sticky;
  z-index: 2;
  top: 5.05rem;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.25rem;
  margin: 0 -0.2rem;
  padding: 0.6rem 0.2rem;
  background: color-mix(in oklab, var(--background) 82%, transparent);
  backdrop-filter: blur(22px);
}
.chat-side-tabs button {
  min-height: 2.2rem;
  border-radius: 999px;
  color: var(--muted-foreground);
  font-size: 0.68rem;
  font-weight: 800;
  transition: 180ms ease;
}
.chat-side-tabs button:hover,
.chat-side-tabs button.is-active {
  background: color-mix(in oklab, var(--chat-accent) 9%, transparent);
  color: var(--foreground);
}
.chat-side-label {
  color: var(--muted-foreground);
  font-size: 0.67rem;
  font-weight: 800;
}
.chat-side-thread {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  border: 1px solid transparent;
  border-radius: 0.6rem;
  padding: 0.25rem 0.35rem;
  transition: 180ms ease;
}
.chat-side-thread:hover {
  background: color-mix(in oklab, var(--chat-accent) 7%, transparent);
}
.chat-side-links {
  display: grid;
  gap: 0.45rem;
}
.chat-side-links > a,
.chat-side-links > button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.7rem;
  min-height: 3.5rem;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 14%, var(--border));
  border-radius: 0.7rem;
  padding: 0.65rem 0.75rem;
  background: color-mix(in oklab, var(--background) 48%, transparent);
  font-size: 0.75rem;
  font-weight: 800;
  transition: 180ms ease;
}
.chat-side-links > a:hover,
.chat-side-links > button:hover {
  border-color: color-mix(in oklab, var(--chat-accent) 42%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 8%, transparent);
}
.chat-side-links small {
  display: block;
  margin-top: 0.1rem;
  color: var(--muted-foreground);
  font-size: 0.62rem;
  font-weight: 600;
}

/* قائمتا الوسائط والطول تطفوان أعلى مربع الكتابة بزجاج شفاف. */
.chat-tool-launcher {
  display: flex;
  gap: 0.45rem;
  padding: 0.3rem 0.35rem 0.45rem;
  border-top: 1px solid color-mix(in oklab, var(--chat-accent) 14%, var(--border));
}
.chat-tool-choice {
  display: inline-flex;
  min-height: 2.15rem;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid var(--border);
  border-radius: 0.65rem;
  padding-inline: 0.75rem;
  background: color-mix(in oklab, var(--background) 42%, transparent);
  color: var(--ink-soft);
  font-size: 0.7rem;
  font-weight: 800;
  transition: 180ms ease;
}
.chat-tool-choice > span {
  display: grid;
  min-width: 1.1rem;
  height: 1.1rem;
  place-items: center;
  border-radius: 999px;
  background: var(--foreground);
  color: var(--background);
  font-size: 0.58rem;
}
.chat-tool-choice:hover,
.chat-tool-choice.is-active {
  border-color: color-mix(in oklab, var(--chat-accent) 52%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 10%, transparent);
  color: var(--foreground);
}
.chat-tool-popover {
  position: absolute;
  z-index: 35;
  inset-inline: 0;
  bottom: calc(100% + 0.65rem);
  max-height: min(65dvh, 36rem);
  overflow-y: auto;
  border: 1px solid color-mix(in oklab, var(--chat-accent) 24%, var(--border));
  border-radius: 0.9rem;
  padding: 0.75rem;
  background:
    linear-gradient(
      145deg,
      color-mix(in oklab, var(--chat-accent) 8%, transparent),
      transparent 50%
    ),
    color-mix(in oklab, var(--background) 76%, transparent);
  box-shadow: 0 28px 70px -40px var(--foreground);
  backdrop-filter: blur(26px) saturate(1.18);
}
.chat-tool-popover-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 1rem;
  margin-bottom: 0.65rem;
  padding: 0.1rem 0.15rem 0.65rem;
  border-bottom: 1px solid var(--border);
}
.chat-tool-popover-head p {
  font-size: 0.78rem;
  font-weight: 900;
}
.chat-tool-popover-head span {
  color: var(--muted-foreground);
  font-size: 0.65rem;
}
.chat-tool-popover-head button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 0.6rem;
  color: var(--muted-foreground);
}
.chat-tool-popover-head button:hover {
  background: var(--secondary);
  color: var(--foreground);
}
.chat-length-options {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
}
.chat-length-option {
  position: relative;
  display: flex;
  min-height: 4.4rem;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: 0.7rem;
  padding: 0.65rem;
  background: color-mix(in oklab, var(--card) 55%, transparent);
  text-align: start;
  transition: 180ms ease;
}
.chat-length-option > span {
  font-size: 0.76rem;
  font-weight: 900;
}
.chat-length-option small {
  color: var(--muted-foreground);
  font-size: 0.62rem;
}
.chat-length-option svg {
  position: absolute;
  top: 0.55rem;
  inset-inline-end: 0.55rem;
  color: var(--chat-accent);
}
.chat-length-option:hover,
.chat-length-option.is-active {
  border-color: color-mix(in oklab, var(--chat-accent) 55%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 10%, transparent);
}

@media (max-width: 640px) {
  .employee-command-bar {
    margin-inline: -0.75rem;
    border-inline: 0;
    border-radius: 0;
  }
  .employee-command-identity {
    position: sticky;
    z-index: 2;
    inset-inline-start: 0;
    min-width: 6.25rem;
    padding-inline: 0.35rem 0.55rem;
    background: color-mix(in oklab, var(--background) 88%, transparent);
    backdrop-filter: blur(18px);
  }
  .employee-command-identity > span:last-child {
    display: block;
  }
  .employee-command-skills {
    min-width: max-content;
    flex: 0 0 auto;
  }
  .employee-command-link span {
    display: inline;
  }
  .chat-length-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .chat-tool-popover {
    inset-inline: -0.15rem;
    max-height: 58dvh;
    padding: 0.6rem;
  }
}

/* محادثة الموظف — اتجاه زجاجي هادئ وخفيف. */
.employee-command-bar {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.55rem;
  min-height: 3.65rem;
  margin-inline: 0;
  padding: 0.45rem 0.55rem;
  overflow: visible;
  border-color: color-mix(in oklab, var(--border) 68%, transparent);
  border-top: 0;
  border-radius: 0 0 0.85rem 0.85rem;
  background: color-mix(in oklab, var(--background) 78%, transparent);
  box-shadow: 0 12px 28px -30px var(--foreground);
  backdrop-filter: blur(24px) saturate(1.12);
}
.employee-command-bar::after {
  display: none;
}
.employee-command-identity {
  grid-column: 1;
  gap: 0.5rem;
  min-width: 7.4rem;
  padding-inline-end: 0.65rem;
  border-inline-end: 1px solid color-mix(in oklab, var(--border) 72%, transparent);
}
.employee-command-identity > span:first-child {
  border-radius: 999px;
  box-shadow:
    0 0 0 2px var(--background),
    0 0 0 3px color-mix(in oklab, var(--chat-accent) 22%, var(--border));
}
.employee-command-skills {
  grid-column: 2;
  min-width: 0;
  overflow: hidden;
}
.employee-command-skills .employee-command-scroll {
  padding-block: 0.1rem;
}
.employee-command-link {
  min-height: 2.15rem;
  border-color: transparent;
  border-radius: 999px;
  padding-inline: 0.62rem;
  background: transparent;
  color: var(--muted-foreground);
  font-size: 0.68rem;
}
.employee-command-link:hover {
  border-color: color-mix(in oklab, var(--chat-accent) 18%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 7%, transparent);
  transform: none;
}
.employee-command-apps {
  display: none;
}
.employee-command-history {
  grid-column: 3;
  grid-row: 1;
  width: 2.4rem;
  min-height: 2.4rem;
  justify-content: center;
  border-color: color-mix(in oklab, var(--border) 72%, transparent);
  border-radius: 0.75rem;
  padding: 0;
  background: color-mix(in oklab, var(--background) 56%, transparent);
}
.employee-command-history span {
  display: none;
}

.chat-thread-backdrop {
  background: color-mix(in oklab, var(--foreground) 14%, transparent);
  backdrop-filter: blur(5px);
}
.chat-thread-panel {
  inset-block: 4rem 0;
  width: min(23rem, 90vw);
  padding: 0 1rem 1.5rem;
  border-inline-start: 1px solid color-mix(in oklab, var(--border) 72%, transparent);
  background: color-mix(in oklab, var(--background) 86%, transparent);
  box-shadow: 0 26px 70px -32px var(--foreground);
  backdrop-filter: blur(30px) saturate(1.08);
}
.chat-side-employee {
  top: 0;
  margin: 0 -1rem;
  padding: 1rem;
  border-bottom-color: color-mix(in oklab, var(--border) 72%, transparent);
  background: color-mix(in oklab, var(--background) 80%, transparent);
}
.chat-side-employee > span:first-child {
  border-radius: 999px;
}
.chat-side-section {
  margin: 0;
  padding: 1.15rem 0;
  border: 0;
  border-bottom: 1px solid color-mix(in oklab, var(--border) 68%, transparent);
  border-radius: 0;
  background: transparent;
}
.chat-side-label {
  font-size: 0.64rem;
  letter-spacing: 0;
}
.chat-side-accounts {
  display: flex;
  gap: 0.45rem;
  margin-top: 0.75rem;
  padding-bottom: 0.15rem;
  overflow-x: auto;
  scrollbar-width: none;
}
.chat-side-accounts::-webkit-scrollbar {
  display: none;
}
.chat-side-accounts > span {
  min-width: max-content;
  border-color: color-mix(in oklab, var(--border) 72%, transparent) !important;
  border-radius: 999px !important;
  background: color-mix(in oklab, var(--background) 50%, transparent);
}
.chat-side-thread {
  min-height: 2.7rem;
  border-radius: 0.65rem;
  padding-inline: 0.35rem;
}
.chat-side-thread:hover,
.chat-side-thread.border-primary\/40 {
  background: color-mix(in oklab, var(--chat-accent) 7%, transparent);
}
.chat-side-links {
  gap: 0;
  padding-top: 0.5rem;
}
.chat-side-links > a,
.chat-side-links > button {
  min-height: 3.35rem;
  border: 0;
  border-bottom: 1px solid color-mix(in oklab, var(--border) 62%, transparent);
  border-radius: 0;
  background: transparent;
}
.chat-side-links > a:hover,
.chat-side-links > button:hover {
  border-bottom-color: color-mix(in oklab, var(--chat-accent) 24%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 5%, transparent);
}
.chat-side-section .mt-5 {
  margin-top: 0;
}
.chat-side-section ul > li {
  border-inline: 0;
  border-radius: 0;
}

.chat-composer-dock {
  padding-bottom: max(0.7rem, env(safe-area-inset-bottom));
}
.chat-composer {
  border-color: color-mix(in oklab, var(--border) 76%, transparent);
  border-radius: 1.15rem;
  background: color-mix(in oklab, var(--background) 34%, transparent);
  box-shadow: 0 18px 48px -38px var(--foreground);
  backdrop-filter: blur(14px) saturate(1.08);
}
.chat-composer > [data-slot="input-group"] {
  position: relative;
  overflow: visible;
}
.chat-composer-textarea {
  height: 3rem;
  flex: 0 0 3rem;
}
.chat-composer-placeholder {
  position: absolute;
  z-index: 2;
  inset-inline: 0.75rem;
  top: 0;
  height: 3rem;
  overflow: hidden;
  pointer-events: none;
  display: flex;
  align-items: center;
  white-space: nowrap;
  color: color-mix(in oklab, var(--muted-foreground) 88%, var(--chat-accent));
  font-size: 0.875rem;
  line-height: 1.5rem;
}
.chat-composer-caret {
  flex: none;
  color: var(--chat-accent);
  animation: chat-caret 0.85s steps(1) infinite;
}
.chat-composer::before {
  display: none;
}
.chat-tool-launcher {
  position: absolute;
  z-index: 36;
  inset-inline-end: 0.55rem;
  bottom: calc(100% + 1.35rem);
  display: flex;
  gap: 0.45rem;
  padding: 0;
  border: 0;
  background: transparent;
  animation: chat-tools-rise 180ms cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes chat-tools-rise {
  from {
    opacity: 0;
    transform: translateY(0.4rem);
  }
}
.chat-tool-choice {
  min-height: 2.35rem;
  border-color: color-mix(in oklab, var(--border) 78%, transparent);
  border-radius: 999px;
  padding-inline: 0.85rem;
  background: color-mix(in oklab, var(--background) 58%, transparent);
  box-shadow: 0 10px 28px -22px var(--foreground);
  backdrop-filter: blur(18px) saturate(1.08);
}
.chat-tool-choice:hover,
.chat-tool-choice.is-active {
  background: color-mix(in oklab, var(--background) 78%, transparent);
}
.chat-tool-popover {
  bottom: calc(100% + 3.55rem);
  border-color: color-mix(in oklab, var(--border) 72%, transparent);
  border-radius: 1rem;
  background: color-mix(in oklab, var(--background) 84%, transparent);
  box-shadow: 0 28px 64px -38px var(--foreground);
  backdrop-filter: blur(28px) saturate(1.08);
}
.chat-length-options {
  display: flex;
  gap: 0.35rem;
}
.chat-length-option {
  min-height: 2.55rem;
  flex: 1;
  align-items: center;
  border-color: transparent;
  border-radius: 999px;
  padding: 0.45rem;
  background: transparent;
  text-align: center;
}
.chat-length-option small,
.chat-length-option svg {
  display: none;
}
.chat-length-option:hover,
.chat-length-option.is-active {
  border-color: color-mix(in oklab, var(--chat-accent) 20%, var(--border));
  background: color-mix(in oklab, var(--chat-accent) 9%, transparent);
}

@media (max-width: 640px) {
  .employee-command-bar {
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0.35rem;
    margin-inline: -0.75rem;
    padding: 0.4rem 0.55rem;
    overflow: visible;
  }
  .employee-command-identity {
    position: static;
    min-width: 6.2rem;
    padding-inline: 0 0.5rem;
    background: transparent;
    backdrop-filter: none;
  }
  .employee-command-identity > span:last-child {
    display: block;
  }
  .employee-command-identity > span:first-child {
    width: 2.1rem;
    height: 2.1rem;
  }
  .employee-command-skills {
    min-width: 0;
    overflow-x: auto;
    scrollbar-width: none;
  }
  .employee-command-skills .employee-command-scroll {
    display: flex;
    min-width: max-content;
  }
  .employee-command-link,
  .employee-command-apps {
    display: none;
  }
  .chat-thread-panel {
    width: min(22rem, 88vw);
  }
  .chat-tool-popover {
    inset-inline: 0;
    bottom: calc(100% + 3.45rem);
    max-height: 58dvh;
  }
  .chat-length-options {
    display: flex;
  }
}

/* الشريط العلوي العائم: حبة واحدة دائرية الأطراف تحمل كل أزرار الموظف. */
.app-topbar {
  background: transparent;
}
.app-topbar-inner {
  border: 1px solid color-mix(in oklab, var(--gold) 16%, var(--border));
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 28%, transparent);
  box-shadow:
    0 1px 0 0 color-mix(in oklab, var(--cream) 60%, transparent) inset,
    0 24px 48px -38px var(--foreground);
  backdrop-filter: blur(10px) saturate(1.08);
}
@media (max-width: 640px) {
  .app-topbar {
    padding-inline: 0.45rem;
    padding-top: max(0.45rem, env(safe-area-inset-top));
  }
  .app-topbar-inner {
    min-height: 3.75rem;
    gap: 0.35rem;
    padding: 0.35rem;
    border-radius: 1.35rem;
  }
  .app-topbar-inner > button,
  .app-topbar-inner > div:last-child > button:last-child {
    width: 2.65rem;
    height: 2.65rem;
    min-width: 2.65rem;
  }
  .chat-topbar-actions {
    gap: 0.4rem;
    justify-content: flex-start;
    padding-inline: 0.1rem;
    scroll-padding-inline: 0.5rem;
    overscroll-behavior-inline: contain;
    scroll-snap-type: inline proximity;
  }
  .chat-topbar-actions > * {
    flex: none;
    scroll-snap-align: start;
  }
  .chat-topbar-actions > div:first-child {
    width: 2.5rem;
    min-width: 2.5rem;
  }
}

/* أزرار الشريط: مدمجة، أيقونة + نص يظهر على الشاشات الأوسع. */
.topbar-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  height: 2.25rem;
  padding-inline: 0.7rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: color-mix(in oklab, var(--background) 60%, transparent);
  font-size: 0.72rem;
  font-weight: 800;
  white-space: nowrap;
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}
.topbar-pill:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: color-mix(in oklab, var(--primary) 40%, var(--border));
}
.topbar-pill:disabled {
  opacity: 0.5;
}
.topbar-pill.is-active {
  border-color: color-mix(in oklab, var(--primary) 45%, var(--border));
  background: color-mix(in oklab, var(--primary) 12%, transparent);
  color: var(--primary);
}
.topbar-pill > small {
  border-radius: 999px;
  background: color-mix(in oklab, var(--secondary) 80%, transparent);
  padding: 0.05rem 0.35rem;
  font-size: 0.62rem;
  font-variant-numeric: tabular-nums;
  color: var(--muted-foreground);
}
@media (max-width: 900px) {
  .topbar-pill > span {
    display: none;
  }
  .topbar-pill {
    padding-inline: 0.55rem;
  }
}
@media (max-width: 640px) {
  .topbar-pill,
  .chat-new-button,
  .chat-topbar-actions > div > button {
    width: 2.5rem;
    height: 2.5rem;
    min-width: 2.5rem;
    min-height: 2.5rem;
    justify-content: center;
    padding: 0;
  }
  .topbar-pill > small {
    display: none;
  }
}
@media (max-width: 380px) {
  .chat-new-button {
    display: none;
  }
}

/* لوحات الشريط: تُفتح داخل نفس الصفحة أسفل الشريط بزجاج نظيف. */
.topbar-sheet-backdrop {
  position: fixed;
  inset: 0;
  z-index: 44;
  background: transparent;
  backdrop-filter: none;
}
.topbar-sheet {
  position: fixed;
  z-index: 46;
  top: 4.6rem;
  inset-inline-end: 0.75rem;
  width: min(25rem, calc(100vw - 1.5rem));
  max-height: min(72dvh, 42rem);
  overflow-y: auto;
  padding: 0.9rem;
  border: 1px solid color-mix(in oklab, var(--gold) 16%, var(--border));
  border-radius: 1.4rem;
  background: color-mix(in oklab, var(--background) 88%, transparent);
  box-shadow: 0 40px 80px -50px var(--foreground);
  backdrop-filter: blur(30px) saturate(1.2);
  opacity: 1 !important;
  animation: none;
}
@media (max-width: 640px) {
  .topbar-sheet {
    top: 4.65rem;
    inset-inline: 0.5rem;
    width: auto;
    max-height: calc(100dvh - 5.15rem - env(safe-area-inset-bottom));
    padding: 0.75rem;
    border-radius: 1.15rem;
    overscroll-behavior: contain;
  }
  .topbar-sheet-head {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0.5rem;
  }
  .topbar-sheet-head > div {
    min-width: 0;
  }
  .topbar-sheet-head p,
  .topbar-sheet-head span {
    overflow-wrap: anywhere;
  }
  .topbar-sheet-head button,
  .chat-history-row > button:last-child {
    width: 2.75rem;
    height: 2.75rem;
  }
  .topbar-app-row {
    min-height: 3.25rem;
    gap: 0.5rem;
  }
  .topbar-app-row button,
  .chat-history-new {
    min-height: 2.75rem;
  }
}

.chat-history-sheet,
.chat-work-sheet {
  margin-top: 0.75rem;
}
.chat-history-search {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  min-height: 2.65rem;
  border: 1px solid var(--border);
  border-radius: 0.8rem;
  padding-inline: 0.75rem;
  color: var(--muted-foreground);
  background: color-mix(in oklab, var(--background) 48%, transparent);
}
.chat-history-search input {
  min-width: 0;
  flex: 1;
  background: transparent;
  color: var(--foreground);
  font-size: 0.8rem;
  outline: none;
}
.chat-history-new {
  display: flex;
  width: 100%;
  min-height: 2.65rem;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  margin-top: 0.55rem;
  border-radius: 0.8rem;
  background: var(--foreground);
  color: var(--background);
  font-size: 0.78rem;
  font-weight: 800;
}
.chat-history-list {
  display: grid;
  gap: 0.25rem;
  margin-top: 0.65rem;
}
.chat-history-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  border-bottom: 1px solid color-mix(in oklab, var(--border) 68%, transparent);
}
.chat-history-row.is-active {
  border-radius: 0.75rem;
  border-color: color-mix(in oklab, var(--primary) 24%, var(--border));
  background: color-mix(in oklab, var(--primary) 7%, transparent);
}
.chat-history-row > button:first-child {
  min-width: 0;
  padding: 0.65rem;
  text-align: start;
}
.chat-history-row strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.8rem;
}
.chat-history-row time {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  margin-top: 0.2rem;
  color: var(--muted-foreground);
  font-size: 0.64rem;
}
.chat-history-row > button:last-child {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 0.6rem;
  color: var(--muted-foreground);
}
.chat-history-row > button:last-child:hover {
  background: color-mix(in oklab, var(--coral) 10%, transparent);
  color: var(--coral);
}
.chat-history-empty {
  padding: 1.5rem 0.5rem;
  text-align: center;
  color: var(--muted-foreground);
  font-size: 0.75rem;
}
.chat-work-sheet .mt-5 {
  margin-top: 0;
}
.chat-work-links {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.5rem;
  margin-top: 0.75rem;
}
.chat-work-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.65rem;
  min-height: 4.25rem;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 0.55rem;
}
.chat-work-card:hover {
  border-color: color-mix(in oklab, var(--primary) 34%, var(--border));
  background: color-mix(in oklab, var(--primary) 7%, transparent);
}
.chat-work-card-icon {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  place-items: center;
  border-radius: 0.65rem;
  background: var(--secondary);
  color: var(--primary);
}
.chat-work-card strong,
.chat-work-card small {
  display: block;
}
.chat-work-card strong {
  font-size: 0.72rem;
  font-weight: 800;
}
.chat-work-card small {
  margin-top: 0.12rem;
  color: var(--muted-foreground);
  font-size: 0.62rem;
}
.chat-work-card-actions {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}
.chat-work-card-actions button,
.chat-work-card-actions a {
  display: grid;
  min-height: 2rem;
  place-items: center;
  border-radius: 0.55rem;
  background: var(--secondary);
  font-size: 0.66rem;
  font-weight: 800;
}
.chat-inline-tool {
  width: 100%;
  min-height: min(38rem, 65dvh);
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--primary) 25%, var(--border));
  border-radius: 0.9rem;
  background: var(--background);
}
.chat-inline-tool > header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 0.4rem;
  min-height: 3.25rem;
  padding-inline: 0.75rem;
  border-bottom: 1px solid var(--border);
}
.chat-inline-tool > header strong,
.chat-inline-tool > header span {
  display: block;
}
.chat-inline-tool > header strong {
  font-size: 0.78rem;
}
.chat-inline-tool > header span {
  color: var(--muted-foreground);
  font-size: 0.64rem;
}
.chat-inline-tool > header button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 0.55rem;
  background: var(--secondary);
}
.chat-inline-tool > iframe {
  width: 100%;
  height: min(34rem, 58dvh);
  border: 0;
  background: var(--background);
}
.chat-work-card-actions button {
  padding-inline: 0.65rem;
}
.chat-work-card-actions a {
  width: 2rem;
}
.chat-work-actions {
  margin-top: 1rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--border);
}
.chat-work-actions > p {
  margin-bottom: 0.6rem;
  color: var(--muted-foreground);
  font-size: 0.68rem;
  font-weight: 800;
}
.chat-embedded-tool {
  position: fixed;
  z-index: 45;
  inset: 4.75rem 0 0;
  display: flex;
  flex-direction: column;
  background: var(--background);
}
@media (min-width: 1024px) {
  .chat-embedded-tool {
    inset-inline-start: 16rem;
  }
}
.chat-embedded-tool > header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  min-height: 3.75rem;
  padding-inline: 0.75rem;
  border-bottom: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 92%, transparent);
  backdrop-filter: blur(18px);
}
.chat-embedded-tool > header > button,
.chat-embedded-tool > header > a {
  display: inline-flex;
  min-height: 2.25rem;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  border: 1px solid var(--border);
  border-radius: 0.7rem;
  padding-inline: 0.65rem;
  font-size: 0.7rem;
  font-weight: 800;
}
.chat-embedded-tool > header strong,
.chat-embedded-tool > header span {
  display: block;
}
.chat-embedded-tool > header span {
  color: var(--muted-foreground);
  font-size: 0.64rem;
}
.chat-embedded-tool > iframe {
  width: 100%;
  min-height: 0;
  flex: 1;
  border: 0;
  background: var(--background);
}
.app-shell.is-embedded > .sahl-smoke {
  display: none;
}
.app-shell.is-embedded main {
  padding: 1rem;
}
@media (max-width: 640px) {
  .chat-message-column {
    padding-bottom: 8.25rem;
  }
  .chat-embedded-tool {
    inset-block-start: 4.65rem;
  }
  .chat-embedded-tool > header {
    grid-template-columns: 2.75rem minmax(0, 1fr) 2.75rem;
    gap: 0.45rem;
    min-height: 3.6rem;
    padding-inline: 0.5rem;
  }
  .chat-embedded-tool > header > button,
  .chat-embedded-tool > header > a {
    width: 2.75rem;
    min-width: 2.75rem;
    min-height: 2.75rem;
    padding: 0;
  }
  .chat-embedded-tool > header > button span,
  .chat-embedded-tool > header > a span,
  .chat-embedded-tool > header > div > span {
    display: none;
  }
  .chat-embedded-tool > header strong {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 0.8rem;
  }
  .chat-inline-tool {
    min-height: 54dvh;
  }
  .chat-inline-tool > header {
    grid-template-columns: minmax(0, 1fr) 2.75rem 2.75rem;
    min-height: 3.6rem;
    padding-inline: 0.55rem;
  }
  .chat-inline-tool > header > div {
    min-width: 0;
  }
  .chat-inline-tool > header strong {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .chat-inline-tool > header button {
    width: 2.75rem;
    height: 2.75rem;
  }
  .chat-inline-tool > iframe {
    height: 48dvh;
  }
  .chat-work-card {
    grid-template-columns: 2.5rem minmax(0, 1fr);
    gap: 0.55rem;
    min-height: 0;
    padding: 0.65rem;
  }
  .chat-work-card-icon {
    width: 2.5rem;
    height: 2.5rem;
  }
  .chat-work-card-actions {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: minmax(0, 1fr) 2.75rem;
    gap: 0.4rem;
  }
  .chat-work-card-actions button,
  .chat-work-card-actions a {
    min-height: 2.75rem;
  }
  .chat-work-card-actions a {
    width: 2.75rem;
  }
  .chat-work-card strong {
    font-size: 0.8rem;
  }
  .chat-work-card small {
    font-size: 0.68rem;
    line-height: 1.45;
  }
}

/* الدخان الذهبي يملأ الغلاف ويتحرك سريعاً في مسارات متعددة قبل بدء المحادثة. */
.chat-smoke i:nth-child(1) {
  animation-duration: 7s;
}
.chat-smoke i:nth-child(2) {
  animation-duration: 8.5s;
}
.chat-smoke i:nth-child(3) {
  animation-duration: 10s;
}
.chat-smoke b:nth-of-type(1) {
  animation-duration: 5.5s;
}
.chat-smoke b:nth-of-type(2) {
  animation-duration: 7s;
  animation-delay: -2s;
}
.chat-smoke b:nth-of-type(3) {
  animation-duration: 8s;
  animation-delay: -4s;
}
.chat-stage.is-engaged::before,
.chat-stage.is-engaged::after {
  display: none;
}
.topbar-sheet-head {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid var(--border);
}
.topbar-sheet-head p {
  font-weight: 900;
  font-size: 0.9rem;
}
.topbar-sheet-head span {
  display: block;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}
.topbar-sheet-head button {
  margin-inline-start: auto;
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 0.7rem;
  color: var(--muted-foreground);
}
.topbar-sheet-head button:hover {
  background: var(--secondary);
  color: var(--foreground);
}
.topbar-app-row {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.5rem 0.15rem;
  border-bottom: 1px solid color-mix(in oklab, var(--border) 60%, transparent);
  font-size: 0.78rem;
  font-weight: 700;
}
.topbar-app-row:last-child {
  border-bottom: 0;
}
.topbar-app-row .is-connected {
  margin-inline-start: auto;
  font-size: 0.66rem;
  font-weight: 800;
  color: var(--jade-deep);
}
@media (prefers-reduced-motion: reduce) {
  .topbar-sheet {
    animation: none;
  }
  .topbar-pill:hover:not(:disabled) {
    transform: none;
  }
}

/* رسائل المستخدم: خط فاتح واضح فوق الفقاعة الداكنة. */
.chat-stage .bubble-user,
.chat-stage .bubble-user *,
.bubble-user,
.bubble-user * {
  color: var(--cream);
}
.chat-stage .bubble-user a,
.bubble-user a {
  color: color-mix(in oklab, var(--gold) 70%, var(--cream));
}

/* الغلاف الذهبي: حركة تلقائية أسرع تروح وتيجي وتُخلّف أثر مرور. */
.chat-stage::before {
  animation:
    sahl-chat-aura 6.5s ease-in-out infinite alternate,
    sahl-gold-breathe 3.2s ease-in-out infinite;
}
.chat-stage::after {
  animation:
    sahl-chat-aura 8s ease-in-out infinite alternate-reverse,
    sahl-gold-breathe 4.1s ease-in-out infinite;
}
.sahl-smoke-app i:nth-child(1) {
  animation-duration: 7s;
}
.sahl-smoke-app i:nth-child(2) {
  animation-duration: 9s;
}
.sahl-smoke-app i:nth-child(3) {
  animation-duration: 11s;
}
@keyframes sahl-gold-breathe {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .chat-stage::before,
  .chat-stage::after,
  .sahl-smoke-app i {
    animation: none;
  }
}

/* رأس لوحة الأداة قابل للسحب داخل نفس المحادثة. */
.chat-tool-drag {
  cursor: grab;
  touch-action: none;
  user-select: none;
}
.chat-tool-drag:active {
  cursor: grabbing;
}
.chat-inline-tool,
.chat-embedded-tool {
  will-change: transform;
}

/* ================================================================
   Sahl homepage — commerce-infrastructure editorial system
   ================================================================ */
.stripe-sahl-home {
  background: var(--background);
  color: var(--foreground);
  overflow: clip;
}
.stripe-sahl-home *,
.stripe-nav * {
  letter-spacing: 0;
}
.stripe-sahl-home h1,
.stripe-sahl-home h2,
.stripe-sahl-home h3,
.stripe-sahl-home p {
  margin: 0;
}
.stripe-sahl-shell {
  width: min(1180px, calc(100% - 40px));
  margin-inline: auto;
  position: relative;
}

.stripe-nav {
  position: fixed;
  inset: 0 0 auto;
  z-index: 80;
  height: 70px;
  border-bottom: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 88%, transparent);
  backdrop-filter: blur(18px) saturate(140%);
