  font-size: 1.3rem;
  font-weight: 800;
  flex: 0 0 auto;
}
.stripe-nav-brand svg,
.stripe-nav-brand img {
  width: 38px;
  height: 38px;
}
.stripe-nav-links {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1;
}
.stripe-nav-links > div {
  position: relative;
}
.stripe-nav-links > a,
.stripe-nav-links button {
  height: 40px;
  color: var(--foreground);
  font-size: 0.86rem;
  font-weight: 650;
  padding-inline: 12px;
}
.stripe-nav-links button svg {
  width: 13px;
  transition: transform 0.2s;
}
.stripe-nav-links button[aria-expanded="true"] svg {
  transform: rotate(180deg);
}
.stripe-nav-popover {
  position: absolute;
  top: 44px;
