}

.stripe-sahl-hero {
  min-height: 760px;
  padding: 155px 0 92px;
  position: relative;
  isolation: isolate;
}
.stripe-sahl-ribbon {
  position: absolute;
  z-index: -2;
  inset: -180px -12% auto 38%;
  height: 720px;
  transform: skewY(-12deg);
  overflow: hidden;
  background: var(--gradient-aurora);
}
.stripe-sahl-ribbon::before {
  content: "";
  position: absolute;
  inset: -30%;
  background: conic-gradient(
    from 120deg,
    transparent,
    color-mix(in oklab, var(--coral) 80%, transparent),
    var(--gold),
    color-mix(in oklab, var(--sky) 75%, transparent),
    transparent 68%
  );
  filter: blur(18px);
  animation: stripe-ribbon-drift 14s ease-in-out infinite alternate;
}
.stripe-sahl-ribbon i {
  position: absolute;
  inset-inline: -20%;
  height: 3px;
  background: color-mix(in oklab, var(--background) 55%, transparent);
  transform: rotate(-8deg);
}
.stripe-sahl-ribbon i:nth-child(1) {
  top: 24%;
}
.stripe-sahl-ribbon i:nth-child(2) {
  top: 55%;
  opacity: 0.5;
}
.stripe-sahl-ribbon i:nth-child(3) {
  top: 78%;
  opacity: 0.3;
}
.stripe-sahl-grid {
  position: absolute;
  z-index: -1;
  inset: 70px 0 0;
  background-image:
    linear-gradient(to left, var(--border) 1px, transparent 1px),
    linear-gradient(to bottom, var(--border) 1px, transparent 1px);
  background-size: calc((100% - 40px) / 6) 100px;
  mask-image: linear-gradient(to bottom, black, transparent 90%);
  opacity: 0.65;
}
.stripe-sahl-hero-inner {
