  grid-template-columns: minmax(0, 0.88fr) minmax(520px, 1.12fr);
  align-items: center;
  gap: 68px;
}
.stripe-sahl-hero-copy {
  padding-top: 15px;
}
.stripe-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 0.78rem;
  font-weight: 700;
  margin-bottom: 28px !important;
}
.stripe-eyebrow span {
  background: var(--gold-deep);
