  padding: 3px 8px;
  border-radius: 4px;
}
.stripe-sahl-hero h1 {
  font-size: clamp(4.25rem, 7vw, 6.9rem);
  line-height: 0.93;
  font-weight: 650;
  max-width: 760px;
}
.stripe-sahl-hero-copy > p:not(.stripe-eyebrow) {
  max-width: 600px;
  margin-top: 28px;
  color: var(--ink-soft);
  font-size: 1.18rem;
  line-height: 1.7;
}
.stripe-sahl-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 28px;
}
.stripe-sahl-actions a {
  min-height: 44px;
  padding: 10px 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border-radius: 6px;
  color: var(--foreground);
  font-size: 0.9rem;
  font-weight: 750;
}
.stripe-sahl-actions a:first-child {
  background: var(--foreground);
  color: var(--background);
}
.stripe-sahl-actions a:last-child {
  border: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 82%, transparent);
}
.stripe-sahl-actions svg {
  width: 16px;
}
.stripe-sahl-hero-copy > small,
.stripe-final-cta .stripe-sahl-shell > small {
  display: flex;
  align-items: center;
