/* ===== هوية سهل الموحدة لكل صفحات الموقع ===== */
.sahl-site-page,
.sahl-app-theme,
.sahl-onboarding-theme {
  --home-bg: oklch(1 0 0);
  --home-ink: oklch(0.20382 0.00871 59.14);
  --home-copy: oklch(0.43 0.014 58);
  --home-muted: oklch(0.968 0.006 66);
  --home-soft: oklch(0.982 0.004 66);
  --home-line: oklch(0.89 0.008 64);
  --home-terracotta: oklch(0.52418 0.13258 37.48);
  --home-teal: oklch(0.48558 0.06376 183.77);
  --home-gold: oklch(0.67771 0.12672 73.45);
  color: var(--home-ink);
  font-family: "IBM Plex Sans Arabic", ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0;
}
.sahl-site-page *,
.sahl-app-theme *,
.sahl-onboarding-theme * {
  letter-spacing: 0;
}
.sahl-site-page h1,
.sahl-site-page h2,
.sahl-site-page h3,
.sahl-app-theme h1,
.sahl-app-theme h2,
.sahl-app-theme h3,
.sahl-onboarding-theme h1,
.sahl-onboarding-theme h2,
.sahl-onboarding-theme h3 {
  font-family: "Almarai", "IBM Plex Sans Arabic", sans-serif;
}
.sahl-site-page main {
  background: var(--home-bg);
}
.sahl-site-page main > section:not(.sahl-page-hero):nth-child(odd) {
  background-color: var(--home-soft);
}
.sahl-site-page main > section:not(.sahl-page-hero) {
  border-color: var(--home-line);
}
.sahl-site-page :is(.rounded-3xl, .rounded-\[1\.75rem\], .rounded-\[2rem\]) {
  border-radius: 12px;
}
.sahl-site-page :is(.shadow-card, .shadow-lift) {
  box-shadow: 0 20px 55px -42px oklch(0.20382 0.00871 59.14 / 0.3);
}
.sahl-site-page :is(input, textarea, select) {
  border-radius: 7px;
}

.sahl-page-hero {
  position: relative;
  min-height: 570px;
  padding: 150px 24px 94px;
  overflow: hidden;
  background: var(--home-bg);
}
.sahl-page-ribbon {
  position: absolute;
  inset: -66% 58% -18% -15%;
  overflow: hidden;
  transform: skewX(-17deg) rotate(-9deg);
  background: linear-gradient(
    135deg,
    var(--home-teal),
    var(--home-gold) 46%,
    var(--home-terracotta)
  );
  animation: sahl-ribbon-drift 9s ease-in-out infinite alternate;
}
.sahl-page-ribbon::after {
  content: "";
  position: absolute;
  inset: -12%;
  background: repeating-linear-gradient(
    112deg,
    transparent 0 3px,
    oklch(1 0 0 / 0.12) 4px,
    transparent 6px 11px
  );
}
.sahl-page-ribbon i {
  position: absolute;
  inset-block: -10%;
  width: 2px;
  background: oklch(1 0 0 / 0.2);
