.sauth-pw-toggle {
  position: absolute;
  inset-inline-end: 10px;
  top: 50%;
  transform: translateY(-50%);
  padding: 6px;
  color: #8c8275;
  background: none;
  border: 0;
  cursor: pointer;
}
.sauth-pw-toggle:hover {
  color: #a8492c;
}

.sauth-error {
  margin: 2px 0 0;
  font-size: 13px;
  font-weight: 700;
  color: #b23b2e;
}
.sauth-form-error {
  margin: 0;
  padding: 11px 14px;
  border-radius: 10px;
  border: 1px solid rgb(178 59 46 / 0.35);
  background: rgb(178 59 46 / 0.08);
  font-size: 13px;
  font-weight: 700;
  color: #b23b2e;
}
.sauth-note {
  margin: 0;
  padding: 11px 14px;
  border-radius: 10px;
  border: 1px solid rgb(47 107 99 / 0.35);
  background: rgb(47 107 99 / 0.08);
  font-size: 13px;
  font-weight: 700;
  color: #2f6b63;
}

.sauth-forgot {
  align-self: flex-start;
  margin-top: 4px;
  font-size: 13px;
  font-weight: 700;
  color: #a8492c;
  background: none;
  border: 0;
  cursor: pointer;
}
.sauth-forgot:hover {
  text-decoration: underline;
}

.sauth-check {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 13px;
  line-height: 1.7;
  color: #5c5348;
}
.sauth-check input {
  margin-top: 3px;
  width: 16px;
  height: 16px;
  accent-color: #a8492c;
}

.sauth-link {
  color: #a8492c;
  font-weight: 700;
  background: none;
  border: 0;
  cursor: pointer;
}
.sauth-link:hover {
  text-decoration: underline;
}

.sauth-submit {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 13px 18px;
  border: 0;
  border-radius: 10px;
  background: #a8492c;
  color: #ffffff;
  font-size: 15px;
  font-weight: 800;
  cursor: pointer;
}
.sauth-submit:hover {
  background: #95401f;
}
.sauth-submit:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

.sauth-card-foot {
  padding: 16px 30px;
  background: #fdfbf7;
  border-top: 1px solid #efe7da;
  text-align: center;
  font-size: 13px;
  color: #5c5348;
}

.sauth-footer {
  width: 100%;
  max-width: 460px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  color: #8c8275;
}
.sauth-footer-links {
  display: flex;
  gap: 14px;
}
.sauth-footer a:hover {
  color: #a8492c;
}

@media (max-width: 640px) {
  .sauth-card {
    background: transparent;
    border: 0;
    box-shadow: none;
  }
  .sauth-card-body {
    padding: 8px 4px 18px;
  }
  .sauth-card-foot {
    background: transparent;
    border-top: 1px solid #efe7da;
    padding: 16px 4px 0;
  }
  .sauth-center {
    padding: 70px 18px 32px;
    justify-content: flex-start;
  }
  .sauth-glow-blob {
    opacity: 0.26;
  }
}

/* قائمة الجوال في الهيدر: تُعرَّف ألوانها على الهيدر نفسه لأن متغيرات الصفحة محصورة في .sahl-white-home */
.sahl-white-nav {
  --home-bg: oklch(1 0 0);
  --home-ink: oklch(0.20382 0.00871 59.14);
  --home-copy: oklch(0.43 0.014 58);
  --home-muted: oklch(0.968 0.006 66);
  --home-line: oklch(0.905 0.008 66);
  --home-terracotta: oklch(0.523 0.134 34.5);
}
@media (max-width: 1024px) {
  .sahl-white-mobile {
    z-index: 60;
    direction: rtl;
    gap: 14px;
    padding: 20px 22px calc(22px + env(safe-area-inset-bottom));
    background: oklch(1 0 0);
    box-shadow: 0 24px 60px -30px oklch(0.2 0.01 59 / 0.35);
  }
  .sahl-white-mobile > div {
    gap: 4px;
  }
  .sahl-white-mobile section {
    margin: 0;
    padding: 4px 0 10px;
  }
  .sahl-white-mobile section > b {
    padding: 8px 0 2px;
    color: var(--home-copy);
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.02em;
  }
  .sahl-white-mobile a {
    justify-content: flex-start;
    gap: 10px;
    padding: 0 12px;
    border-radius: 10px;
    font-weight: 600;
    background: transparent;
  }
  .sahl-white-mobile a:active {
    background: var(--home-muted);
  }
  .sahl-white-mobile a > span {
    color: var(--home-terracotta);
    font-size: 0.85rem;
  }
  .sahl-white-mobile > [data-slot="button"],
  .sahl-white-mobile > .inline-flex {
    margin-top: 16px;
    border-radius: 999px;
    background: var(--home-terracotta);
    color: oklch(1 0 0);
    font-weight: 700;
  }
}

/* ===== إثباتات حقيقية + قسم إعلانات سِراج ===== */
.sahl-proof-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-top: 40px;
}
.sahl-proof-grid article {
  height: 100%;
  padding: 30px;
  border: 1px solid var(--home-line);
  border-radius: 12px;
  background: var(--home-bg);
}
.sahl-proof-grid article span {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--home-teal) 12%, transparent);
  color: var(--home-teal);
  font-size: 0.7rem;
  font-weight: 700;
}
.sahl-proof-grid article h3 {
  margin-top: 16px;
  font-size: 1.35rem;
  line-height: 1.35;
  color: var(--home-ink);
}
.sahl-proof-grid article p {
  margin-top: 12px;
  color: var(--home-copy);
  font-size: 0.92rem;
  line-height: 1.85;
}

.sahl-ads-board {
  margin-top: 40px;
  padding: 34px;
  border: 1px solid var(--home-line);
  border-radius: 14px;
  background: color-mix(in oklab, var(--home-terracotta) 6%, var(--home-bg));
}
.sahl-ads-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}
.sahl-ads-metrics span {
  display: block;
  padding: 20px;
  border: 1px solid var(--home-line);
  border-radius: 10px;
  background: var(--home-bg);
}
.sahl-ads-metrics small {
  display: block;
  color: var(--home-copy);
  font-size: 0.74rem;
}
.sahl-ads-metrics strong {
  display: block;
  margin-top: 8px;
  font-size: 1.75rem;
  line-height: 1.1;
  color: var(--home-terracotta);
}
.sahl-ads-metrics em {
  display: block;
  margin-top: 6px;
  color: var(--home-copy);
  font-size: 0.7rem;
  font-style: normal;
}
.sahl-ads-steps {
  counter-reset: ads;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-top: 22px;
  padding: 0;
  list-style: none;
}
.sahl-ads-steps li {
  counter-increment: ads;
  padding-top: 16px;
  border-top: 2px solid color-mix(in oklab, var(--home-terracotta) 40%, transparent);
}
.sahl-ads-steps li::before {
  content: "٠" counter(ads, arabic-indic);
  display: block;
  margin-bottom: 8px;
  color: var(--home-terracotta);
  font-size: 0.74rem;
  font-weight: 700;
}
.sahl-ads-steps b {
  display: block;
  color: var(--home-ink);
  font-size: 1rem;
}
.sahl-ads-steps span {
  display: block;
  margin-top: 7px;
  color: var(--home-copy);
  font-size: 0.84rem;
  line-height: 1.8;
}
.sahl-ads-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 28px;
  padding-top: 18px;
  border-top: 1px solid var(--home-line);
  color: var(--home-copy);
  font-size: 0.78rem;
  line-height: 1.8;
}
.sahl-ads-note svg {
  flex: none;
  width: 15px;
  margin-top: 3px;
  color: var(--home-teal);
}

@media (max-width: 720px) {
  .sahl-proof-grid,
  .sahl-ads-metrics,
  .sahl-ads-steps {
    grid-template-columns: 1fr;
  }
  .sahl-ads-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .sahl-proof-grid article {
    padding: 22px;
  }
  .sahl-ads-board {
    padding: 20px;
  }

  /* بطاقات الموظفين: نفس المحتوى كاملاً، بمقاس أصغر ومساحات أقل على الهاتف */
  .sahl-cap-card,
  .sahl-cap-card.is-wide {
    margin-bottom: 10px;
  }
  .sahl-cap-card > div:first-child {
    padding: 20px;
  }
  .sahl-cap-card > div:first-child > svg {
    width: 20px;
    margin-bottom: 16px;
  }
  .sahl-cap-card > div:first-child > span {
    font-size: 0.7rem;
  }
  .sahl-cap-card h3 {
    margin-top: 8px;
    font-size: 1.32rem;
    line-height: 1.3;
  }
  .sahl-cap-card p {
    margin-top: 10px;
    font-size: 0.86rem;
    line-height: 1.75;
  }
  .sahl-cap-card .sahl-coming-ads {
    padding: 14px;
  }
  .sahl-cap-card .sahl-coming-ads p {
    font-size: 0.72rem;
  }
  .sahl-cap-card a {
    margin-top: 16px;
    font-size: 0.76rem;
  }
  .sahl-cap-card .sahl-device-frame,
  .sahl-cap-card.is-wide .sahl-device-frame {
    width: min(58%, 196px);
    margin: 16px auto 20px;
  }
}
.sahl-pricing .sahl-section-head p a {
  color: var(--home-terracotta);
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* ===== مقدمة بصورة المنتج + الأقسام الجديدة (عينة مخرج · مقارنة · ضمانات) ===== */
.sahl-cap-card:not(.is-wide) > div:first-child {
  padding: 34px 32px 32px;
}
.sahl-cap-card:not(.is-wide) h3 {
  font-size: clamp(1.5rem, 2.2vw, 2.1rem);
}
.sahl-cap-card:not(.is-wide) > div:first-child > svg {
  margin-bottom: 26px;
}
.sahl-cap-card:not(.is-wide) a {
  margin-top: 20px;
}

/* ===== dark editorial sections: sample / versus / guard ===== */
.sahl-dark {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--home-ink);
  color: var(--home-bg);
}
.sahl-dark > .sahl-shell {
  position: relative;
  z-index: 2;
}
.sahl-dark .sahl-section-head > span,
.sahl-dark .sahl-section-head > div > span {
  color: color-mix(in oklab, var(--home-gold) 85%, var(--home-bg));
}
.sahl-dark .sahl-section-head h2 {
  color: color-mix(in oklab, var(--home-bg) 96%, var(--home-gold));
}
.sahl-dark .sahl-section-head h2 em {
  color: color-mix(in oklab, var(--home-bg) 54%, transparent);
}
.sahl-dark .sahl-section-head > p,
.sahl-dark .sahl-section-head > div + p {
  color: color-mix(in oklab, var(--home-bg) 66%, transparent);
}
.sahl-dark-veil {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

/* sample — streaming output lines */
.sahl-sample .sahl-dark-veil {
  background:
    radial-gradient(
      circle at 12% 10%,
      color-mix(in oklab, var(--home-terracotta) 20%, transparent),
      transparent 42%
    ),
    radial-gradient(
      circle at 88% 82%,
      color-mix(in oklab, var(--home-teal) 17%, transparent),
      transparent 44%
    );
}
/* sahl-sample-stream removed — was animated gold light trails */
.sahl-sample-board {
  position: relative;
  margin-top: 44px;
  padding: clamp(20px, 3vw, 34px);
  border: 1px solid color-mix(in oklab, var(--home-bg) 16%, transparent);
  border-radius: 18px;
  background: color-mix(in oklab, var(--home-bg) 7%, transparent);
  backdrop-filter: blur(8px);
}
.sahl-sample-ask {
  padding: 16px 18px;
  border: 1px dashed color-mix(in oklab, var(--home-gold) 46%, transparent);
  border-radius: 12px;
  background: color-mix(in oklab, var(--home-gold) 9%, transparent);
}
.sahl-sample-ask small {
  display: block;
  color: color-mix(in oklab, var(--home-gold) 88%, var(--home-bg));
  font-size: 0.68rem;
  font-weight: 700;
}
.sahl-sample-ask p {
  margin-top: 6px;
  color: var(--home-bg);
  font-size: 1.02rem;
  font-weight: 600;
}
.sahl-sample-grid {
  display: grid;
  grid-template-columns: 1.25fr 1fr 1fr;
  gap: 14px;
  margin-top: 18px;
}
.sahl-sample-grid article {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  border: 1px solid color-mix(in oklab, var(--home-bg) 14%, transparent);
  border-radius: 12px;
  background: color-mix(in oklab, var(--home-bg) 5%, transparent);
  overflow: hidden;
}
.sahl-sample-grid article::after {
  content: none;
}
.sahl-sample-grid header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 15px;
  border-bottom: 1px solid color-mix(in oklab, var(--home-bg) 12%, transparent);
  background: color-mix(in oklab, var(--home-bg) 6%, transparent);
}
.sahl-sample-grid header svg {
  width: 17px;
  color: color-mix(in oklab, var(--home-terracotta) 62%, var(--home-bg));
}
.sahl-sample-grid header b {
  font-size: 0.82rem;
  color: var(--home-bg);
}
.sahl-sample-grid header span {
  margin-inline-start: auto;
  padding: 3px 9px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--home-teal) 30%, transparent);
  color: color-mix(in oklab, var(--home-teal) 40%, var(--home-bg));
  font-size: 0.62rem;
  font-weight: 700;
}
.sahl-sample-grid pre {
  margin: 0;
  padding: 16px 17px;
  flex: 1;
  color: color-mix(in oklab, var(--home-bg) 88%, transparent);
  font-family: "Almarai", "IBM Plex Sans Arabic", sans-serif;
  font-size: 0.85rem;
  line-height: 1.95;
  white-space: pre-wrap;
  word-break: break-word;
}
.sahl-sample-grid .is-ad header svg,
.sahl-sample-grid .is-brief header svg {
  color: color-mix(in oklab, var(--home-teal) 46%, var(--home-bg));
}
.sahl-sample-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-top: 18px;
  color: color-mix(in oklab, var(--home-bg) 62%, transparent);
  font-size: 0.76rem;
  line-height: 1.75;
}
.sahl-sample-note svg {
  width: 15px;
  margin-top: 4px;
  color: color-mix(in oklab, var(--home-teal) 44%, var(--home-bg));
  flex: none;
}

/* versus — slow tilted beam behind the table */
.sahl-versus .sahl-dark-veil {
  background:
    radial-gradient(
      circle at 82% 8%,
      color-mix(in oklab, var(--home-terracotta) 18%, transparent),
      transparent 40%
    ),
    radial-gradient(
      circle at 6% 92%,
      color-mix(in oklab, var(--home-teal) 16%, transparent),
      transparent 42%
    );
}
.sahl-versus-beam {
  position: absolute;
  inset: -20% -10%;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(
    115deg,
    transparent 38%,
    color-mix(in oklab, var(--home-gold) 16%, transparent) 50%,
    transparent 62%
  );
  animation: sahl-beam-slide 14s ease-in-out infinite alternate;
}
@keyframes sahl-beam-slide {
  from {
    transform: translateX(-16%);
  }
  to {
    transform: translateX(16%);
  }
}
.sahl-versus-table {
  position: relative;
  margin-top: 44px;
  border: 1px solid color-mix(in oklab, var(--home-bg) 15%, transparent);
  border-radius: 14px;
  overflow: hidden;
  background: color-mix(in oklab, var(--home-bg) 5%, transparent);
  backdrop-filter: blur(6px);
}
.sahl-versus-head,
.sahl-versus-row {
  display: grid;
  grid-template-columns: 150px 1fr 1.15fr;
  align-items: center;
}
.sahl-versus-head {
  background: color-mix(in oklab, var(--home-bg) 10%, transparent);
  color: var(--home-bg);
}
.sahl-versus-head span {
  padding: 15px 18px;
  font-size: 0.8rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}
.sahl-versus-head span:last-child {
  background: var(--home-terracotta);
}
.sahl-versus-row {
  border-top: 1px solid color-mix(in oklab, var(--home-bg) 11%, transparent);
  /* الخلايا تمتد لكامل ارتفاع الصف: بدونها كان عمود «سهل» الملوّن يقصر عند الصفوف
     الطويلة فيظهر فراغ أفقي يكسر الجدول على شاشة الكمبيوتر. */
  align-items: stretch;
}
.sahl-versus-row span {
  display: flex;
  align-items: center;
  padding: 16px 18px;
  font-size: 0.86rem;
  line-height: 1.7;
}
.sahl-versus-row > span:first-child {
  color: var(--home-bg);
  font-weight: 800;
}
.sahl-versus-row .is-plain {
  color: color-mix(in oklab, var(--home-bg) 46%, transparent);
}
.sahl-versus-row .is-sahl {
  align-items: center;
  gap: 9px;
  background: color-mix(in oklab, var(--home-terracotta) 16%, transparent);
  color: var(--home-bg);
  font-weight: 600;
}
.sahl-versus-row .is-sahl svg {
  width: 16px;
  margin-top: 0;
  color: color-mix(in oklab, var(--home-gold) 72%, var(--home-bg));
  flex: none;
  animation: sahl-check-pop 7s ease-in-out infinite;
}
.sahl-versus-row:nth-child(3) .is-sahl svg {
  animation-delay: -1s;
}
.sahl-versus-row:nth-child(4) .is-sahl svg {
  animation-delay: -2s;
}
.sahl-versus-row:nth-child(5) .is-sahl svg {
  animation-delay: -3s;
}
.sahl-versus-row:nth-child(6) .is-sahl svg {
  animation-delay: -4s;
}
.sahl-versus-row:nth-child(7) .is-sahl svg {
  animation-delay: -5s;
}
@keyframes sahl-check-pop {
  0%,
  82%,
  100% {
    transform: scale(1);
    opacity: 0.85;
  }
  88% {
    transform: scale(1.28);
    opacity: 1;
  }
}

/* guard — radar sweep + orbiting shield rings */
.sahl-guard .sahl-dark-veil {
  background:
    radial-gradient(
      circle at 50% 0%,
      color-mix(in oklab, var(--home-teal) 20%, transparent),
      transparent 46%
    ),
    radial-gradient(
      circle at 14% 96%,
      color-mix(in oklab, var(--home-terracotta) 14%, transparent),
      transparent 42%
    );
}
.sahl-guard-radar {
  position: absolute;
  z-index: 1;
  top: -34%;
  inset-inline-start: 50%;
  width: min(1100px, 130%);
  aspect-ratio: 1;
  transform: translateX(-50%);
  pointer-events: none;
  opacity: 0.5;
}
.sahl-guard-radar i {
  position: absolute;
  inset: 0;
  margin: auto;
  border: 1px solid color-mix(in oklab, var(--home-teal) 34%, transparent);
  border-radius: 50%;
  animation: sahl-radar-pulse 7s ease-out infinite;
}
.sahl-guard-radar i:nth-child(1) {
  width: 34%;
  height: 34%;
}
.sahl-guard-radar i:nth-child(2) {
  width: 58%;
  height: 58%;
  animation-delay: -2.3s;
}
.sahl-guard-radar i:nth-child(3) {
  width: 82%;
  height: 82%;
  animation-delay: -4.6s;
}
.sahl-guard-radar b {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(
    from 0deg,
    transparent 0deg,
    color-mix(in oklab, var(--home-teal) 22%, transparent) 26deg,
    transparent 58deg
  );
  animation: sahl-radar-sweep 16s linear infinite;
}
@keyframes sahl-radar-pulse {
  0% {
    transform: scale(0.86);
    opacity: 0.12;
  }
  45% {
    opacity: 0.5;
  }
  100% {
    transform: scale(1.1);
    opacity: 0;
  }
}
@keyframes sahl-radar-sweep {
  to {
    transform: rotate(360deg);
  }
}
.sahl-guard-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-top: 44px;
}
.sahl-guard-grid article {
  position: relative;
  height: 100%;
  padding: 26px 22px;
  border: 1px solid color-mix(in oklab, var(--home-bg) 14%, transparent);
  border-radius: 14px;
  background: color-mix(in oklab, var(--home-bg) 6%, transparent);
  backdrop-filter: blur(6px);
  overflow: hidden;
}
.sahl-guard-grid article::before {
  content: "";
  position: absolute;
  inset-inline: -40%;
  top: -60%;
  height: 60%;
  background: radial-gradient(
    ellipse at center,
    color-mix(in oklab, var(--home-teal) 26%, transparent),
    transparent 70%
  );
  animation: sahl-guard-glow 9s ease-in-out infinite;
}
.sahl-guard-grid > *:nth-child(2) article::before {
  animation-delay: -2.2s;
}
.sahl-guard-grid > *:nth-child(3) article::before {
  animation-delay: -4.4s;
}
.sahl-guard-grid > *:nth-child(4) article::before {
  animation-delay: -6.6s;
}
@keyframes sahl-guard-glow {
  0%,
  100% {
    transform: translateY(0);
    opacity: 0.25;
  }
  50% {
    transform: translateY(40%);
    opacity: 0.6;
  }
}
.sahl-guard-grid svg {
  position: relative;
  width: 22px;
  color: color-mix(in oklab, var(--home-teal) 44%, var(--home-bg));
}
.sahl-guard-grid h3 {
  position: relative;
  margin-top: 18px;
  color: var(--home-bg);
  font-size: 1.02rem;
  line-height: 1.5;
}
.sahl-guard-grid p {
  position: relative;
  margin-top: 10px;
  color: color-mix(in oklab, var(--home-bg) 62%, transparent);
  font-size: 0.82rem;
  line-height: 1.8;
}
.sahl-guard .sahl-section-head p a {
  color: color-mix(in oklab, var(--home-gold) 86%, var(--home-bg));
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
  .sahl-sample-stream span,
  .sahl-sample-grid article::after,
  .sahl-versus-beam,
  .sahl-versus-row .is-sahl svg,
  .sahl-guard-radar i,
  .sahl-guard-radar b,
  .sahl-guard-grid article::before {
    animation: none !important;
  }
}

@media (max-width: 1080px) {
  .sahl-sample-grid {
    grid-template-columns: 1fr 1fr;
  }
  .sahl-sample-grid .is-post {
    grid-column: 1/-1;
  }
  .sahl-guard-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 860px) {
  .sahl-hero-layout {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 720px) {
  .sahl-hero-product {
    margin-top: 38px;
  }
  .sahl-device-frame.is-hero {
    width: 100%;
    transform: none;
  }
  .sahl-sample-grid {
    grid-template-columns: 1fr;
  }
  .sahl-versus-head,
  .sahl-versus-row {
    grid-template-columns: 1fr;
  }
  .sahl-versus-head {
    display: none;
  }
  .sahl-versus-row {
    padding: 6px 0 12px;
  }
  .sahl-versus-row > span:first-child {
    padding-bottom: 4px;
    font-size: 0.95rem;
  }
  .sahl-versus-row .is-plain {
    padding-top: 0;
    padding-bottom: 8px;
  }
  .sahl-versus-row .is-plain::before {
    content: "محادثة عامة: ";
    color: var(--home-terracotta);
    font-weight: 700;
  }
  .sahl-versus-row .is-sahl {
    margin: 0 12px 4px;
    border-radius: 10px;
  }
  .sahl-guard-grid {
    grid-template-columns: 1fr;
  }
  .sahl-trust-row {
    position: relative;
  }
  .sahl-trust-row::after {
    content: "";
    position: sticky;
    inset-inline-end: 0;
    width: 34px;
    flex: none;
    background: linear-gradient(to left, var(--home-bg), transparent);
    pointer-events: none;
  }
}

@media (max-width: 720px) {
  .sahl-hero-product {
    margin-inline: auto;
    width: 68%;
  }
  .sahl-hero-product .sahl-device-frame.is-hero img {
    max-height: none;
    object-fit: contain;
  }
  .sahl-hero-product .sahl-float-note {
    position: static;
    margin-top: 14px;
    min-width: 0;
    width: 100%;
    animation: none;
  }
}

/* ===== هبوط الأجهزة + مشاهد متحركة جديدة + سلاسة التمرير ===== */
html {
  scroll-padding-top: 96px;
}
.sahl-white-home {
  overflow-x: clip;
}

/* الأجهزة تنزل من الأعلى إلى مكانها — بأسلوب Stripe */
.sahl-device-drop {
  opacity: 0;
  transform: translate3d(0, -72px, 0) scale(0.965);
  transition:
    opacity 0.9s cubic-bezier(0.16, 0.84, 0.3, 1),
    transform 1.05s cubic-bezier(0.16, 0.84, 0.3, 1);
  will-change: transform, opacity;
}
.sahl-device-drop.is-landed {
  opacity: 1;
  transform: translate3d(0, 0, 0) scale(1);
  will-change: auto;
}
.sahl-device-frame.is-hero.sahl-device-drop {
  transform: translate3d(0, -88px, 0) rotateY(5deg) rotateX(1deg) scale(0.96);
}
.sahl-device-frame.is-hero.sahl-device-drop.is-landed {
  transform: translate3d(0, 0, 0) rotateY(5deg) rotateX(1deg) scale(1);
}
.sahl-cap-card .sahl-device-frame.sahl-device-drop.is-landed {
  transform: none;
}

/* إيقاف الحركة خارج الشاشة = تمرير أنعم */
.sahl-scene:not(.is-onscreen) *,
.sahl-scene:not(.is-onscreen) *::before,
.sahl-scene:not(.is-onscreen) *::after {
  animation-play-state: paused !important;
}

/* قسم الإثباتات الداكن */
.sahl-proof {
  position: relative;
  overflow: hidden;
}
.sahl-proof .sahl-dark-veil {
  background:
    radial-gradient(
      circle at 18% 12%,
      color-mix(in oklab, var(--home-teal) 20%, transparent),
      transparent 44%
    ),
    radial-gradient(
      circle at 86% 88%,
      color-mix(in oklab, var(--home-gold) 16%, transparent),
      transparent 46%
    );
}
.sahl-proof-ledger {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  opacity: 0.32;
}
.sahl-proof-ledger i {
  position: absolute;
  inset-inline: 6%;
  height: 1px;
  background: repeating-linear-gradient(
    90deg,
    color-mix(in oklab, var(--home-bg) 40%, transparent) 0 3px,
    transparent 3px 16px
  );
  animation: sahl-ledger-tick 7.5s ease-in-out infinite;
}
.sahl-proof-ledger i:nth-child(1) {
  top: 14%;
}
.sahl-proof-ledger i:nth-child(2) {
  top: 28%;
  animation-delay: -1.1s;
}
.sahl-proof-ledger i:nth-child(3) {
  top: 44%;
  animation-delay: -2.4s;
}
.sahl-proof-ledger i:nth-child(4) {
  top: 60%;
  animation-delay: -3.6s;
}
.sahl-proof-ledger i:nth-child(5) {
  top: 76%;
  animation-delay: -4.8s;
}
.sahl-proof-ledger i:nth-child(6) {
  top: 90%;
  animation-delay: -6s;
}
@keyframes sahl-ledger-tick {
  0%,
  100% {
    opacity: 0.25;
    transform: translateX(0);
  }
  50% {
    opacity: 0.8;
    transform: translateX(-14px);
  }
}
.sahl-proof .sahl-shell {
  position: relative;
  z-index: 2;
}
.sahl-proof .sahl-proof-grid article {
  border-color: color-mix(in oklab, var(--home-bg) 15%, transparent);
  background: color-mix(in oklab, var(--home-bg) 6%, transparent);
  backdrop-filter: blur(6px);
}
.sahl-proof .sahl-proof-grid article h3 {
  color: var(--home-bg);
}
.sahl-proof .sahl-proof-grid article p {
  color: color-mix(in oklab, var(--home-bg) 66%, transparent);
}
.sahl-proof .sahl-proof-grid article span {
  background: color-mix(in oklab, var(--home-gold) 22%, transparent);
  color: color-mix(in oklab, var(--home-gold) 40%, var(--home-bg));
}

/* لوحات الصور الجديدة */
.sahl-proof-visual {
  margin-top: 40px;
}
.sahl-proof-visual figure,
.sahl-ads-visual figure {
  position: relative;
  margin: 0;
  border: 1px solid color-mix(in oklab, var(--home-ink) 12%, transparent);
  border-radius: 18px;
  overflow: hidden;
  background: var(--home-bg);
}
.sahl-proof-visual figure {
  border-color: color-mix(in oklab, var(--home-bg) 16%, transparent);
}
.sahl-proof-visual img,
.sahl-ads-visual img {
  display: block;
  width: 100%;
  height: auto;
}
.sahl-proof-visual figcaption {
  margin-top: 14px;
  color: color-mix(in oklab, var(--home-bg) 62%, transparent);
  font-size: 0.82rem;
}
.sahl-visual-sweep {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    105deg,
    transparent 40%,
    color-mix(in oklab, var(--home-bg) 42%, transparent) 50%,
    transparent 60%
  );
  mix-blend-mode: overlay;
  animation: sahl-visual-sweep 9s ease-in-out infinite;
}
@keyframes sahl-visual-sweep {
  0% {
    transform: translateX(-60%);
    opacity: 0;
  }
  18% {
    opacity: 1;
  }
  60% {
    transform: translateX(60%);
    opacity: 0;
  }
  100% {
    transform: translateX(60%);
    opacity: 0;
  }
}
.sahl-visual-ring {
  position: absolute;
  inset-inline-start: 8%;
  top: 12%;
  width: 120px;
  height: 120px;
  border: 1px solid color-mix(in oklab, var(--home-gold) 55%, transparent);
  border-radius: 50%;
  pointer-events: none;
  animation: sahl-visual-ring 6s ease-out infinite;
}
@keyframes sahl-visual-ring {
  0% {
    transform: scale(0.6);
    opacity: 0;
  }
  25% {
    opacity: 0.75;
  }
  100% {
    transform: scale(1.9);
    opacity: 0;
  }
}
.sahl-ads-visual {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  align-items: center;
  gap: 28px;
  margin-top: 40px;
}
.sahl-ads-visual > div span {
  display: inline-block;
  padding: 5px 11px;
  border-radius: 999px;
  background: color-mix(in oklab, var(--home-terracotta) 12%, transparent);
  color: var(--home-terracotta);
  font-size: 0.72rem;
  font-weight: 700;
}
.sahl-ads-visual > div h3 {
  margin-top: 14px;
  font-size: clamp(1.4rem, 2.4vw, 1.85rem);
  line-height: 1.4;
  color: var(--home-ink);
}
.sahl-ads-visual > div p {
  margin-top: 12px;
  color: var(--home-copy);
  font-size: 0.95rem;
  line-height: 1.9;
}
.sahl-visual-orbit {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.sahl-visual-orbit i {
  position: absolute;
  inset-inline-end: 16%;
  top: 24%;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--home-terracotta);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--home-terracotta) 16%, transparent);
  animation: sahl-orbit-float 7s ease-in-out infinite;
}
.sahl-visual-orbit i:nth-child(2) {
  inset-inline-end: 34%;
  top: 62%;
  background: var(--home-teal);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--home-teal) 16%, transparent);
  animation-delay: -2.3s;
}
.sahl-visual-orbit i:nth-child(3) {
  inset-inline-end: 62%;
  top: 38%;
  background: var(--home-gold);
  box-shadow: 0 0 0 6px color-mix(in oklab, var(--home-gold) 18%, transparent);
  animation-delay: -4.6s;
}
@keyframes sahl-orbit-float {
  0%,
  100% {
    transform: translate3d(0, 0, 0);
    opacity: 0.55;
  }
  50% {
    transform: translate3d(0, -16px, 0);
    opacity: 1;
  }
}

@media (max-width: 860px) {
  .sahl-ads-visual {
    grid-template-columns: 1fr;
  }
  .sahl-visual-ring {
    width: 78px;
    height: 78px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sahl-device-drop,
  .sahl-device-frame.is-hero.sahl-device-drop {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .sahl-device-frame.is-hero.sahl-device-drop.is-landed {
    transform: rotateY(5deg) rotateX(1deg);
  }
  .sahl-proof-ledger i,
  .sahl-visual-sweep,
  .sahl-visual-ring,
  .sahl-visual-orbit i {
    animation: none;
  }
  .sahl-visual-sweep,
  .sahl-visual-ring {
    opacity: 0;
  }
}

@media (max-width: 1080px) {
  .sahl-device-frame.is-hero.sahl-device-drop {
    transform: translate3d(0, -64px, 0) scale(0.965);
  }
  .sahl-device-frame.is-hero.sahl-device-drop.is-landed {
    transform: none;
  }
}

.sahl-proof-visual img {
  max-height: 380px;
  object-fit: cover;
  object-position: center;
}
.sahl-ads-visual img {
  max-height: 360px;
  object-fit: cover;
  object-position: center;
}
@media (max-width: 720px) {
  .sahl-proof-visual img {
    max-height: 220px;
  }
  .sahl-ads-visual img {
    max-height: 200px;
  }
}

/* ===== لوحة العمل الأحادية — قياس ونتائج بلا زخرفة ===== */
.app-command-center {
  overflow: hidden;
  border: 1px solid var(--command-line);
  border-radius: 3px;
  background: var(--command-bg);
  color: var(--command-ink);
  box-shadow: 0 28px 70px -48px color-mix(in oklab, var(--foreground) 78%, transparent);
}
.app-command-center > * {
  margin: 0 !important;
  border-inline: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.app-command-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 1.4rem;
  border-bottom: 1px solid var(--command-line);
}
.app-command-head p {
  color: var(--command-muted);
  font-family: ui-monospace, monospace;
  font-size: 0.58rem;
  font-weight: 700;
}
.app-command-head h2 {
  margin-top: 0.25rem;
  color: var(--command-ink);
  font-family: var(--font-display);
  font-size: clamp(1.2rem, 2.5vw, 1.7rem);
  font-weight: 700;
}
.app-command-head > span {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  color: var(--command-muted);
  font-size: 0.65rem;
}
.app-command-head > span i {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 50%;
  background: var(--command-ink);
  animation: command-live 1.8s ease-in-out infinite;
}
@keyframes command-live {
  50% {
    opacity: 0.25;
    transform: scale(0.7);
  }
}
.app-command-center .app-metric-strip {
  border-bottom-color: var(--command-line);
  background: transparent;
  color: var(--command-ink);
}
.app-command-center .app-metric {
  border-color: var(--command-line);
  background: transparent;
}
.app-command-center .app-metric.is-urgent {
  background: var(--command-ink);
  color: var(--command-bg);
}
.app-command-center .activation-compact {
  border-color: var(--command-line);
  background: transparent;
  color: var(--command-ink);
}
.app-command-center .app-editorial-panel {
  border-color: var(--command-line);
  background: transparent;
  color: var(--command-ink);
}
.app-command-center .app-running-panel {
  background: var(--command-ink);
  color: var(--command-bg);
}
.app-command-center .app-operations-grid {
  gap: 0;
  border-top: 1px solid var(--command-line);
}
.app-command-center .app-operations-grid > * + * {
  border-inline-start: 1px solid var(--command-line) !important;
}
.app-command-center .text-muted-foreground {
  color: var(--command-muted);
}
.app-sidebar-pricing {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.9rem 1rem;
  border: 1px solid var(--foreground);
  border-radius: 6px;
  background: var(--foreground);
  color: var(--background);
  transition: transform 180ms ease;
}
.app-sidebar-pricing:hover {
  transform: translateY(-2px);
}
.app-sidebar-pricing span {
  display: grid;
}
.app-sidebar-pricing small {
  opacity: 0.58;
  font-size: 0.6rem;
}
.app-sidebar-pricing b {
  font-size: 0.78rem;
}
.app-sidebar-pricing i {
  font-style: normal;
}
.app-editorial-panel {
  overflow: hidden;
  border: 1px solid color-mix(in oklab, var(--foreground) 16%, transparent);
  border-radius: 6px;
  background: var(--card);
  padding: clamp(1.15rem, 2.4vw, 1.75rem);
  box-shadow: 0 18px 48px -38px color-mix(in oklab, var(--foreground) 35%, transparent);
}
.app-editorial-kicker {
  color: var(--foreground);
  font-size: 0.68rem;
  font-weight: 800;
}
.app-first-run {
  position: relative;
}
.app-first-run::before {
  content: "";
  position: absolute;
  inset-inline: 0;
  top: 0;
  height: 3px;
  background: var(--foreground);
}
.app-team-directory {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-top: 1.4rem;
  border-top: 1px solid var(--border);
  border-inline-start: 1px solid var(--border);
}
.app-team-row {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.8rem;
  padding: 0.9rem;
  border-inline-end: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  transition:
    background-color 180ms ease,
    color 180ms ease;
}
.app-team-row:hover {
  background: var(--foreground);
  color: var(--background);
}
.app-team-row:hover .text-muted-foreground {
  color: color-mix(in oklab, var(--background) 66%, transparent);
}
.app-system-alert {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.8rem;
  margin-bottom: 1rem;
  padding: 0.85rem 1rem;
  border: 1px solid var(--foreground);
  border-radius: 4px;
  background: var(--card);
}
.app-system-alert-label {
  padding: 0.18rem 0.5rem;
  background: var(--foreground);
  color: var(--background);
  font-size: 0.64rem;
  font-weight: 900;
}
.app-text-link {
  color: var(--foreground);
  font-size: 0.78rem;
  font-weight: 800;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 4px;
}
.app-metric-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--foreground);
  border-radius: 5px;
  background: var(--card);
}
.app-metric {
  position: relative;
  min-width: 0;
  padding: 1rem 1.15rem 1.1rem;
  border-inline-end: 1px solid color-mix(in oklab, var(--foreground) 22%, transparent);
}
.app-metric:last-child {
  border-inline-end: 0;
}
.app-metric::after {
  content: "";
  position: absolute;
  inset-inline: 1.15rem;
  bottom: 0.45rem;
  height: 1px;
  background: var(--foreground);
  transform: scaleX(0.14);
  transform-origin: right;
  opacity: 0.35;
  animation: app-meter-scan 4.8s ease-in-out infinite;
}
.app-metric:nth-child(2)::after {
  animation-delay: -1.2s;
}
.app-metric:nth-child(3)::after {
  animation-delay: -2.4s;
}
.app-metric:nth-child(4)::after {
  animation-delay: -3.6s;
}
.app-metric.is-urgent {
  background: var(--foreground);
  color: var(--background);
}
.app-metric-label {
  font-size: 0.68rem;
  font-weight: 700;
  opacity: 0.62;
}
.app-metric-number {
  margin-top: 0.3rem;
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3.15rem);
  font-weight: 900;
  line-height: 1;
}
.app-metric-note {
  margin-top: 0.5rem;
  overflow: hidden;
  color: inherit;
  font-size: 0.66rem;
  opacity: 0.56;
  text-overflow: ellipsis;
  white-space: nowrap;
}
@keyframes app-meter-scan {
  0%,
  100% {
    transform: scaleX(0.12);
    opacity: 0.22;
  }
  50% {
    transform: scaleX(1);
    opacity: 0.72;
  }
}

.activation-compact {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.85rem;
  overflow: hidden;
  padding: 0.9rem 1rem;
  border: 1px solid var(--foreground);
  border-radius: 5px;
  background: var(--card);
  transition:
    background-color 180ms ease,
    color 180ms ease;
}
.activation-compact::after {
  content: "";
  position: absolute;
  inset-block: 0;
  width: 20%;
  inset-inline-start: -25%;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--foreground) 8%, transparent),
    transparent
  );
  animation: activation-sweep 3.8s ease-in-out infinite;
}
.activation-compact:hover {
  background: var(--foreground);
  color: var(--background);
}
.activation-compact:hover .text-muted-foreground {
  color: color-mix(in oklab, var(--background) 62%, transparent);
}
.activation-count {
  display: grid;
  width: 2.35rem;
  height: 2.35rem;
  flex: none;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-size: 0.65rem;
  font-weight: 900;
}
.activation-cta {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.72rem;
  font-weight: 800;
}
@keyframes activation-sweep {
  0%,
  55% {
    inset-inline-start: -25%;
  }
  100% {
    inset-inline-start: 110%;
  }
}

.app-operations-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(16rem, 0.75fr);
  gap: 1rem;
}
.app-work-list {
  margin-top: 1rem;
  border-top: 1px solid var(--foreground);
}
.app-work-row {
  padding: 0.9rem 0.15rem;
  border-bottom: 1px solid var(--border);
  transition: padding-inline 180ms ease;
}
.app-work-row:hover {
  padding-inline: 0.55rem;
}
.app-status-word {
  border-bottom: 1px solid currentColor;
  font-weight: 800;
}
.app-running-panel {
  background: var(--foreground);
  color: var(--background);
}
.app-running-panel .app-text-link {
  color: var(--background);
}
.app-running-list {
  margin-top: 1rem;
  border-top: 1px solid color-mix(in oklab, var(--background) 24%, transparent);
}
.app-running-list li {
  padding-block: 0.85rem;
  border-bottom: 1px solid color-mix(in oklab, var(--background) 16%, transparent);
}
.app-running-panel .text-muted-foreground {
  color: color-mix(in oklab, var(--background) 56%, transparent);
}
.app-running-index {
  width: 1.15rem;
  height: 1px;
  flex: none;
  background: currentColor;
  animation: running-line 1.5s ease-in-out infinite;
}
@keyframes running-line {
  50% {
    transform: scaleX(0.45);
    opacity: 0.35;
  }
}

.ads-report {
  overflow: hidden;
  border: 1px solid var(--foreground);
  border-radius: 5px;
  background: var(--foreground);
  color: var(--background);
  box-shadow: 0 24px 58px -42px color-mix(in oklab, var(--foreground) 70%, transparent);
}
.ads-platform-rail {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  border-bottom: 1px solid var(--command-line);
}
.ads-platform-rail > div {
  position: relative;
  min-width: 0;
  padding: 0.85rem 0.8rem;
  border-inline-end: 1px solid var(--command-line);
}
.ads-platform-rail > div:last-child {
  border-inline-end: 0;
}
.ads-platform-rail small,
.ads-platform-rail b,
.ads-platform-rail span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ads-platform-rail small {
  color: var(--command-dim);
  font-family: ui-monospace, monospace;
  font-size: 0.48rem;
}
.ads-platform-rail b {
  margin-top: 0.25rem;
  font-size: 0.72rem;
}
.ads-platform-rail span {
  margin-top: 0.45rem;
  color: var(--command-dim);
  font-size: 0.58rem;
}
.ads-platform-rail .is-connected::after,
.ads-platform-rail .is-reporting::after {
  content: "";
  position: absolute;
  inset-inline: 0.8rem;
  bottom: 0;
  height: 2px;
  background: var(--command-muted);
}
.ads-platform-rail .is-connected span,
.ads-platform-rail .is-reporting span {
  color: var(--command-ink);
}
.ads-platform-rail .is-reporting::after {
  background: var(--command-ink);
  animation: platform-reporting 1.9s ease-in-out infinite;
}
@keyframes platform-reporting {
  50% {
    opacity: 0.32;
    transform: scaleX(0.65);
  }
}
.ads-report-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 1.35rem;
  border-bottom: 1px solid color-mix(in oklab, var(--background) 22%, transparent);
}
.ads-report-head p {
  color: color-mix(in oklab, var(--background) 58%, transparent);
  font-size: 0.66rem;
  font-weight: 700;
}
.ads-report-head h2 {
  margin-top: 0.2rem;
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 900;
}
.ads-report-head > span {
  max-width: 44%;
  overflow: hidden;
  color: color-mix(in oklab, var(--background) 62%, transparent);
  font-size: 0.7rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ads-report-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.ads-report-metrics > div {
  padding: 1.15rem 1.35rem;
  border-inline-end: 1px solid color-mix(in oklab, var(--background) 18%, transparent);
  border-bottom: 1px solid color-mix(in oklab, var(--background) 18%, transparent);
}
.ads-report-metrics > div:last-child {
  border-inline-end: 0;
}
.ads-report-metrics p {
  color: color-mix(in oklab, var(--background) 52%, transparent);
  font-size: 0.67rem;
}
.ads-report-metrics strong {
  display: block;
  margin-top: 0.28rem;
  font-size: clamp(1.35rem, 2.6vw, 2.25rem);
  font-weight: 900;
  line-height: 1.15;
}
.ads-analysis-grid {
  display: grid;
  grid-template-columns: minmax(15rem, 0.72fr) minmax(0, 1.28fr);
}
.ads-chart {
  min-height: 15rem;
  padding: 1.25rem 1.35rem;
  border-inline-end: 1px solid var(--command-line);
}
.ads-chart-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--command-muted);
  font-size: 0.65rem;
}
.ads-chart-bars {
  height: 9.5rem;
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
  margin-top: 1rem;
  border-bottom: 1px solid var(--command-line);
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 31%,
    var(--command-line) 32%
  );
}
.ads-chart-bars i {
  flex: 1;
  min-width: 0.8rem;
  background: var(--command-ink);
  transform: scaleY(0);
  transform-origin: bottom;
  animation: ads-column-in 0.8s var(--ease-enter) forwards;
}
.ads-chart-bars i:nth-child(2) {
  animation-delay: 0.12s;
}
.ads-chart-bars i:nth-child(3) {
  animation-delay: 0.24s;
}
@keyframes ads-column-in {
  to {
    transform: scaleY(1);
  }
}
.ads-chart > p {
  display: flex;
  justify-content: space-between;
  margin-top: 0.8rem;
  color: var(--command-muted);
  font-size: 0.65rem;
}
.ads-chart > p b {
  color: var(--command-ink);
}
.ads-campaign-board {
  min-width: 0;
}
.ads-empty-state {
  min-height: 13rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  padding: 2rem 1.4rem;
}
.ads-empty-state small {
  color: var(--command-dim);
  font-size: 0.62rem;
}
.ads-empty-state h3 {
  max-width: 38rem;
  margin-top: 0.45rem;
  font-size: clamp(1.2rem, 2.5vw, 1.75rem);
}
.ads-empty-state p {
  max-width: 40rem;
  margin-top: 0.55rem;
  color: var(--command-muted);
  font-size: 0.75rem;
  line-height: 1.7;
}
.ads-empty-state > a {
  flex: none;
  padding: 0.72rem 1rem;
  border: 1px solid var(--command-ink);
  background: var(--command-ink);
  color: var(--command-bg);
  font-size: 0.72rem;
  font-weight: 800;
}
.ads-report-cost {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem 1.35rem;
  border-bottom: 1px solid color-mix(in oklab, var(--background) 18%, transparent);
  color: color-mix(in oklab, var(--background) 62%, transparent);
  font-size: 0.7rem;
}
.ads-report-cost b {
  color: var(--background);
}
.ads-report-label {
  display: flex;
  justify-content: space-between;
  padding: 1rem 1.35rem 0.55rem;
  color: color-mix(in oklab, var(--background) 50%, transparent);
  font-size: 0.62rem;
  font-weight: 700;
}
.ads-campaigns {
  padding: 0 1.35rem 1.3rem;
}
.ads-campaigns li {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0.75rem 0;
}
.ads-campaign-rank {
  color: var(--command-dim);
  font-family: ui-monospace, monospace;
  font-size: 0.62rem;
}
.ads-campaign-copy {
  min-width: 0;
  flex: 1;
}
.ads-campaign-line {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.76rem;
}
.ads-campaign-line > span {
  min-width: 0;
  overflow: hidden;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ads-campaign-line b {
  flex: none;
  min-width: 0;
  overflow-wrap: anywhere;
  color: color-mix(in oklab, var(--background) 62%, transparent);
  font-size: 0.66rem;
}
@media (min-width: 640px) {
  .ads-campaign-line {
    grid-template-columns: minmax(0, 1fr) minmax(0, auto);
  }
}
.ads-campaign-track {
  display: block;
  height: 2px;
  margin-top: 0.5rem;
  background: color-mix(in oklab, var(--background) 15%, transparent);
}
.ads-campaign-track i {
  display: block;
  height: 100%;
  background: var(--background);
  transform: scaleX(0);
  transform-origin: right;
  animation: ads-bar-in 0.9s var(--ease-enter) forwards;
}
.ads-campaigns li:nth-child(2) i {
  animation-delay: 0.12s;
}
.ads-campaigns li:nth-child(3) i {
  animation-delay: 0.24s;
}
@keyframes ads-bar-in {
  to {
    transform: scaleX(1);
  }
}

/* خلفية حيّة قبل أول رسالة — مسارات سريعة تظهر وتختفي في كامل الواجهة. */
.chat-smoke {
  opacity: 1;
  transition:
    opacity 0.72s var(--ease-exit),
    filter 0.72s var(--ease-exit);
}
.chat-stage.is-engaged .chat-smoke {
  display: none;
}
.chat-smoke span {
  position: absolute;
  display: block;
  width: clamp(9rem, 22vw, 22rem);
  height: 1px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in oklab, var(--foreground) 42%, transparent),
    transparent
  );
  opacity: 0;
  will-change: transform, opacity;
  animation: chat-flare-flight 4.2s cubic-bezier(0.2, 0.7, 0.25, 1) infinite;
}
.chat-smoke span:nth-of-type(1) {
  top: 14%;
  inset-inline-start: -24%;
  animation-delay: -0.4s;
}
.chat-smoke span:nth-of-type(2) {
  top: 34%;
  inset-inline-start: -24%;
  animation-delay: -1.7s;
  animation-duration: 5.1s;
}
.chat-smoke span:nth-of-type(3) {
  top: 55%;
  inset-inline-start: -24%;
  animation-delay: -3.1s;
  animation-duration: 3.8s;
}
.chat-smoke span:nth-of-type(4) {
  top: 72%;
  inset-inline-start: -24%;
  animation-delay: -2.2s;
  animation-duration: 4.7s;
}
.chat-smoke span:nth-of-type(5) {
  top: 88%;
  inset-inline-start: -24%;
  animation-delay: -3.8s;
  animation-duration: 5.4s;
}
@keyframes chat-flare-flight {
  0% {
    opacity: 0;
    transform: translate3d(0, 1.4rem, 0) rotate(-8deg) scaleX(0.45);
  }
  18% {
    opacity: 0.48;
  }
  58% {
    opacity: 0.18;
  }
  100% {
    opacity: 0;
    transform: translate3d(145vw, -2rem, 0) rotate(7deg) scaleX(1.35);
  }
}
.chat-smoke i:nth-child(1) {
  animation-duration: 3.1s;
}
.chat-smoke i:nth-child(2) {
  animation-duration: 3.8s;
}
.chat-smoke i:nth-child(3) {
  animation-duration: 4.5s;
}
.chat-smoke b:nth-of-type(1) {
  animation-duration: 2.7s;
}
.chat-smoke b:nth-of-type(2) {
  animation-duration: 3.4s;
  animation-delay: -1.1s;
}
.chat-smoke b:nth-of-type(3) {
  animation-duration: 4.1s;
  animation-delay: -2.2s;
}

@media (max-width: 900px) {
  .app-team-directory {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .app-operations-grid {
    grid-template-columns: 1fr;
  }
  .app-command-center .app-operations-grid > * + * {
    border-inline-start: 0 !important;
    border-top: 1px solid var(--command-line) !important;
  }
  .ads-platform-rail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .ads-platform-rail > div:nth-child(3) {
    border-inline-end: 0;
  }
  .ads-platform-rail > div:nth-child(-n + 3) {
    border-bottom: 1px solid var(--command-line);
  }
}
@media (max-width: 640px) {
  .app-command-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .app-metric-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .app-metric:nth-child(2) {
    border-inline-end: 0;
  }
  .app-metric:nth-child(-n + 2) {
    border-bottom: 1px solid var(--foreground);
  }
  .app-team-directory {
    grid-template-columns: 1fr;
  }
  .activation-compact {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .activation-compact > .min-w-0 {
    min-width: calc(100% - 3.4rem);
  }
  .activation-cta {
    margin-inline-start: 3.2rem;
  }
  .ads-report-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ads-report-metrics > div:nth-child(2) {
    border-inline-end: 0;
  }
  .ads-report-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .ads-report-head > span {
    max-width: 100%;
  }
  .ads-analysis-grid {
    grid-template-columns: 1fr;
  }
  .ads-chart {
    border-inline-end: 0;
    border-bottom: 1px solid var(--command-line);
  }
  .ads-empty-state {
    align-items: flex-start;
    flex-direction: column;
  }
  .chat-smoke i {
    filter: blur(42px);
  }
  .chat-smoke span:nth-of-type(n + 4) {
    display: none;
  }
}

/* ===== ضبط الهاتف: مقارنة كاملة، تسجيل بلا تمرير، وموجة أسعار نقطية ===== */
@media (max-width: 720px) {
  .sahl-versus-table {
    margin-top: 26px;
  }

  .sahl-versus-head {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sahl-versus-head span:first-child {
    display: none;
  }

  .sahl-versus-head span:nth-child(2) {
    display: flex;
    color: color-mix(in oklab, var(--home-bg) 74%, transparent);
  }

  .sahl-versus-head span {
    min-height: 46px;
    justify-content: center;
    padding: 10px 8px;
    text-align: center;
  }

  .sahl-versus-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sahl-versus-row > span:first-child {
    grid-column: 1 / -1;
    min-height: 0;
    justify-content: center;
    padding: 9px 12px 7px;
    border-bottom: 1px solid color-mix(in oklab, var(--home-bg) 9%, transparent);
    background: color-mix(in oklab, var(--home-bg) 4%, transparent);
    font-size: 0.72rem;
    line-height: 1.45;
    text-align: center;
  }

  .sahl-versus-row .is-plain,
  .sahl-versus-row .is-sahl {
    display: flex;
    min-width: 0;
    min-height: 74px;
    margin: 0;
    padding: 11px 10px;
    border-radius: 0;
    font-size: clamp(0.68rem, 3vw, 0.78rem);
    line-height: 1.65;
  }

  .sahl-versus-row .is-plain {
    color: color-mix(in oklab, var(--home-bg) 62%, transparent);
  }

  .sahl-versus-row .is-plain::before {
    content: none;
  }
}

