@media (max-width: 767px) {
  .sahl-upgrade {
    --pricing-dot-brick: #a8492c;
    --pricing-dot-gold: #c68a2e;
    --pricing-dot-teal: #2f6b63;
    background: var(--background);
  }

  .sahl-upgrade-dots {
    inset: 0;
    opacity: 1;
    background-image:
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-brick) 24%, transparent) 1.1px,
        transparent 1.7px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-gold) 22%, transparent) 1.1px,
        transparent 1.7px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-teal) 23%, transparent) 1.1px,
        transparent 1.7px
      );
    background-position:
      0 0,
      12px 12px,
      24px 24px;
    background-size: 36px 36px;
    mask-image: linear-gradient(to bottom, black 0%, black 76%, transparent 100%);
  }

  .sahl-upgrade-dots::before,
  .sahl-upgrade-dots::after {
    content: "";
    position: absolute;
    inset: -24% -38%;
    pointer-events: none;
    will-change: background-position;
  }

  .sahl-upgrade-dots::before {
    background-image:
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-brick) 76%, transparent) 2.2px,
        transparent 3.1px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-gold) 72%, transparent) 2.2px,
        transparent 3.1px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-teal) 74%, transparent) 2.2px,
        transparent 3.1px
      );
    background-position:
      0 0,
      12px 12px,
      24px 24px;
    background-size: 36px 36px;
    mask-image: linear-gradient(125deg, transparent 40%, black 46%, black 54%, transparent 60%);
    animation: sahl-pricing-dot-wave-primary 2.4s linear infinite;
  }

  .sahl-upgrade-dots::after {
    inset: -18% -30%;
    background-image:
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-teal) 55%, transparent) 1.8px,
        transparent 2.6px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-brick) 52%, transparent) 1.8px,
        transparent 2.6px
      ),
      radial-gradient(
        circle,
        color-mix(in oklab, var(--pricing-dot-gold) 52%, transparent) 1.8px,
        transparent 2.6px
      );
    background-position:
      0 0,
      12px 12px,
      24px 24px;
    background-size: 36px 36px;
    mask-image: linear-gradient(55deg, transparent 43%, black 48%, black 52%, transparent 57%);
    opacity: 0.55;
    animation: sahl-pricing-dot-wave-secondary 2.4s linear infinite;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sahl-upgrade-dots::before,
  .sahl-upgrade-dots::after {
    animation: none !important;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .app-metric::after,
  .activation-compact::after,
  .app-running-index,
  .ads-campaign-track i,
  .chat-smoke i,
  .chat-smoke b,
  .chat-smoke span,
  .sahl-first-claim,
  .ads-chart-bars i,
  .app-command-head > span i,
  .ads-platform-rail .is-reporting::after {
    animation: none !important;
  }
  .sahl-first-claim {
    background-image: none;
    -webkit-text-fill-color: currentColor;
  }
  .ads-campaign-track i {
    transform: none;
  }
  .chat-smoke {
    transition: none;
  }
  .chat-smoke i {
    opacity: 0.1;
    transform: none;
  }
  .chat-smoke b,
  .chat-smoke span {
    opacity: 0.08;
    transform: none;
  }
}

/* ===== مركز القيادة الفاتح — بطاقات تنفيذية وهوية المنصات ===== */
.app-command-center {
  border-color: var(--border);
  border-radius: 1.25rem;
  background: var(--background);
  color: var(--foreground);
  box-shadow: var(--shadow-card);
}
.app-command-head {
  background: color-mix(in oklab, var(--secondary) 62%, var(--background));
}
.app-command-center .app-metric,
.app-command-center .app-metric.is-urgent,
.app-command-center .app-running-panel,
.ads-report {
  background: var(--background) !important;
  color: var(--foreground) !important;
}
.app-metric-icon {
  display: grid;
  width: 2rem;
  height: 2rem;
  margin-bottom: 0.9rem;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 0.65rem;
  background: var(--secondary);
  color: var(--jade-deep);
}
.app-metric-icon svg {
  width: 1rem;
  height: 1rem;
}
.app-command-center .app-metric.is-urgent .app-metric-icon {
  color: var(--gold-deep);
}
.ads-report {
  border-color: var(--border);
  box-shadow: none;
}
.ads-report-head {
  border-color: var(--border);
}
.ads-report-head p,
.ads-report-head > span,
.ads-report-metrics p,
.ads-campaign-line b {
  color: var(--muted-foreground);
}
.ads-platform-rail {
  gap: 0.65rem;
  padding: 0.8rem;
  background: var(--secondary);
}
.ads-platform-rail > div {
  min-height: 4.4rem;
  padding: 0.75rem !important;
  border: 1px solid var(--border) !important;
  border-radius: 0.85rem;
  background: var(--background);
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease;
}
.ads-platform-rail > div:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card);
}
.ads-platform-rail > div::after {
  inset-inline: 0.75rem !important;
}
.ads-platform-rail > div > div:first-child {
  border: 1px solid var(--border);
  background: var(--background);
}
.ads-report-metrics > div {
  position: relative;
  background: var(--background);
}
.ads-report-metrics p {
  font-weight: 750;
}
.ads-report-metrics p svg {
  color: var(--jade-deep);
}
.ads-chart-bars i,
.ads-campaign-track i {
  background: var(--jade);
}
.ads-empty-state > a {
  border-radius: 0.7rem;
  background: var(--foreground);
  color: var(--background);
}
.app-running-panel .app-text-link {
  color: var(--foreground);
}

/* سحب الدخان في كل الاتجاهات مع فترات اختفاء قبل أول إرسال. */
.chat-smoke i {
  inset: auto !important;
}
.chat-smoke i:nth-child(1) {
  left: -22%;
  top: -18%;
  animation: chat-roam-one 5.8s ease-in-out infinite !important;
}
.chat-smoke i:nth-child(2) {
  right: -24%;
  top: 30%;
  animation: chat-roam-two 6.7s ease-in-out infinite -2.1s !important;
}
.chat-smoke i:nth-child(3) {
  left: 18%;
  bottom: -24%;
  animation: chat-roam-three 7.4s ease-in-out infinite -4s !important;
}
@keyframes chat-roam-one {
  0%,
  100% {
    opacity: 0;
    transform: translate3d(-10vw, -10vh, 0) scale(0.72);
  }
  14% {
    opacity: 0.3;
  }
  42% {
    opacity: 0.1;
    transform: translate3d(66vw, 28vh, 0) scale(1.12);
  }
  58% {
    opacity: 0;
  }
  78% {
    opacity: 0.28;
    transform: translate3d(22vw, 74vh, 0) scale(0.9);
  }
}
@keyframes chat-roam-two {
  0%,
  100% {
    opacity: 0;
    transform: translate3d(10vw, -8vh, 0) scale(0.75);
  }
  20% {
    opacity: 0.26;
    transform: translate3d(-62vw, 18vh, 0) scale(1.08);
  }
  48% {
    opacity: 0;
  }
  72% {
    opacity: 0.3;
    transform: translate3d(-24vw, 52vh, 0) scale(0.92);
  }
  88% {
    opacity: 0.08;
  }
}
@keyframes chat-roam-three {
  0%,
  100% {
    opacity: 0;
    transform: translate3d(-12vw, 14vh, 0) scale(0.8);
  }
  18% {
    opacity: 0.28;
    transform: translate3d(42vw, -72vh, 0) scale(1.12);
  }
  46% {
    opacity: 0.06;
  }
  62% {
    opacity: 0;
  }
  82% {
    opacity: 0.25;
    transform: translate3d(-18vw, -34vh, 0) scale(0.95);
  }
}

@media (max-width: 640px) {
  .ads-platform-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ads-platform-rail > div:nth-child(n) {
    border: 1px solid var(--border) !important;
  }
  .app-metric-icon {
    margin-bottom: 0.65rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-smoke i {
    animation: none !important;
    opacity: 0.1;
  }
}

/* Cookie consent must stay viewport-fixed after the duplicated glass foundation rules. */
.liquid-glass-sahl.sahl-cookie-consent {
  position: fixed;
  z-index: 150;
  inset: auto auto max(20px, env(safe-area-inset-bottom)) 20px;
  overflow: hidden;
}
@media (max-width: 720px) {
  .liquid-glass-sahl.sahl-cookie-consent {
    inset: auto 12px max(12px, env(safe-area-inset-bottom)) 12px;
  }
}

/* Polishing Activation Map Icons */
.activation-map-icon {
  transition: all 0.3s ease;
}

/* Lightening First Run */
.app-first-run::before {
  display: none;
}
.app-first-run {
  border-top: 3px solid var(--primary);
  border-radius: 20px !important;
}

/* Polishing Business Profile Card */
.business-profile-card {
  box-shadow: var(--shadow-card);
  border-radius: 20px !important;
}

/* ===== تجاوب الهواتف: منع تداخل الكلمات ===== */
/* شارة «الفريق كاملًا» كانت تركب على وسم الخطة في الشاشات الضيّقة. */
@media (max-width: 640px) {
  .sahl-plan-grid article {
    padding-top: 22px;
  }
  .sahl-plan-tag {
    position: static;
    inset: auto;
    display: inline-block;
    margin-bottom: 10px;
    max-width: 100%;
  }
  .sahl-plan-grid article > small,
  .sahl-plan-grid article > h3,
  .sahl-plan-grid article > p {
    overflow-wrap: anywhere;
  }
}

/* حضور الموظف في شريط المحادثة: يوحي أن في زميلاً متاحاً الآن لا أداة صامتة. */
.chat-presence {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  flex-shrink: 0;
  padding: 0.25rem 0.55rem;
  border-radius: 999px;
  border: 1px solid hsl(var(--border));
  background: hsl(var(--secondary) / 0.6);
  font-size: 0.68rem;
  font-weight: 600;
  color: hsl(var(--muted-foreground));
  white-space: nowrap;
}
.chat-presence i {
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: #16a34a;
  box-shadow: 0 0 0 0 rgb(22 163 74 / 0.55);
  animation: chat-presence-pulse 2.2s ease-out infinite;
}
@keyframes chat-presence-pulse {
  70% {
    box-shadow: 0 0 0 0.35rem rgb(22 163 74 / 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgb(22 163 74 / 0);
  }
}
@media (max-width: 420px) {
  .chat-presence span {
    display: none;
  }
}

/* ملاحظة «أثناء غيابك»: زميل يلخّص ما حدث، لا لوحة أرقام. */
.app-catchup {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.6rem;
  padding: 0.7rem 0.9rem;
  border-radius: 1rem;
  border: 1px solid hsl(var(--border));
  background: hsl(var(--secondary) / 0.55);
  font-size: 0.84rem;
  line-height: 1.7;
}
.app-catchup p {
  min-width: 0;
  flex: 1 1 16rem;
  margin: 0;
}
.app-catchup-icon {
  display: grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  flex-shrink: 0;
  border-radius: 0.7rem;
  background: hsl(var(--primary) / 0.12);
  color: hsl(var(--primary));
}

/* ============================================================
   ملاءمة الشاشات الصغيرة: مقاس نص ومسافات مريحة على الهاتف
   والتابلت، دون تغيير أي محتوى أو كلام في الصفحات.
   ============================================================ */
@media (max-width: 720px) {
  /* الصفحة الرئيسية: عنوان يناسب عرض الهاتف بلا تراكب مع الشريط الملوّن. */
  .sahl-hero h1 {
    max-width: none;
    margin-top: 26px;
    font-size: clamp(2.05rem, 8.6vw, 2.95rem);
    line-height: 1.14;
    text-wrap: balance;
  }
  .sahl-first-claim {
    margin-top: 18px !important;
    font-size: 1.05rem;
  }
  .sahl-lead {
    margin-top: 14px !important;
    font-size: 0.96rem;
    line-height: 1.75;
  }
  .sahl-hero-copy > small {
    margin-top: 16px;
  }
  .sahl-hero-product {
    margin-top: 30px;
  }

  /* الصفحات الداخلية: نفس المنطق للعنوان والمقدمة. */
  .sahl-page-title {
    max-width: none;
    margin-top: 18px;
    font-size: clamp(1.95rem, 8.2vw, 2.75rem);
    line-height: 1.16;
  }
  .sahl-page-lead {
    margin-top: 16px;
    font-size: 0.96rem;
    line-height: 1.8;
  }
  .sahl-page-hero-inner > .sahl-reveal:last-child {
    margin-top: 22px;
  }

  /* أقسام الموقع: عناوين ومسافات أقصر تناسب الهاتف. */
  .sahl-site-page main > section,
  .sahl-home main > section {
    padding-block: clamp(2.4rem, 8vw, 3.4rem);
  }
  .sahl-site-page main > .sahl-page-hero {
    padding-block: 7.25rem 4.5rem;
  }
  .sahl-site-page :is(.text-6xl, .text-5xl),
  .sahl-home :is(.text-6xl, .text-5xl) {
    font-size: 1.95rem;
    line-height: 1.22;
  }
  .sahl-site-page .text-4xl,
  .sahl-home .text-4xl {
    font-size: 1.68rem;
    line-height: 1.26;
  }
  .sahl-site-page .text-3xl,
  .sahl-home .text-3xl {
    font-size: 1.42rem;
    line-height: 1.3;
  }
  .sahl-site-page .text-2xl,
  .sahl-home .text-2xl {
    font-size: 1.22rem;
    line-height: 1.35;
  }
  .sahl-site-page .text-xl,
  .sahl-home .text-xl {
    font-size: 1.08rem;
  }

  /* مساحة العمل: بطاقات وعناوين أصغر قليلاً لتظهر معلومات أكثر. */
  .sahl-app-theme :is(.text-4xl) {
    font-size: 1.6rem;
    line-height: 1.28;
  }
  .sahl-app-theme :is(.text-3xl) {
    font-size: 1.38rem;
    line-height: 1.32;
  }
  .sahl-app-theme :is(.text-2xl) {
    font-size: 1.2rem;
  }
}

@media (max-width: 430px) {
  .sahl-hero h1 {
    font-size: clamp(1.9rem, 9vw, 2.5rem);
  }
  .sahl-page-title {
    font-size: clamp(1.8rem, 8.6vw, 2.35rem);
  }
  .sahl-live-metric {
    font-size: 0.76rem;
  }
}

/* ============================================================
   قراءة مريحة على الهاتف: حد أدنى لحجم النص الصغير جدًا
   وحد أدنى لمساحة اللمس — بلا تغيير في التصميم أو المحتوى.
   ============================================================ */
@media (max-width: 720px) {
  [class*="text-[0.6"],
  [class*="text-[0.7"],
  [class*="text-[9px]"],
  [class*="text-[10px]"],
  [class*="text-[11px]"] {
    font-size: 0.72rem;
  }
  .sahl-home footer a,
  .sahl-site-page footer a {
    display: inline-flex;
    align-items: center;
    min-height: 2.4rem;
  }
  .sahl-site-page main button,
  .sahl-home main button {
    min-height: 2.25rem;
  }
}

/* ===== علامة التوثيق الأصلية داخل إشعار «بانتظار اعتمادك» ===== */
.sahl-float-note-icon.is-verified {
