}
.sahl-float-note-icon.is-verified svg {
  width: 100%;
  height: 100%;
  stroke-width: 0;
  color: inherit;
  --verified-check: oklch(1 0 0);
  filter: drop-shadow(
    0 4px 10px color-mix(in oklab, var(--verified-blue, oklch(0.7 0.16 238)) 28%, transparent)
  );
}
.sahl-hero-product > .sahl-float-note {
  width: fit-content;
  min-height: 52px;
  grid-template-columns: 28px auto 7px;
  padding: 9px 12px;
}
.sahl-hero-product > .sahl-float-note b {
  font-size: 0.82rem;
}

@media (max-width: 720px) {
  .sahl-hero-product > .sahl-float-note {
    width: fit-content;
    min-height: 48px;
    grid-template-columns: 25px auto 7px;
    padding: 8px 11px;
  }
  .sahl-hero-product > .sahl-float-note b {
    font-size: 0.75rem;
  }
}

/* ===== ضبط نهائي للهاتف: قائمة مدمجة وجدول مقارنة متماسك ===== */
@media (max-width: 1024px) {
  .sahl-white-mobile {
    inset: 76px auto auto 50%;
