    display: flex;
    min-width: 0;
    min-height: 74px;
    padding: 11px 10px;
    font-size: clamp(0.68rem, 3vw, 0.78rem);
    line-height: 1.65;
  }
  .sahl-versus-row .is-sahl {
    min-width: 0;
    min-height: 74px;
    margin: 0;
    padding: 11px 10px;
    border-radius: 0;
    align-items: flex-start;
    font-size: clamp(0.68rem, 3vw, 0.78rem);
    line-height: 1.65;
  }
}

/* ===== زر «أحدث رسالة»: يظهر فقط عندما يقلّب المستخدم بحرّيته ===== */
.chat-jump-bottom {
  position: absolute;
  inset-inline: 0;
  bottom: clamp(84px, 12vh, 132px);
  z-index: 30;
  margin-inline: auto;
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.4rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--card);
  color: var(--foreground);
  font-size: 0.72rem;
  font-weight: 700;
  box-shadow: 0 12px 30px -16px oklch(0.2 0.02 260 / 0.45);
}
.chat-jump-bottom:hover {
  background: var(--secondary);
}

/* ===== بطاقات المنشور الجاهزة داخل المحادثة ===== */
.post-card-grid {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
}
.post-card {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  padding: 0.75rem;
  border: 1px solid var(--border);
  border-radius: 1rem;
  background: var(--card);
  box-shadow: 0 14px 34px -26px oklch(0.2 0.02 260 / 0.5);
}
.post-card-head {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}
.post-card-logo {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 0.6rem;
  background: var(--secondary);
}
.post-card-name {
  min-width: 0;
  flex: 1;
  font-size: 0.75rem;
  font-weight: 800;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.post-card-icon {
  display: grid;
  place-items: center;
  width: 1.85rem;
  height: 1.85rem;
  border-radius: 0.6rem;
  border: 1px solid var(--border);
  color: var(--muted-foreground);
}
.post-card-icon:hover {
  background: var(--secondary);
  color: var(--foreground);
}
.post-card-publish {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.4rem 0.7rem;
  border-radius: 999px;
  background: var(--foreground);
  color: var(--background);
  font-size: 0.7rem;
  font-weight: 800;
  white-space: nowrap;
}
.post-card-publish:disabled {
  opacity: 0.55;
}
.post-card-publish.is-connect {
  background: transparent;
  color: var(--foreground);
  border: 1px dashed var(--border);
}
.post-card-body {
  margin: 0;
  font-size: 0.82rem;
  line-height: 1.75;
  white-space: pre-line;
  color: var(--foreground);
}
.post-card-body.is-clamped {
  display: -webkit-box;
  -webkit-line-clamp: 5;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.post-card-body button {
  margin-inline-start: 0.3rem;
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--muted-foreground);
}
.post-card-body button:hover {
  text-decoration: underline;
}
.post-card-edit textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: var(--background);
  padding: 0.6rem 0.7rem;
  font-size: 0.82rem;
  line-height: 1.75;
  outline: none;
}
.post-card-edit-foot {
  margin-top: 0.35rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}
.post-card-edit-foot button {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-weight: 800;
  color: var(--foreground);
}
.post-card-media {
  display: grid;
  gap: 0.4rem;
  grid-template-columns: repeat(auto-fill, minmax(4.5rem, 1fr));
}
.post-card-media > span {
  position: relative;
  display: block;
}
.post-card-media img,
.post-card-media video {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  border-radius: 0.65rem;
  border: 1px solid var(--border);
}
.post-card-media > span > button {
  position: absolute;
  inset-block-end: 0.2rem;
  inset-inline-end: 0.2rem;
  display: grid;
  place-items: center;
  width: 1.4rem;
  height: 1.4rem;
  border-radius: 0.4rem;
  background: oklch(0.2 0.02 260 / 0.65);
  color: #fff;
}
.post-card-foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.68rem;
  color: var(--muted-foreground);
}
.post-card-foot > button {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.3rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  font-weight: 800;
}
.post-card-foot > button:hover {
  background: var(--secondary);
}
.post-card-schedule {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem;
}
.post-card-schedule input {
  min-width: 0;
  flex: 1;
  border: 1px solid var(--border);
  border-radius: 0.6rem;
  background: var(--background);
  padding: 0.35rem 0.5rem;
  font-size: 0.72rem;
}
.post-card-schedule button {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.4rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-size: 0.7rem;
  font-weight: 800;
}
@media (max-width: 480px) {
  .post-card-grid {
    grid-template-columns: 1fr;
  }
  .post-card-body {
    font-size: 0.8rem;
  }
}

/* ===== معرض المنشور: وسائط أولاً، تقليب ولمس، ومعاينة كاملة ===== */
.post-publisher-media-first {
  margin: -0.25rem -0.25rem 1rem;
}
.post-media-gallery {
  width: 100%;
}
.post-media-stage {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: var(--secondary);
  touch-action: pan-y;
}
.post-media-stage > img,
.post-media-stage > video {
  width: 100%;
  height: 100%;
  object-fit: contain;
  background: var(--secondary);
}
.post-media-expand,
.post-media-delete,
.post-media-close,
.post-media-next,
.post-media-prev {
  position: absolute;
  z-index: 3;
  box-shadow: var(--shadow-card);
}
.post-media-expand {
  inset-block-start: 0.75rem;
  inset-inline-start: 0.75rem;
}
.post-media-delete {
  inset-block-start: 0.75rem;
  inset-inline-end: 0.75rem;
}
.post-media-next {
  inset-inline-end: 0.75rem;
  inset-block-start: 50%;
  transform: translateY(-50%);
}
.post-media-prev {
  inset-inline-start: 0.75rem;
  inset-block-start: 50%;
  transform: translateY(-50%);
}
.post-media-count {
  position: absolute;
  inset-block-end: 0.75rem;
  inset-inline-start: 50%;
  translate: -50% 0;
  border-radius: 999px;
  background: color-mix(in oklab, var(--foreground) 78%, transparent);
  color: var(--background);
  padding: 0.25rem 0.65rem;
  font-size: 0.68rem;
  font-weight: 800;
  direction: ltr;
}
.post-media-strip {
  display: flex;
  gap: 0.4rem;
  margin-top: 0.5rem;
  overflow-x: auto;
  padding-block-end: 0.25rem;
  scrollbar-width: thin;
  padding-block-start: 0.5rem;
  padding-inline: 0.5rem;
}
.post-media-thumb {
  flex: 0 0 3.5rem;
  overflow: hidden;
  border: 2px solid transparent;
  border-radius: 0.5rem;
  opacity: 0.65;
}
.post-media-thumb.is-active {
  border-color: var(--foreground);
  opacity: 1;
}
.post-media-thumb img,
.post-media-thumb video {
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
}
.post-media-empty {
  display: grid;
  min-height: 11rem;
  place-items: center;
  align-content: center;
  gap: 0.6rem;
  border: 1px dashed var(--border);
  border-radius: 0.75rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
  font-weight: 700;
}
.post-media-lightbox {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: grid;
  place-items: center;
  padding: clamp(0.75rem, 3vw, 2rem);
  background: color-mix(in oklab, var(--foreground) 92%, transparent);
}
.post-media-lightbox .post-media-stage.is-fullscreen {
  width: min(100%, 90rem);
  height: 100%;
  min-height: 0;
  aspect-ratio: auto;
  border: 0;
  background: transparent;
}
.post-media-lightbox .post-media-stage > img,
.post-media-lightbox .post-media-stage > video {
  object-fit: contain;
  background: transparent;
}
.post-media-close {
  inset-block-start: max(0.75rem, env(safe-area-inset-top));
  inset-inline-end: max(0.75rem, env(safe-area-inset-right));
}
.post-inline-calendar {
  margin-top: 0.75rem;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background: var(--card);
  padding: 0.75rem;
}
.post-inline-calendar-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
}
.post-inline-calendar-head button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 0.5rem;
}
.post-inline-calendar-head button:hover {
  background: var(--secondary);
}
.post-calendar-weekdays,
.post-calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.25rem;
}
.post-calendar-weekdays {
  margin-top: 0.6rem;
  color: var(--muted-foreground);
  font-size: 0.6rem;
  font-weight: 800;
  text-align: center;
}
.post-calendar-day {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 0.15rem;
  min-height: 3.6rem;
  padding: 0.25rem 0.15rem;
  border: 1px solid var(--border);
  border-radius: 0.45rem;
  font-size: 0.68rem;
}
.post-calendar-day:hover,
.post-calendar-day.is-selected {
  border-color: var(--foreground);
  background: var(--secondary);
}
.post-calendar-day.is-today > b {
  border-radius: 999px;
  background: var(--foreground);
  color: var(--background);
  padding-inline: 0.35rem;
}
.post-calendar-day.has-posts {
  background: color-mix(in oklab, var(--secondary) 55%, transparent);
}
.post-calendar-day-thumbs {
  display: flex;
  align-items: center;
  gap: 0.1rem;
  flex-wrap: nowrap;
  justify-content: center;
  max-width: 100%;
  overflow: hidden;
}
.post-calendar-day-thumbs img {
  width: 0.85rem;
  height: 0.85rem;
  border-radius: 0.2rem;
  object-fit: cover;
}
.post-calendar-day-thumbs .dot {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 999px;
  background: var(--foreground);
}
.post-calendar-day-thumbs .dot.is-draft {
  background: var(--muted-foreground);
}
.post-calendar-day-thumbs .dot.is-failed {
  background: var(--destructive);
}
.post-calendar-day-thumbs em {
  font-size: 0.5rem;
  font-style: normal;
  font-weight: 800;
  color: var(--muted-foreground);
}
.post-inline-calendar-list {
  margin-top: 0.6rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: 0.4rem;
}
.post-inline-calendar-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 0.6rem;
  padding: 0.5rem;
  font-size: 0.68rem;
  text-align: start;
}
.post-inline-calendar-item > img,
.post-inline-calendar-noimg {
  width: 2.6rem;
  height: 2.6rem;
  border-radius: 0.5rem;
  object-fit: cover;
  display: grid;
  place-items: center;
  background: var(--secondary);
}
.post-inline-calendar-body {
  min-width: 0;
}
.post-inline-calendar-meta {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.post-inline-calendar-item p {
  margin-top: 0.15rem;
  color: var(--muted-foreground);
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}
.post-inline-calendar-item small {
  color: var(--muted-foreground);
}
.post-inline-calendar-item small.status {
  border-radius: 999px;
  border: 1px solid var(--border);
  padding-inline: 0.35rem;
  font-size: 0.58rem;
  font-weight: 800;
}
.post-inline-calendar-item small.status.is-failed {
  color: var(--destructive);
  border-color: var(--destructive);
}
.post-calendar-link {
  display: inline-flex;
  margin-top: 0.7rem;
  font-size: 0.7rem;
  font-weight: 800;
  text-decoration: underline;
  text-underline-offset: 0.2rem;
}
@media (max-width: 480px) {
  .post-media-stage {
    aspect-ratio: 1 / 1;
  }
  .post-media-next,
  .post-media-prev {
    width: 2rem;
    height: 2rem;
  }
  .post-media-thumb {
    flex-basis: 3rem;
  }
}

.post-media-thumb-wrap {
  position: relative;
  flex: 0 0 3.5rem;
}
.post-media-thumb-wrap .post-media-thumb {
  flex: 1 1 auto;
  width: 100%;
  display: block;
}
.post-media-thumb-remove {
  position: absolute;
  inset-block-start: -0.3rem;
  inset-inline-end: -0.3rem;
  display: grid;
  width: 1.5rem;
  height: 1.5rem;
  padding: 0;
  place-items: center;
  border-radius: 999px;
  background: var(--destructive);
  color: var(--background);
  box-shadow: var(--shadow-card);
}

/* ===== بطاقة النشر داخل المحادثة ===== */
.post-publisher-panel {
  box-shadow: var(--shadow-card);
}
.post-publisher-copy {
  border: 1px solid color-mix(in oklab, var(--border) 70%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--background) 70%, transparent);
}
.post-schedule-slot {
  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--background) 65%, transparent);
}
.post-schedule-row input,
.post-schedule-row select {
  min-height: 2.5rem;
}
.post-publish-actions > button {
  min-height: 2.75rem;
}
@media (max-width: 480px) {
  .post-media-thumb-wrap {
    flex-basis: 3rem;
  }
  .post-publisher-panel {
    margin-inline: -0.35rem;
    padding: 0.85rem;
  }
  .post-schedule-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .post-schedule-row > input[type="date"],
  .post-schedule-row > span,
  .post-schedule-row > button:nth-last-child(1) {
    width: 100%;
  }
  .post-publish-actions {
    display: grid;
    grid-template-columns: 1fr;
  }
  .post-publish-actions > button {
    width: 100%;
  }
}

/* ===== جودة المنشور قبل النشر ===== */
.post-quality-card {
  box-shadow: var(--shadow-card);
}
.post-quality-score {
  display: inline-grid;
  place-items: center;
  width: 3.35rem;
  height: 3.35rem;
  flex: 0 0 auto;
  border-radius: 999px;
  color: var(--primary-foreground);
  line-height: 1;
  box-shadow: var(--shadow-card);
}
.post-quality-score.is-excellent {
  background: linear-gradient(135deg, var(--jade), var(--jade-deep));
}
.post-quality-score.is-good {
  background: linear-gradient(135deg, var(--gold), var(--jade));
}
.post-quality-score.is-needs-work {
  background: linear-gradient(135deg, var(--gold), var(--coral));
}
.post-quality-score.is-weak {
  background: linear-gradient(135deg, var(--coral), var(--gold-deep));
}
.post-quality-score > span {
  font-size: 1rem;
  font-weight: 900;
}
.post-quality-score > small {
  margin-top: -0.15rem;
  font-size: 0.58rem;
  font-weight: 800;
  opacity: 0.82;
  direction: ltr;
}
.post-quality-meter {
  display: block;
  width: 100%;
  height: 0.45rem;
  overflow: hidden;
  border: 0;
  border-radius: 999px;
  background: var(--secondary);
  color: var(--foreground);
}
.post-quality-meter::-webkit-progress-bar {
  background: var(--secondary);
}
.post-quality-meter::-webkit-progress-value {
  border-radius: 999px;
  background: linear-gradient(90deg, var(--coral), var(--gold), var(--jade));
}
.post-quality-meter::-moz-progress-bar {
  border-radius: 999px;
  background: linear-gradient(90deg, var(--coral), var(--gold), var(--jade));
}

@media (max-width: 480px) {
  .post-quality-score {
    width: 2.75rem;
    height: 2.75rem;
  }
  .post-quality-score > span {
    font-size: 0.88rem;
  }
}

/* الشريط العلوي: الشريط نفسه أبيض، من دون الغلاف الملوّن المحيط به. */
.app-shell header.app-topbar,
.sahl-app-theme header.app-topbar {
  padding: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}
.app-shell header.app-topbar .app-topbar-inner,
.sahl-app-theme header.app-topbar .app-topbar-inner {
  width: 100% !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--background) !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

/* محادثة الهاتف: كل رد وبطاقة يبقيان داخل الشاشة، دون قص أفقي. */
@media (max-width: 640px) {
  .chat-message-column {
    padding-inline: 0.65rem !important;
    overflow-x: clip;
  }
  .chat-message-column > div,
  .chat-message-column .chat-message-row,
  .chat-message-column .chat-message-content {
    min-width: 0;
    max-width: 100%;
  }
  .chat-message-column .chat-message-row {
    width: 100%;
    gap: 0.5rem;
  }
  .chat-message-column .is-assistant {
    width: 100%;
    max-width: 100%;
  }
  .chat-message-column .is-assistant .chat-message-content {
    width: calc(100% - 2.5rem);
    padding: 0.5rem 0 0.75rem;
    overflow: visible;
  }
  .chat-thinking-row {
    width: 100%;
    max-width: 100%;
    gap: 0.5rem;
  }
  .chat-thinking-content {
    width: calc(100% - 2.5rem);
    max-width: none;
  }
  .chat-message-content :is(p, li, a, h1, h2, h3, h4, h5, h6) {
    overflow-wrap: anywhere;
  }
  .chat-message-content pre {
    display: block;
    max-width: 100%;
    overflow-x: auto;
  }
  .chat-message-content img,
  .chat-message-content video,
  .post-publisher-panel,
  .post-publisher-panel > * {
    max-width: 100%;
  }
  .post-publisher-panel {
    width: 100%;
    margin-inline: 0;
    padding: 0.75rem;
    overflow: hidden;
  }
  .post-media-tool-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .post-media-tool-grid > button {
    width: 100%;
    min-width: 0;
    min-height: 2.75rem;
    justify-content: center;
    border-radius: 0.75rem;
    line-height: 1.35;
    text-align: center;
    white-space: normal;
  }
  .post-media-settings {
    display: grid;
    grid-template-columns: 1fr;
  }
  .post-media-settings > label,
  .post-media-settings > button,
  .post-media-settings select {
    width: 100%;
  }
  .post-media-settings > label {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
  }
  .post-schedule-row {
    width: 100%;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .post-schedule-row > * {
    min-width: 0;
    max-width: 100%;
  }
  .post-schedule-row > input[type="date"],
  .post-schedule-row > span {
    width: 100%;
  }
  .post-schedule-row > button {
    white-space: normal;
  }
  .post-schedule-row > button:nth-of-type(3) {
    grid-column: 1 / -1;
    width: 100%;
    justify-content: center;
  }
}

@media (max-width: 380px) {
  .post-media-tool-grid {
    grid-template-columns: 1fr;
  }
}

/* sample section — نتائج بشكل واجهة العمل الحقيقية (كروت فاتحة داخل غلاف داكن) */
.sahl-sample-board + .sahl-sample-board {
  margin-top: 18px;
}
.sahl-sample-grid[data-cards="single"] {
  grid-template-columns: 1fr;
}
.sahl-sample-grid[data-cards="multi"] {
  grid-template-columns: 1fr 1fr;
}
.sahl-sample-grid article {
  border: 1px solid hsl(28 20% 88%);
  border-radius: 16px;
  background: #fffdfa;
  box-shadow: 0 10px 28px rgb(24 16 10 / 0.16);
}
.sahl-sample-grid header {
  border-bottom: 1px solid hsl(28 20% 91%);
  background: hsl(34 44% 97%);
}
.sahl-sample-grid header svg,
.sahl-sample-grid .is-ad header svg,
.sahl-sample-grid .is-brief header svg {
  color: hsl(16 52% 44%);
}
.sahl-sample-grid header b {
  color: hsl(24 22% 14%);
}
.sahl-sample-grid header span {
  background: hsl(174 30% 92%);
  color: hsl(184 42% 24%);
  border: 1px solid hsl(174 26% 84%);
}
.sahl-sample-grid pre {
  color: hsl(24 16% 24%);
}
@media (max-width: 860px) {
  .sahl-sample-grid[data-cards="multi"] {
    grid-template-columns: 1fr;
  }
}
.sahl-sample-body {
  flex: 1;
  padding: 16px 17px;
  font-family: "Almarai", "IBM Plex Sans Arabic", sans-serif;
  font-size: 0.85rem;
  line-height: 1.95;
  color: hsl(24 16% 24%);
}
.sahl-sample-body h4 {
  margin: 0 0 2px;
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.01em;
  color: hsl(16 52% 40%);
}
.sahl-sample-body p {
  margin: 0;
}
.sahl-sample-gap {
  display: block;
  height: 10px;
}
.sahl-sample-media {
  margin: 0 17px 4px;
  border: 1px solid hsl(28 20% 90%);
  border-radius: 12px;
  overflow: hidden;
  background: hsl(34 30% 96%);
}
.sahl-sample-media img {
  display: block;
  width: 100%;
  max-height: 320px;
  object-fit: cover;
}
.sahl-sample-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding: 12px 15px;
  border-top: 1px solid hsl(28 20% 91%);
  background: hsl(34 44% 97.5%);
}
.sahl-sample-quality {
  padding: 3px 9px;
  border-radius: 999px;
  background: hsl(140 34% 92%);
  color: hsl(152 40% 24%);
  font-size: 0.62rem;
  font-weight: 700;
}
.sahl-sample-pending {
  color: hsl(24 12% 44%);
  font-size: 0.66rem;
  font-weight: 700;
}
.sahl-sample-actions div {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-inline-start: auto;
}
.sahl-sample-actions button {
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid hsl(28 20% 86%);
  background: #fff;
  color: hsl(24 20% 22%);
  font-size: 0.68rem;
  font-weight: 700;
  cursor: default;
}
.sahl-sample-actions button:first-child {
  border-color: transparent;
  background: hsl(16 52% 44%);
  color: #fff;
}

/* sample section — لقطة المحادثة الحقيقية داخل الغلاف الداكن */
.sahl-shot {
  border: 1px solid hsl(28 20% 88%);
  border-radius: 18px;
  background: #fffdfa;
  box-shadow: 0 16px 40px rgb(24 16 10 / 0.22);
  overflow: hidden;
  color: hsl(24 16% 20%);
}
.sahl-shot-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  border-bottom: 1px solid hsl(28 20% 91%);
  background: hsl(34 44% 97%);
}
.sahl-shot-bar span {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: hsl(28 18% 84%);
}
.sahl-shot-bar p {
  margin-inline-start: 10px;
  font-size: 0.72rem;
  font-weight: 700;
  color: hsl(24 14% 40%);
}
.sahl-shot-thread {
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: clamp(14px, 2.4vw, 22px);
}
.sahl-shot-user {
  align-self: flex-start;
  max-width: min(36rem, 88%);
  padding: 12px 16px;
  border-radius: 16px 16px 16px 4px;
  background: hsl(16 52% 44%);
  color: #fff;
  font-size: 0.9rem;
  line-height: 1.85;
  font-weight: 600;
}
.sahl-shot-row {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.sahl-shot-avatar {
  display: block;
  width: 38px;
  height: 38px;
  flex: none;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgb(24 16 10 / 0.12);
}
.sahl-shot-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.sahl-shot-content {
  min-width: 0;
  flex: 1;
}
.sahl-shot-who {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 2px;
}
.sahl-shot-who b {
  font-size: 0.84rem;
  color: hsl(24 22% 14%);
}
.sahl-shot-who small {
  font-size: 0.66rem;
  font-weight: 700;
  color: hsl(24 12% 48%);
}
.sahl-shot-content .prose {
  font-size: 0.86rem;
  line-height: 1.95;
  color: hsl(24 16% 24%);
}
.sahl-shot-content .prose :is(h1, h2, h3, h4) {
  font-size: 0.86rem;
  color: hsl(24 22% 14%);
}
.sahl-shot-media {
  margin: 12px 0 0;
  max-width: 260px;
  border: 1px solid hsl(28 20% 90%);
  border-radius: 14px;
  overflow: hidden;
  background: hsl(34 30% 96%);
}
.sahl-shot-media img {
  display: block;
  width: 100%;
}
.sahl-shot-publish {
  margin-top: 12px;
  padding: 12px 14px;
  border: 1px solid hsl(28 20% 90%);
  border-radius: 14px;
  background: hsl(34 44% 97.5%);
}
.sahl-shot-publish-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.sahl-shot-publish-head > span {
  padding: 3px 10px;
  border-radius: 999px;
  background: hsl(140 34% 92%);
  color: hsl(152 40% 24%);
  font-size: 0.64rem;
  font-weight: 700;
}
.sahl-shot-publish button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  border: 1px solid hsl(28 20% 86%);
  background: #fff;
  color: hsl(24 20% 22%);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 7px 14px;
  cursor: default;
}
.sahl-shot-publish button.is-connect {
  border-style: dashed;
  color: hsl(24 14% 44%);
  font-size: 0.68rem;
  padding: 5px 11px;
}
.sahl-shot-publish-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.sahl-shot-publish button.is-primary {
  border-color: transparent;
  background: hsl(24 22% 14%);
  color: #fff;
}

/* واجهة أمثلة مختصرة: نشاط واحد ظاهر مع الاحتفاظ بالنصوص الحقيقية كاملة */
.sahl-sample-showcase {
  margin-top: clamp(28px, 4vw, 48px);
}
.sahl-sample-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  width: min(100%, 680px);
  margin: 0 auto 16px;
  padding: 6px;
  border: 1px solid color-mix(in oklab, var(--home-bg) 18%, transparent);
  border-radius: 10px;
  background: color-mix(in oklab, var(--home-ink) 84%, transparent);
}
.sahl-sample-tabs button {
  min-width: 0;
  height: 42px;
  color: color-mix(in oklab, var(--home-bg) 68%, transparent);
  font-weight: 800;
}
.sahl-sample-tabs button:hover {
  background: color-mix(in oklab, var(--home-bg) 8%, transparent);
  color: var(--home-bg);
}
.sahl-sample-tabs button.is-active {
  background: var(--home-bg);
  color: var(--home-ink);
  box-shadow: 0 4px 14px color-mix(in oklab, var(--home-ink) 28%, transparent);
}
.sahl-sample-tabs button > span {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 6px;
  background: color-mix(in oklab, currentColor 10%, transparent);
  font-size: 0.72rem;
}
.sahl-sample-viewport {
  position: relative;
  max-height: 590px;
  overflow: hidden;
  border-radius: 18px;
  transition: max-height 500ms ease;
}
.sahl-sample-viewport::after {
  position: absolute;
  inset: auto 0 0;
  height: 130px;
  content: "";
  pointer-events: none;
  background: linear-gradient(to bottom, transparent, var(--home-ink));
  transition: opacity 200ms ease;
}
.sahl-sample-viewport.is-expanded {
  max-height: 2400px;
}
.sahl-sample-viewport.is-expanded::after {
  opacity: 0;
}
.sahl-sample-expand {
  display: flex;
  min-width: 190px;
  margin: -22px auto 0;
  position: relative;
  z-index: 1;
  border-color: color-mix(in oklab, var(--home-bg) 28%, transparent);
  background: var(--home-ink);
  color: var(--home-bg);
  box-shadow: 0 16px 36px color-mix(in oklab, var(--home-ink) 42%, transparent);
}
.sahl-sample-expand:hover {
  background: color-mix(in oklab, var(--home-bg) 10%, var(--home-ink));
  color: var(--home-bg);
}
.sahl-sample-expand svg {
  transition: transform 200ms ease;
}
.sahl-sample-expand[aria-expanded="true"] svg {
  transform: rotate(180deg);
}
@media (max-width: 640px) {
  .sahl-sample-tabs {
    gap: 4px;
    padding: 4px;
  }
  .sahl-sample-tabs button {
    height: 52px;
    padding-inline: 6px;
    white-space: normal;
    font-size: 0.7rem;
    line-height: 1.3;
  }
  .sahl-sample-tabs button > span {
    display: none;
  }
  .sahl-sample-viewport {
    max-height: 520px;
  }
  .sahl-sample-expand {
    min-width: 176px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sahl-sample-viewport,
  .sahl-sample-expand svg {
    transition: none;
  }
}

/* ===== غلاف أسعار الكمبيوتر: عنوان واضح وموكب موظفين معزول بلا تداخل ===== */
.sahl-beyond {
  display: none;
}

@media (min-width: 768px) {
  .sahl-pricing-shell {
    --sahl-pricing-page-bg: oklch(0.94 0.025 83);
    background: var(--sahl-pricing-page-bg);
  }

  .sahl-pricing-shell > main,
  .sahl-pricing-shell > main > .hidden,
  .sahl-pricing-shell .sahl-page-cta {
    background: var(--sahl-pricing-page-bg);
  }

  .sahl-beyond {
    --sahl-parade-bg: var(--sahl-pricing-page-bg);
    --sahl-parade-ink: oklch(0.27 0.018 45);
    --sahl-parade-brand: oklch(0.58 0.16 38);
    --sahl-parade-accent: oklch(0.52 0.09 175);
    display: grid;
    min-height: min(100svh, 75rem);
    grid-template-rows:
      minmax(1rem, 1fr)
      auto
      minmax(clamp(2.5rem, 7vh, 5rem), 1fr)
      auto;
    overflow: hidden;
    background: var(--sahl-parade-bg);
    color: var(--sahl-parade-ink);
    padding-block: clamp(4rem, 11vh, 8rem) clamp(2rem, 4vh, 3.5rem);
  }

  .sahl-beyond-copy {
    position: relative;
    z-index: 2;
    grid-row: 2;
    width: min(90vw, 78rem);
    margin-inline: auto;
    text-align: center;
  }

  .sahl-beyond-copy h1 {
    display: flex;
    align-items: baseline;
    justify-content: center;
    gap: clamp(0.8rem, 1.7vw, 1.5rem);
    color: var(--sahl-parade-brand);
    font-family: "Almarai", var(--font-display);
    font-size: clamp(5rem, 11vw, 10rem);
    font-weight: 800;
    line-height: 0.9;
    letter-spacing: 0;
  }

  .sahl-beyond-copy h1 span {
    color: var(--sahl-parade-ink);
    font-size: 0.3em;
    font-weight: 700;
  }

  .sahl-beyond-copy p {
    margin-top: clamp(1rem, 2vh, 1.5rem);
    color: var(--sahl-parade-ink);
    font-family: "IBM Plex Sans Arabic", var(--font-sans);
    font-size: clamp(1.25rem, 2.2vw, 2rem);
    font-weight: 600;
    line-height: 1.45;
    letter-spacing: 0;
  }

  .sahl-parade {
    display: grid;
    gap: clamp(0.85rem, 1.8vh, 1.35rem);
    grid-row: 4;
    direction: ltr;
  }

  .sahl-parade-window {
    position: relative;
    overflow: hidden;
    width: 100%;
    padding-block: 0.25rem;
    mask-image: linear-gradient(to right, transparent, black 5%, black 95%, transparent);
  }

  .sahl-parade-track {
    display: flex;
    width: max-content;
    transform: translate3d(0, 0, 0);
    backface-visibility: hidden;
    contain: layout paint;
    will-change: transform;
    animation: sahl-parade-forward 40s linear infinite;
    animation-play-state: paused;
  }

  .sahl-parade.is-ready .sahl-parade-track {
    animation-play-state: running;
  }

  .sahl-parade-track.is-reverse {
    animation-name: sahl-parade-reverse;
  }

  .sahl-parade-set {
    display: flex;
    flex: none;
    gap: clamp(0.65rem, 1vw, 1rem);
    padding-inline-end: clamp(0.65rem, 1vw, 1rem);
  }

  .sahl-parade-card {
    position: relative;
    display: block;
    flex: none;
    width: clamp(6.25rem, 8vw, 8rem);
    aspect-ratio: 0.78;
    overflow: hidden;
    border: 1px solid color-mix(in oklab, var(--sahl-parade-ink) 12%, transparent);
    border-radius: 0.5rem;
    background: color-mix(in oklab, var(--sahl-parade-bg) 84%, var(--sahl-parade-accent) 16%);
    box-shadow: 0 0.8rem 2rem color-mix(in oklab, var(--sahl-parade-ink) 10%, transparent);
  }

  .sahl-parade-portrait {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center top;
    transform: translateZ(0);
  }
}

@media (min-width: 768px) and (max-width: 1199px) {
  .sahl-beyond {
    padding-block: clamp(4rem, 10vh, 7rem) 1.75rem;
  }

  .sahl-beyond-copy h1 {
    font-size: clamp(4.5rem, 12vw, 7rem);
  }

  .sahl-parade-card {
    width: clamp(5.5rem, 10vw, 6.75rem);
  }
}

@keyframes sahl-parade-forward {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(-50%, 0, 0); }
}

@keyframes sahl-parade-reverse {
  from { transform: translate3d(-50%, 0, 0); }
  to { transform: translate3d(0, 0, 0); }
}

@media (prefers-reduced-motion: reduce) {
  .sahl-parade-track,
  .sahl-parade-track.is-reverse {
    animation-play-state: paused;
  }
}

/* قسم أسعار الصفحة الرئيسية — مستقل عن صفحة /pricing */
@property --sahl-price-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@keyframes sahl-price-border-spin {
  to { --sahl-price-angle: 360deg; }
}

@keyframes sahl-perk-arrive {
  from { opacity: 0; transform: translate3d(0, 0.45rem, 0) scale(0.94); }
  to { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}

.sahl-white-home .sahl-pricing {
  --pricing-night: oklch(0.195 0.012 54);
  --pricing-cream: oklch(0.94 0.025 83);
  --pricing-brick: oklch(0.523 0.134 34.5);
  --pricing-gold: oklch(0.64 0.13 72);
  --pricing-teal: oklch(0.47 0.077 176);
  overflow: hidden;
  background: var(--pricing-night);
  color: var(--pricing-cream);
}

.sahl-pricing .sahl-section-head > span {
  color: color-mix(in oklab, var(--pricing-gold) 84%, var(--pricing-cream));
}

.sahl-pricing .sahl-section-head h2,
.sahl-pricing .sahl-section-head h2 em {
  color: var(--pricing-cream);
  font-family: "Almarai", sans-serif;
}

.sahl-pricing .sahl-section-head h2 em {
  color: color-mix(in oklab, var(--pricing-cream) 58%, transparent);
}

.sahl-pricing .sahl-section-head > p {
  color: color-mix(in oklab, var(--pricing-cream) 64%, transparent);
  font-family: "IBM Plex Sans Arabic", sans-serif;
}

.sahl-pricing .sahl-section-head p a {
  color: color-mix(in oklab, var(--pricing-gold) 88%, var(--pricing-cream));
}

.sahl-home-billing {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  width: min(100%, 22rem);
  margin: -1rem auto 3.5rem;
  padding: 0.3rem;
  border: 1px solid color-mix(in oklab, var(--pricing-cream) 14%, transparent);
  border-radius: 999px;
  background: color-mix(in oklab, var(--pricing-cream) 6%, transparent);
}

.sahl-home-billing [data-slot="button"] {
  min-width: 0;
  border-radius: 999px;
  color: color-mix(in oklab, var(--pricing-cream) 62%, transparent);
  font-family: "IBM Plex Sans Arabic", sans-serif;
  font-weight: 700;
}

.sahl-home-billing [data-slot="button"].is-active {
  background: var(--pricing-cream);
  color: var(--pricing-night);
  box-shadow: 0 0.55rem 1.5rem color-mix(in oklab, var(--pricing-night) 55%, transparent);
}

.sahl-home-billing small {
  margin-inline-start: 0.35rem;
  color: var(--pricing-brick);
  font-size: 0.65rem;
}

.sahl-pricing .sahl-plan-grid {
  gap: 1.4rem;
  align-items: stretch;
}

.sahl-pricing .sahl-plan-reveal {
  height: 100%;
}

.sahl-pricing .sahl-plan-reveal:nth-child(2) { transition-delay: 90ms; }
.sahl-pricing .sahl-plan-reveal:nth-child(3) { transition-delay: 180ms; }

.sahl-pricing .sahl-plan-grid article.sahl-home-plan {
  position: relative;
  isolation: isolate;
  min-height: 42rem;
  height: 100%;
  padding: 2.25rem 1.8rem 1.75rem;
  overflow: visible;
  border: 1px solid color-mix(in oklab, var(--pricing-cream) 14%, transparent);
  border-radius: 1.45rem;
  background: color-mix(in oklab, var(--pricing-cream) 6%, transparent);
  box-shadow: 0 1.5rem 3.8rem -3rem color-mix(in oklab, var(--pricing-night) 88%, transparent);
  backdrop-filter: blur(28px) saturate(150%);
  color: var(--pricing-cream);
  font-family: "IBM Plex Sans Arabic", sans-serif;
  transition: transform 280ms ease, box-shadow 280ms ease, border-color 280ms ease;
}

.sahl-pricing .sahl-plan-grid article.sahl-home-plan::before {
  border-radius: inherit;
  background: linear-gradient(180deg, color-mix(in oklab, var(--pricing-cream) 19%, transparent), transparent 36%, color-mix(in oklab, var(--pricing-teal) 18%, transparent));
}

.sahl-home-plan > * {
  position: relative;
  z-index: 3;
}

.sahl-pricing .sahl-plan-grid article.sahl-home-plan.is-featured {
  border-color: color-mix(in oklab, var(--pricing-brick) 88%, transparent);
  box-shadow: 0 2.4rem 5.8rem -2.65rem color-mix(in oklab, var(--pricing-brick) 68%, transparent);
}

.sahl-pricing .sahl-plan-tag {
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 50%;
  transform: translate(50%, -50%);
  min-width: 8rem;
  padding: 0.5rem 0.9rem;
  border: 1px solid color-mix(in oklab, var(--pricing-cream) 30%, transparent);
  border-radius: 999px;
  background: linear-gradient(110deg, var(--pricing-brick), var(--pricing-gold));
  box-shadow: 0 0.75rem 1.8rem -0.85rem color-mix(in oklab, var(--pricing-brick) 85%, transparent);
  color: var(--pricing-cream);
  font-size: 0.72rem;
  font-weight: 800;
  text-align: center;
}

.sahl-home-plan-head h3 {
  margin: 0;
  color: var(--pricing-cream);
  font-family: "Almarai", sans-serif;
  font-size: 1.65rem;
  font-weight: 800;
}

.sahl-home-plan-head p,
.sahl-pricing .sahl-plan-grid article.sahl-home-plan > p {
  min-height: 2.8rem;
  margin-top: 0.65rem;
  color: color-mix(in oklab, var(--pricing-cream) 62%, transparent);
  font-size: 0.82rem;
  line-height: 1.7;
}

.sahl-pricing .sahl-price {
  min-height: 7.3rem;
  margin-top: 1.15rem;
  display: flex;
  align-items: flex-end;
  gap: 0.6rem;
}

.sahl-pricing .sahl-price strong {
  color: var(--pricing-cream);
  font-family: "Almarai", sans-serif;
  font-size: clamp(3.35rem, 4.5vw, 4.8rem);
  font-weight: 800;
  line-height: 1;
}

.sahl-pricing .sahl-price strong.is-custom {
  font-size: clamp(2.15rem, 3vw, 3rem);
}

.sahl-pricing .sahl-price span {
  padding-bottom: 0.5rem;
  color: color-mix(in oklab, var(--pricing-cream) 58%, transparent);
  font-size: 0.75rem;
  font-weight: 600;
  white-space: nowrap;
}

.sahl-plan-divider {
  height: 1px;
  background: color-mix(in oklab, var(--pricing-cream) 13%, transparent);
}

.sahl-pricing .sahl-plan-grid article.sahl-home-plan ul {
  margin: 1.45rem 0 1.75rem;
  padding: 0;
  display: grid;
  gap: 0;
  border: 0;
}

.sahl-pricing .sahl-plan-grid article.sahl-home-plan li {
  display: grid;
  grid-template-columns: 1.35rem minmax(0, 1fr);
  align-items: flex-start;
  gap: 0.75rem;
  min-height: 3rem;
  padding-block: 0.68rem;
  border-bottom: 1px solid color-mix(in oklab, var(--pricing-cream) 9%, transparent);
  color: color-mix(in oklab, var(--pricing-cream) 82%, transparent);
  font-family: "IBM Plex Sans Arabic", sans-serif;
  font-size: 0.92rem;
  font-weight: 500;
  line-height: 1.65;
}

.sahl-pricing .sahl-plan-grid article.sahl-home-plan li:last-child {
  border-bottom: 0;
}

.sahl-home-perk-icon {
  display: grid;
  width: 1.35rem;
  height: 1.35rem;
  margin-top: 0.1rem;
  place-items: center;
  border: 1px solid color-mix(in oklab, var(--perk-color) 34%, transparent);
  border-radius: 999px;
  background: color-mix(in oklab, var(--perk-color) 10%, transparent);
  color: var(--perk-color);
}

.sahl-home-perk-icon[data-tone="0"] { --perk-color: var(--pricing-brick); }
.sahl-home-perk-icon[data-tone="1"] { --perk-color: var(--pricing-gold); }
.sahl-home-perk-icon[data-tone="2"] { --perk-color: var(--pricing-teal); }

.sahl-home-perk-icon svg,
.sahl-pricing .sahl-plan-grid li .sahl-home-perk-icon svg {
  width: 0.9rem;
  height: 0.9rem;
  color: currentColor;
}

.sahl-plan-reveal.is-visible .sahl-home-plan li {
  animation: sahl-perk-arrive 360ms ease-out both;
  animation-delay: calc(280ms + var(--perk-order) * 55ms + var(--plan-order) * 70ms);
}

.sahl-pricing .sahl-plan-grid article.sahl-home-plan > .sahl-home-plan-cta {
  width: 100%;
  min-height: 3.15rem;
  margin-top: auto;
  border-color: var(--pricing-brick);
  border-radius: 999px;
  background: transparent;
  color: color-mix(in oklab, var(--pricing-brick) 60%, var(--pricing-cream));
  font-weight: 800;
}

.sahl-pricing .sahl-home-plan-cta svg {
  width: 1rem;
  height: 1rem;
}

.sahl-pricing .sahl-home-plan.is-featured > .sahl-home-plan-cta {
  border-color: transparent;
  background: linear-gradient(110deg, var(--pricing-brick), var(--pricing-gold));
  color: var(--pricing-cream);
  box-shadow: 0 0 1.6rem color-mix(in oklab, var(--pricing-brick) 36%, transparent);
}

@media (min-width: 1024px) {
  .sahl-pricing .sahl-plan-grid article.sahl-home-plan::after {
    content: "";
    position: absolute;
    z-index: 1;
    inset: -1px;
    padding: 1.4px;
    border-radius: inherit;
    background: conic-gradient(from var(--sahl-price-angle), var(--pricing-brick), var(--pricing-gold), var(--pricing-teal), var(--pricing-brick));
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask-composite: exclude;
    pointer-events: none;
    animation: sahl-price-border-spin 4s linear infinite;
  }

  .sahl-pricing .sahl-plan-grid article.sahl-home-plan.is-featured {
    transform: scale(1.04);
  }

  .sahl-pricing .sahl-plan-grid article.sahl-home-plan.is-featured::after {
    padding: 2px;
    animation-duration: 3s;
  }

  .sahl-pricing .sahl-plan-grid article.sahl-home-plan:hover {
    transform: translateY(-0.35rem);
    box-shadow: 0 2.3rem 5rem -2.6rem color-mix(in oklab, var(--pricing-gold) 52%, transparent);
  }

  .sahl-pricing .sahl-plan-grid article.sahl-home-plan.is-featured:hover {
    transform: translateY(-0.35rem) scale(1.04);
  }
}

@media (max-width: 1023px) {
  .sahl-home-billing { margin-bottom: 2.6rem; }
  .sahl-pricing .sahl-plan-grid { gap: 2rem; }
  .sahl-pricing .sahl-plan-grid article.sahl-home-plan {
    min-height: 0;
    padding: 2rem 1.35rem 1.35rem;
  }
  .sahl-home-plan-head p { min-height: 0; }
  .sahl-pricing .sahl-price { min-height: 6.5rem; }
  .sahl-pricing .sahl-price strong { font-size: clamp(3.6rem, 15vw, 5rem); }
  .sahl-pricing .sahl-plan-grid article.sahl-home-plan li {
    min-height: 3.2rem;
    padding-block: 0.72rem;
    font-size: clamp(0.92rem, 3.8vw, 1rem);
    line-height: 1.65;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sahl-pricing .sahl-plan-grid article.sahl-home-plan,
  .sahl-plan-reveal.is-visible .sahl-home-plan li,
  .sahl-pricing .sahl-plan-grid article.sahl-home-plan::after {
    animation: none;
    transition: none;
  }
  .sahl-plan-reveal.is-visible .sahl-home-plan li { opacity: 1; transform: none; }
}
